import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";

/**
 * Validate that fetching a category with a non-existent id returns an error (404 Not Found or equivalent).
 *
 * This test ensures that the system conforms to correct error handling when an invalid or deleted category id is requested for details.
 *
 * Step-by-step process:
 * 1. Generate a random UUID that does not correspond to any existing discussion board category (since we don't have a category creation API, we simply use a random id).
 * 2. Attempt to fetch the category details using the API with this random UUID.
 * 3. Assert that the API rejects with a 404 error, or equivalent error indicating the resource does not exist.
 * 4. Do not attempt to inspect the error message; just check that an error is thrown.
 */
export async function test_api_discussionBoard_test_get_nonexistent_category(
  connection: api.IConnection,
) {
  // 1. Generate a random UUID for a non-existent category
  const nonexistentId = typia.random<string & tags.Format<"uuid">>();

  // 2. Attempt to fetch the category and expect error
  await TestValidator.error("should fail on non-existent id")(
    async () => {
      await api.functional.discussionBoard.categories.categories.getById(
        connection,
        { id: nonexistentId },
      );
    },
  );
}

