import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";

/**
 * Test registration of a discussion board member with duplicate username.
 *
 * This test validates that the username uniqueness constraint is enforced during member sign-up. It first registers a member with a fresh username, and then attempts to register a second member with the same username but a different email. The second attempt must fail due to a unique username violation.
 *
 * Steps:
 * 1. Register a member with a unique username and email.
 * 2. Attempt to register another member with the SAME username and a different email.
 * 3. Assert that the second registration fails (catches uniqueness constraint violation for username).
 */
export async function test_api_discussionBoard_test_register_member_with_duplicate_username(
  connection: api.IConnection,
) {
  // 1. Register a member with a unique username and email.
  const uniqueUsername: string = RandomGenerator.alphaNumeric(12);
  const member1_email: string = typia.random<string & tags.Format<"email">>();
  const member1_password: string = RandomGenerator.alphaNumeric(16);
  const member1_display_name: string = RandomGenerator.name();

  const member1 = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: uniqueUsername,
      email: member1_email,
      hashed_password: member1_password,
      display_name: member1_display_name,
      profile_image_url: null,
      is_active: true
    } satisfies IdiscussionBoardMembers.ICreate,
  });
  typia.assert(member1);
  TestValidator.equals("username matches")(member1.username)(uniqueUsername);
  TestValidator.equals("email matches")(member1.email)(member1_email);
  TestValidator.equals("display_name matches")(member1.display_name)(member1_display_name);
  TestValidator.equals("is_active true")(member1.is_active)(true);

  // 2. Attempt to register another member with the SAME username and a different email.
  const member2_email: string = typia.random<string & tags.Format<"email">>();
  const member2_password: string = RandomGenerator.alphaNumeric(16);
  const member2_display_name: string = RandomGenerator.name();

  // 3. Assert that registration fails due to duplicate username.
  await TestValidator.error("duplicate username should fail")(
    async () => {
      await api.functional.discussionBoard.actors.members.post(connection, {
        body: {
          username: uniqueUsername,
          email: member2_email,
          hashed_password: member2_password,
          display_name: member2_display_name,
          profile_image_url: null,
          is_active: true
        } satisfies IdiscussionBoardMembers.ICreate,
      });
    },
  );
}

