import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";

/**
 * Validate error response when fetching a soft-deleted discussion board category by id.
 *
 * This test ensures that after creating a new category and then soft-deleting it, attempting to retrieve it by its id fails as expected (i.e., returns an error such as 404 or 410 instead of the resource).
 *
 * Steps:
 * 1. Create a new category using a randomly generated name and optional description.
 * 2. Soft delete the created category.
 * 3. Attempt to retrieve the deleted category by id; this should yield an error (404 Not Found or 410 Gone).
 * 4. Validate that the error occurs (TestValidator.error()) and the resource is not retrieved.
 */
export async function test_api_discussionBoard_test_get_soft_deleted_category(
  connection: api.IConnection,
) {
  // 1. Create a new discussion board category
  const createInput: IDiscussionBoardCategory.ICreate = {
    name: RandomGenerator.paragraph()(1),
    description: RandomGenerator.content()()(),
  };
  const category = await api.functional.discussionBoard.categories.categories.post(connection, {
    body: createInput,
  });
  typia.assert(category);

  // 2. Soft delete the category
  await api.functional.discussionBoard.categories.categories.eraseById(connection, {
