import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";

/**
 * Test successful updating of a post's body by the author member.
 *
 * This end-to-end scenario validates that only the original author member can update a post's body, the is_edited flag becomes true, and the timestamps are correctly updated. It ensures the system's edit-tracking compliance, relationship integrity, and audit log update for post revisions.
 *
 * Steps:
 * 1. Register a new member (the author)
 * 2. Create a new thread as that member
 * 3. Add a post in that thread as the same member
 * 4. Update the post's body
 * 5. Verify is_edited is true, updated_at is later than created_at, body matches, author and thread linkage are intact
 */
export async function test_api_discussionBoard_test_update_post_body_success_by_author_member(
  connection: api.IConnection,
) {
  // 1. Register a new member who will be the post author
  const email = typia.random<string & tags.Format<"email">>();
  const username = RandomGenerator.alphaNumeric(10);
  const displayName = RandomGenerator.name();
  const password = RandomGenerator.alphaNumeric(16);
  const member = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username,
      email,
      hashed_password: password,
      display_name: displayName,
      is_active: true,
    } satisfies IdiscussionBoardMembers.ICreate,
  });
  typia.assert(member);

  // 2. Create a new thread as the member
  const thread = await api.functional.discussionBoard.articles.threads.post(connection, {
    body: {
      discussion_board_category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(),
      body: RandomGenerator.content()()(),
      is_pinned: false,
      is_closed: false,
    } satisfies IDiscussionBoardThread.ICreate,
  });
  typia.assert(thread);

  // 3. Add a post in the thread as the same member
  const originalBody = RandomGenerator.paragraph()();
  const post = await api.functional.discussionBoard.articles.posts.post(connection, {
    body: {
      discussion_board_thread_id: thread.id,
      discussion_board_member_id: member.id,
      body: originalBody,
    } satisfies IDiscussionBoardPost.ICreate,
  });
  typia.assert(post);
  TestValidator.equals("original post body")(post.body)(originalBody);
  TestValidator.equals("is_edited is false on create")(post.is_edited)(false);

  // 4. Update the body of the post as the author
  const updatedBody = RandomGenerator.paragraph()();
  const updated = await api.functional.discussionBoard.articles.posts.putById(connection, {
    id: post.id,
    body: {
      body: updatedBody,
    } satisfies IDiscussionBoardPost.IUpdate,
  });
  typia.assert(updated);

  // 5. Verify outcome: body, is_edited, timestamps, author/thread linkage
  TestValidator.equals("body updated")(updated.body)(updatedBody);
  TestValidator.equals("is_edited true after update")(updated.is_edited)(true);
  TestValidator.equals("author linkage intact")(updated.discussion_board_member_id)(member.id);
  TestValidator.equals("thread linkage intact")(updated.discussion_board_thread_id)(thread.id);
  TestValidator.predicate("updated_at later than created_at")(new Date(updated.updated_at) > new Date(updated.created_at));
}

