 * Validate assignment of administrator privileges to a valid existing member.
 *
 * Business context:
 * - Only members who exist in the discussion_board_members table can be promoted to administrator status.
 * - The process should correctly persist administrator assignment and ensure returned data conforms to expected schema.
 * - This is critical for maintaining accurate privilege control and audit trail.
 *
 * Test process:
 * 1. Create a new discussion_board_member (covers signup and uniqueness constraints).
 * 2. Use the member's id to create a new administrator assignment via POST /discussionBoard/actors/administrators.
 * 3. Validate that the result contains the expected member_id and a valid assignment timestamp.
 * 4. Run schema assertions to ensure all required fields are correct.
 */
export async function test_api_discussionBoard_actors_administrators_test_create_admin_assignment_for_valid_member(
  connection: api.IConnection,
) {
  // 1. Create a new member to be promoted.
  const newMember: IdiscussionBoardMembers = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(12),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(20),
      display_name: RandomGenerator.name(),
      is_active: true,
      // profile_image_url is optional
      profile_image_url: null,
    } satisfies IdiscussionBoardMembers.ICreate,
  });
  typia.assert(newMember);

  // 2. Promote the member to admin
  const now = new Date().toISOString();
  const adminAssignment: IDiscussionBoardAdministrator = await api.functional.discussionBoard.actors.administrators.post(connection, {
    body: {
      member_id: newMember.id,
