 *
 * 1. Create several unique categories via the POST endpoint.
 * 2. Soft delete at least one category using the DELETE endpoint (deleted_at should be set).
 * 3. List all categories with a PATCH request including deleted ones (using the 'deleted_at' filter).
 * 4. Verify:
 *    - All created categories (including the soft-deleted one) are present in the response.
 *    - The soft-deleted category has a non-null deleted_at field.
 *    - All others have deleted_at as null or undefined.
 */
export async function test_api_discussionBoard_test_list_categories_include_soft_deleted(
  connection: api.IConnection,
) {
  // 1. Create several categories.
  const categories: IDiscussionBoardCategory[] = [];
  for (let i = 0; i < 3; ++i) {
    const input = {
      name: `TestCategory_${RandomGenerator.alphaNumeric(8)}`,
      description: RandomGenerator.paragraph()(),
    } satisfies IDiscussionBoardCategory.ICreate;
    const created = await api.functional.discussionBoard.categories.categories.post(
      connection,
      { body: input },
    );
    typia.assert(created);
    categories.push(created);
  }

