import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test listing categories with typical pagination and filtering.
 *
 * This test creates at least 5 categories, each with a unique name and description. It then
 * lists categories filtered by a substring in the name, and uses a 'limit' smaller than the
 * total records to test pagination. The test checks that the returned records match the filter,
 * the results are correctly paginated, and the total count reflects all matching records.
 *
 * Steps:
 * 1. Create 5+ categories with unique names and descriptions.
 * 2. Pick a substring (from one of the created names) to use as a search filter.
 * 3. List categories with the filter and with 'limit' < number of matches (e.g., 2).
 * 4. Verify that:
 *    a. All returned categories have names containing that substring, case-sensitively.
 *    b. Only up to 'limit' results are returned on the page.
 *    c. The total count matches the number of categories containing the filter.
 *    d. Pagination metadata is consistent with returned data and total matches.
 * 5. (Optional) Fetch a second page and verify that remaining records are present as expected.
 */
export async function test_api_discussionBoard_test_list_categories_with_pagination_and_filtering(
  connection: api.IConnection,
) {
  // 1. Create 6 categories with unique names
  const categoryNames = ArrayUtil.repeat(6)(i => `TestCategory_${RandomGenerator.alphabets(6)}_${i}`);
  const descriptions = ArrayUtil.repeat(6)(i => `Description ${RandomGenerator.alphabets(10)} ${i}`);

  const createdCategories: IDiscussionBoardCategory[] = [];
  for (let i = 0; i < 6; ++i) {
    const cat = await api.functional.discussionBoard.categories.categories.post(connection, {
      body: { name: categoryNames[i], description: descriptions[i] } satisfies IDiscussionBoardCategory.ICreate,
    });
    typia.assert(cat);
    createdCategories.push(cat);
  }

  // 2. Pick filter substring (from the middle of one category name)
  const filterName = categoryNames[2].slice(3, 9); // Use part of the 3rd name
  // At least the 3rd category will match, possibly more

  // 3. List categories where name contains the substring, limit=2
  const limit = 2;
  const page1 = await api.functional.discussionBoard.categories.categories.patch(connection, {
    body: { name: filterName, limit, page: 1 } satisfies IDiscussionBoardCategory.IRequest,
  });
  typia.assert(page1);
  // Find all created categories whose name includes filterName
  const matching = createdCategories.filter(c => c.name.includes(filterName));
  TestValidator.predicate('all names contain filter')(page1.data.every(c => c.name.includes(filterName)));
  TestValidator.equals('pagination limit')(page1.pagination.limit)(limit);
  TestValidator.equals('records equal filtered count')(page1.pagination.records)(matching.length);
  TestValidator.equals('data length ≤ limit')(page1.data.length <= limit)(true);

  // If more than limit, check next page
  if (matching.length > limit) {
    const page2 = await api.functional.discussionBoard.categories.categories.patch(connection, {
      body: { name: filterName, limit, page: 2 } satisfies IDiscussionBoardCategory.IRequest,
    });
    typia.assert(page2);
    TestValidator.equals('second page')(page2.pagination.current)(2);
    const allResults = [...page1.data, ...page2.data];
    TestValidator.equals('total returned matches all')(allResults.length)(matching.length);
  }
}

