 *
 * 1. Create a target member account to be banned.
 * 2. Create a moderator account with authority to impose bans.
 * 3. The moderator creates a temporary ban against the member (with expires_at set).
 * 4. The moderator updates the ban: sets permanent: true and expires_at: null.
 * 5. Validate that the ban update is reflected (permanent: true, expires_at: null) and other fields remain consistent.
 */
export async function test_api_discussionBoard_test_update_ban_to_permanent(connection: api.IConnection) {
  // 1. Create member account
  const member = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(24),
      display_name: RandomGenerator.name(),
      is_active: true,
      profile_image_url: null,
    } satisfies IdiscussionBoardMembers.ICreate
  });
  typia.assert(member);

  // 2. Create moderator account (assume same schema for test)
  const moderator = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(24),
      display_name: RandomGenerator.name(),
      is_active: true,
      profile_image_url: null,
    } satisfies IdiscussionBoardMembers.ICreate
  });
