  TestValidator.equals("Ban id unchanged")(updatedBan.id)(tempBan.id);
  TestValidator.equals("Ban member_id unchanged")(updatedBan.member_id)(member.id);
  TestValidator.equals("Ban moderator_id unchanged")(updatedBan.moderator_id)(moderator.id);
  TestValidator.equals("Ban reason unchanged")(updatedBan.ban_reason)(tempBan.ban_reason);
