/**
 * Test listing tags including soft-deleted records when the request filters explicitly allow deleted tags.
 * 
 * This test validates that:
 * 1. You can create a tag.
 * 2. You can soft-delete the tag (which sets its deleted_at timestamp but does not actually delete it from the DB).
 * 3. When searching with include_deleted: true, the soft-deleted tag is included in results, with a non-null deleted_at field.
 * 
 * Steps:
 * 1. Create a new tag with a unique name and (optional) description.
 * 2. Soft delete the tag by its id.
 * 3. Search for tags, setting include_deleted: true and a name filter that matches the created tag's name.
 * 4. Assert that the search returns the tag with a populated deleted_at timestamp (indicating it is soft-deleted), in addition to matching the expected name.
 */
export async function test_api_discussionBoard_categories_tags_test_search_tags_includes_soft_deleted_tags_when_flagged(connection: api.IConnection) {
  // 1. Create tag
  const tagName = RandomGenerator.alphabets(12);
  const description = RandomGenerator.paragraph()();
  const created = await api.functional.discussionBoard.categories.tags.post(connection, {
    body: {
      name: tagName,
      description
    }
  });
  typia.assert(created);

  // 2. Soft-delete tag
  await api.functional.discussionBoard.categories.tags.eraseById(connection, {
    id: created.id,
  });

  // 3. Search for tags with include_deleted: true and name filter
  const searchResult = await api.functional.discussionBoard.categories.tags.patch(connection, {
    body: {
      name: tagName,
      include_deleted: true,
      page: 1,
      limit: 10,
    },
  });
  typia.assert(searchResult);

  // 4. Assert: tag is found, deleted_at is populated
  const found = searchResult.data.find(t => t.id === created.id);
  if (!found)
    throw new Error("Soft-deleted tag not found in results");
  TestValidator.equals("deleted_at is set")(typeof found.deleted_at === "string" && !!found.deleted_at)(true);
  TestValidator.equals("name matches")(found.name)(tagName);
}

