import type { discussion_board_vote_types } from "@ORGANIZATION/PROJECT-api/lib/structures/discussion_board_vote_types";

/**
 * Test retrieving vote type details using a valid and invalid id.
 *
 * This test validates the GET /discussionBoard/votes/voteTypes/{id} endpoint for both successful retrieval and robust error handling.
 *
 * **Business Workflow:**
 * 1. Create a new vote type using POST /discussionBoard/votes/voteTypes and save its id and input payload.
 * 2. Retrieve this vote type with GET /discussionBoard/votes/voteTypes/{id}.
 *    - Assert: All fields match what was originally created (id, code, name, description, created_at, updated_at).
 * 3. Attempt to retrieve a vote type using a random non-existent (but well-formed) uuid.
 *    - Assert: Not found/business error is thrown as expected.
 * 4. Attempt to retrieve a vote type with a malformed (not-uuid) id.
 *    - Assert: Error is thrown, confirming validation or not found behavior.
 */
export async function test_api_discussionBoard_test_get_vote_type_by_valid_and_invalid_id(
  connection: api.IConnection,
) {
  // 1. Create a new vote type (dependency setup)
  const voteTypeInput: discussion_board_vote_types.ICreate = {
    code: RandomGenerator.alphaNumeric(8),
    name: RandomGenerator.alphabets(8),
    description: RandomGenerator.paragraph()(),
  };
  const created: discussion_board_vote_types = await api.functional.discussionBoard.votes.voteTypes.post(connection, {
    body: voteTypeInput,
  });
  typia.assert(created);

  // 2. Retrieve by valid id and verify fields
  const retrieved: discussion_board_vote_types = await api.functional.discussionBoard.votes.voteTypes.getById(connection, {
    id: created.id,
  });
