  TestValidator.equals("code matches")(retrieved.code)(created.code);
  TestValidator.equals("name matches")(retrieved.name)(created.name);
  TestValidator.equals("description matches")(retrieved.description ?? null)(created.description ?? null);
  TestValidator.predicate("created_at is ISO 8601")(!!Date.parse(retrieved.created_at));
  TestValidator.predicate("updated_at is ISO 8601")(!!Date.parse(retrieved.updated_at));

  // 3. Attempt to retrieve a non-existent (but well-formed) uuid
