/**
 * Validate retrieving a notification record by its unique identifier (ID).
 *
 * Test ensures a notification created for a newly registered member can be retrieved via the detail API, and that all required schema fields are present and accurate.
 *
 * Business context: Notifications in the discussion board are used to inform members about various events (mentions, replies, moderation, etc.). Retrieving by ID is critical for notification UI, detail popups, as well as audit and moderation interfaces.
 *
 * Steps:
 * 1. Register a new discussion board member with unique credentials.
 * 2. Create a notification for that member (with all required fields set, plus a mix of optional fields).
 * 3. Retrieve the notification by its ID using GET /discussionBoard/notifications/notifications/{id}.
 * 4. Assert all fields match between creation and retrieval, including (but not limited to): recipient_member_id, trigger_actor_id (nullable), type, content_preview (nullable/if set), url, read status, delivered_at (nullable/if set), created_at, and that deleted_at is null for active notifications.
 * 5. Verify that only the permitted user (the recipient, since authentication is not detailed here) can access this notification, and that all schema-defined fields are present and of correct type.
 */
export async function test_api_discussionBoard_notifications_notifications_test_get_notification_by_id_success(
  connection: api.IConnection,
) {
  // 1. Register a new member
  const memberInput: IdiscussionBoardMembers.ICreate = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    // Simulate a hashed password string (must not be plain text)
    hashed_password: RandomGenerator.alphaNumeric(32),
    display_name: RandomGenerator.name(),
    profile_image_url: null,
    is_active: true,
  };
  const member = await api.functional.discussionBoard.actors.members.post(connection, { body: memberInput });
  typia.assert(member);

  // 2. Create a notification for this member
  const notificationInput: IDiscussionBoardNotification.ICreate = {
    recipient_member_id: member.id,
    trigger_actor_id: null,  // System notification for simplicity
    type: "mention", // Example type
    content_preview: "You were mentioned in a post!",
    url: "https://board.example.com/thread/abc123#42",
    read: false,
    delivered_at: null,
    created_at: new Date().toISOString() as string & tags.Format<"date-time">,
  };
  const notification = await api.functional.discussionBoard.notifications.notifications.post(connection, { body: notificationInput });
  typia.assert(notification);

  // 3. Retrieve the notification by ID
  const fetched = await api.functional.discussionBoard.notifications.notifications.getById(connection, { id: notification.id });
  typia.assert(fetched);

  // 4. Field-by-field validation between creation and retrieval
  TestValidator.equals("notification recipient_member_id")(fetched.recipient_member_id)(notificationInput.recipient_member_id);
  TestValidator.equals("notification trigger_actor_id")(fetched.trigger_actor_id)(notificationInput.trigger_actor_id);
  TestValidator.equals("notification type")(fetched.type)(notificationInput.type);
  TestValidator.equals("notification content_preview")(fetched.content_preview)(notificationInput.content_preview);
  TestValidator.equals("notification url")(fetched.url)(notificationInput.url);
  TestValidator.equals("notification read")(fetched.read)(notificationInput.read);
  TestValidator.equals("notification delivered_at")(fetched.delivered_at)(notificationInput.delivered_at);
  TestValidator.equals("notification created_at")(fetched.created_at)(notificationInput.created_at);
  TestValidator.equals("notification deleted_at (active, should be null)")(fetched.deleted_at)(null);
}

