/**
 * E2E test: searching and paginating discussion board vote types.
 *
 * Validates administrative platform requirements for vote type management UI:
 *
 * 1. Create multiple unique vote type records (each with unique code/name) via POST /discussionBoard/votes/voteTypes.
 * 2. Search for an exact vote type by code using PATCH /discussionBoard/votes/voteTypes; confirm only this is returned.
 * 3. Paginate the list of all vote types (limit: 2), verify returned count matches page size, and total = num created.
 * 4. Search with both code AND name criteria; ensure only matching records are returned. 
 *
 * All API response types are statically and dynamically asserted.
 */
export async function test_api_discussionBoard_votes_voteTypes_test_search_vote_types_with_pagination_and_code_filter(
  connection: api.IConnection,
) {
  // 1. Create multiple unique vote type records with POST
  const voteTypeCount = 5;
  const created: discussion_board_vote_types[] = [];
  for (let i = 0; i < voteTypeCount; ++i) {
    const code = `autotest_code_${Date.now()}_${i}`;
    const name = `AutoTest VoteType ${i} - ${RandomGenerator.alphabets(8)}`;
    const body: discussion_board_vote_types.ICreate = {
      code,
      name,
      description: `E2E Generated Description ${i}`,
    };
    const resp = await api.functional.discussionBoard.votes.voteTypes.post(
      connection, { body } 
    );
    typia.assert(resp);
    created.push(resp);
  }
  // Ensure all codes and names are unique (sanity check)
  const uniqueCodes = new Set(created.map(v => v.code));
  TestValidator.equals('All codes unique')(uniqueCodes.size)(voteTypeCount);
