    { body: { code: pick.code } satisfies discussion_board_vote_types.IRequest }
  );
  typia.assert(codeSearchResp);
  TestValidator.equals('Filtered to 1 record')(codeSearchResp.data.length)(1);
  TestValidator.equals('Returned code matches')(codeSearchResp.data[0].code)(pick.code);
  // 3. Retrieve full list paginated (limit: 2), validate count/page/total
  const pageLimit = 2;
  const pageResp = await api.functional.discussionBoard.votes.voteTypes.patch(
    connection,
