  const memberUsername = RandomGenerator.alphaNumeric(8);
  const member: IdiscussionBoardMembers = await api.functional.discussionBoard.actors.members.post(
    connection,
    {
      body: {
        username: memberUsername,
        email: memberEmail,
        hashed_password: RandomGenerator.alphaNumeric(16),
        display_name: RandomGenerator.name(),
        profile_image_url: null,
        is_active: true,
      } satisfies IdiscussionBoardMembers.ICreate,
    },
  );
