/**
 * Validate API schema strictness by attempting to create a discussion board section with extra fields not defined in the schema.
 *
 * This test ensures that when a client submits additional properties not present in IDiscussionBoardSection.ICreate (such as deleted_at or any random custom property),
 * the API either ignores or—preferably—rejects the creation and returns a validation error. This validates contract adherence and robustness against invalid or malicious input.
 *
 * Test workflow:
 * 1. Create a valid discussion board channel (dependency for section creation).
 * 2. Attempt to create a section for that channel, but include extra fields (e.g., "deleted_at" or "foo").
 * 3. Validate that the API responds with an error (preferably 400 or other validation error), and that no section is created in violation of the strict schema.
 *
 * Coverage:
 * - Test with a legitimate section request body plus extra fields (e.g., deleted_at, random key)
 * - Validate API's error (TestValidator.error)
 * - Never include IDiscussionBoardSection.ICreate properties that don't exist in schema in valid requests; use them only to trigger failure as per scenario
 * - Do NOT attempt to introspect error messages or types—just validate error is thrown
 */
export async function test_api_discussionBoard_systematic_sections_test_create_section_with_extra_fields_not_in_schema(
  connection: api.IConnection,
) {
  // 1. Create a valid channel for the section
  const channelInput: IDiscussionBoardChannel.ICreate = {
    code: RandomGenerator.alphaNumeric(8),
    name: RandomGenerator.paragraph()(1),
    description: RandomGenerator.paragraph()(),
  };
  const channel = await api.functional.discussionBoard.systematic.channels.post(connection, { body: channelInput });
  typia.assert(channel);

  // 2. Prepare a valid section body
  const sectionInput: IDiscussionBoardSection.ICreate = {
    discussion_board_channel_id: channel.id,
    code: RandomGenerator.alphaNumeric(6),
    name: RandomGenerator.paragraph()(1),
    description: RandomGenerator.paragraph()(),
  };

  // 3. Try to create a section with illegal 'deleted_at' property
  await TestValidator.error("section create with deleted_at fails")(() =>
    api.functional.discussionBoard.systematic.sections.post(connection, {
      body: {
        ...sectionInput,
        // Extra property not in schema:
        deleted_at: new Date().toISOString(),
      } as any,
    })
  );

  // 4. Try to create a section with extra arbitrary property
  await TestValidator.error("section create with arbitrary unsupported field fails")(() =>
    api.functional.discussionBoard.systematic.sections.post(connection, {
      body: {
        ...sectionInput,
        foo: "bar",
      } as any,
    })
  );
}

