import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";

/**
 * Validate that registering a member account enforces email uniqueness.
 *
 * This test ensures that the discussion board membership system prevents
 * creation of two accounts with the same email address. The scenario validates
 * a business-critical constraint: email must be unique among all members.
 *
 * Steps:
 * 1. Register the first member with a unique email (should succeed).
 * 2. Attempt to register a second member using the same email but a different username (should fail).
 * 3. Confirm the second registration attempt results in a uniqueness violation error.
 */
export async function test_api_discussionBoard_actors_members_test_register_member_with_duplicate_email(
  connection: api.IConnection,
) {
  // 1. Register the first member with a unique email
  const uniqueEmail = typia.random<string & tags.Format<"email">>();
  const member1Input: IdiscussionBoardMembers.ICreate = {
    username: RandomGenerator.alphaNumeric(10),
    email: uniqueEmail,
    hashed_password: RandomGenerator.alphaNumeric(30),
    display_name: RandomGenerator.name(),
    profile_image_url: null,
    is_active: true,
  };
  const member1 = await api.functional.discussionBoard.actors.members.post(connection, { body: member1Input });
  typia.assert(member1);
  TestValidator.equals("email matches")(member1.email)(uniqueEmail);

  // 2. Attempt to register a second member with the same email
  const member2Input: IdiscussionBoardMembers.ICreate = {
    username: RandomGenerator.alphaNumeric(10), // different username
    email: uniqueEmail,                         // duplicate email
    hashed_password: RandomGenerator.alphaNumeric(30),
    display_name: RandomGenerator.name(),
    profile_image_url: null,
    is_active: true,
  };

  // 3. Validate uniqueness enforcement: error must be thrown
  await TestValidator.error("duplicate email forbidden")(async () => {
    await api.functional.discussionBoard.actors.members.post(connection, { body: member2Input });
  });
}

