import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IDiscussionBoardSubscription } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardSubscription";

/**
 * 테스트 목적: 알림 구독을 조회할 때, 존재하지 않거나 소유하지 않은 구독 id를 요청한 경우의 에러 처리 검증
 *
 * 시나리오:
 * 1. 회원 A와 회원 B를 각각 가입시킨다.
 * 2. 회원 A의 계정으로 알림 구독을 생성한다.
 * 3. 회원 B의 계정으로 회원 A가 생성한 구독을 id로 조회한다. (실패: 소유권 없음)
 * 4. 회원 B의 계정으로 임의의 존재하지 않는 구독 id로 조회한다. (실패: 존재하지 않음)
 * 5. 두 경우 모두 404 not found 혹은 forbidden 에러가 발생해야 한다.
 */
export async function test_api_discussionBoard_test_get_notification_subscription_by_id_not_found_or_forbidden(connection: api.IConnection) {
  // 1. 회원 A 가입
  const memberA = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      display_name: RandomGenerator.name(),
      is_active: true
    }
  });
  typia.assert(memberA);

  // 2. 회원 B 가입
  const memberB = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      display_name: RandomGenerator.name(),
      is_active: true
    }
  });
  typia.assert(memberB);

  // 3. 회원 A의 계정으로 알림 구독 생성
  // (테스트 환경상 별도의 인증 프로세스가 없으므로 member_id 직접 지정)
  const subscription = await api.functional.discussionBoard.notifications.subscriptions.post(connection, {
    body: {
      member_id: memberA.id,
      target_type: 'thread',
      target_id: typia.random<string & tags.Format<"uuid">>(),
      created_at: new Date().toISOString()
    }
  });
