    api.functional.discussionBoard.notifications.subscriptions.getById(connection, { id: subscription.id })
  );

  // 5. 회원 B의 계정으로 존재하지 않는 구독 id로 조회 시도 → 에러 발생해야 함
  await TestValidator.error("존재하지 않는 구독 id 조회 404")(() =>
    api.functional.discussionBoard.notifications.subscriptions.getById(connection, { id: typia.random<string & tags.Format<"uuid">>() })
  );
