 * 2. Issue a notification event to that member.
 * 3. Soft-delete the notification as the recipient.
 * 4. Assert that deleted_at is set in the response.
 * 5. Try to soft-delete as a non-recipient (should fail, if support present).
 * 6. (Optional) Try to soft-delete as admin, if permitted by API.
 */
export async function test_api_discussionBoard_notifications_notifications_test_soft_delete_notification_event_by_recipient(
  connection: api.IConnection,
) {
  // 1. Register a new member to act as notification recipient
  const member = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      display_name: RandomGenerator.name(),
      is_active: true,
      profile_image_url: null,
    } satisfies IdiscussionBoardMembers.ICreate,
  });
  typia.assert(member);

  // 2. Issue a notification to this member
  const notification = await api.functional.discussionBoard.notifications.notifications.post(connection, {
    body: {
      recipient_member_id: member.id,
      trigger_actor_id: member.id,
      type: "reply",
      content_preview: "Test notification preview.",
      url: "https://board.local/thread/1#comment12",
      read: false,
      delivered_at: null,
      created_at: new Date().toISOString(),
    } satisfies IDiscussionBoardNotification.ICreate,
  });
  typia.assert(notification);
  TestValidator.equals("recipient matches")(notification.recipient_member_id)(member.id);

  // 3. Soft-delete the notification as recipient
  const deletedNotification = await api.functional.discussionBoard.notifications.notifications.eraseById(connection, {
    id: notification.id,
  });
  typia.assert(deletedNotification);
  TestValidator.predicate("deleted_at set")(typeof deletedNotification.deleted_at === "string" && deletedNotification.deleted_at.length > 0);

  // 4. Try to soft-delete as another member (should be forbidden)
  const otherMember = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      display_name: RandomGenerator.name(),
      is_active: true,
      profile_image_url: null,
    } satisfies IdiscussionBoardMembers.ICreate,
  });
  typia.assert(otherMember);
  // Simulate login as otherMember; in real flows, switch token/context here
  // Try soft-delete (expected: error)
  TestValidator.error("non-recipient cannot soft delete notification")(async () => {
    await api.functional.discussionBoard.notifications.notifications.eraseById(connection, {
      id: notification.id,
    });
  });
}

