 *      - target_type and target_id reflect the updated values
 *      - All date/time and type constraints are respected
 *
 * Steps:
 *   1. Create member with random but valid fields (username, email, display_name, etc.)
 *   2. Create initial subscription (member_id above; target_type = 'thread'; target_id = random UUID; created_at = now)
 *   3. Update: call putById changing target_type to 'tag', and provide a different target_id (random UUID). Only supply the updatable fields in the body per schema (target_type, target_id; member_id remains unchanged for this scenario)
 *   4. Assert that the response subscription record has:
 *      - The same id and member_id as before
 *      - target_type = 'tag' and new target_id
 *      - created_at remains unchanged (because PUT does not specify change)
 *      - All fields type safe and correct
 */
export async function test_api_discussionBoard_notifications_subscriptions_test_update_subscription_target_type_and_id_with_valid_data(connection: api.IConnection) {
  // 1. Create a member
  const member = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphabets(16),
      display_name: RandomGenerator.name(),
      profile_image_url: null,
