  const initialTargetType = "thread";
  const initialTargetId = typia.random<string & tags.Format<"uuid">>();
  const subscription = await api.functional.discussionBoard.notifications.subscriptions.post(connection, {
    body: {
      member_id: member.id,
      target_type: initialTargetType,
      target_id: initialTargetId,
      created_at: new Date().toISOString(),
    } satisfies IDiscussionBoardSubscription.ICreate,
  });
  typia.assert(subscription);

  // 3. Update the subscription to follow a tag with a new target_id
  const newTargetType = "tag";
  const newTargetId = typia.random<string & tags.Format<"uuid">>();
  const updated = await api.functional.discussionBoard.notifications.subscriptions.putById(
    connection,
    {
      id: subscription.id,
      body: {
        target_type: newTargetType,
        target_id: newTargetId,
      } satisfies IDiscussionBoardSubscription.IUpdate,
    }
  );
  typia.assert(updated);

  // 4. Validate the fields after update
