 *
 * This test ensures that once a notification record's deleted_at field is set (indicating a soft deletion), any attempt to update it using the update endpoint should be rejected by the system. The correct API behavior is to return a 404 or similar error indicating the resource is not found or is no longer active. This captures critical business rules for compliance, audit, and UX consistency.
 *
 * Business scenario:
 * - A member is created and receives a notification event via the appropriate APIs
 * - The notification is soft deleted (not hard deleted, just marked as deleted via deleted_at)
 * - Attempting to update any property (such as mark-as-read or editing preview/content) on the soft-deleted notification should be rejected
 * - The API response must clearly reject the update with a 404 (not found) error or similar, never allowing edits on deleted resources
 *
 * Steps:
 * 1. Register a discussion board member
 * 2. Create a notification event for that member
 * 3. Soft delete the notification event (set deleted_at)
 * 4. Attempt to update the soft-deleted notification (e.g., mark as read)
 * 5. Expect the API to respond with a not found/forbidden error (use TestValidator.error)
 */
export async function test_api_discussionBoard_test_update_notification_event_forbidden_on_soft_deleted(connection: api.IConnection) {
  // 1. Register a discussion board member
  const member = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(32),
      display_name: RandomGenerator.alphabets(8),
      profile_image_url: null,
      is_active: true,
    } satisfies IdiscussionBoardMembers.ICreate,
  });
  typia.assert(member);

  // 2. Create a notification for that member
  const notification = await api.functional.discussionBoard.notifications.notifications.post(connection, {
    body: {
      recipient_member_id: member.id,
      trigger_actor_id: null,
      type: "reply",
      content_preview: "Unit test notification event.",
      url: "/discussionBoard/test/resource",
      read: false,
      delivered_at: null,
      created_at: new Date().toISOString(),
    } satisfies IDiscussionBoardNotification.ICreate,
  });
  typia.assert(notification);

  // 3. Soft delete the notification
  const erased = await api.functional.discussionBoard.notifications.notifications.eraseById(connection, {
    id: notification.id,
  });
  typia.assert(erased);
  TestValidator.predicate("deleted_at should be set after erase")(erased.deleted_at !== null && typeof erased.deleted_at === "string");

  // 4. Attempt to update the soft-deleted notification
  TestValidator.error("update should fail for soft-deleted notification")(
    async () => {
      await api.functional.discussionBoard.notifications.notifications.putById(connection, {
        id: notification.id,
        body: {
          read: true,
          content_preview: "Should not succeed for deleted.",
        } satisfies IDiscussionBoardNotification.IUpdate,
      });
    },
  );
}

