 *
 * This test simulates an administrator updating both the 'name' and the 'description' fields
 * of a category. The steps are as follows:
 *
 * 1. Create a new category to obtain a valid id (dependency).
 * 2. Prepare new values for both 'name' and 'description'.
 * 3. Update the category using the PUT endpoint and provide the new values.
 * 4. Verify that the returned category reflects the new 'name' and 'description'.
 * 5. Confirm that the 'updated_at' field shows a later timestamp than the original (created) record.
 */
export async function test_api_discussionBoard_test_update_category_with_valid_name_and_description(
  connection: api.IConnection,
) {
  // 1. Create a new category (dependency)
  const originalCategory = await api.functional.discussionBoard.categories.categories.post(
    connection,
    {
      body: {
        name: "Original Category Name",
        description: "This is the original description.",
      },
    },
  );
  typia.assert(originalCategory);

  // 2. Prepare new values
  const updatedName = "Updated Category Name";
  const updatedDescription = "This is the updated description.";

  // 3. Update the category
  const updatedCategory = await api.functional.discussionBoard.categories.categories.putById(
    connection,
    {
      id: originalCategory.id,
      body: {
        name: updatedName,
        description: updatedDescription,
      },
    },
  );
