 * Test error-handling of updating a subscription to an invalid resource type.
 *
 * This test validates that the API enforces schema constraints on the 'target_type' property when updating a discussion board subscription. Specifically, it attempts to update an existing subscription with a 'target_type' string value that does not represent a recognized or accepted resource type.
 *
 * Business context:
 * If subscription records are allowed to reference arbitrary types, notification and follow logic can become inconsistent or vulnerable to abuse. Ensuring this field is validated both at creation and update is critical for platform stability.
 *
 * Step-by-step process:
 * 1. Create a member to own the notification subscription.
 * 2. Create a valid subscription for this member, using a plausible 'target_type' and resource ID (uuid).
 * 3. Attempt to update the subscription using PUT, supplying a 'target_type' value that the schema (or business logic) does NOT recognize (e.g. 'nonexistent_resource').
 * 4. Assert that the update fails—a schema validation error or appropriate HTTP error code (typically 400). The record itself must remain unaltered.
 */
export async function test_api_discussionBoard_test_update_subscription_to_invalid_resource_type(
  connection: api.IConnection,
) {
  // 1. Create a member
  const member = await api.functional.discussionBoard.actors.members.post(
    connection,
    {
      body: {
        username: RandomGenerator.alphaNumeric(8),
        email: typia.random<string & tags.Format<"email">>(),
        hashed_password: RandomGenerator.alphaNumeric(32),
        display_name: RandomGenerator.name(),
        is_active: true,
      } satisfies IdiscussionBoardMembers.ICreate,
    }
  );
  typia.assert(member);

  // 2. Create a valid subscription for this member
  const validTargetType = "thread";
  const subscription = await api.functional.discussionBoard.notifications.subscriptions.post(
    connection,
    {
      body: {
        member_id: member.id,
        target_type: validTargetType,
        target_id: typia.random<string & tags.Format<"uuid">>(),
        created_at: new Date().toISOString(),
      } satisfies IDiscussionBoardSubscription.ICreate,
    }
  );
  typia.assert(subscription);

  // 3. Attempt to update subscription to an invalid target_type
  await TestValidator.error("Should reject updating to invalid target_type")(
    async () => {
      await api.functional.discussionBoard.notifications.subscriptions.putById(
        connection,
        {
          id: subscription.id,
          body: {
            target_type: "nonexistent_resource",
          } satisfies IDiscussionBoardSubscription.IUpdate,
        },
      );
    }  
  );
  // 4. Optionally, re-read subscription (if GET supported) to confirm it is unmodified
}

