 * ensuring idempotency and appropriate error/no-op handling when attempting to soft-delete the same moderation ban twice.
 *
 * Steps:
 * 1. Create a target member account (the user to be banned).
 * 2. Create a moderator account (the actor who will issue the ban).
 * 3. Create a moderation ban record linking the member and moderator.
 * 4. Soft-delete the ban record (sets deleted_at on the ban).
 * 5. Attempt to soft-delete the same ban again.
 * 6. Verify the expected behavior on the second delete (should be error or handled as no-op according to endpoint design).
 */
export async function test_api_discussionBoard_moderation_bans_test_soft_delete_ban_twice(
  connection: api.IConnection,
) {
  // Step 1: Create a target member (account to be banned)
  const targetMember: IdiscussionBoardMembers =
    await api.functional.discussionBoard.actors.members.post(connection, {
      body: {
        username: RandomGenerator.alphaNumeric(10),
        email: typia.random<string & tags.Format<"email">>(),
        hashed_password: RandomGenerator.alphaNumeric(32),
        display_name: RandomGenerator.name(),
        is_active: true,
        profile_image_url: null,
      } satisfies IdiscussionBoardMembers.ICreate,
    });
  typia.assert(targetMember);

  // Step 2: Create a moderator (account issuing the ban)
  const moderator: IdiscussionBoardMembers =
    await api.functional.discussionBoard.actors.members.post(connection, {
      body: {
        username: RandomGenerator.alphaNumeric(10),
        email: typia.random<string & tags.Format<"email">>(),
        hashed_password: RandomGenerator.alphaNumeric(32),
        display_name: RandomGenerator.name(),
        is_active: true,
        profile_image_url: null,
      } satisfies IdiscussionBoardMembers.ICreate,
    });
  typia.assert(moderator);

  // Step 3: Create a moderation ban for the target member by the moderator
  const ban: IModerationBan =
    await api.functional.discussionBoard.moderation.bans.post(connection, {
      body: {
        member_id: targetMember.id,
        moderator_id: moderator.id,
        ban_reason: RandomGenerator.paragraph()(),
        permanent: true,
        expires_at: null,
      } satisfies IModerationBan.ICreate,
    });
  typia.assert(ban);

  // Step 4: Soft delete (DELETE) the ban record
  await api.functional.discussionBoard.moderation.bans.eraseById(connection, {
    id: ban.id,
  });

  // Step 5: Attempt to delete the ban a second time, expect error or no-op
  await TestValidator.error("Deleting twice is error or no-op")(() =>
    api.functional.discussionBoard.moderation.bans.eraseById(connection, { id: ban.id })
  );
}

