 *
 * 주요 절차:
 * 1. 설정 1 생성: key: keyA, value: valueA
 * 2. 설정 2 생성: key: keyB, value: valueB
 * 3. 설정 2를 업데이트하며 key를 keyA로 변경 시도
 * 4. 고유 제약 조건 위반(중복 에러) 발생 확인
 */
export async function test_api_discussionBoard_test_update_configuration_with_duplicate_key_returns_unique_constraint_error(connection: api.IConnection) {
  // 1. 첫 번째 구성 생성
