 * 4. The second creation attempt must fail due to uniqueness constraint violation (business rule: only one subscription per member/resource pair).
 *
 * Successful outcome: The duplicate subscription attempt is rejected by the system, and an error is thrown as expected. This test safeguards notification delivery logic and enforces a consistent subscription model.
 */
export async function test_api_discussionBoard_notifications_subscriptions_test_create_duplicate_notification_subscription_failure(
  connection: api.IConnection,
) {
  // 1. Register a new member
  const memberInput: IdiscussionBoardMembers.ICreate = {
    username: RandomGenerator.alphabets(12),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(24),
    display_name: RandomGenerator.alphabets(8),
    is_active: true,
    // Optionally set profile_image_url, but omit for minimal coverage
  };
  const member = await api.functional.discussionBoard.actors.members.post(connection, { body: memberInput });
  typia.assert(member);

  // 2. Create a valid subscription for the new member to a target resource
  const subscriptionInput: IDiscussionBoardSubscription.ICreate = {
    member_id: member.id,
    target_type: "thread",
    target_id: typia.random<string & tags.Format<"uuid">>(),
    created_at: new Date().toISOString(),
