  const subscription = await api.functional.discussionBoard.notifications.subscriptions.post(connection, { body: subscriptionInput });
  typia.assert(subscription);

  // 3. Attempt to create the same subscription again (should fail)
  await TestValidator.error("Reject duplicate subscription creation")(
    async () => {
      await api.functional.discussionBoard.notifications.subscriptions.post(connection, { body: subscriptionInput });
    },
  );
}

