import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IDiscussionBoardThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardThread";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";

/**
 * 댓글 생성이 soft delete(부드러운 삭제)된 게시글(post)에서 실패하는지 검증합니다.
 *
 * - 게시글이 soft delete되면 댓글 달기가 불가능해야 하며,
 *   이를 통해 삭제된 글에 고아(comments orphaned)로 댓글이 남지 않음을 보장해야 한다.
 *
 * 테스트 단계 (성공 케이스 없음, 오직 실패 케이스만 검증됨):
 * 1. 회원 가입(댓글 작성자)
 * 2. 스레드 생성
 * 3. 게시글(post) 생성
 * 4. 해당 게시글을 soft delete(삭제)
 * 5. soft delete된 게시글에 댓글 생성 시도 → 반드시 실패해야 함
 *
 * 검증 방법:
 * - 댓글 생성 API 요청 시 에러가 정상적으로 발생하는지 (TestValidator.error 사용)
 * - 에러 발생 시 기존 게시글은 여전히 soft deleted 상태인지 (optionally 재확인)
 */
export async function test_api_discussionBoard_test_create_comment_fails_if_post_soft_deleted(
  connection: api.IConnection,
) {
  // 1. 회원 가입
  const email = typia.random<string & tags.Format<"email">>();
  const member = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphabets(10),
      email,
      hashed_password: RandomGenerator.alphaNumeric(30),
      display_name: RandomGenerator.name(),
      profile_image_url: null,
      is_active: true,
    },
  });
  typia.assert(member);

  // 2. 스레드 생성 (카테고리 UUID는 랜덤)
  const thread = await api.functional.discussionBoard.articles.threads.post(connection, {
    body: {
      discussion_board_category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(10),
      body: RandomGenerator.content()()(10),
      is_pinned: false,
      is_closed: false,
    },
  });
  typia.assert(thread);

  // 3. 게시글(post) 생성
  const post = await api.functional.discussionBoard.articles.posts.post(connection, {
    body: {
      discussion_board_thread_id: thread.id,
      discussion_board_member_id: member.id,
      body: RandomGenerator.content()()(10),
    },
  });
  typia.assert(post);

  // 4. 게시글 soft-delete
  const del = await api.functional.discussionBoard.articles.posts.eraseById(connection, {
    id: post.id,
  });
  typia.assert(del);
  TestValidator.predicate("게시글 soft delete 성공")(del.success === true && !!del.post.deleted_at);

  // 5. soft delete된 게시글에 댓글 생성 시도 → 반드시 실패해야 함
  await TestValidator.error("soft deleted 게시글에 댓글 생성 에러")(() =>
    api.functional.discussionBoard.articles.comments.post(connection, {
      body: {
        discussion_board_post_id: post.id,
        discussion_board_member_id: member.id,
        parent_id: null,
        body: RandomGenerator.content()()(6),
      },
    })
  );
}

