import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IModerationBan } from "@ORGANIZATION/PROJECT-api/lib/structures/IModerationBan";

/**
 * Validate updating an existing member ban record with legitimate field changes.
 *
 * This test simulates the typical moderation workflow: issuing, then later updating, a ban on a member.
 * Steps include:
 * 1. Register a new member to use as the ban target.
 * 2. Register a second member as the moderator.
 * 3. Create an initial ban for the target member, issued by the moderator.
 * 4. Update the ban by modifying fields such as the ban reason, expiration, and permanent status. 
 * 5. Confirm the updated record reflects the new data and preserves required audit trail fields.
 *
 * This test ensures field updates (ban_reason, permanent status, expires_at) are processed, and irreducible audit metadata (ban id, member id, moderator id, created_at) remain unchanged unless updated, in line with moderation compliance needs.
 */
export async function test_api_discussionBoard_moderation_bans_test_update_ban_with_valid_data(
  connection: api.IConnection,
) {
  // 1. Register a new member to be banned
  const banned_member = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(32),
      display_name: RandomGenerator.name(),
      is_active: true
    } satisfies IdiscussionBoardMembers.ICreate
  });
  typia.assert(banned_member);

  // 2. Register a second member as moderator
  const moderator_member = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(32),
      display_name: RandomGenerator.name(),
      is_active: true
    } satisfies IdiscussionBoardMembers.ICreate
  });
  typia.assert(moderator_member);

  // 3. Create an initial ban (temporary, non-permanent, specific reason)
  const initialExpiresAt = new Date(Date.now() + 3 * 24 * 60 * 60 * 1000).toISOString();
  const ban = await api.functional.discussionBoard.moderation.bans.post(connection, {
    body: {
      member_id: banned_member.id,
      moderator_id: moderator_member.id,
      ban_reason: "Initial violation: spamming",
      permanent: false,
      expires_at: initialExpiresAt
    } satisfies IModerationBan.ICreate
  });
  typia.assert(ban);

  // 4. Update ban: change reason, extend expiry, switch to permanent
  const updateInput: IModerationBan.IUpdate = {
    ban_reason: "Updated after review: multiple spamming infractions - permanent lockout.",
    permanent: true,
    expires_at: null
  };
  const updatedBan = await api.functional.discussionBoard.moderation.bans.putById(connection, {
    id: ban.id,
    body: updateInput
  });
  typia.assert(updatedBan);

  // 5. Confirm updates were applied and audit fields are preserved
  TestValidator.equals("ban_reason updated")(updatedBan.ban_reason)(updateInput.ban_reason);
  TestValidator.equals("ban made permanent")(updatedBan.permanent)(true);
  TestValidator.equals("expires_at cleared for permanent")(updatedBan.expires_at)(null);
  TestValidator.equals("id unchanged")(updatedBan.id)(ban.id);
  TestValidator.equals("member_id unchanged")(updatedBan.member_id)(ban.member_id);
  TestValidator.equals("moderator_id unchanged")(updatedBan.moderator_id)(ban.moderator_id);
  TestValidator.equals("created_at unchanged")(updatedBan.created_at)(ban.created_at);
}

