 * 3. Fetch the subscription via GET /discussionBoard/notifications/subscriptions/:id using its exact id.
 * 4. Assert all returned fields match the subscription originally created—including id, member_id, target_type, target_id, created_at.
 */
export async function test_api_discussionBoard_test_get_notification_subscription_by_id_success(
  connection: api.IConnection
) {
  // 1. Register a new member
  const member = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(32),
      display_name: RandomGenerator.name(),
      is_active: true,
      profile_image_url: null,
    } satisfies IdiscussionBoardMembers.ICreate,
  });
  typia.assert(member);

  // 2. Create a new notification subscription for the member
  const subscriptionCreate = {
    member_id: member.id,
    target_type: "thread",
    target_id: typia.random<string & tags.Format<"uuid">>(),
    created_at: new Date().toISOString(),
  } satisfies IDiscussionBoardSubscription.ICreate;

  const subscription = await api.functional.discussionBoard.notifications.subscriptions.post(connection, {
    body: subscriptionCreate,
  });
  typia.assert(subscription);

  // 3. Retrieve the subscription by its id
  const fetched = await api.functional.discussionBoard.notifications.subscriptions.getById(connection, {
    id: subscription.id,
  });
  typia.assert(fetched);

  // 4. Assert all fields are equal
  TestValidator.equals("subscription record: id")(fetched.id)(subscription.id);
  TestValidator.equals("subscription record: member_id")(fetched.member_id)(subscription.member_id);
  TestValidator.equals("subscription record: target_type")(fetched.target_type)(subscription.target_type);
  TestValidator.equals("subscription record: target_id")(fetched.target_id)(subscription.target_id);
  TestValidator.equals("subscription record: created_at")(fetched.created_at)(subscription.created_at);
}

