import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardChannel";
import type { IDiscussionBoardSection } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardSection";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageDiscussionBoardSection } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageDiscussionBoardSection";

/**
 * [검증 목적] 상위 채널 ID와 섹션명(부분일치) 기준으로 섹션 목록 필터 검색 능력 검증.
 * 
 * [비즈니스 및 테스트 로직]
 * 1. 신규 토론 채널을 생성한다.
 * 2. 해당 채널 하위에 서로 다른 이름을 가진 섹션 여러 개를 등록한다 (예: '정치', '경제', '정책', '정치사회').
 * 3. 임의의 섹션명을 부분 문자열(예: '정치')로 추출한 후 이 이름 fragment와 상위 채널 ID를 기준으로 필터 검색 요청을 한다.
 * 4. 응답 결과가 fragment에 부합하는 섹션명들만 포함하는지 확인하고, 다른 이름(미포함) 섹션이 결과에 포함되지 않았는지 검증한다. 전체 페이징 데이터도 정합성 체크.
 */
export async function test_api_discussionBoard_test_search_sections_with_filtering_by_channel_id_and_name(connection: api.IConnection) {
  // 1. 신규 토론 채널 생성
  const channelCreateInput = {
    code: RandomGenerator.alphaNumeric(8),
    name: RandomGenerator.paragraph()(2),
    description: RandomGenerator.content()()(1)
  } satisfies IDiscussionBoardChannel.ICreate;
  const channel = await api.functional.discussionBoard.systematic.channels.post(connection, { body: channelCreateInput });
  typia.assert(channel);

  // 2. 서로 다른 이름으로 섹션 여러 개 등록 ('정치', '경제', '정책', '정치사회')
  const sectionNames = ["정치", "경제", "정책", "정치사회"];
  const createdSections: IDiscussionBoardSection[] = [];
  for(const name of sectionNames) {
    const sectionInput = {
      discussion_board_channel_id: channel.id,
      code: RandomGenerator.alphaNumeric(8),
      name,
      description: null
    } satisfies IDiscussionBoardSection.ICreate;
    const section = await api.functional.discussionBoard.systematic.sections.post(connection, { body: sectionInput });
    typia.assert(section);
    createdSections.push(section);
  }

  // 3. 섹션명 부분일치 fragment 및 채널 id로 필터 검색 (fragment: '정치')
  const nameFragment = "정치";
  const response = await api.functional.discussionBoard.systematic.sections.patch(connection, {
    body: {
      discussion_board_channel_id: channel.id,
      name: nameFragment
    } satisfies IDiscussionBoardSection.IRequest
