import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";

/**
 * Test API does not allow updating immutable fields (like id, created_at).
 *
 * This test first creates a new discussion board category, then attempts to update
 * the category using the PUT /discussionBoard/categories/categories/{id} endpoint,
 * intentionally trying to change immutable/system-controlled fields (e.g., id or created_at),
 * even though the update DTO only allows name and description. It covers two cases:
 * 1. Attempting to update by spreading extra fields into the update DTO (should be ignored)
 * 2. Supplying a valid update (name/description) and verifying only those fields change
 *
 * The test expects that immutable/system fields are not changed, and that attempts to send
 * extra immutable fields are either ignored or result in an error. The actual update should
 * only impact allowed fields (name, description). All other fields must remain unchanged.
 *
 * Steps:
 * 1. Create a category (POST)
 * 2. Try to PUT update with extra fields like id and created_at added intentionally in the update body (forced via cast)
 *    (Type system will prevent direct injection, so error scenario must be runtime check)
 * 3. If API allows, verify response ignores those fields and immutable fields remain unchanged.
 *    If API rejects, assert an error is thrown.
 * 4. Do a legitimate name/description update and verify expected field changes, others do not.
 */
export async function test_api_discussionBoard_test_update_category_with_immutable_field(connection: api.IConnection) {
  // 1. Create a category
  const createInput: IDiscussionBoardCategory.ICreate = {
    name: RandomGenerator.alphabets(8),
    description: RandomGenerator.paragraph()(),
  };
  const created = await api.functional.discussionBoard.categories.categories.post(connection, { body: createInput });
  typia.assert(created);

  // 2. Attempt to update immutable fields (id, created_at, updated_at)
  const maliciousUpdate: any = {
    name: RandomGenerator.alphabets(8),
    id: typia.random<string & tags.Format<"uuid">>(),
    created_at: typia.random<string & tags.Format<"date-time">>(),
    updated_at: typia.random<string & tags.Format<"date-time">>(),
    description: RandomGenerator.paragraph()(),
    deleted_at: null,
  };

  // Expect error or fields to be ignored
  await TestValidator.error("Should reject update with forbidden fields")(
    async () => {
      await api.functional.discussionBoard.categories.categories.putById(connection, {
        id: created.id,
        body: maliciousUpdate,
      });
    }
  );

  // 3. Normal valid update should work
  const updateInput: IDiscussionBoardCategory.IUpdate = {
    name: RandomGenerator.alphabets(12),
    description: RandomGenerator.paragraph()(),
  };
  const updated = await api.functional.discussionBoard.categories.categories.putById(connection, {
    id: created.id,
    body: updateInput,
  });
  typia.assert(updated);

  // 4. Validate that only allowed fields are changed
  TestValidator.equals("id unchanged")(updated.id)(created.id);
  TestValidator.equals("created_at unchanged")(updated.created_at)(created.created_at);
  TestValidator.equals("name updated")(updated.name)(updateInput.name);
  TestValidator.equals("description updated")(updated.description)(updateInput.description);
  TestValidator.equals("deleted_at unchanged")(updated.deleted_at)(created.deleted_at ?? null);
}

