import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardChannel";
import type { IDiscussionBoardSection } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardSection";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageDiscussionBoardSection } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageDiscussionBoardSection";

/**
 * Test fetching a paginated list of discussion board sections (게시판 섹션) with default pagination and no filters.
 *
 * This test verifies that the API returns a paginated list of only active (non-soft-deleted) sections when no filters are applied, after several channels and sections are created.
 * 
 * Test process:
 * 1. Create multiple channels to act as section parents (IDiscussionBoardChannel.ICreate → .channels.post)
 * 2. For each channel, create several sections (IDiscussionBoardSection.ICreate → .sections.post),
 *    making sure a couple sections are soft-deleted afterwards to test active-items-only logic.
 * 3. Fetch the section list without any filters (IDiscussionBoardSection.IRequest minimally populated → .sections.patch)
 * 4. Confirm: (a) Response structure and type; (b) All returned sections are active (deleted_at is null); (c) Content matches created sections except those that were soft-deleted (if possible)
 * 5. Confirm that pagination is in effect (pagination object present in the result)
 */
export async function test_api_discussionBoard_test_list_sections_with_default_pagination_and_no_filters(connection: api.IConnection) {
  // 1. Create multiple channels for parent assignment
  const channels: IDiscussionBoardChannel[] = [];
  for (let i = 0; i < 3; ++i) {
    const channel = await api.functional.discussionBoard.systematic.channels.post(connection, {
      body: {
        code: `test-channel-${RandomGenerator.alphabets(6)}-${i}`,
        name: `테스트 채널 ${i}`,
        description: `테스트용 채널 설명 ${i}`,
      } satisfies IDiscussionBoardChannel.ICreate,
    });
    typia.assert(channel);
    channels.push(channel);
  }

  // 2. Create multiple sections under each channel
  const allSections: IDiscussionBoardSection[] = [];
  for (const channel of channels) {
    for (let j = 0; j < 4; ++j) {
      const section = await api.functional.discussionBoard.systematic.sections.post(connection, {
        body: {
          discussion_board_channel_id: channel.id,
          code: `sect-${RandomGenerator.alphabets(5)}-${j}`,
          name: `테스트 섹션 ${j} for ${channel.code}`,
          description: `테스트용 섹션 설명 ${j}`,
        } satisfies IDiscussionBoardSection.ICreate,
      });
      typia.assert(section);
      allSections.push(section);
    }
  }

  // Note: No soft-deletion endpoint exists, so all sections are active by default
  // 3. Fetch the section list with default (empty) filter
  const result = await api.functional.discussionBoard.systematic.sections.patch(connection, {
    body: {} satisfies IDiscussionBoardSection.IRequest,
  });
  typia.assert(result);

  // Check structure and required pagination fields
  TestValidator.equals("pagination structure")(typeof result.pagination === "object")(true);
  TestValidator.predicate("pagination fields present")(typeof result.pagination.current === "number" && typeof result.pagination.limit === "number" && typeof result.pagination.records === "number" && typeof result.pagination.pages === "number");

  // 4. Confirm all returned sections are active (not soft-deleted)
  for (const s of result.data) {
    TestValidator.equals("active sections only")(s.deleted_at)(null);
  }

  // 5. (Optional) Confirm content includes created sections (may include extra sections from system, can't check exact match)
  const createdSectionIDs = new Set(allSections.map(s => s.id));
  const foundCreatedSections = result.data.filter(s => createdSectionIDs.has(s.id));
  TestValidator.predicate("created sections are present")(foundCreatedSections.length >= allSections.length);
}

