import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IDiscussionBoardSubscription } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardSubscription";
import type { IPageIDiscussionBoardSubscription } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardSubscription";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 테스트 목적: 알림 구독 목록 조회 및 필터링 동작 확인
 * 
 * 이 테스트는 멤버 등록과 다양한 리소스에 대한 구독 생성, 그리고 적절한 필터 조건(member_id, target_type 등)으로 구독 목록을 조회했을 때 올바른 결과만 반환되는지 확인한다. 요청 시 스키마에 정의된 필드만 필터링에 사용해야 함을 검증한다. 또한 응답 결과의 각 필드가 정의된 스키마에만 일치하는지 검증한다.
 * 
 * **테스트 시나리오:**
 * 1. 멤버 계정을 생성한다.
 * 2. 해당 멤버가 서로 다른 target_type, target_id를 가진 여러 리소스에 대해 구독(subscription)을 생성한다.
 * 3. subscriptions.patch API를 member_id, target_type 등으로 각각 요청하여 필터 조건에 맞는 구독만 리스트에 나타나는지 확인한다.
 * 4. 반환된 subscription 목록의 각 항목이 올바른 member_id, target_type 값을 가지는지 검증한다.
 * 5. pagination 정보(현재 페이지, limit 등)에 대해서도 타입 검증을 실시한다.
 */
export async function test_api_discussionBoard_notifications_subscriptions_test_list_notification_subscriptions_with_valid_filters(connection: api.IConnection) {
  // 1. 멤버 등록
  const memberCreate: IdiscussionBoardMembers.ICreate = {
    username: RandomGenerator.alphabets(8),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphabets(16),
    display_name: RandomGenerator.name(),
    is_active: true
  };
  const member = await api.functional.discussionBoard.actors.members.post(connection, { body: memberCreate });
  typia.assert(member);

  // 2. 서로 다른 구독 생성 (target_type 2개, 각 1개 이상)
  const types = ["thread", "section"];
  const subscriptions: IDiscussionBoardSubscription[] = [];
  for (const target_type of types) {
    // 두 개의 서로 다른 리소스 id 생성
    for (let i = 0; i < 2; ++i) {
      const sub = await api.functional.discussionBoard.notifications.subscriptions.post(connection, {
        body: {
          member_id: member.id,
          target_type,
          target_id: typia.random<string & tags.Format<"uuid">>(),
          created_at: new Date().toISOString()
        }
      });
      typia.assert(sub);
      subscriptions.push(sub);
    }
  }

  // 3. member_id로만 필터링 테스트
  const pageByMember = await api.functional.discussionBoard.notifications.subscriptions.patch(connection, {
    body: { member_id: member.id } as IDiscussionBoardSubscription.IRequest
  });
  typia.assert(pageByMember);
  for (const item of pageByMember.data) {
    TestValidator.equals("모든 구독은 해당 멤버의 것")(item.member_id)(member.id);
  }

  // 4. target_type도 같이 필터링
  const targetTypeToCheck = types[0];
  const pageByType = await api.functional.discussionBoard.notifications.subscriptions.patch(connection, {
    body: { member_id: member.id, target_type: targetTypeToCheck }
  });
  typia.assert(pageByType);
  for (const item of pageByType.data) {
    TestValidator.equals("필터된 구독의 멤버가 일치")(item.member_id)(member.id);
    TestValidator.equals("필터된 구독의 타입이 일치")(item.target_type)(targetTypeToCheck);
  }

  // 5. 타입 및 페이지네이션 필드 검증
  TestValidator.predicate("pagination.current이 1 이상")(pageByType.pagination.current >= 1);
  TestValidator.predicate("pagination.limit이 1 이상")(pageByType.pagination.limit >= 1);
  TestValidator.predicate("pagination.records이 1 이상")(pageByType.pagination.records >= 1);
}

