 *    - data array contains only expected tags according to filter
 *    - pagination metadata (`current`, `limit`, `records`, `pages`) reflects actual data
 *    - all returned tags comply with the IDiscussionBoardTag schema
 *    - paging works (correct tags appear for given `page`, `limit`)
 */
export async function test_api_discussionBoard_test_search_tags_with_name_filter_and_pagination(connection: api.IConnection) {
