import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";

/**
 * Test the idempotency and error handling of the soft-delete (eraseById) endpoint for discussion board categories.
 *
 * This test creates a new discussion board category, performs a soft delete (eraseById), and then attempts to soft delete the same category again.
 * The second deletion should fail with an error, confirming that already-deleted categories are not deletable again (proper idempotency and resource-not-found behavior).
 *
 * Steps:
 * 1. Create a new discussion board category (with random name/description)
 * 2. Soft delete (eraseById) that category by its id; expect success
 * 3. Attempt to eraseById on the same id again; expect an error (category is already deleted)
 * 4. Validates that correct error is produced on second deletion attempt
 */
export async function test_api_discussionBoard_test_soft_delete_category_already_deleted(
  connection: api.IConnection,
) {
  // 1. Create a new category
  const createInput: IDiscussionBoardCategory.ICreate = {
    name: RandomGenerator.paragraph()(3),
    description: RandomGenerator.content()()(),
  };
  const category = await api.functional.discussionBoard.categories.categories.post(connection, {
    body: createInput,
  });
  typia.assert(category);

  // 2. Soft delete the category
  await api.functional.discussionBoard.categories.categories.eraseById(connection, {
    id: category.id,
  });

  // 3. Attempt to soft delete again (should fail)
  await TestValidator.error("double soft-deletion should fail")(
    async () => {
      await api.functional.discussionBoard.categories.categories.eraseById(connection, {
        id: category.id,
      });
    },
  );
}

