import type { IModerationWarning } from "@ORGANIZATION/PROJECT-api/lib/structures/IModerationWarning";

/**
 * 테스트 목적: 모더레이터가 경고(warning) 레코드를 소프트 삭제(soft delete)하는 기능을 검증합니다.
 *
 * 이 테스트는 다음과 같은 절차를 따릅니다:
 * 1. 경고를 받을 멤버를 생성
 * 2. 멤버를 모더레이터로 승격
 * 3. 모더레이터가 해당 멤버에게 경고를 발급
 * 4. 모더레이터가 생성된 경고(warning)에 대해 DELETE API 호출(소프트 삭제)
