 * 3. Create a notification by sending a POST request to /discussionBoard/notifications/notifications, setting all required and optional fields in the body.
 *    - Provide recipient_member_id using the first created member.
 *    - Provide trigger_actor_id using the second member.
 *    - Set all required: type, url, read, created_at.
 *    - Optionally set: content_preview, delivered_at.
 * 4. Assert a proper 201 response (or success) and validate the response follows the IDiscussionBoardNotification schema with all fields present and matching input/expectations.
 */
export async function test_api_discussionBoard_notifications_notifications_test_create_notification_with_valid_data(connection: api.IConnection) {
  // 1. Create member to receive the notification
  const recipient: IdiscussionBoardMembers = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
