      display_name: RandomGenerator.name(),
      profile_image_url: null,
      is_active: true
    } satisfies IdiscussionBoardMembers.ICreate,
  });
  typia.assert(recipient);

  // 2. Create trigger actor member for notification context
  const triggerActor: IdiscussionBoardMembers = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(24),
      display_name: RandomGenerator.name(),
      profile_image_url: null,
      is_active: true,
    } satisfies IdiscussionBoardMembers.ICreate,
  });
  typia.assert(triggerActor);

  // 3. Create notification event with all required/optional fields set
  const now: string & tags.Format<"date-time"> = new Date().toISOString() as string & tags.Format<"date-time">;
  const notificationInput: IDiscussionBoardNotification.ICreate = {
    recipient_member_id: recipient.id,
    trigger_actor_id: triggerActor.id,
    type: "mention",
    content_preview: "You were mentioned in the discussion.",
    url: "https://forum.example.com/thread/123#comment-456",
    read: false,
    delivered_at: now,
    created_at: now,
  };

