  // 4. Validate returned data matches sent input and schema requirements
  TestValidator.equals("recipient matches")(notification.recipient_member_id)(recipient.id);
  TestValidator.equals("trigger actor matches")(notification.trigger_actor_id)(triggerActor.id);
  TestValidator.equals("type")(notification.type)(notificationInput.type);
  TestValidator.equals("content_preview")(notification.content_preview)(notificationInput.content_preview);
  TestValidator.equals("url")(notification.url)(notificationInput.url);
  TestValidator.equals("read status")(notification.read)(false);
  TestValidator.equals("delivered_at")(notification.delivered_at)(now);
  TestValidator.equals("created_at")(notification.created_at)(now);
  TestValidator.predicate("notification should have an id")(
    typeof notification.id === "string" && notification.id.length > 0
  );
  TestValidator.equals("deleted_at should be null or undefined")(notification.deleted_at)(null);
