import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IdiscussionBoardModerators } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardModerators";
import type { IDiscussionBoardThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardThread";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";

/**
 * Validate that soft-deleting a discussion thread that has already been soft-deleted returns an error.
 *
 * Business rationale: Soft-deletion in discussion board threads uses the deleted_at timestamp. Once a thread is soft-deleted, attempting to delete it again should be handled safely by the backend, returning a non-successful operation and clear feedback (e.g., not found, already deleted).
 *
 * Detailed process:
 * 1. Create a normal member account.
 * 2. Escalate the member to a moderator role, as only moderators can perform thread deletions.
 * 3. Create a category for the thread (needed for thread creation).
 * 4. As a moderator, create a discussion thread in that category.
 * 5. Soft-delete the thread by calling eraseById once and verify the success and effect.
 * 6. Attempt to soft-delete the same thread again. Expect the API to return a failure (e.g., success: false) or error result, indicating the thread is already deleted.
 * 7. Assert that the failure is as expected (do not check error message detail, just failure/exception).
 */
export async function test_api_discussionBoard_test_soft_delete_thread_already_deleted_returns_error(
  connection: api.IConnection,
) {
  // Step 1: Create normal member
  const member = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: typia.random<string>(),
      display_name: RandomGenerator.name(),
      is_active: true,
    },
  });
  typia.assert(member);

  // Step 2: Escalate member to moderator role
  const moderator = await api.functional.discussionBoard.actors.moderators.post(connection, {
    body: {
      member_id: member.id,
      assigned_at: new Date().toISOString(),
    },
  });
  typia.assert(moderator);

  // Step 3: Create category for the thread
  const category = await api.functional.discussionBoard.categories.categories.post(connection, {
    body: {
      name: RandomGenerator.alphabets(8),
      description: RandomGenerator.paragraph()(),
    },
  });
  typia.assert(category);

  // Step 4: Create the thread as moderator
  const thread = await api.functional.discussionBoard.articles.threads.post(connection, {
    body: {
      discussion_board_category_id: category.id,
      title: RandomGenerator.paragraph()(),
      body: RandomGenerator.content()()(),
      is_pinned: false,
      is_closed: false,
    },
  });
  typia.assert(thread);

  // Step 5: Soft-delete (first time)
  const deletedResult = await api.functional.discussionBoard.articles.threads.eraseById(connection, { id: thread.id });
  typia.assert(deletedResult);
  TestValidator.equals("delete thread success")(deletedResult.success)(true);
  TestValidator.predicate("thread deleted_at is set")(!!deletedResult.thread.deleted_at);

  // Step 6 & 7: Attempt soft-delete again, expect failure
  await TestValidator.error("cannot delete already deleted thread")(
    async () => {
      await api.functional.discussionBoard.articles.threads.eraseById(connection, { id: thread.id });
    }
  );
}

