/**
 * 이 테스트는 한 채널 내에서 섹션 코드(code)가 중복될 경우 section 생성이 실패(고유 제약 위반)해야 함을 검증합니다.
 *
 * 비즈니스 규칙상, discussion_board_sections의 code는 같은 discussion_board_channel_id 내에서만 유일하면 되므로
 * 아래와 같은 시나리오를 진행합니다:
 *
 * 1. 채널(channel)을 생성한다.
 * 2. 특정 code로 첫 번째 section을 생성한다.
 * 3. 동일한 parent channel 아래에서 같은 code로 두 번째 section 생성 시도를 한다.
 * 4. 두 번째 시도는 반드시 unique constraint 오류로 인해 실패해야 한다.
 *
 * 성공 및 오류 시나리오를 모두 점검하여 API가 고유성 정책을 엄격히 준수하는지 확인합니다.
 */
export async function test_api_discussionBoard_test_create_section_with_duplicate_code_in_same_channel(
  connection: api.IConnection,
) {
  // 1. 채널 생성
  const channelInput: IDiscussionBoardChannel.ICreate = {
    code: RandomGenerator.alphaNumeric(8),
    name: RandomGenerator.paragraph()(2),
    description: RandomGenerator.paragraph()(3),
  };
  const channel = await api.functional.discussionBoard.systematic.channels.post(connection, {
    body: channelInput,
  });
  typia.assert(channel);

  // 2. 첫 번째 section 생성 (유니크 code 사용)
  const sectionCode = RandomGenerator.alphabets(7);
  const sectionInput: IDiscussionBoardSection.ICreate = {
    discussion_board_channel_id: channel.id,
    code: sectionCode,
    name: RandomGenerator.paragraph()(2),
    description: RandomGenerator.paragraph()(3),
  };
  const section = await api.functional.discussionBoard.systematic.sections.post(connection, {
    body: sectionInput,
  });
  typia.assert(section);

  // 3. 같은 채널/같은 code로 중복 section 등록 시도
  // 4. 에러 검증 (unique constraint violation)
  await TestValidator.error("duplicate section code should fail")(
    async () => {
      await api.functional.discussionBoard.systematic.sections.post(connection, {
        body: {
          discussion_board_channel_id: channel.id,
          code: sectionCode,
          name: RandomGenerator.paragraph()(2),
          description: RandomGenerator.paragraph()(2),
        },
      });
    },
  );
}

