/**
 * Validate retrieving a discussion board vote by ID after successful creation.
 *
 * This test simulates the workflow of a user voting on a thread and then reading that vote by its unique ID, verifying all properties and associations are as expected.
 *
 * 1. Register a new discussion board member as the voter.
 * 2. Create a new vote type (e.g., 'upvote').
 * 3. Generate a new discussion thread (to be the vote target).
 * 4. Cast a new vote by the voter on the thread using the vote type.
 * 5. Retrieve the vote using its unique ID and validate all returned data matches creation, including foreign key relationships (voter_id, vote_type_id, thread_id).
 */
export async function test_api_discussionBoard_test_get_vote_by_id_success(
  connection: api.IConnection,
) {
  // 1. Register a member (voter)
  const memberBody: IdiscussionBoardMembers.ICreate = {
    username: RandomGenerator.alphabets(12),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(32),
    display_name: RandomGenerator.name(),
    profile_image_url: null,
    is_active: true,
  };
  const member = await api.functional.discussionBoard.actors.members.post(connection, {
    body: memberBody,
  });
  typia.assert(member);

  // 2. Create a vote type
  const voteTypeBody: discussion_board_vote_types.ICreate = {
    code: RandomGenerator.alphabets(8),
    name: RandomGenerator.alphabets(10),
    description: "A test vote type.",
  };
  const voteType = await api.functional.discussionBoard.votes.voteTypes.post(connection, { body: voteTypeBody });
  typia.assert(voteType);

  // 3. Create a thread to vote on
  const threadBody: IDiscussionBoardThread.ICreate = {
    discussion_board_category_id: typia.random<string & tags.Format<"uuid">>(),
    title: RandomGenerator.paragraph()(),
    body: RandomGenerator.content()()(),
    is_pinned: false,
    is_closed: false,
  };
