  typia.assert(thread);

  // 4. Cast a vote on the thread
  const voteBody: discussion_board_votes.ICreate = {
    voter_id: member.id,
    vote_type_id: voteType.id,
    thread_id: thread.id,
    post_id: null,
    comment_id: null,
  };
  const vote = await api.functional.discussionBoard.votes.votes.post(connection, { body: voteBody });
  typia.assert(vote);

  // 5. Retrieve the vote by ID and validate all properties
  const fetched = await api.functional.discussionBoard.votes.votes.getById(connection, { id: vote.id });
  typia.assert(fetched);
  TestValidator.equals("vote id")(fetched.id)(vote.id);
  TestValidator.equals("voter id")(fetched.voter_id)(member.id);
  TestValidator.equals("vote type id")(fetched.vote_type_id)(voteType.id);
  TestValidator.equals("thread id")(fetched.thread_id)(thread.id);
  TestValidator.equals("post id")(fetched.post_id)(null);
  TestValidator.equals("comment id")(fetched.comment_id)(null);
}

