import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IDiscussionBoardThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardThread";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";

/**
 * 검증: 게시글(포스트)이 소프트 삭제된 경우에는 본문 수정(업데이트) 시도가 실패해야 함을 테스트한다.
 * 
 * 비즈니스 목적: 게시판 시스템에서는 게시글이 소프트 삭제(되살릴 수 있는 삭제)된 경우, 추가 편집 행위를 금지하여 감사와 규정 준수를 보장해야 한다. 이 e2e 테스트는 해당 정책의 엄격성을 검증한다.
 *
 * [시나리오]
 * 1. 새로운 멤버 계정을 등록한다.
 * 2. 생성된 멤버로 새로운 스레드를 발행한다 (임의 카테고리-타이틀-본문, is_pinned: false, is_closed: false)
 * 3. 해당 스레드에 멤버가 새 게시글(post)을 작성한다
 * 4. 작성된 게시글에 대해 soft-delete(삭제) 연산을 실행한다
 * 5. soft-delete된 게시글에 대해 본문(body) update(편집) 연산을 시도한다
 * 6. 업데이트 연산은 실패(에러 반환)해야 하며, TestValidator.error로 오류 발생을 검증한다
 *
 * [핵심 검증 포인트]
 * - 소프트 삭제된 게시글(post)은 편집 시도가 차단/거부되어야 한다
 * - API의 에러 반환 경로가 정상적으로 동작하는지를 확인한다
 */
export async function test_api_discussionBoard_test_update_post_body_fails_for_soft_deleted_post(connection: api.IConnection) {
  // 1. 새로운 멤버 등록
  const member = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<'email'>>(),
      hashed_password: RandomGenerator.alphabets(16),
      display_name: RandomGenerator.name(),
      is_active: true,
      profile_image_url: null,
    }
  });
  typia.assert(member);

  // 2. 새로운 스레드 생성 (카테고리 UUID 임의 생성)
  const thread = await api.functional.discussionBoard.articles.threads.post(connection, {
    body: {
      discussion_board_category_id: typia.random<string & tags.Format<'uuid'>>(),
      title: RandomGenerator.paragraph()(0),
      body: RandomGenerator.content()(0)(0),
      is_pinned: false,
      is_closed: false
    }
  });
  typia.assert(thread);

  // 3. 포스트 생성 (thread와 member UUID 활용)
  const post = await api.functional.discussionBoard.articles.posts.post(connection, {
    body: {
      discussion_board_thread_id: thread.id,
      discussion_board_member_id: member.id,
      body: RandomGenerator.content()(0)(0)
    }
  });
  typia.assert(post);

  // 4. 해당 포스트 소프트 삭제
  const deleteResult = await api.functional.discussionBoard.articles.posts.eraseById(connection, {
    id: post.id
  });
  typia.assert(deleteResult);
  TestValidator.equals('soft-delete 성공')(deleteResult.success)(true);
  TestValidator.equals('포스트 deleted_at이 null이 아님')(deleteResult.post.deleted_at !== null)(true);

  // 5. 소프트 삭제된 포스트에 대해 body 업데이트 시도 & 실패 검증
  await TestValidator.error('소프트 삭제된 포스트는 update 불가')(
    async () => {
      await api.functional.discussionBoard.articles.posts.putById(connection, {
        id: post.id,
        body: { body: RandomGenerator.content()(0)(0) }
      });
    }
  );
}

