import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IModerationBan } from "@ORGANIZATION/PROJECT-api/lib/structures/IModerationBan";

/**
 * Test that updating a ban record after it has been soft deleted is forbidden.
 *
 * This test ensures the system enforces rules preventing updates to ban entries that are no longer active (soft deleted).
 * 
 * Step-by-step procedure:
 * 1. Create a normal member account (target for ban)
 * 2. Create a moderator account (the actor who will perform the ban)
 * 3. Moderator creates a ban on the member
 * 4. Moderator soft deletes the ban (using DELETE, which sets deleted_at)
 * 5. Attempt to update the ban via PUT (should be rejected)
 * 6. Confirm rejection (error code 404 or forbidden)
 */
export async function test_api_discussionBoard_moderation_bans_test_update_ban_after_soft_deletion(connection: api.IConnection) {
  // 1. Create target member
  const memberSignup = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      display_name: RandomGenerator.alphabets(8),
      is_active: true,
      profile_image_url: null
    } satisfies IdiscussionBoardMembers.ICreate
  });
  typia.assert(memberSignup);

  // 2. Create moderator account
  const moderatorSignup = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      display_name: RandomGenerator.alphabets(8),
      is_active: true,
      profile_image_url: null
    } satisfies IdiscussionBoardMembers.ICreate
  });
  typia.assert(moderatorSignup);

  // 3. Create ban
  const createBan = await api.functional.discussionBoard.moderation.bans.post(connection, {
    body: {
      member_id: memberSignup.id,
      moderator_id: moderatorSignup.id,
      ban_reason: "Violation of board rules",
      permanent: false,
      expires_at: new Date(Date.now() + 7 * 86400 * 1000).toISOString()
    } satisfies IModerationBan.ICreate
  });
  typia.assert(createBan);

  // 4. Soft delete the ban
  await api.functional.discussionBoard.moderation.bans.eraseById(connection, {
    id: createBan.id
  });

  // 5 & 6. Attempt to update soft-deleted ban (should fail)
  await TestValidator.error("Updating a soft-deleted ban must be forbidden")(
    () => api.functional.discussionBoard.moderation.bans.putById(connection, {
      id: createBan.id,
      body: {
        ban_reason: "Ban reason updated",
        permanent: true,
        expires_at: null
      } satisfies IModerationBan.IUpdate
    })
  );
}

