 *
 * Steps:
 * 1. Create a member.
 * 2. Create a vote type (e.g., upvote).
 * 3. Create a thread.
 * 4. Cast the first vote by the member with the vote type for the thread (success expected).
 * 5. Attempt to cast a second vote with the same member/vote_type/thread combination (should fail with a unique constraint error).
 */
export async function test_api_discussionBoard_test_create_vote_duplicate_vote_type_on_same_target(connection: api.IConnection) {
  // 1. Create a discussion board member
  const member = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(32),
      display_name: RandomGenerator.name(),
      profile_image_url: null,
      is_active: true,
    } satisfies IdiscussionBoardMembers.ICreate,
  });
  typia.assert(member);

  // 2. Create a vote type
  const voteType = await api.functional.discussionBoard.votes.voteTypes.post(connection, {
    body: {
      code: RandomGenerator.alphaNumeric(8),
      name: "Upvote",
      description: "An upvote type for testing purposes.",
    } satisfies discussion_board_vote_types.ICreate,
  });
  typia.assert(voteType);

  // 3. Create a thread (category ID can be random as it's not in test scope)
  const thread = await api.functional.discussionBoard.articles.threads.post(connection, {
    body: {
      discussion_board_category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(1),
      body: RandomGenerator.content()()(),
      is_pinned: false,
      is_closed: false,
    } satisfies IDiscussionBoardThread.ICreate,
  });
  typia.assert(thread);

  // 4. Cast the first vote (successfully)
  const firstVote = await api.functional.discussionBoard.votes.votes.post(connection, {
    body: {
      voter_id: member.id,
      vote_type_id: voteType.id,
      thread_id: thread.id,
      post_id: null,
      comment_id: null,
    } satisfies discussion_board_votes.ICreate,
  });
  typia.assert(firstVote);

  // 5. Attempt to cast a duplicate vote (should fail)
  await TestValidator.error("Duplicate vote should not be allowed")(() =>
    api.functional.discussionBoard.votes.votes.post(connection, {
      body: {
        voter_id: member.id,
        vote_type_id: voteType.id,
        thread_id: thread.id,
        post_id: null,
        comment_id: null,
      } satisfies discussion_board_votes.ICreate,
    })
  );
