 * 4. 각 시도에서 정상적으로 에러가 반환되는지, 허용 필드/유효성 관련 가이드가 나오는지 확인
 */
export async function test_api_discussionBoard_actors_moderators_test_update_moderator_assignment_with_invalid_fields(
  connection: api.IConnection,
) {
