  const assignedAt = new Date(baseDate.getTime());
  const revokedAtInPast = new Date(baseDate.getFullYear() - 10, baseDate.getMonth(), baseDate.getDate()).toISOString();
  const revokedAtInFuture = new Date(baseDate.getFullYear() + 10, baseDate.getMonth(), baseDate.getDate()).toISOString();
