import type { IPageIDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardCategory";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 테스트 목적: 카테고리의 description(설명) 필드에 대한 부분 일치 검색 기능을 검증합니다.
 *
 * 시나리오:
 * 1. 유니크한 description을 갖는 여러 개의 카테고리를 생성합니다.
 * 2. 그 중 일부에서 공통적으로 포함된 키워드(예: "통계")를 description의 일부로 사용하여 카테고리들을 만듭니다.
 * 3. PATCH /discussionBoard/categories/categories 엔드포인트를 호출할 때 description 필드에 해당 키워드를 입력하여, 부분 일치 검색을 수행합니다.
 * 4. 반환된 카테고리들 중 description에 해당 키워드를 포함한 카테고리만 있는지 검증합니다.
 * 5. 검색한 키워드를 포함하지 않는 카테고리들은 결과에 포함되지 않아야 함을 추가적으로 검증합니다.
 */
export async function test_api_discussionBoard_test_search_categories_by_description(
  connection: api.IConnection,
) {
  // 1. 테스트에 사용할 고유한 description 문자열 생성
  const keyword = "통계";
  const uniqueDescriptions = [
    `${keyword}에 관한 토론 카테고리`,
    `심층 ${keyword} 분석`,
    "생물학 카테고리",
    "정치 카테고리"
  ];

  // 2. 카테고리 생성
  const createdCategories: IDiscussionBoardCategory[] = [];
  for (const [idx, desc] of uniqueDescriptions.entries()) {
    const category = await api.functional.discussionBoard.categories.categories.post(
      connection,
      {
        body: {
          name: `테스트카테고리_${idx}_${Date.now()}`,
          description: desc,
        } satisfies IDiscussionBoardCategory.ICreate,
      },
    );
    typia.assert(category);
    createdCategories.push(category);
  }

  // 3. description 키워드로 부분 검색
  const searchResult = await api.functional.discussionBoard.categories.categories.patch(
    connection,
    {
      body: {
        description: keyword
      } satisfies IDiscussionBoardCategory.IRequest,
    }
  );
  typia.assert(searchResult);

  // 4. 검색 결과에는 keyword가 포함된 카테고리만 존재해야 함을 검증
  const filtered = createdCategories.filter(c => c.description && c.description.includes(keyword));
  for (const cat of searchResult.data) {
    TestValidator.predicate("description에 키워드가 포함되어야 함")(!!cat.description && cat.description.includes(keyword));
  }
  // 5. 검색 결과에 포함되어야 하는 카테고리들은 모두 결과에 포함되어야 한다
  for (const cat of filtered) {
    TestValidator.predicate(`생성된 카테고리(${cat.id})가 검색 결과에 존재해야 함`)(
      searchResult.data.some(r => r.id === cat.id),
    );
  }
  // 6. 키워드가 없는 카테고리들은 검색 결과에 포함되지 않아야 한다
  const others = createdCategories.filter(c => !c.description || !c.description.includes(keyword));
  for (const cat of others) {
    TestValidator.predicate(`keyword 없는 카테고리(${cat.id})가 검색 결과에 없어야 함`)(
      searchResult.data.every(r => r.id !== cat.id),
    );
  }
}

