 * 3. Create a new thread under the category, open (is_closed: false).
 * 4. Update the thread, setting is_closed: true.
 * 5. Attempt to create a post in this closed thread. Assert that an error is thrown, confirming the thread's closed status is enforced at post creation.
 *
 * This validates moderation/locking features and error handling for closed-thread posting attempts.
 */
export async function test_api_discussionBoard_test_create_post_in_closed_thread_returns_error(connection: api.IConnection) {
  // 1. Register a new discussion board member
  const member = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      display_name: RandomGenerator.name(),
      is_active: true,
      profile_image_url: null,
    } satisfies IdiscussionBoardMembers.ICreate,
  });
  typia.assert(member);

  // 2. Create a category for threads
  const category = await api.functional.discussionBoard.categories.categories.post(connection, {
    body: {
      name: RandomGenerator.alphaNumeric(6),
      description: RandomGenerator.paragraph()(),
    } satisfies IDiscussionBoardCategory.ICreate,
  });
  typia.assert(category);

  // 3. Create a thread in that category, open
  const thread = await api.functional.discussionBoard.articles.threads.post(connection, {
    body: {
      discussion_board_category_id: category.id,
      title: RandomGenerator.paragraph()(),
      body: RandomGenerator.content()()(),
      is_pinned: false,
      is_closed: false,
    } satisfies IDiscussionBoardThread.ICreate,
  });
  typia.assert(thread);

  // 4. Close the thread
  const closedThread = await api.functional.discussionBoard.articles.threads.putById(connection, {
    id: thread.id,
    body: {
      is_closed: true,
    } satisfies IDiscussionBoardThread.IUpdate,
  });
  typia.assert(closedThread);
  TestValidator.equals("thread is now closed")(closedThread.is_closed)(true);

  // 5. Attempt to post to the closed thread (should error)
  await TestValidator.error("post creation in closed thread should fail")(async () => {
    await api.functional.discussionBoard.articles.posts.post(connection, {
      body: {
        discussion_board_thread_id: thread.id,
        discussion_board_member_id: member.id,
        body: RandomGenerator.content()()(),
      } satisfies IDiscussionBoardPost.ICreate,
    });
  });
}

