import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IDiscussionBoardThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardThread";
import type { IDiscussionBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReport";

/**
 * Validate fetching a moderation report after it has been soft deleted.
 *
 * This test checks whether a soft-deleted moderation report is accessible to privileged roles (moderator/admin) or properly throws an error if access is denied.
 *
 * Step-by-step process:
 * 1. Create a new discussion board member (as the reporter).
 * 2. Create a thread on the discussion board (to serve as reportable content).
 * 3. Submit a new moderation report against the thread, using the created member as reporter.
 * 4. Soft-delete the report using the provided endpoint.
 * 5. Attempt to fetch the deleted report by its ID using the getById API.
 * 6. Validate one of the following:
 *    a. If the report is returned, ensure the 'deleted_at' field is present and correctly populated.
 *    b. If access is denied (business policy), assert that the proper API error is thrown.
 *
 * Assumptions:
 * - The test does not perform moderator/admin authentication switching, as no such API is described in definitions.
 * - The fetch-after-delete operation is attempted with the same connection that created and deleted the report (default context).
 * - Both success (returns deleted report with 'deleted_at') and error (API throws appropriately) outcomes are considered valid depending on platform policy.
 */
export async function test_api_discussionBoard_moderation_reports_test_get_moderation_report_after_soft_deletion(connection: api.IConnection) {
  // 1. Create reporter member
  const reporter: IdiscussionBoardMembers = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      display_name: RandomGenerator.name(),
      is_active: true
    } satisfies IdiscussionBoardMembers.ICreate
  });
  typia.assert(reporter);

  // 2. Create a thread for reporting
  const thread: IDiscussionBoardThread = await api.functional.discussionBoard.articles.threads.post(connection, {
    body: {
      discussion_board_category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(10),
      body: RandomGenerator.content()(5)(2),
      is_pinned: false,
      is_closed: false
    } satisfies IDiscussionBoardThread.ICreate
  });
  typia.assert(thread);

  // 3. Create a moderation report
  const report: IDiscussionBoardReport = await api.functional.discussionBoard.moderation.reports.post(connection, {
    body: {
      reporter_member_id: reporter.id,
      thread_id: thread.id,
      reason: "Test soft delete report fetch",
      status: "pending"
    } satisfies IDiscussionBoardReport.ICreate
  });
  typia.assert(report);

  // 4. Soft delete the report
  const erased: IDiscussionBoardReport = await api.functional.discussionBoard.moderation.reports.eraseById(connection, { id: report.id });
  typia.assert(erased);
  TestValidator.predicate("deleted_at is set")(typeof erased.deleted_at === "string" && erased.deleted_at.length > 0);

  // 5. Attempt to fetch the (soft deleted) report
  let fetchError = null;
  let fetched: IDiscussionBoardReport | null = null;
  try {
    fetched = await api.functional.discussionBoard.moderation.reports.getById(connection, { id: report.id });
    typia.assert(fetched);
    // 6.a. Success: Check deleted_at is set
    TestValidator.predicate("deleted_at is set in fetched report")(typeof fetched.deleted_at === "string" && fetched.deleted_at.length > 0);
  } catch (exp) {
    fetchError = exp;
    // 6.b. Error: Should be an API error (e.g., 404 or forbidden)
    TestValidator.error("Fetching deleted report throws error")(() => { throw exp; });
  }
}

