 *
 * 비즈니스 시나리오:
 * 1. 토론 게시판의 channel 엔터티를 먼저 생성합니다(부모 row).
 * 2. 해당 channel에 연결된 section을 생성합니다.
 * 3. 위에서 만든 section의 id로 상세 정보를 조회합니다.
 * 4. 반환된 section의 모든 필드(부모 채널 UUID 포함, 스키마 정의 필드들)가 정확히 일치함을 검증합니다 (id, discussion_board_channel_id, code, name, description, created_at, updated_at, deleted_at).
 * 5. 응답에 스키마에 없는 불필요한 필드가 포함되어 있지 않음을 확인합니다.
 *
 * 검증 절차:
 * - channel과 section을 각각 생성할 때 입력값을 정확히 기록한 후,
 *   getById로 조회한 결과와 생성 결과 및 기대값을 field별 비교합니다.
 * - 반환된 객체가 입력했던 값 및 section 생성 시 반환값과 모두 정확히 일치해야 하며,
 *   nullable 필드(예: description, deleted_at)는 null 또는 입력값과 일치함을 assert합니다.
 * - 불필요한 프로퍼티(extraneous data)가 응답에 없어야 하고, 오직 schema 필드만 존재함을 확인합니다.
 */
export async function test_api_discussionBoard_systematic_sections_test_get_section_detail_by_id_success(
  connection: api.IConnection,
) {
  // 1. 채널 생성
  const channelInput: IDiscussionBoardChannel.ICreate = {
    code: RandomGenerator.alphaNumeric(8),
    name: RandomGenerator.alphaNumeric(12),
    description: RandomGenerator.alphaNumeric(20),
  };
  const channel = await api.functional.discussionBoard.systematic.channels.post(connection, { body: channelInput });
  typia.assert(channel);

  // 2. section 생성 (채널에 연결)
  const sectionInput: IDiscussionBoardSection.ICreate = {
    discussion_board_channel_id: channel.id,
    code: RandomGenerator.alphaNumeric(8),
    name: RandomGenerator.alphaNumeric(14),
    description: RandomGenerator.alphaNumeric(20),
  };
  const section = await api.functional.discussionBoard.systematic.sections.post(connection, { body: sectionInput });
  typia.assert(section);

  // 3. 생성된 section의 id로 상세조회
  const detail = await api.functional.discussionBoard.systematic.sections.getById(connection, { id: section.id });
  typia.assert(detail);

  // 4. 반환된 section이 기대값들과 정확히 일치하는지 검증 (스키마 필드별 비교)
