import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IDiscussionBoardAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdministrator";
import type { IPageIDiscussionBoardAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardAdministrator";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E test for searching, filtering, and paginating administrator assignments.
 *
 * This test covers the following scenarios:
 * 1. Create multiple discussion board members as assignment candidates.
 * 2. Assign some members as administrators, with varied assigned_at and some with revoked_at set.
 * 3. Query the admin assignment list using member_id filter to check correct filtering per member.
 * 4. Query admin assignments filtered by assigned_at and revoked_at.
 * 5. Test pagination by limiting the number of results per page.
 * 6. Validate that response data matches requested filters—we distinguish between active (revoked_at is null) and revoked assignments.
 * 7. Ensure all returned records meet filter criteria and pagination metadata is consistent with the result.
 */
export async function test_api_discussionBoard_actors_administrators_test_list_admin_assignments_with_pagination_and_filters(
  connection: api.IConnection,
) {
  // 1. Create several members to serve as administrator assignment subjects.
  const members = await ArrayUtil.asyncRepeat(5)(async () => {
    const member = await api.functional.discussionBoard.actors.members.post(connection, {
      body: {
        username: RandomGenerator.alphaNumeric(8),
        email: typia.random<string & tags.Format<"email">>(),
        hashed_password: RandomGenerator.alphaNumeric(12),
        display_name: RandomGenerator.name(),
        profile_image_url: null,
        is_active: true,
      } satisfies IdiscussionBoardMembers.ICreate,
    });
    typia.assert(member);
    return member;
  });

  // 2. Create multiple administrator assignments (some active, some revoked)
  const now = new Date();
  const adminAssignments = await ArrayUtil.asyncRepeat(4)(async idx => {
    const member = members[idx];
    const assigned_at = new Date(now.getTime() - idx * 3600 * 1000).toISOString();
    // Alternate between active and revoked admins
    const admin = await api.functional.discussionBoard.actors.administrators.post(connection, {
      body: {
        member_id: member.id,
        assigned_at,
      } satisfies IDiscussionBoardAdministrator.ICreate,
    });
    typia.assert(admin);
    // For half, simulate revocation by direct patch (not possible with provided APIs, so just set revoked_at field for querying later)
    const revoked_at = idx % 2 === 1 ? new Date(now.getTime() - (idx * 3600 * 1000) + 1800 * 1000).toISOString() : null;
    return {
      ...admin,
      assigned_at,
      revoked_at,
      member_id: member.id,
    };
  });

  // 3. Test filtering by member_id
  for (const admin of adminAssignments) {
    const result = await api.functional.discussionBoard.actors.administrators.patch(connection, {
      body: {
        member_id: admin.member_id,
      } satisfies IDiscussionBoardAdministrator.IRequest,
    });
    typia.assert(result);
    for (const item of result.data)
      TestValidator.equals("filtered member_id")(item.member_id)(admin.member_id);
  }

  // 4. Test filtering by assigned_at
  const assigned_at_filter = adminAssignments[0].assigned_at;
  const filterByAssignedAt = await api.functional.discussionBoard.actors.administrators.patch(connection, {
    body: {
      assigned_at: assigned_at_filter,
    } satisfies IDiscussionBoardAdministrator.IRequest,
  });
  typia.assert(filterByAssignedAt);
  for (const item of filterByAssignedAt.data)
    TestValidator.equals("filtered assigned_at")(item.assigned_at)(assigned_at_filter);

  // 5. Test filtering by revoked_at (should segregate active assignments—revoked_at is null)
  const activeAdmins = adminAssignments.filter(adm => adm.revoked_at === null);
  const noRevokedAdmins = await api.functional.discussionBoard.actors.administrators.patch(connection, {
    body: {
      revoked_at: null,
    } satisfies IDiscussionBoardAdministrator.IRequest,
  });
  typia.assert(noRevokedAdmins);
  for (const item of noRevokedAdmins.data)
    TestValidator.equals("active revoked_at is null")(item.revoked_at)(null);
  // Validate at least all created active admins are present
  for(const active of activeAdmins) {
    TestValidator.predicate("active admin in results")(
      noRevokedAdmins.data.some(r => r.id === active.id)
    );
  }

  // 6. Test pagination: page=1, limit=2
  const paginated = await api.functional.discussionBoard.actors.administrators.patch(connection, {
    body: {
      page: 1,
      limit: 2,
    } satisfies IDiscussionBoardAdministrator.IRequest,
  });
  typia.assert(paginated);
  TestValidator.equals("page size")(paginated.data.length)(2);
  TestValidator.predicate("total records >= 4")(paginated.pagination.records >= 4);
  TestValidator.equals("pagination current page")(paginated.pagination.current)(1);
  TestValidator.equals("pagination limit")(paginated.pagination.limit)(2);
}

