  TestValidator.equals("thread_id should match")(fetchedVote.thread_id)(thread.id);
  TestValidator.equals("post_id must be null")(fetchedVote.post_id)(null);
  TestValidator.equals("comment_id must be null")(fetchedVote.comment_id)(null);
