import type { IDiscussionBoardMention } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMention";
import type { IPageIDiscussionBoardMention } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardMention";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test mention listing filtered by actor_member_id and mentioned_member_id combinations.
 *
 * This test creates three members, generates cross-mentions with different actor/mentioned pairs,
 * then validates that filtering by actor_member_id, mentioned_member_id, and both together returns only the intended mentions.
 *
 * 1. Create Member A (actor/recipient), Member B, and Member C.
 * 2. Create mentions where:
 *    - A mentions B in type 'thread', content_id X
 *    - A mentions C in type 'post', content_id Y
 *    - B mentions A in type 'comment', content_id Z
 *    - C mentions B in type 'thread', content_id W
 *    - C mentions C in type 'post', content_id V (self-mention)
 * 3. For each member:
 *    - Filter mentions by actor_member_id only: validate matches only those where that member is the actor
 *    - Filter mentions by mentioned_member_id only: validate results only where that member is mentioned
 *    - Filter by both: ensure matches are only those where both roles match together
 */
export async function test_api_discussionBoard_notifications_mentions_test_list_mentions_actor_and_target_filters(
  connection: api.IConnection,
) {
  // 1. Create 3 members: A, B, C
  const passwordHash = RandomGenerator.alphaNumeric(32);
  const members = await ArrayUtil.asyncRepeat(3)(async (i) =>
    api.functional.discussionBoard.actors.members.post(connection, {
      body: {
        username: RandomGenerator.alphaNumeric(8),
        email: typia.random<string & tags.Format<"email">>(),
        hashed_password: passwordHash,
        display_name: RandomGenerator.name(),
        profile_image_url: null,
        is_active: true,
      },
    }),
  );
  members.forEach(typia.assert);
  const [A, B, C] = members;

  // 2. Create diverse mentions
  const [mention1, mention2, mention3, mention4, mention5] = await Promise.all([
    // A mentions B (thread)
    api.functional.discussionBoard.notifications.mentions.post(connection, {
      body: {
        mentioned_member_id: B.id,
        actor_member_id: A.id,
        content_type: 'thread',
        content_id: typia.random<string & tags.Format<"uuid">>(),
        created_at: new Date().toISOString(),
      },
    }),
    // A mentions C (post)
    api.functional.discussionBoard.notifications.mentions.post(connection, {
      body: {
        mentioned_member_id: C.id,
        actor_member_id: A.id,
        content_type: 'post',
        content_id: typia.random<string & tags.Format<"uuid">>(),
        created_at: new Date().toISOString(),
      },
    }),
    // B mentions A (comment)
    api.functional.discussionBoard.notifications.mentions.post(connection, {
      body: {
        mentioned_member_id: A.id,
        actor_member_id: B.id,
