import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IDiscussionBoardMention } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMention";
import type { IPageIDiscussionBoardMention } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardMention";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * actor_member_id와 mentioned_member_id 조합 필터의 언급(@mention) 목록 검증
 *
 * 이 테스트는 세 명의 멤버(A, B, C)를 생성하고,
 * 이들 사이에서 다양한 조합(서로 혹은 자기 자신을 언급)으로 mention을 생성한 뒤,
 * actor_member_id, mentioned_member_id, 둘 다로 필터 시 의도한 mention만 반환되는지 검증합니다.
 *
 * 1. 멤버 A, 멤버 B, 멤버 C를 생성합니다.
 * 2. 다음과 같이 CROSS-mention 데이터 5개를 만듭니다:
 *    - A가 B를 thread에서 언급
 *    - A가 C를 post에서 언급
 *    - B가 A를 comment에서 언급
 *    - C가 B를 thread에서 언급
 *    - C가 C를 post에서 언급(셀프 언급)
 * 3. 각 멤버에 대해:
 *    - actor_member_id로만 필터: 해당 멤버가 actor인 mention만 반환되는지 검증
 *    - mentioned_member_id로만 필터: 해당 멤버가 언급받은 mention만 반환되는지 검증
 *    - 둘 다로 필터: 자기 자신을 언급한 mention만 반환되는지 검증
 */
export async function test_api_discussionBoard_notifications_mentions_test_list_mentions_actor_and_target_filters(
  connection: api.IConnection,
) {
  // 1. 멤버 3명 생성(A, B, C)
  const passwordHash = RandomGenerator.alphaNumeric(32);
  const members = await ArrayUtil.asyncRepeat(3)(async () =>
    api.functional.discussionBoard.actors.members.post(connection, {
      body: {
        username: RandomGenerator.alphaNumeric(8),
        email: typia.random<string & tags.Format<"email">>(),
        hashed_password: passwordHash,
        display_name: RandomGenerator.name(),
        profile_image_url: null,
        is_active: true,
      },
    }),
  );
  members.forEach(typia.assert);
  const [A, B, C] = members;

  // 2. 언급(CROSS-mention) 데이터 생성
  const [mention1, mention2, mention3, mention4, mention5] = await Promise.all([
    // A -> B (thread)
    api.functional.discussionBoard.notifications.mentions.post(connection, {
      body: {
        mentioned_member_id: B.id,
        actor_member_id: A.id,
        content_type: 'thread',
        content_id: typia.random<string & tags.Format<"uuid">>(),
        created_at: new Date().toISOString(),
      },
    }),
    // A -> C (post)
    api.functional.discussionBoard.notifications.mentions.post(connection, {
      body: {
        mentioned_member_id: C.id,
        actor_member_id: A.id,
        content_type: 'post',
        content_id: typia.random<string & tags.Format<"uuid">>(),
        created_at: new Date().toISOString(),
      },
    }),
    // B -> A (comment)
    api.functional.discussionBoard.notifications.mentions.post(connection, {
      body: {
        mentioned_member_id: A.id,
        actor_member_id: B.id,
        content_type: 'comment',
        content_id: typia.random<string & tags.Format<"uuid">>(),
        created_at: new Date().toISOString(),
      },
    }),
    // C -> B (thread)
    api.functional.discussionBoard.notifications.mentions.post(connection, {
      body: {
        mentioned_member_id: B.id,
        actor_member_id: C.id,
        content_type: 'thread',
        content_id: typia.random<string & tags.Format<"uuid">>(),
        created_at: new Date().toISOString(),
      },
    }),
    // C -> C (post)
    api.functional.discussionBoard.notifications.mentions.post(connection, {
      body: {
        mentioned_member_id: C.id,
        actor_member_id: C.id,
        content_type: 'post',
        content_id: typia.random<string & tags.Format<"uuid">>(),
        created_at: new Date().toISOString(),
      },
    }),
  ]);
  [mention1, mention2, mention3, mention4, mention5].forEach(typia.assert);

  // 3. 필터 조합별 결과 검증
  for (const member of members) {
    // actor_member_id 필터만
    const filteredByActor = await api.functional.discussionBoard.notifications.mentions.patch(connection, {
      body: { actor_member_id: member.id },
    });
    typia.assert(filteredByActor);
    TestValidator.predicate(`actor_member_id 필터: ${member.username}이 actor인 mention만 리턴`)(
      filteredByActor.data.every(m => m.actor_member_id === member.id)
    );

    // mentioned_member_id 필터만
    const filteredByMentioned = await api.functional.discussionBoard.notifications.mentions.patch(connection, {
      body: { mentioned_member_id: member.id },
    });
    typia.assert(filteredByMentioned);
    TestValidator.predicate(`mentioned_member_id 필터: ${member.username}이 언급된 mention만 리턴`)(
      filteredByMentioned.data.every(m => m.mentioned_member_id === member.id)
    );

    // 둘 다 필터(자기 자신을 언급한 경우만)
    const filteredByBoth = await api.functional.discussionBoard.notifications.mentions.patch(connection, {
      body: { actor_member_id: member.id, mentioned_member_id: member.id },
    });
    typia.assert(filteredByBoth);
    TestValidator.predicate(`actor+mentioned 필터: ${member.username}이 자기 자신만 언급한 mention만 리턴`)(
      filteredByBoth.data.every(m => m.actor_member_id === member.id && m.mentioned_member_id === member.id)
    );
  }
}

