import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IDiscussionBoardThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardThread";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";

/**
 * Test thread creation with invalid foreign keys for category and member.
 *
 * This test verifies that the system properly enforces foreign key constraints when attempting to create a discussion thread with non-existent category or member IDs. It ensures that the API returns the appropriate error (such as a 404 not found or foreign key violation error) and does not create the thread entity in either of these error conditions. This is essential for data integrity and business process correctness.
 *
 * Step-by-step process:
 * 1. Create a valid discussion board category and a valid member for control.
 * 2. Attempt to create a thread using a completely random (non-existent) category ID but a valid member ID. Expect error.
 * 3. Attempt to create a thread using a valid category ID but a random (non-existent) member ID. Expect error.
 * 4. Attempt to create a thread using both invalid (random) category and member IDs. Expect error.
 * 5. Optionally, create a thread with both valid category and member IDs to confirm success (control check).
 */
export async function test_api_discussionBoard_test_create_thread_invalid_or_nonexistent_category_or_member(
  connection: api.IConnection,
) {
  // 1. Create valid category
  const category = await api.functional.discussionBoard.categories.categories.post(connection, {
    body: {
      name: RandomGenerator.paragraph()(1),
      description: RandomGenerator.content()()(1),
    },
  });
  typia.assert(category);

  // 2. Create valid member
  const member = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<'email'>>(),
      hashed_password: RandomGenerator.alphaNumeric(32),
      display_name: RandomGenerator.name(),
      is_active: true,
    },
  });
  typia.assert(member);

  const fakeCategoryId = typia.random<string & tags.Format<'uuid'>>();
  const fakeMemberId = typia.random<string & tags.Format<'uuid'>>();

  // 3. Attempt: valid member, fake category -> Expect failure
  await TestValidator.error("should fail for non-existent category")(() =>
    api.functional.discussionBoard.articles.threads.post(connection, {
      body: {
        discussion_board_category_id: fakeCategoryId,
        title: RandomGenerator.paragraph()(1),
        body: RandomGenerator.content()()(1),
        is_pinned: false,
        is_closed: false,
        discussion_board_member_id: member.id,
      },
    })
  );

  // 4. Attempt: valid category, fake member -> Expect failure
  await TestValidator.error("should fail for non-existent member")(() =>
    api.functional.discussionBoard.articles.threads.post(connection, {
      body: {
        discussion_board_category_id: category.id,
        title: RandomGenerator.paragraph()(1),
        body: RandomGenerator.content()()(1),
        is_pinned: false,
        is_closed: false,
        discussion_board_member_id: fakeMemberId,
      },
    })
  );

  // 5. Attempt: both fake category and member -> Expect failure
  await TestValidator.error("should fail for both IDs non-existent")(() =>
    api.functional.discussionBoard.articles.threads.post(connection, {
      body: {
        discussion_board_category_id: fakeCategoryId,
        title: RandomGenerator.paragraph()(1),
        body: RandomGenerator.content()()(1),
        is_pinned: false,
        is_closed: false,
        discussion_board_member_id: fakeMemberId,
      },
    })
  );

  // 6. (Control) Attempt with all valid references, should succeed
  const thread = await api.functional.discussionBoard.articles.threads.post(connection, {
    body: {
      discussion_board_category_id: category.id,
      title: RandomGenerator.paragraph()(1),
      body: RandomGenerator.content()()(1),
      is_pinned: false,
      is_closed: false,
      discussion_board_member_id: member.id,
    },
  });
  typia.assert(thread);
  TestValidator.equals("category id matches")(thread.discussion_board_category_id)(category.id);
  TestValidator.equals("member id matches")(thread.discussion_board_member_id)(member.id);
}

