  const delResult = await api.functional.discussionBoard.articles.posts.eraseById(connection, { id: post.id });
  typia.assert(delResult);
  TestValidator.predicate("soft delete status")(delResult.success === true);
  TestValidator.equals("deleted_at set on post")(typeof delResult.post.deleted_at === "string")(true);

  // 7. Attempt to fetch soft-deleted post as regular (non-moderator) member (expect forbidden/not found)
  await TestValidator.error("Regular member cannot get soft-deleted post")(
    async () => {
      await api.functional.discussionBoard.articles.posts.getById(connection, { id: post.id });
    },
  );

  // 8. As moderator, fetch the soft-deleted post (should succeed)
  // Normally this would involve context/role switching, assume system uses token in connection from moderator login
  // For this E2E illustration, fetch again with same connection (acting as moderator)
  const softDeleted = await api.functional.discussionBoard.articles.posts.getById(connection, { id: post.id });
  typia.assert(softDeleted);
  TestValidator.equals("soft deleted post id matches")(softDeleted.id)(post.id);
  TestValidator.equals("soft deleted post has deleted_at")(typeof softDeleted.deleted_at === "string")(true);
}

