  const category = await api.functional.discussionBoard.categories.categories.post(connection, {
    body: {
      name: RandomGenerator.paragraph()(2),
      description: RandomGenerator.paragraph()(1),
    },
  });
  typia.assert(category);

  // 3. Create thread
  const thread = await api.functional.discussionBoard.articles.threads.post(connection, {
    body: {
      discussion_board_category_id: category.id,
      title: RandomGenerator.alphabets(12),
      body: RandomGenerator.content()()(),
      is_pinned: false,
      is_closed: false,
    },
  });
