/**
 * 개별 모더레이션 로그 단건 조회 (성공/실패) 시나리오 검증
 *
 * 이 테스트는 moderation log 단건 상세 조회 API의
 * 다음 2가지 동작을 검증합니다:
 * 1) 실제 moderation log id로 요청시 모든 필드가 올바르게 반환되는지
 * 2) 존재하지 않는 id로 조회 시 적절한 not found(404) 오류가 발생하는지
 *
 * 테스트 흐름:
 * 1. 토론장 멤버 계정 신규 생성 (랜덤 username/email/hash)
 * 2. 해당 멤버를 모더레이터로 임명 (assigned_at 현재시각)
 * 3. 실제 moderation action 로그의 대상이 될 스레드 생성
 * 4. moderation log 레코드 생성 (moderator/thread/action/reason 등 임의 값 활용)
 * 5. moderation log id로 API 단건 요청 - 모든 필드 매칭 및 typia.assert로 타입 체크
 * 6. 존재하지 않는 랜덤 uuid로 조회 시도 - 404 not found 등 오류 발생 검증
 */
export async function test_api_discussionBoard_test_get_single_moderation_log_success_and_error_cases(
  connection: api.IConnection,
) {
  // 1. 토론장 멤버 계정 생성
  const member = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      display_name: RandomGenerator.name(),
      profile_image_url: null,
      is_active: true
    } satisfies IdiscussionBoardMembers.ICreate
  });
  typia.assert(member);

  // 2. 해당 멤버를 모더레이터로 임명
  const assignedAt = new Date().toISOString();
  const moderator = await api.functional.discussionBoard.actors.moderators.post(connection, {
    body: {
      member_id: member.id,
      assigned_at: assignedAt
    } satisfies IdiscussionBoardModerators.ICreate
  });
  typia.assert(moderator);

  // 3. moderation action의 대상이 될 thread 생성
  const thread = await api.functional.discussionBoard.articles.threads.post(connection, {
    body: {
      discussion_board_category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(32),
      body: RandomGenerator.content()()(64),
      is_pinned: false,
      is_closed: false
    } satisfies IDiscussionBoardThread.ICreate
  });
  typia.assert(thread);

  // 4. moderation log 레코드 생성 (moderator/thread/action/reason 등 지정)
  const actionStr = RandomGenerator.pick([
    "hide", "delete", "warn", "edit"
  ]);
  const actionReason = RandomGenerator.paragraph()(24);
  const moderationLog = await api.functional.discussionBoard.moderation.moderationLogs.post(connection, {
    body: {
      moderator_id: moderator.id,
      thread_id: thread.id,
      post_id: null,
      comment_id: null,
      action: actionStr,
      action_reason: actionReason
    } satisfies IDiscussionBoardModerationLog.ICreate
  });
  typia.assert(moderationLog);

  // 5. moderation log id로 단건 조회 및 필드 값 검증
  const fetchedLog = await api.functional.discussionBoard.moderation.moderationLogs.getById(connection, {
    id: moderationLog.id
  });
  typia.assert(fetchedLog);
  TestValidator.equals("id 일치")(fetchedLog.id)(moderationLog.id);
  TestValidator.equals("moderator_id 일치")(fetchedLog.moderator_id)(moderationLog.moderator_id);
  TestValidator.equals("thread_id 일치")(fetchedLog.thread_id)(moderationLog.thread_id);
  TestValidator.equals("post_id 일치")(fetchedLog.post_id)(moderationLog.post_id);
  TestValidator.equals("comment_id 일치")(fetchedLog.comment_id)(moderationLog.comment_id);
  TestValidator.equals("action 일치")(fetchedLog.action)(moderationLog.action);
  TestValidator.equals("action_reason 일치")(fetchedLog.action_reason)(moderationLog.action_reason);
  // created_at은 입력 불가 필드이므로 값 체크(동일 시각이 아님에 주의)
  TestValidator.predicate("created_at(ISO8601) 존재/문자열")(
    typeof fetchedLog.created_at === "string" && fetchedLog.created_at.length >= 20
  );

  // 6. 존재하지 않는 id로 조회 - 404 not found 등 오류 발생 확인
  await TestValidator.error("존재하지 않는 moderation log id 조회시 404 오류 발생")(
    async () => {
      await api.functional.discussionBoard.moderation.moderationLogs.getById(connection, {
        id: typia.random<string & tags.Format<"uuid">>()
      });
    }
  );
}

