 * 3. Moderator issues a warning for the target member.
 * 4. Retrieve the warning by id as the moderator.
 * 5. Validate that all schema fields are returned and match the created warning.
 */
export async function test_api_discussionBoard_test_get_warning_by_id_success(
  connection: api.IConnection,
) {
  // 1. Create a member to be warned
  const targetMember = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(32),
      display_name: RandomGenerator.name(),
      profile_image_url: null,
      is_active: true,
    } satisfies IdiscussionBoardMembers.ICreate,
  });
  typia.assert(targetMember);

  // 2. Create a member for moderator and escalate
  const moderatorMember = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(32),
      display_name: RandomGenerator.name(),
      profile_image_url: null,
      is_active: true,
    } satisfies IdiscussionBoardMembers.ICreate,
  });
  typia.assert(moderatorMember);
  const moderator = await api.functional.discussionBoard.actors.moderators.post(connection, {
    body: {
      member_id: moderatorMember.id,
      assigned_at: new Date().toISOString(),
    } satisfies IdiscussionBoardModerators.ICreate,
  });
  typia.assert(moderator);

  // 3. Moderator issues a warning
  const now = new Date().toISOString();
  const warningType = "spam";
  const warningMessage = "Posting spam links in forum threads.";
  const warning = await api.functional.discussionBoard.moderation.warnings.post(connection, {
    body: {
      member_id: targetMember.id,
      moderator_id: moderator.id,
      warning_type: warningType,
      message: warningMessage,
      created_at: now,
      expires_at: null,
    } satisfies IModerationWarning.ICreate,
  });
  typia.assert(warning);

  // 4. Fetch the warning by id as moderator
  const fetched = await api.functional.discussionBoard.moderation.warnings.getById(connection, {
    id: warning.id,
  });
  typia.assert(fetched);

  // 5. Validate that all fields are present and correct
  TestValidator.equals("Warning ID matches")(fetched.id)(warning.id);
  TestValidator.equals("Member ID matches")(fetched.member_id)(targetMember.id);
  TestValidator.equals("Moderator ID matches")(fetched.moderator_id)(moderator.id);
  TestValidator.equals("Warning type matches")(fetched.warning_type)(warningType);
  TestValidator.equals("Message matches")(fetched.message)(warningMessage);
  TestValidator.equals("Created at matches")(fetched.created_at)(now);
  TestValidator.equals("Expires at matches")(fetched.expires_at)(null);
  TestValidator.equals("Deleted at is null")(fetched.deleted_at)(null);
}

