import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IDiscussionBoardThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardThread";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { discussion_board_vote_types } from "@ORGANIZATION/PROJECT-api/lib/structures/discussion_board_vote_types";
import type { discussion_board_votes } from "@ORGANIZATION/PROJECT-api/lib/structures/discussion_board_votes";

/**
 * 테스트 목적: 댓글에 대한 투표가 성공적으로 생성되는지 검증합니다.
 *
 * 이 시나리오는 투표 레코드가 올바르게 생성되기 위한 선행 조건(회원, 스레드, 게시물, 댓글, 투표 타입)의 준비부터 실제 댓글 투표 및 생성된 투표 객체의 검증까지 전체 과정을 다룹니다.
 *
 * 1. 토론 게시판 회원을 생성합니다.
 * 2. 투표 타입(예: upvote, downvote 등)을 생성합니다.
 * 3. 회원이 속할 카테고리 UUID를 발급(임의로 생성)하여 스레드를 생성합니다.
 * 4. 해당 스레드와 회원으로 게시물을 생성합니다.
 * 5. 생성된 게시물에 댓글을 추가합니다.
 * 6. 준비된 요소(회원, 투표 타입, 댓글)를 사용해 댓글에 투표(vote)를 실시합니다.
 * 7. 응답 값 및 각 필드의 연관성(투표자, 투표 타입, 댓글 ID)의 일치 여부를 검증합니다.
 */
export async function test_api_discussionBoard_votes_votes_post_test_create_vote_on_comment_success(
  connection: api.IConnection,
) {
  // 1. 회원(투표자) 생성
  const member = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(14),
      display_name: RandomGenerator.name(),
      profile_image_url: null,
      is_active: true,
    },
  });
  typia.assert(member);

  // 2. 투표 타입 생성
  const voteType = await api.functional.discussionBoard.votes.voteTypes.post(connection, {
    body: {
      code: `upvote_${RandomGenerator.alphaNumeric(6)}`,
      name: "Upvote",
      description: "Upvote for comment",
    },
  });
  typia.assert(voteType);

  // 3. 스레드 카테고리 ID 임의 생성 및 스레드 생성
  const threadCategoryId = typia.random<string & tags.Format<"uuid">>();
  const thread = await api.functional.discussionBoard.articles.threads.post(connection, {
    body: {
      discussion_board_category_id: threadCategoryId,
      title: RandomGenerator.paragraph()(),
      body: RandomGenerator.content()()(),
      is_pinned: false,
      is_closed: false,
    },
  });
  typia.assert(thread);

  // 4. 게시물 생성
  const post = await api.functional.discussionBoard.articles.posts.post(connection, {
    body: {
      discussion_board_thread_id: thread.id,
      discussion_board_member_id: member.id,
      body: RandomGenerator.content()()(),
    },
  });
  typia.assert(post);

  // 5. 댓글 생성
  const comment = await api.functional.discussionBoard.articles.comments.post(connection, {
    body: {
      discussion_board_post_id: post.id,
      discussion_board_member_id: member.id,
      body: RandomGenerator.content()()(),
    },
  });
  typia.assert(comment);

  // 6. 댓글에 투표(vote) 생성
  const vote = await api.functional.discussionBoard.votes.votes.post(connection, {
    body: {
      voter_id: member.id,
      vote_type_id: voteType.id,
      thread_id: null,
      post_id: null,
      comment_id: comment.id,
    },
  });
  typia.assert(vote);

  // 7. 연관성 및 응답 검증
  TestValidator.equals("투표자 일치")(vote.voter_id)(member.id);
  TestValidator.equals("투표 타입 일치")(vote.vote_type_id)(voteType.id);
  TestValidator.equals("투표 댓글 일치")(vote.comment_id)(comment.id);
  TestValidator.equals("스레드 투표 아님")(vote.thread_id)(null);
  TestValidator.equals("게시물 투표 아님")(vote.post_id)(null);
}

