import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IDiscussionBoardThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardThread";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";

/**
 * 테스트 목적: 비작성자(비 소유 멤버)가 댓글을 soft delete(삭제)하는 것을 불허해야 함을 검증합니다.
 *
 * 비즈니스 시나리오:
 * 1. 멤버 2명을 모두 가입시킵니다. (owner, non-owner)
 * 2. owner 멤버의 계정으로 스레드, 게시물, 댓글을 차례로 모두 생성합니다.
 * 3. non-owner 멤버 계정으로 전환 후, owner가 작성한 댓글에 soft delete(DELETE) 요청을 보냅니다.
 * 4. 권한이 없으므로 응답 오브젝트의 result 값이 "forbidden"이고, deleted_at 값이 댓글 기존 deleted_at 값 또는 null임을 검증합니다.
 *
 * 세부 단계:
 * 1. owner 멤버(member1) 회원가입
 * 2. non-owner 멤버(member2) 회원가입
 * 3. member1로 쓰레드 생성
 * 4. member1로 게시물(post) 생성
 * 5. member1로 댓글(comment) 생성
 * 6. member2로 로그인 전환
 * 7. member2가 생성된 댓글에 soft delete 요청 시도
 * 8. 결과: 삭제 거부(result: forbidden) + 삭제 시각 없음(deleted_at 유지) 검증
 */
export async function test_api_discussionBoard_test_soft_delete_comment_by_non_author_forbidden(
  connection: api.IConnection,
) {
  // 1. owner 멤버(member1) 회원가입
  const ownerSignup = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(16),
    display_name: RandomGenerator.name(),
    is_active: true,
    profile_image_url: null,
  } satisfies IdiscussionBoardMembers.ICreate;
  const member1 = await api.functional.discussionBoard.actors.members.post(connection, { body: ownerSignup });
  typia.assert(member1);

  // 2. non-owner 멤버(member2) 회원가입
  const nonOwnerSignup = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(16),
    display_name: RandomGenerator.name(),
    is_active: true,
    profile_image_url: null,
  } satisfies IdiscussionBoardMembers.ICreate;
  const member2 = await api.functional.discussionBoard.actors.members.post(connection, { body: nonOwnerSignup });
  typia.assert(member2);

  // 3. member1(소유자)로 discussion_board_threads 생성
  const threadInput = {
    discussion_board_category_id: typia.random<string & tags.Format<"uuid">>(),
    title: RandomGenerator.paragraph()(),
    body: RandomGenerator.paragraph()(),
    is_pinned: false,
    is_closed: false,
  } satisfies IDiscussionBoardThread.ICreate;
  const thread = await api.functional.discussionBoard.articles.threads.post(connection, { body: threadInput });
  typia.assert(thread);

  // 4. member1로 post 생성
  const postInput = {
    discussion_board_thread_id: thread.id,
    discussion_board_member_id: member1.id,
    body: RandomGenerator.content()()(),
  } satisfies IDiscussionBoardPost.ICreate;
  const post = await api.functional.discussionBoard.articles.posts.post(connection, { body: postInput });
  typia.assert(post);

