/**
 * Test filtering discussion board posts by a single member ID across multiple threads.
 *
 * This scenario verifies that the posts listing endpoint can correctly filter by the author's member ID even when posts are spread across different threads.
 * The steps imitate a real workflow:
 *   1. Create a member who will be authoring multiple posts.
 *   2. Create several categories (one per thread) to allow for thread distribution.
 *   3. For each category, create a separate discussion thread authored by the member.
 *   4. In each thread, create one or more posts by the same member (could be more than one post per thread to test robustness).
 *   5. List all posts using the posts PATCH endpoint, filtering by the member's id.
 *   6. Paginate the results (if total_post_count > page_size), iterate through pages if needed.
 *   7. Assert that:
 *         - Every returned post is authored by the target member
 *         - (Optionally) All created posts are eventually found among the paginated results
 */
export async function test_api_discussionBoard_test_list_posts_by_member_id_with_multiple_threads(
  connection: api.IConnection,
) {
  // 1. Create a member (author)
  const memberEmail: string = typia.random<string & tags.Format<"email">>();
  const memberUsername: string = RandomGenerator.alphaNumeric(10);
  const memberPassword: string = RandomGenerator.alphaNumeric(16);
  const memberDisplayName: string = RandomGenerator.name();

  const member = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: memberUsername,
      email: memberEmail,
      hashed_password: memberPassword,
      display_name: memberDisplayName,
      is_active: true,
      profile_image_url: null,
    },
  });
  typia.assert(member);

  // 2. Create multiple categories and threads
  const THREAD_COUNT = 3;
  const POSTS_PER_THREAD = 2;
  const categories = await Promise.all(
    ArrayUtil.repeat(THREAD_COUNT)(async (_, idx) => {
      const cat = await api.functional.discussionBoard.categories.categories.post(connection, {
        body: {
          name: `TestCat_${RandomGenerator.alphaNumeric(6)}`,
          description: `Test description ${idx}`,
        },
      });
      typia.assert(cat);
      return cat;
    }),
  );

  const threads = await Promise.all(
    categories.map(async (category, idx) => {
      const thread = await api.functional.discussionBoard.articles.threads.post(connection, {
        body: {
          discussion_board_category_id: category.id,
          title: `Test thread ${idx}`,
          body: `Thread body ${idx}`,
          is_pinned: false,
          is_closed: false,
        },
      });
      typia.assert(thread);
      return thread;
    }),
  );

  // 3. Create posts by the member in each thread
  const createdPostIds: Array<string> = [];
  for (const thread of threads) {
    for (let i = 0; i < POSTS_PER_THREAD; ++i) {
      const post = await api.functional.discussionBoard.articles.posts.post(connection, {
        body: {
          discussion_board_thread_id: thread.id,
          discussion_board_member_id: member.id,
          body: `Post body for thread ${thread.title}, post #${i}`,
        },
      });
      typia.assert(post);
      createdPostIds.push(post.id);
    }
  }

  // 4. List posts filtering by discussion_board_member_id
  let allRetrievedPostIds: Array<string> = [];
  let page = 1;
  const limit = 2; // Small limit to force pagination
  let totalPages = 1;
  do {
    const result = await api.functional.discussionBoard.articles.posts.patch(connection, {
      body: {
        page: page,
        limit: limit,
        discussion_board_member_id: member.id,
      },
    });
    typia.assert(result);
    TestValidator.predicate("all returned posts belong to the member")(
      result.data.every((p) => p.discussion_board_member_id === member.id),
    );
    allRetrievedPostIds.push(...result.data.map((p) => p.id));

    if (page === 1) totalPages = result.pagination.pages;
    page += 1;
  } while (page <= totalPages);

  // 5. Optionally assert that all created post ids are found among the result
  for (const id of createdPostIds) {
    TestValidator.predicate(`created post with id ${id} was found in paginated results?`)(
      allRetrievedPostIds.includes(id),
    );
  }
}

