import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IDiscussionBoardThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardThread";
import type { IDiscussionBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReport";
import type { IPageIDiscussionBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardReport";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test that PATCH /discussionBoard/moderation/reports correctly lists reports including soft-deleted ones when requested by filter.
 *
 * This scenario emulates the following business flow:
 * 1. Create or register a member who can report content.
 * 2. Create another member or select existing as target of a report.
 * 3. Create a discussion thread (thread is needed as report target).
 * 4. Submit a moderation report against the thread, by the reporting member.
 * 5. Soft-delete the report with eraseById.
 * 6. Retrieve the report list with filter body {deleted: true} to include deleted reports.
 * 7. Assert that the soft-deleted report is present and its deleted_at field is set (i.e., included in the results when deleted=true).
 * 8. Optionally, validate that soft-deleted reports are absent if not requesting deleted.
 */
export async function test_api_discussionBoard_test_list_reports_including_deleted(connection: api.IConnection) {
  // 1. Register reporting member
  const reporter = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphabets(12),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(32),
      display_name: RandomGenerator.name(),
      is_active: true,
      profile_image_url: null
    },
  });
  typia.assert(reporter);

  // 2. Register another member (target, may not be strictly necessary, but simulates separate accounts)
  const other_member = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphabets(12),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(32),
      display_name: RandomGenerator.name(),
      is_active: true,
      profile_image_url: null
    },
  });
  typia.assert(other_member);

  // 3. Create a discussion thread with reporter as author (as minimum setup for reporting)
  const thread = await api.functional.discussionBoard.articles.threads.post(connection, {
    body: {
      discussion_board_category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(1),
      body: RandomGenerator.content()()(1),
      is_pinned: false,
      is_closed: false,
    },
  });
  typia.assert(thread);

  // 4. Create a report against the new thread, by the reporting member
  const report = await api.functional.discussionBoard.moderation.reports.post(connection, {
    body: {
      reporter_member_id: reporter.id,
      thread_id: thread.id,
      post_id: null,
      comment_id: null,
      reason: "Violation of guidelines (test)",
      status: "pending"
    },
  });
  typia.assert(report);

  // 5. Soft-delete the report
  const deleted_report = await api.functional.discussionBoard.moderation.reports.eraseById(connection, {
    id: report.id,
  });
  typia.assert(deleted_report);
  TestValidator.predicate("deleted_at should be set on deleted report")(!!deleted_report.deleted_at);

  // 6. List all reports requesting deleted=true - should include the soft-deleted report
  const reports_with_deleted = await api.functional.discussionBoard.moderation.reports.patch(connection, {
    body: {
      deleted: true,
      page: 1,
      limit: 20,
      reporter_member_id: null,
      moderator_id: null,
      thread_id: null,
      post_id: null,
      comment_id: null,
      reason: null,
      status: null,
      created_at_from: null,
      created_at_to: null,
      sort: null,
      order: null
    },
  });
  typia.assert(reports_with_deleted);
  const found = reports_with_deleted.data.find(r => r.id === report.id);
  TestValidator.predicate("soft-deleted report should be present when deleted=true")(!!found && !!found.deleted_at);

  // 7. List reports without deleted filter (should NOT include soft-deleted report)
  const reports_excluding_deleted = await api.functional.discussionBoard.moderation.reports.patch(connection, {
    body: {
      deleted: false,
      page: 1,
      limit: 20,
      reporter_member_id: null,
      moderator_id: null,
      thread_id: null,
      post_id: null,
      comment_id: null,
      reason: null,
      status: null,
      created_at_from: null,
      created_at_to: null,
      sort: null,
      order: null
    },
  });
  typia.assert(reports_excluding_deleted);
  const shouldNotBeFound = reports_excluding_deleted.data.find(r => r.id === report.id);
  TestValidator.equals("should not find soft-deleted report when deleted=false")(shouldNotBeFound)(undefined);
}

