      email,
      hashed_password: typia.random<string>(), // Assuming pre-hashed string per security best practice
      display_name,
      is_active: true,
      // Optionally profile_image_url
    } satisfies IdiscussionBoardMembers.ICreate
  });
  typia.assert(member);
  TestValidator.equals("username")(member.username)(username);
  TestValidator.equals("email")(member.email)(email);

  // 2. Create a thread in some category (simulate by random UUID);
  const categoryId = typia.random<string & tags.Format<"uuid">>();
