      discussion_board_thread_id: thread.id,
      discussion_board_member_id: member.id,
      body: postBody,
    } satisfies IDiscussionBoardPost.ICreate
  });
  typia.assert(post);
  TestValidator.equals("post thread id")(post.discussion_board_thread_id)(thread.id);
  TestValidator.equals("member id")(post.discussion_board_member_id)(member.id);
  TestValidator.equals("body")(post.body)(postBody);

  // 4. Upload attachment to the post as the member
  const fileName = "attachment.pdf";
  const fileUri = "https://cdn.example.com/testing/" + RandomGenerator.alphaNumeric(12) + ".pdf";
