import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IDiscussionBoardThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardThread";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IPageIDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardPost";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";

/**
 * Validate the retrieval of a paginated post list filtered by thread ID in the discussion board.
 *
 * This test ensures that after creating a member, category, thread, and multiple posts under that thread, querying the posts list endpoint with the thread ID and pagination parameters will correctly filter, sort, and paginate results.
 *
 * Steps:
 * 1. Register a new discussion board member (author).
 * 2. Create a new discussion board category.
 * 3. Create a new discussion thread under the category (authored by the member).
 * 4. Create several posts (e.g., 7) under the created thread by the member.
 * 5. Fetch the paginated list of posts using PATCH /discussionBoard/articles/posts with the thread_id filter, with limit and page parameters:
 *    - First, fetch page 1 with limit 5; expect 5 posts, and pagination info to match limit, current, and record count.
 *    - Then, fetch page 2 with limit 5; expect the remaining posts (2), and adjusted pagination info.
 *    - Confirm that the posts are only from the created thread, and IDs/order match expected insertion order.
 *    - Confirm that pagination meta fields (records, current, limit, pages) are correct per total data.
 */
export async function test_api_discussionBoard_test_list_posts_by_thread_id_with_pagination(
  connection: api.IConnection,
) {
  // 1. Create member
  const memberInput: IdiscussionBoardMembers.ICreate = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(16),
    display_name: RandomGenerator.name(),
    profile_image_url: null,
    is_active: true,
  };
  const member = await api.functional.discussionBoard.actors.members.post(connection, {
    body: memberInput,
  });
  typia.assert(member);

  // 2. Create category
  const category = await api.functional.discussionBoard.categories.categories.post(connection, {
    body: {
      name: RandomGenerator.alphaNumeric(10),
      description: RandomGenerator.paragraph()(),
    },
  });
  typia.assert(category);

  // 3. Create thread in the category by member
  const threadInput: IDiscussionBoardThread.ICreate = {
    discussion_board_category_id: category.id,
    title: RandomGenerator.paragraph()(),
    body: RandomGenerator.content()()(),
    is_pinned: false,
    is_closed: false,
  };
  const thread = await api.functional.discussionBoard.articles.threads.post(connection, {
    body: threadInput,
  });
  typia.assert(thread);

  // 4. Create multiple posts (7) in thread by member
  const postInputs = ArrayUtil.repeat(7)(i => ({
    discussion_board_thread_id: thread.id,
    discussion_board_member_id: member.id,
    body: RandomGenerator.paragraph()(),
  } satisfies IDiscussionBoardPost.ICreate));
  const createdPosts = await ArrayUtil.asyncMap(postInputs)(async input => {
    const post = await api.functional.discussionBoard.articles.posts.post(connection, { body: input });
    typia.assert(post);
    return post;
  });
  // Sort posts by creation time ASC for expected order.
  createdPosts.sort((a, b) => new Date(a.created_at).getTime() - new Date(b.created_at).getTime());

  // 5. Fetch paginated posts page 1, limit 5
  const page1Response = await api.functional.discussionBoard.articles.posts.patch(connection, {
    body: {
      discussion_board_thread_id: thread.id,
      page: 1,
      limit: 5,
    } satisfies IDiscussionBoardPost.IListRequest,
  });
  typia.assert(page1Response);
  TestValidator.equals("page1 count")(page1Response.data.length)(5);
  TestValidator.equals("page1 current")(page1Response.pagination.current)(1);
  TestValidator.equals("page1 limit")(page1Response.pagination.limit)(5);
  TestValidator.equals("page1 records")(page1Response.pagination.records)(7);
  TestValidator.equals("page1 pages")(page1Response.pagination.pages)(2);
  // Confirm post IDs/order
  for (let i = 0; i < 5; ++i) {
    TestValidator.equals(`page1 post ${i} id`)(page1Response.data[i].id)(createdPosts[i].id);
    TestValidator.equals(`page1 post ${i} thread_id`)(page1Response.data[i].discussion_board_thread_id)(thread.id);
  }

  // 6. Fetch paginated posts page 2, limit 5
  const page2Response = await api.functional.discussionBoard.articles.posts.patch(connection, {
    body: {
      discussion_board_thread_id: thread.id,
      page: 2,
      limit: 5,
    },
  });
  typia.assert(page2Response);
  TestValidator.equals("page2 count")(page2Response.data.length)(2);
  TestValidator.equals("page2 current")(page2Response.pagination.current)(2);
  TestValidator.equals("page2 limit")(page2Response.pagination.limit)(5);
  TestValidator.equals("page2 records")(page2Response.pagination.records)(7);
  TestValidator.equals("page2 pages")(page2Response.pagination.pages)(2);
  for (let i = 0; i < 2; ++i) {
    TestValidator.equals(`page2 post ${i} id`)(page2Response.data[i].id)(createdPosts[5 + i].id);
    TestValidator.equals(`page2 post ${i} thread_id`)(page2Response.data[i].discussion_board_thread_id)(thread.id);
  }
}

