/**
 * Test successful creation of a new discussion board category using valid input data.
 *
 * This test verifies the end-to-end process of an administrator creating a new category. It ensures that when a unique name and an optional description are provided:
 * 1. The API call completes successfully and a new resource is created.
 * 2. The returned category object contains the exact name and description submitted.
 * 3. The system-managed fields (created_at, updated_at) are properly set (present and valid ISO date-times).
 * 4. The id field is a valid UUID and is non-empty.
 * 5. The category is not deleted (deleted_at is null or undefined).
 *
 * Steps:
 * 1. Construct a unique category name and an optional description.
 * 2. Call the API to create a new category with this data.
 * 3. Assert that the response includes the correct name and description.
 * 4. Assert that id is a valid UUID, and created_at/updated_at are valid date-times.
 * 5. Assert that deleted_at is either null or undefined (active category).
 */
export async function test_api_discussionBoard_test_create_category_with_valid_data(
  connection: api.IConnection,
) {
  // 1. Prepare unique category name and description
  const name = `TestCategory_${typia.random<string>()}`;
  const description = "A test description for the discussion board category.";

  // 2. Call API to create the new category
  const output = await api.functional.discussionBoard.categories.categories.post(
    connection,
    {
      body: {
        name,
        description
      } satisfies IDiscussionBoardCategory.ICreate,
    },
  );
  typia.assert(output);

  // 3. Assert the returned name and description match the input
  TestValidator.equals("Category name matches")(output.name)(name);
  TestValidator.equals("Category description matches")(output.description)(description);

  // 4. Assert id is a valid uuid, and system fields are valid date-times
  TestValidator.predicate("id is a non-empty uuid")(
    typeof output.id === "string" && output.id.length > 0 && /^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$/.test(output.id),
  );
  TestValidator.predicate("created_at is a valid ISO date string")(
    typeof output.created_at === "string" && !isNaN(Date.parse(output.created_at)),
  );
  TestValidator.predicate("updated_at is a valid ISO date string")(
    typeof output.updated_at === "string" && !isNaN(Date.parse(output.updated_at)),
  );

  // 5. Assert deleted_at is null or undefined
  TestValidator.predicate("deleted_at is null or undefined")(
    output.deleted_at === null || output.deleted_at === undefined,
  );
}

