/**
 * Test successful creation of a new channel by an administrator.
 *
 * This test verifies that an administrator can create a new discussion board channel by supplying a unique code, a unique name, and an optional description.
 * It validates the API's response to ensure all expected fields are present (including timestamps and no soft-delete),
 * and that only schema-defined fields are accepted/returned (no extra data or schema pollution).
 *
 * Steps:
 * 1. Generate unique channel code and name for the test (to prevent conflict).
 * 2. Call the create channel API as a system admin, passing valid code, name, and random description.
 * 3. Assert that the response includes: code, name, description as sent, plus system fields: id (uuid), created_at and updated_at (ISO8601 datetime), and deleted_at as null/undefined.
 * 4. Assert that the response does not contain any extra/undefined properties.
 * 5. Optionally, confirm that the channel is available for immediate use (could be done by listing channels or retrieving by code, but here focus on create response itself).
 */
export async function test_api_discussionBoard_test_create_channel_with_valid_unique_data(
  connection: api.IConnection,
) {
  // 1. Generate test input data - unique code and name, with description
  const code = `test-chan-` + typia.random<string>().slice(0, 8);
  const name = `Test Channel ` + typia.random<string>().slice(0, 4);
  const description = `Channel for E2E creation test: ` + typia.random<string>().slice(0, 12);

  // 2. Create the channel via API
  const channel = await api.functional.discussionBoard.systematic.channels.post(connection, {
    body: {
      code,
      name,
      description,
    } satisfies IDiscussionBoardChannel.ICreate,
  });
  typia.assert(channel);

  // 3. Assert all expected fields are present and valid
  TestValidator.equals("code matches")(channel.code)(code);
  TestValidator.equals("name matches")(channel.name)(name);
  TestValidator.equals("description matches")(channel.description)(description);
  TestValidator.predicate("has id and id is uuid")(typeof channel.id === "string" && channel.id.length > 10);
  TestValidator.predicate("has created_at ISO")(typeof channel.created_at === "string" && !isNaN(Date.parse(channel.created_at)));
  TestValidator.predicate("has updated_at ISO")(typeof channel.updated_at === "string" && !isNaN(Date.parse(channel.updated_at)));
  TestValidator.equals("not deleted")(channel.deleted_at)(null);

  // 4. Assert no extra properties (schema pollution check)
  const returnedKeys = Object.keys(channel).sort();
  const validKeys = ["id","code","name","description","created_at","updated_at","deleted_at"].sort();
  TestValidator.equals("No extra fields returned")(returnedKeys)(validKeys);
}

