import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IDiscussionBoardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardNotification";
import type { IPageIDiscussionBoardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardNotification";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test listing notifications for a user, with multiple notifications and various filter and pagination parameters.
 *
 * 1. Register a new member to receive notifications. (POST /discussionBoard/actors/members)
 * 2. (Optionally) Register one or more additional members as actors.
 * 3. Create several notifications (different types, read/unread, delivered_at values, with/without actor).
 *    - Use the new member as recipient for all notifications.
 *    - Vary type (e.g., 'reply', 'mention', 'alert'), read value, delivered_at presence, content, etc.
 * 4. Use PATCH /discussionBoard/notifications/notifications to list notifications:
 *    a. Filter by one type (e.g., 'reply'); check only 'reply' type is present in data
 *    b. Filter by read = false; check only unread notifications returned
 *    c. Filter by delivered_from and delivered_to; check only matching delivered_at in data
 *    d. Omit filters (all for recipient); list all, check count/meta matches notification count
 *    e. (If supported) Try small pagination limit, check pagination metadata and slices
 * 5. Validate result arrays are correct (each notification data matches query criteria), meta has current/limit/records/pages as expected, and typia.assert on response.
 */
export async function test_api_discussionBoard_notifications_notifications_test_list_notifications_with_filtering_and_pagination(connection: api.IConnection) {
  // 1. Register a recipient member
  const memberEmail: string = typia.random<string & tags.Format<"email">>();
  const memberUsername: string = RandomGenerator.alphaNumeric(8);
  const recipient = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: memberUsername,
      email: memberEmail,
      hashed_password: RandomGenerator.alphaNumeric(16),
      display_name: RandomGenerator.name(),
      profile_image_url: null,
      is_active: true,
    },
  });
  typia.assert(recipient);

  // 2. Register another member to act as optional notification trigger actor
  const actorEmail: string = typia.random<string & tags.Format<"email">>();
  const actorUsername: string = RandomGenerator.alphaNumeric(8);
  const actor = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: actorUsername,
      email: actorEmail,
      hashed_password: RandomGenerator.alphaNumeric(16),
      display_name: RandomGenerator.name(),
      profile_image_url: null,
      is_active: true,
    },
  });
  typia.assert(actor);

  // 3. Create multiple notifications with diverse attributes for the recipient
  const now = new Date();
  const notificationsToCreate = [
    {
      type: 'reply', read: false, delivered_at: now.toISOString(), trigger_actor_id: actor.id,
    },
    {
      type: 'mention', read: false, delivered_at: null, trigger_actor_id: null,
    },
    {
      type: 'alert', read: true, delivered_at: new Date(now.getTime() - 1000 * 60 * 60).toISOString(), trigger_actor_id: actor.id,
    },
    {
      type: 'reply', read: true, delivered_at: new Date(now.getTime() - 1000 * 60 * 120).toISOString(), trigger_actor_id: null,
    },
    {
      type: 'alert', read: false, delivered_at: new Date(now.getTime() - 1000 * 60 * 120).toISOString(), trigger_actor_id: actor.id,
    },
  ];
  const createdNotifications: IDiscussionBoardNotification[] = [];
  for (const input of notificationsToCreate) {
    const created = await api.functional.discussionBoard.notifications.notifications.post(connection, {
      body: {
        recipient_member_id: recipient.id,
        trigger_actor_id: input.trigger_actor_id,
        type: input.type,
        content_preview: `Test: ${input.type}`,
        url: `https://example.com/${input.type}/${RandomGenerator.alphaNumeric(10)}`,
        read: input.read,
        delivered_at: input.delivered_at,
        created_at: now.toISOString(),
      },
    });
    typia.assert(created);
    createdNotifications.push(created);
  }

  // 4a. Filter by type = 'reply'
  let response = await api.functional.discussionBoard.notifications.notifications.patch(connection, {
    body: { type: 'reply' },
  });
  typia.assert(response);
  response.data.forEach((n) => TestValidator.equals('type')(n.type)('reply'));

  // 4b. Filter by read = false
  response = await api.functional.discussionBoard.notifications.notifications.patch(connection, {
    body: { read: false },
  });
  typia.assert(response);
  response.data.forEach((n) => TestValidator.equals('read')(n.read)(false));

  // 4c. Filter by delivered_from and delivered_to (range includes only a subset)
  const deliveredFrom = new Date(now.getTime() - 1000 * 60 * 61).toISOString();
  const deliveredTo = now.toISOString();
  response = await api.functional.discussionBoard.notifications.notifications.patch(connection, {
    body: { delivered_from: deliveredFrom, delivered_to: deliveredTo },
  });
  typia.assert(response);
  response.data.forEach((n) => {
    if (n.delivered_at !== null) {
      TestValidator.predicate('delivered_at in range')(
        n.delivered_at >= deliveredFrom && n.delivered_at <= deliveredTo,
      );
    }
  });

  // 4d. List all notifications for the recipient (omit all filters)
  response = await api.functional.discussionBoard.notifications.notifications.patch(connection, {
    body: {},
  });
  typia.assert(response);
  TestValidator.equals('total notifications')(response.pagination.records)(createdNotifications.length);

  // 4e. Use pagination (simulate by limiting to 2 per page, if pagination params supported)
  // (Since schema does not specify pagination fields in IRequest, we assume pagination is automatic or default in backend)
  // Here we just check that sliced data and meta are consistent with total
  TestValidator.equals('pagination records')(response.data.length)(response.pagination.records <= 2 ? response.data.length : 2);
  TestValidator.equals('pagination count')(response.pagination.pages >= 1)(true);
  TestValidator.equals('current page')(response.pagination.current >= 1)(true);
  TestValidator.equals('limit')(response.pagination.limit >= 1)(true);
}

