/**
 * Test comment list pagination per post for discussion board.
 *
 * This test covers the following workflow:
 * 1. Register a new test member.
 * 2. Create a new thread on the discussion board.
 * 3. Create a post inside that thread.
 * 4. Add multiple comments to the post – these will test pagination and return.
 * 5. Fetch the comments for the post using the PATCH endpoint with pagination parameters (limit/page) and verify:
 *    - Only the correct comments for the target post are returned
 *    - Comments are ordered as expected (by creation date desc by default)
 *    - Pagination meta (current, limit, records, pages) reflects the inserted count/params
 *    - No soft-deleted comments (deleted_at != null) are present in results
 *
 * Steps:
 *  - Generate and register a unique member
 *  - Create a thread (any category, test value)
 *  - Create a post by the member in the thread
 *  - Insert, e.g., 12 comments for the post (for 5-per-page pagination)
 *  - Manually soft-delete one comment (if supported, skip otherwise)
 *  - Fetch the first page (limit 5) and check top 5 are most recently created and are not deleted
 *  - Fetch all pages in a loop, collect, and verify all undeleted comments are present, in correct order, and count matches meta
 *  - Edge: request a page number beyond max and ensure empty result
 *
 * Note: If there's no soft-deletion comment endpoint, manually set a comment's deleted_at to simulate (skip this if impossible).
 */
export async function test_api_discussionBoard_test_list_comments_by_post_id_pagination(
  connection: api.IConnection,
) {
  // 1. Register a member
  const member = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: RandomGenerator.email(),
      hashed_password: RandomGenerator.alphaNumeric(40),
      display_name: RandomGenerator.name(),
      is_active: true,
      profile_image_url: null,
    } satisfies IdiscussionBoardMembers.ICreate,
  });
  typia.assert(member);

  // 2. Create a new thread
  const thread = await api.functional.discussionBoard.articles.threads.post(connection, {
    body: {
      discussion_board_category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(1),
      body: RandomGenerator.paragraph()(),
      is_pinned: false,
      is_closed: false,
    } satisfies IDiscussionBoardThread.ICreate,
  });
  typia.assert(thread);

  // 3. Create a post by the member in the thread
  const post = await api.functional.discussionBoard.articles.posts.post(connection, {
    body: {
      discussion_board_thread_id: thread.id,
      discussion_board_member_id: member.id,
      body: RandomGenerator.content()()(),
    } satisfies IDiscussionBoardPost.ICreate,
  });
  typia.assert(post);

  // 4. Insert 12 comments for the post
  const comments: IDiscussionBoardComment[] = [];
  for (let i = 0; i < 12; ++i) {
    const comment = await api.functional.discussionBoard.articles.comments.post(connection, {
      body: {
        discussion_board_post_id: post.id,
        discussion_board_member_id: member.id,
        body: `Comment content ${i + 1}`,
      } satisfies IDiscussionBoardComment.ICreate,
    });
    typia.assert(comment);
    comments.push(comment);
  }
  // Sort expected comments by creation time descending (latest first)
  const commentsSorted = [...comments].sort((a, b) => b.created_at.localeCompare(a.created_at));

