  const page1 = await api.functional.discussionBoard.articles.comments.patch(connection, {
    body: {
      discussion_board_post_id: post.id,
      page: 1,
      limit: 5,
      sort: "created_at",
      order: "desc",
      deleted: false,
    } satisfies IDiscussionBoardComment.IListRequest,
  });
  typia.assert(page1);

  // Validate page1: 5 newest comments, correct pagination
  TestValidator.equals("first page count")(page1.data.length)(5);
  TestValidator.equals("first page meta")(page1.pagination.current)(1);
  TestValidator.equals("first page meta limit")(page1.pagination.limit)(5);
  TestValidator.equals("first page total")(page1.pagination.records)(12);
  TestValidator.equals("first page pages")(page1.pagination.pages)(Math.ceil(12 / 5));
  for (let i = 0; i < 5; ++i)
    TestValidator.equals(`comment order[${i}]`)(page1.data[i].id)(commentsSorted[i].id);
  for (const c of page1.data)
    TestValidator.equals("not soft deleted")(c.deleted_at)(null);

  // 6. Fetch all pages and collect ids
  const allCollected: IDiscussionBoardComment[] = [];
  for (let page = 1; page <= page1.pagination.pages; ++page) {
    const pg = await api.functional.discussionBoard.articles.comments.patch(connection, {
      body: {
        discussion_board_post_id: post.id,
        page,
        limit: 5,
        sort: "created_at",
        order: "desc",
        deleted: false,
      } satisfies IDiscussionBoardComment.IListRequest,
    });
    typia.assert(pg);
    for (const c of pg.data)
      allCollected.push(c);
  }
  // All collected should match sorted and not include soft-deleted
  TestValidator.equals("all collected length")(allCollected.length)(12);
  for (let i = 0; i < commentsSorted.length; ++i)
    TestValidator.equals(`comment id[${i}]`)(allCollected[i].id)(commentsSorted[i].id);

  // 7. Edge: Fetch page beyond range returns empty list
  const beyond = await api.functional.discussionBoard.articles.comments.patch(connection, {
    body: {
      discussion_board_post_id: post.id,
      page: 10,
      limit: 5,
      sort: "created_at",
      order: "desc",
      deleted: false,
    } satisfies IDiscussionBoardComment.IListRequest,
  });
  typia.assert(beyond);
  TestValidator.equals("beyond-page-empty")(beyond.data.length)(0);
}

