import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IDiscussionBoardThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardThread";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAttachment";

/**
 * Validate repeated deletion (soft delete) of an attachment entity in the discussion board.
 *
 * This test verifies that when a client attempts to delete (soft delete) an attachment that was already deleted, the server returns the appropriate error (such as 404 not found or a business error indicating the attachment was already deleted).
 *
 * Business context: Moderators, admins, or owners may mistakenly retry deletion operations. The system must consistently return an error instead of reapplying the soft delete logic or succeeding silently.
 *
 * Step-by-step process:
 * 1. Create a new member (who will be the uploader and owner of the attachment).
 * 2. Create a new discussion thread (context for the post that will have an attachment).
 * 3. Create a post within the created thread (the attachment will be linked here).
 * 4. Upload (create) an attachment and associate it to the created post, specifying the uploader as the new member.
 * 5. Perform the first soft delete (DELETE) for the newly uploaded attachment and check succeeded deletion.
 * 6. Attempt to delete the same attachment again: expect an error to be thrown (404 or already deleted error).
 */
export async function test_api_discussionBoard_test_soft_delete_attachment_already_deleted(
  connection: api.IConnection,
) {
  // 1. Create a new member
  const memberInput: IdiscussionBoardMembers.ICreate = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(16),
    display_name: RandomGenerator.name(),
    profile_image_url: null,
    is_active: true,
  };
  const member = await api.functional.discussionBoard.actors.members.post(connection, {
    body: memberInput,
  });
  typia.assert(member);

  // 2. Create a thread for context
  const threadInput: IDiscussionBoardThread.ICreate = {
    discussion_board_category_id: typia.random<string & tags.Format<"uuid">>(),
    title: RandomGenerator.paragraph()(1),
    body: RandomGenerator.content()()(),
    is_pinned: false,
    is_closed: false
  };
  const thread = await api.functional.discussionBoard.articles.threads.post(connection, {
    body: threadInput,
  });
  typia.assert(thread);

  // 3. Create a post to attach the file
  const postInput: IDiscussionBoardPost.ICreate = {
    discussion_board_thread_id: thread.id,
    discussion_board_member_id: member.id,
    body: RandomGenerator.content()()(),
  };
  const post = await api.functional.discussionBoard.articles.posts.post(connection, {
    body: postInput,
  });
  typia.assert(post);

  // 4. Create an attachment linked to the post
  const attachmentInput: IDiscussionBoardAttachment.ICreate = {
    discussion_board_post_id: post.id,
    discussion_board_comment_id: null,
    discussion_board_member_id: member.id,
    file_name: `${RandomGenerator.alphaNumeric(6)}.png`,
    file_uri: `https://cdn.example.com/${RandomGenerator.alphaNumeric(12)}`,
    content_type: "image/png",
    content_hash: RandomGenerator.alphaNumeric(64),
  };
  const attachment = await api.functional.discussionBoard.articles.attachments.post(connection, {
    body: attachmentInput,
  });
  typia.assert(attachment);

  // 5. First soft delete: should succeed
  const deleted = await api.functional.discussionBoard.articles.attachments.eraseById(connection, {
    id: attachment.id,
  });
  typia.assert(deleted);
  TestValidator.predicate("attachment is marked as deleted")(!!deleted.deleted_at);

  // 6. Attempt second delete: should fail as already deleted
  await TestValidator.error("Deleting an already-deleted attachment should fail")(
    async () => {
      await api.functional.discussionBoard.articles.attachments.eraseById(connection, {
        id: attachment.id,
      });
    },
  );
}

