 *    - status
 *    - thread_id
 *    - date range (from created_at values)
 *    - reason substring, if applicable
 *    - Multiple filters combined (e.g., reporter_member_id + status, etc.)
 * 6. Use limit/page options to verify paginated results are correct.
 * 7. For all queries: verify that each report returned satisfies the filters, that "records" counts match number of matched records, and that segmentation is correct for each page.
 */
export async function test_api_discussionBoard_moderation_reports_test_list_reports_with_pagination_and_filtering(
  connection: api.IConnection,
