    const thread = await api.functional.discussionBoard.articles.threads.post(connection, {
      body: {
        discussion_board_category_id: category_id,
        title: RandomGenerator.paragraph()(1),
        body: RandomGenerator.content()(1)(1),
        is_pinned: false,
        is_closed: false,
      } satisfies IDiscussionBoardThread.ICreate,
    });
    typia.assert(thread);
    return thread;
  });

  // Step 3: Create 5 reports, distributed between members & threads; timestamps staggered a bit
  const now = new Date();
  const reportData = [
    // Diverse properties: reporter, thread, status, reason
    { reporter: members[0], thread: threads[0], status: "pending", reason: "스팸", offsetDays: -3 },
    { reporter: members[1], thread: threads[1], status: "under_review", reason: "욕설", offsetDays: -2 },
    { reporter: members[2], thread: threads[2], status: "pending", reason: "광고", offsetDays: -1 },
    { reporter: members[0], thread: threads[1], status: "resolved", reason: "개인정보 노출", offsetDays: 0 },
    { reporter: members[1], thread: threads[0], status: "pending", reason: "욕설", offsetDays: 1 },
  ];
  const reports = [];
  for (const item of reportData) {
    // To gain better control over created_at for date filter, simulate dates via test or track them ourselves
    const report = await api.functional.discussionBoard.moderation.reports.post(connection, {
