      TestValidator.equals("thread matches")(r.thread_id)(thread.id);
    TestValidator.equals("count matches")(res.pagination.records)(filtered.length);
  }

  // Filter by status
  const statuses = [...new Set(reports.map((r) => r.status))];
  for (const status of statuses) {
    const filtered = reports.filter((r) => r.status === status);
    if (filtered.length === 0) continue;
    const res = await api.functional.discussionBoard.moderation.reports.patch(connection, {
      body: { status, page: 1, limit: 10 } satisfies IDiscussionBoardReport.IRequest,
