 * 7. If duplication is not allowed, verify clean error and proper handling
 */
export async function test_api_discussionBoard_moderation_warnings_test_create_warning_duplicate_idempotency_or_uniqueness(connection: api.IConnection) {
  // 1. Create a member to be warned
  const memberRes = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
