    } satisfies IdiscussionBoardMembers.ICreate,
  });
  typia.assert(memberRes);

  // 2. Assign moderator role to new member
  const moderatorRes = await api.functional.discussionBoard.actors.moderators.post(connection, {
    body: {
      member_id: memberRes.id,
      assigned_at: new Date().toISOString(),
    } satisfies IdiscussionBoardModerators.ICreate,
  });
  typia.assert(moderatorRes);

  // 3. Compose warning details
  const warningBody = {
    member_id: memberRes.id,
    moderator_id: moderatorRes.id,
    warning_type: "spam",
    message: "Repeated spam content in forum thread.",
    created_at: new Date().toISOString(),
    expires_at: null,
  } satisfies IModerationWarning.ICreate;

  // 4. Create first warning
  const warning1 = await api.functional.discussionBoard.moderation.warnings.post(connection, {
    body: warningBody,
  });
  typia.assert(warning1);

  // 5. Attempt to create duplicate warning (identical input)
  let duplicateWarning2 = null;
  let errorCaught = false;
  try {
    duplicateWarning2 = await api.functional.discussionBoard.moderation.warnings.post(connection, { body: warningBody });
    typia.assert(duplicateWarning2);
  } catch (error) {
    errorCaught = true;
  }

  // 6. Assert correct system behavior
  if (!errorCaught) {
    // If duplicate allowed, both must have distinct ID
    TestValidator.notEquals("warning IDs should differ")(warning1.id)(duplicateWarning2.id);
    TestValidator.equals("member ID identical")(warning1.member_id)(duplicateWarning2.member_id);
    TestValidator.equals("moderator ID identical")(warning1.moderator_id)(duplicateWarning2.moderator_id);
    TestValidator.equals("type identical")(warning1.warning_type)(duplicateWarning2.warning_type);
    TestValidator.equals("message identical")(warning1.message)(duplicateWarning2.message);
  } else {
    // If uniqueness enforced, duplicated request must have failed
    TestValidator.predicate("duplicate warning correctly blocked")(errorCaught);
  }
}

