import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IdiscussionBoardModerators } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardModerators";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";

/**
 * discussion_board_moderators 엔티티 업데이트 API의 밸리데이션 - 허용되지 않은 필드(id, member_id)나 타입/비즈니스 규칙 위반(revoked_at 잘못된 타입 또는 논리적 불가 시점 등) 업데이트 시도 시, 정상적으로 실패(에러)하는지 검증합니다.
 *
 * 1. 테스트용 회원을 생성합니다.
 * 2. 해당 회원에게 모더레이터 역할을 할당합니다.
 * 3. 아래와 같은 실패 케이스를 각각 검증합니다.
 *    a. 불변/허용되지 않은 필드(id, member_id 등)를 body에 포함하여 업데이트 시도 → 에러 발생해야 함
 *    b. revoked_at에 잘못된 타입(숫자 등)을 넣거나, revoked_at이 assigned_at보다 과거 등 논리 규칙을 위반한 값 입력 → 에러 발생해야 함
 *
 * 모든 실패 시나리오에서 TestValidator.error를 통해 명확하게 에러 검증을 수행합니다.
 */
export async function test_api_discussionBoard_actors_moderators_test_update_moderator_assignment_with_invalid_fields(
  connection: api.IConnection,
) {
  // 1. 테스트용 회원 생성 (의존성 시나리오: 멤버 계정 생성)
  const member = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphabets(10),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(32),
      display_name: RandomGenerator.name(),
      is_active: true,
    },
  });
  typia.assert(member);

  // 2. 해당 회원에 모더레이터 할당
  const moderator = await api.functional.discussionBoard.actors.moderators.post(connection, {
    body: {
      member_id: member.id,
      assigned_at: new Date().toISOString(),
    },
  });
  typia.assert(moderator);

  // 3a. 존재하지 않거나 불변 필드(id, member_id 등)를 업데이트 body에 포함시도 → 에러 발생
  await TestValidator.error("불변/비허용 필드(id, member_id)를 업데이트 시도하면 실패해야 한다")(() =>
    // @ts-expect-error: 타입 가드 우회 (에러 유발 목적)
    api.functional.discussionBoard.actors.moderators.putById(connection, {
      id: moderator.id,
      body: {
        id: typia.random<string & tags.Format<"uuid">>(),
        member_id: typia.random<string & tags.Format<"uuid">>(),
        assigned_at: new Date().toISOString(),
      },
    }),
  );

  // 3b. revoked_at 필드 타입/논리 밸리데이션 에러 검증
  // 타입 위반(숫자)
  await TestValidator.error("revoked_at 타입(숫자) 잘못 입력하면 실패해야 한다")(() =>
    // @ts-expect-error: 타입 무시 (schema validation error 유도)
    api.functional.discussionBoard.actors.moderators.putById(connection, {
      id: moderator.id,
      body: {
        revoked_at: 12345, // 잘못된 타입 (string & format: date-time이 아님)
      },
    }),
  );

  // revoked_at이 논리적으로 허용되지 않는 값(assigned_at보다 전 날짜)
  const assignedAt = new Date();
  const revokedAtInPast = new Date(assignedAt.getFullYear() - 10, assignedAt.getMonth(), assignedAt.getDate()).toISOString();
  await TestValidator.error("revoked_at이 assigned_at보다 과거면 실패해야 한다")(() =>
    api.functional.discussionBoard.actors.moderators.putById(connection, {
      id: moderator.id,
      body: {
        assigned_at: assignedAt.toISOString(),
        revoked_at: revokedAtInPast,
      },
    }),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IDiscussionBoardThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardThread";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";

/**
 * Validate successful creation of a discussion thread by an authenticated member.
 *
 * This test verifies that a member can create a top-level (root) discussion thread
 * after signing up, ensuring all required and optional fields are respected, and
 * that security rules block unauthenticated access. Test covers business flow,
 * atomic field population, and essential authorization logic.
 *
 * Step-by-step process:
 * 1. Create a category to assign as the discussion_board_category_id.
 * 2. Register a member to be the authentic thread creator.
 * 3. Attempt to create a thread (providing valid discussion_board_member_id, category id, title, body, is_pinned, is_closed).
 *     - Validate all atomic fields are present; assert key data matches input.
 * 4. Confirm access control:
 *     - Try to create a thread using an unauthenticated connection and assert it fails.
 */
export async function test_api_discussionBoard_test_create_thread_success_all_required_fields(
  connection: api.IConnection,
) {
  // 1. Create a category for assignment
  const category = await api.functional.discussionBoard.categories.categories.post(connection, {
    body: {
      name: RandomGenerator.alphabets(8),
      description: RandomGenerator.paragraph()(),
    },
  });
  typia.assert(category);

  // 2. Register a member to be the thread creator
  const email = typia.random<string & tags.Format<"email">>();
  const username = RandomGenerator.alphaNumeric(10);
  const member = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username,
      email,
      hashed_password: RandomGenerator.alphaNumeric(32),
      display_name: RandomGenerator.name(),
      profile_image_url: null,
      is_active: true,
    },
  });
  typia.assert(member);

  // 3. Create thread (authenticated)
  const threadInput = {
    discussion_board_category_id: category.id,
    title: RandomGenerator.paragraph()(),
    body: RandomGenerator.content()()(),
    is_pinned: true,
    is_closed: false,
  } satisfies IDiscussionBoardThread.ICreate;
  const thread = await api.functional.discussionBoard.articles.threads.post(connection, { body: threadInput });
  typia.assert(thread);
  TestValidator.equals("category id on thread")(thread.discussion_board_category_id)(category.id);
  TestValidator.equals("title")(thread.title)(threadInput.title);
  TestValidator.equals("is_pinned")(thread.is_pinned)(true);
  TestValidator.equals("is_closed")(thread.is_closed)(false);
  TestValidator.equals("thread body")(thread.body)(threadInput.body);

  // 4. Attempt to create thread as unauthenticated/anonymous (should fail)
  const anonymousConnection = { ...connection, headers: { ...connection.headers, Authorization: undefined } };
  await TestValidator.error("unauthenticated cannot create thread")(() =>
    api.functional.discussionBoard.articles.threads.post(anonymousConnection, { body: threadInput }),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IDiscussionBoardThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardThread";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";

/**
 * Test thread creation fails for invalid or non-existent category/member IDs (foreign key integrity).
 *
 * Verifies: The API correctly enforces foreign key/ownership integrity by refusing thread creation
 * when an invalid (non-existent) discussion_board_category_id or discussion_board_member_id is supplied.
 *
 * Business context: Ensures that the system reliably prevents orphaned threads and data integrity is maintained
 * when clients attempt to use random UUIDs that do not correspond to real member or category records.
 *
 * Test steps:
 * 1. Create a valid category and a valid member for use as controls.
 * 2. Attempt thread creation with a non-existent category but valid member: must fail (error expected).
 * 3. Attempt thread creation with a valid category but non-existent member: must fail (error expected).
 * 4. Attempt thread creation with both IDs non-existent: must fail (error expected).
 * 5. (Control) Attempt thread creation with valid member and category: must succeed, and check links.
 */
export async function test_api_discussionBoard_test_create_thread_invalid_or_nonexistent_category_or_member(
  connection: api.IConnection,
) {
  // 1. Create a valid discussion board category
  const category = await api.functional.discussionBoard.categories.categories.post(connection, {
    body: {
      name: RandomGenerator.paragraph()(1),
      description: RandomGenerator.content()()(1),
    } satisfies IDiscussionBoardCategory.ICreate,
  });
  typia.assert(category);

  // 2. Create a valid discussion board member
  const member = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(32),
      display_name: RandomGenerator.name(),
      is_active: true,
    } satisfies IdiscussionBoardMembers.ICreate,
  });
  typia.assert(member);

  const fakeCategoryId = typia.random<string & tags.Format<"uuid">>();
  const fakeMemberId = typia.random<string & tags.Format<"uuid">>();

  // 3. Try: valid member, non-existent category (should error)
  await TestValidator.error("thread creation fails for non-existent category")(() =>
    api.functional.discussionBoard.articles.threads.post(connection, {
      body: {
        discussion_board_category_id: fakeCategoryId,
        title: RandomGenerator.paragraph()(1),
        body: RandomGenerator.content()()(1),
        is_pinned: false,
        is_closed: false,
        discussion_board_member_id: member.id,
      } satisfies IDiscussionBoardThread.ICreate,
    })
  );

  // 4. Try: valid category, non-existent member (should error)
  await TestValidator.error("thread creation fails for non-existent member")(() =>
    api.functional.discussionBoard.articles.threads.post(connection, {
      body: {
        discussion_board_category_id: category.id,
        title: RandomGenerator.paragraph()(1),
        body: RandomGenerator.content()()(1),
        is_pinned: false,
        is_closed: false,
        discussion_board_member_id: fakeMemberId,
      } satisfies IDiscussionBoardThread.ICreate,
    })
  );

  // 5. Try: both category and member non-existent (should error)
  await TestValidator.error("thread creation fails for both IDs non-existent")(() =>
    api.functional.discussionBoard.articles.threads.post(connection, {
      body: {
        discussion_board_category_id: fakeCategoryId,
        title: RandomGenerator.paragraph()(1),
        body: RandomGenerator.content()()(1),
        is_pinned: false,
        is_closed: false,
        discussion_board_member_id: fakeMemberId,
      } satisfies IDiscussionBoardThread.ICreate,
    })
  );

  // 6. (Control) Try: all valid references (should succeed)
  const thread = await api.functional.discussionBoard.articles.threads.post(connection, {
    body: {
      discussion_board_category_id: category.id,
      title: RandomGenerator.paragraph()(1),
      body: RandomGenerator.content()()(1),
      is_pinned: false,
      is_closed: false,
      discussion_board_member_id: member.id,
    } satisfies IDiscussionBoardThread.ICreate,
  });
  typia.assert(thread);
  TestValidator.equals("category ID matches")(thread.discussion_board_category_id)(category.id);
  TestValidator.equals("member ID matches")(thread.discussion_board_member_id)(member.id);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardConfiguration } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardConfiguration";
import type { IdiscussionBoardConfigurations } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardConfigurations";

/**
 * Validate that updating a configuration property with non-schema fields is rejected.
 *
 * This test ensures the API strictly validates request bodies against schema, rejecting any extra properties.
 * Such validation enforces API contract integrity and prevents accidental or malicious injection of invalid fields.
 *
 * Steps:
 * 1. Create a configuration using only schema-compliant fields.
 * 2. Attempt to update the configuration property by including a non-schema field (e.g., 'unauthorizedField').
 * 3. Ensure that the update fails, raising a validation error and not modifying the configuration.
 * 4. Update the configuration using only valid schema fields for control, and verify success.
 */
export async function test_api_discussionBoard_systematic_configurations_test_update_configuration_includes_only_schema_fields_and_other_fields_are_rejected(
  connection: api.IConnection,
) {
  // 1. Create a valid configuration
  const created = await api.functional.discussionBoard.systematic.configurations.post(
    connection,
    {
      body: {
        key: `key_${typia.random<string>()}`,
        value: typia.random<string>(),
        description: RandomGenerator.paragraph()(),
      } satisfies IDiscussionBoardConfiguration.ICreate,
    }
  );
  typia.assert(created);

  // 2. Attempt to update with an extra non-schema field
  await TestValidator.error("putById should reject extra fields")(
    async () => {
      // @ts-expect-error: Intentionally test the system's schema validation for extra fields
      await api.functional.discussionBoard.systematic.configurations.putById(
        connection,
        {
          id: created.id,
          body: {
            value: typia.random<string>(),
            unauthorizedField: "should fail", // field not in schema
          } as any, // purposely break type safety to trigger runtime validation
        }
      );
    }
  );

  // 3. Update using only schema-compliant fields (control test for success)
  const updated = await api.functional.discussionBoard.systematic.configurations.putById(
    connection,
    {
      id: created.id,
      body: {
        value: typia.random<string>()
      } satisfies IdiscussionBoardConfigurations.IUpdate,
    }
  );
  typia.assert(updated);
  TestValidator.equals("update success")(updated.id)(created.id);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardGuests } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardGuests";

/**
 * 테스트 목적: 중복된 session_token으로 게스트 세션 생성 시 시스템이 고유성 제약(Unique Constraint)을 제대로 적용하는지 검증합니다.
 * 
 * 비즈니스 컨텍스트:
 * discussion_board_guests 테이블은 session_token의 중복을 허용하지 않으므로,
 * 이미 존재하는 session_token으로 다시 게스트 세션을 생성하려고 시도하면 고유성 위반 오류가 발생해야 합니다.
 * 이는 세션 추적 및 데이터 무결성 유지에 필수적입니다.
 * 
 * 테스트 시나리오 단계:
 * 1. 임의의 session_token으로 정상적인 게스트 세션을 생성한다.
 * 2. 동일한 session_token으로 한 번 더 생성 시도를 하여,
 *    시스템이 unique constraint violation 에러를 반환하는지 검증한다.
 */
export async function test_api_discussionBoard_test_create_guest_session_with_duplicate_session_token(
  connection: api.IConnection,
) {
  // 1. 테스트용 세션 정보 구성
  const sessionToken: string = RandomGenerator.alphabets(24);
  const ipAddress: string = "192.168.1." + typia.random<number & tags.Type<"uint8">>().toString();
  const userAgent: string = "Mozilla/5.0 (E2E-Test)";
  const expiresAt: string = new Date(Date.now() + 1000 * 60 * 60).toISOString();

  // 2. 첫 번째 세션 정상 생성
  const guest = await api.functional.discussionBoard.actors.guests.post(connection, {
    body: {
      session_token: sessionToken,
      ip_address: ipAddress,
      user_agent: userAgent,
      expires_at: expiresAt,
    },
  });
  typia.assert(guest);
  TestValidator.equals("session_token 일치")(guest.session_token)(sessionToken);
  TestValidator.equals("ip_address 일치")(guest.ip_address)(ipAddress);
  TestValidator.equals("user_agent 일치")(guest.user_agent)(userAgent);
  TestValidator.equals("expires_at 일치")(guest.expires_at)(expiresAt);

  // 3. 동일 session_token으로 중복 생성 시도 → 오류 발생해야 함
  await TestValidator.error("중복 session_token unique 제약 에러")(() =>
    api.functional.discussionBoard.actors.guests.post(connection, {
      body: {
        session_token: sessionToken,
        ip_address: ipAddress,
        user_agent: userAgent,
        expires_at: expiresAt,
      },
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IPageIdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIdiscussionBoardMembers";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate listing and filtering of discussion board members with default filters and pagination.
 *
 * This test covers the typical admin/member-directory listing scenario:
 *
 * 1. Register three active members with distinct usernames and emails via POST.
 * 2. Use the PATCH endpoint with an empty body to list all active, non-deleted members.
 *    - Ensure all created members are present in the result.
 *    - Validate pagination object for minimum record count and logical metadata.
 * 3. Use PATCH to list only inactive members (should return none).
 * 4. Use PATCH to filter by a specific known username, expecting only that member in response.
 * 5. Assert correct response types and business logic at all steps.
 */
export async function test_api_discussionBoard_actors_members_test_list_members_with_default_filter(
  connection: api.IConnection,
) {
  // 1. Register three active members
  const members: IdiscussionBoardMembers[] = [];
  for (const suffix of ["A", "B", "C"]) {
    const member: IdiscussionBoardMembers = await api.functional.discussionBoard.actors.members.post(connection, {
      body: {
        username: RandomGenerator.alphabets(8) + suffix,
        email: `${RandomGenerator.alphabets(8)}${suffix}@example.com`,
        hashed_password: RandomGenerator.alphabets(20),
        display_name: "User" + suffix,
        is_active: true,
        profile_image_url: null,
      } satisfies IdiscussionBoardMembers.ICreate,
    });
    typia.assert(member);
    members.push(member);
  }

  // 2. Fetch member list with default filter (should return active, non-deleted)
  const result = await api.functional.discussionBoard.actors.members.patch(connection, {
    body: {} satisfies IdiscussionBoardMembers.IRequest,
  });
  typia.assert(result);

  // Ensure all created members are returned and not soft-deleted
  for (const m of members) {
    const found = result.data.find((x) => x.id === m.id);
    TestValidator.predicate("Newly created member present")(!!found);
    TestValidator.equals("deleted_at")(found.deleted_at)(null);
    TestValidator.equals("is_active")(found.is_active)(true);
  }

  // Validate pagination metadata (at least 3 exists, page structure is logical)
  TestValidator.predicate("pagination.records >= 3")(result.pagination.records >= 3);
  TestValidator.predicate("pagination.limit > 0")(result.pagination.limit > 0);
  TestValidator.predicate("pagination.current >= 1")(result.pagination.current >= 1);
  TestValidator.predicate("pagination.pages >= 1")(result.pagination.pages >= 1);

  // 3. List ONLY inactive members (should be none)
  const inactiveResult = await api.functional.discussionBoard.actors.members.patch(connection, {
    body: { is_active: false } satisfies IdiscussionBoardMembers.IRequest,
  });
  typia.assert(inactiveResult);
  TestValidator.equals("No inactive members")(inactiveResult.data.length)(0);
  TestValidator.equals("Inactive records count")(inactiveResult.pagination.records)(0);

  // 4. Filter by known username (should match only one member)
  const username = members[0].username;
  const byName = await api.functional.discussionBoard.actors.members.patch(connection, {
    body: { username } satisfies IdiscussionBoardMembers.IRequest,
  });
  typia.assert(byName);
  TestValidator.equals("Exact username match")(byName.data.length)(1);
  TestValidator.equals("Username correct")(byName.data[0].username)(username);
  TestValidator.equals("Records == 1")(byName.pagination.records)(1);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardChannel";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageDiscussionBoardChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageDiscussionBoardChannel";

/**
 * 키워드(부분일치) 및 페이지네이션이 결합된 토론 채널 목록 조회 검증.
 *
 * 관리자 뷰, 어드민에서 사용할 수 있는 채널 관리 검색을 전제로 한다.
 *
 * [절차]
 * 1. 다양한 code, name, description 조합으로 채널 여러 개 등록(적어도 6개 이상)
 * 2. code의 일부(keyword)를 검색어로 하여 부분일치+페이지네이션 1page 검색 및 응답검증
 *    - code 일부와 일치하는 데이터만 반환되는지, 한페이지 크기만큼만 오는지
 *    - pagination.current/limit/records 등 메타 일치성 체크
 * 3. name 일부(keyword)를 검색어로 하여 2페이지 검색 및 일치성 응답검증
 *    - name 일부와 일치하는 데이터만 반환, 2page/2개씩 등 검증
 * 4. 일치하는 code, name, description이 아예 없는 zero-result 검색에서 empty 확인
 * 5. 각 단계 데이터는 모두 typia.assert, TestValidator로 정밀 검증
 */
export async function test_api_discussionBoard_test_search_channels_with_keyword_and_pagination(
  connection: api.IConnection,
) {
  // 1. 여러 code, name, description 조합으로 6개 채널 생성
  const channels: IDiscussionBoardChannel[] = [];
  for (let i = 0; i < 6; ++i) {
    const code = `eco-keyword-${i}`;
    const name = `TestNameKeywordMatch${i}`;
    const description = i % 2 === 0
      ? `description with keyword${i}`
      : `misc-description-${i}`;
    const created: IDiscussionBoardChannel = await api.functional.discussionBoard.systematic.channels.post(connection, {
      body: { code, name, description } satisfies IDiscussionBoardChannel.ICreate,
    });
    typia.assert(created);
    channels.push(created);
  }

  // 2. 코드 일부로 keyword 검색 + 페이지네이션(page=1, limit=3)
  const codeKeyword = 'eco-keyword-';
  const codeSearch: IPageDiscussionBoardChannel = await api.functional.discussionBoard.systematic.channels.patch(connection, {
    body: {
      code: codeKeyword,
      pagination: { current: 1, limit: 3 },
    } satisfies IDiscussionBoardChannel.IRequest,
  });
  typia.assert(codeSearch);
  for (const c of codeSearch.data) {
    typia.assert(c);
    TestValidator.predicate('code matched keyword')(c.code.includes(codeKeyword));
  }
  TestValidator.equals('pagination.current')(codeSearch.pagination.current)(1);
  TestValidator.equals('pagination.limit')(codeSearch.pagination.limit)(3);
  TestValidator.equals('pagination.records')(codeSearch.pagination.records)(channels.length);

  // 3. 이름 일부로 keyword 검색 + 2페이지(2개씩) 검색
  const nameKeyword = 'KeywordMatch';
  const nameSearch: IPageDiscussionBoardChannel = await api.functional.discussionBoard.systematic.channels.patch(connection, {
    body: {
      name: nameKeyword,
      pagination: { current: 2, limit: 2 },
    } satisfies IDiscussionBoardChannel.IRequest,
  });
  typia.assert(nameSearch);
  for (const c of nameSearch.data) {
    typia.assert(c);
    TestValidator.predicate('name matched keyword')(c.name.includes(nameKeyword));
  }
  TestValidator.equals('pagination.current')(nameSearch.pagination.current)(2);
  TestValidator.equals('pagination.limit')(nameSearch.pagination.limit)(2);

  // 4. 일치하는게 없는 케이스(code, name, description 모두 미일치)
  const notFoundSearch: IPageDiscussionBoardChannel = await api.functional.discussionBoard.systematic.channels.patch(connection, {
    body: {
      code: 'ZZZZZZ-404',
      name: 'NoSuchName',
      description: 'NoSuchDesc',
      pagination: { current: 1, limit: 2 },
    } satisfies IDiscussionBoardChannel.IRequest,
  });
  typia.assert(notFoundSearch);
  TestValidator.equals('empty result')(notFoundSearch.data.length)(0);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IDiscussionBoardMention } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMention";
import type { IPageIDiscussionBoardMention } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardMention";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * actor_member_id와 mentioned_member_id 조합 필터의 언급(@mention) 목록 검증
 *
 * 이 테스트는 세 명의 멤버(A, B, C)를 생성하고,
 * 이들 사이에서 다양한 조합(서로 혹은 자기 자신을 언급)으로 mention을 생성한 뒤,
 * actor_member_id, mentioned_member_id, 둘 다로 필터 시 의도한 mention만 반환되는지 검증합니다.
 *
 * 1. 멤버 A, 멤버 B, 멤버 C를 생성합니다.
 * 2. 다음과 같이 CROSS-mention 데이터 5개를 만듭니다:
 *    - A가 B를 thread에서 언급
 *    - A가 C를 post에서 언급
 *    - B가 A를 comment에서 언급
 *    - C가 B를 thread에서 언급
 *    - C가 C를 post에서 언급(셀프 언급)
 * 3. 각 멤버에 대해:
 *    - actor_member_id로만 필터: 해당 멤버가 actor인 mention만 반환되는지 검증
 *    - mentioned_member_id로만 필터: 해당 멤버가 언급받은 mention만 반환되는지 검증
 *    - 둘 다로 필터: 자기 자신을 언급한 mention만 반환되는지 검증
 */
export async function test_api_discussionBoard_notifications_mentions_test_list_mentions_actor_and_target_filters(
  connection: api.IConnection,
) {
  // 1. 멤버 3명 생성(A, B, C)
  const passwordHash = RandomGenerator.alphaNumeric(32);
  const members = await ArrayUtil.asyncRepeat(3)(async () =>
    api.functional.discussionBoard.actors.members.post(connection, {
      body: {
        username: RandomGenerator.alphaNumeric(8),
        email: typia.random<string & tags.Format<"email">>(),
        hashed_password: passwordHash,
        display_name: RandomGenerator.name(),
        profile_image_url: null,
        is_active: true,
      },
    }),
  );
  members.forEach(typia.assert);
  const [A, B, C] = members;

  // 2. 언급(CROSS-mention) 데이터 생성
  const [mention1, mention2, mention3, mention4, mention5] = await Promise.all([
    // A -> B (thread)
    api.functional.discussionBoard.notifications.mentions.post(connection, {
      body: {
        mentioned_member_id: B.id,
        actor_member_id: A.id,
        content_type: 'thread',
        content_id: typia.random<string & tags.Format<"uuid">>(),
        created_at: new Date().toISOString(),
      },
    }),
    // A -> C (post)
    api.functional.discussionBoard.notifications.mentions.post(connection, {
      body: {
        mentioned_member_id: C.id,
        actor_member_id: A.id,
        content_type: 'post',
        content_id: typia.random<string & tags.Format<"uuid">>(),
        created_at: new Date().toISOString(),
      },
    }),
    // B -> A (comment)
    api.functional.discussionBoard.notifications.mentions.post(connection, {
      body: {
        mentioned_member_id: A.id,
        actor_member_id: B.id,
        content_type: 'comment',
        content_id: typia.random<string & tags.Format<"uuid">>(),
        created_at: new Date().toISOString(),
      },
    }),
    // C -> B (thread)
    api.functional.discussionBoard.notifications.mentions.post(connection, {
      body: {
        mentioned_member_id: B.id,
        actor_member_id: C.id,
        content_type: 'thread',
        content_id: typia.random<string & tags.Format<"uuid">>(),
        created_at: new Date().toISOString(),
      },
    }),
    // C -> C (post)
    api.functional.discussionBoard.notifications.mentions.post(connection, {
      body: {
        mentioned_member_id: C.id,
        actor_member_id: C.id,
        content_type: 'post',
        content_id: typia.random<string & tags.Format<"uuid">>(),
        created_at: new Date().toISOString(),
      },
    }),
  ]);
  [mention1, mention2, mention3, mention4, mention5].forEach(typia.assert);

  // 3. 필터 조합별 결과 검증
  for (const member of members) {
    // actor_member_id 필터만
    const filteredByActor = await api.functional.discussionBoard.notifications.mentions.patch(connection, {
      body: { actor_member_id: member.id },
    });
    typia.assert(filteredByActor);
    TestValidator.predicate(`actor_member_id 필터: ${member.username}이 actor인 mention만 리턴`)(
      filteredByActor.data.every(m => m.actor_member_id === member.id)
    );

    // mentioned_member_id 필터만
    const filteredByMentioned = await api.functional.discussionBoard.notifications.mentions.patch(connection, {
      body: { mentioned_member_id: member.id },
    });
    typia.assert(filteredByMentioned);
    TestValidator.predicate(`mentioned_member_id 필터: ${member.username}이 언급된 mention만 리턴`)(
      filteredByMentioned.data.every(m => m.mentioned_member_id === member.id)
    );

    // 둘 다 필터(자기 자신을 언급한 경우만)
    const filteredByBoth = await api.functional.discussionBoard.notifications.mentions.patch(connection, {
      body: { actor_member_id: member.id, mentioned_member_id: member.id },
    });
    typia.assert(filteredByBoth);
    TestValidator.predicate(`actor+mentioned 필터: ${member.username}이 자기 자신만 언급한 mention만 리턴`)(
      filteredByBoth.data.every(m => m.actor_member_id === member.id && m.mentioned_member_id === member.id)
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IDiscussionBoardThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardThread";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IPageIDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardComment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test comment list pagination per post for discussion board.
 *
 * This test covers the following workflow:
 * 1. Register a new test member.
 * 2. Create a new thread on the discussion board.
 * 3. Create a post inside that thread.
 * 4. Add multiple comments to the post – these will test pagination and return.
 * 5. Fetch the comments for the post using the PATCH endpoint with pagination parameters (limit/page) and verify:
 *    - Only the correct comments for the target post are returned
 *    - Comments are ordered as expected (by creation date desc by default)
 *    - Pagination meta (current, limit, records, pages) reflects the inserted count/params
 *    - No soft-deleted comments (deleted_at != null) are present in results
 *
 * Steps:
 *  - Generate and register a unique member
 *  - Create a thread (any category, test value)
 *  - Create a post by the member in the thread
 *  - Insert, e.g., 12 comments for the post (for 5-per-page pagination)
 *  - Fetch the first page (limit 5) and check top 5 are most recently created and are not deleted
 *  - Fetch all pages in a loop, collect, and verify all undeleted comments are present, in correct order, and count matches meta
 *  - Edge: request a page number beyond max and ensure empty result
 *
 * Note: If there's no soft-deletion comment endpoint, manually set a comment's deleted_at to simulate (skip this if impossible).
 */
export async function test_api_discussionBoard_test_list_comments_by_post_id_pagination(
  connection: api.IConnection,
) {
  // 1. Register a member
  const member = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: RandomGenerator.email(),
      hashed_password: RandomGenerator.alphaNumeric(40),
      display_name: RandomGenerator.name(),
      is_active: true,
      profile_image_url: null,
    } satisfies IdiscussionBoardMembers.ICreate,
  });
  typia.assert(member);

  // 2. Create a new thread
  const thread = await api.functional.discussionBoard.articles.threads.post(connection, {
    body: {
      discussion_board_category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(1),
      body: RandomGenerator.paragraph()(),
      is_pinned: false,
      is_closed: false,
    } satisfies IDiscussionBoardThread.ICreate,
  });
  typia.assert(thread);

  // 3. Create a post by the member in the thread
  const post = await api.functional.discussionBoard.articles.posts.post(connection, {
    body: {
      discussion_board_thread_id: thread.id,
      discussion_board_member_id: member.id,
      body: RandomGenerator.content()()(),
    } satisfies IDiscussionBoardPost.ICreate,
  });
  typia.assert(post);

  // 4. Insert 12 comments for the post
  const comments: IDiscussionBoardComment[] = [];
  for (let i = 0; i < 12; ++i) {
    const comment = await api.functional.discussionBoard.articles.comments.post(connection, {
      body: {
        discussion_board_post_id: post.id,
        discussion_board_member_id: member.id,
        body: `Comment content ${i + 1}`,
      } satisfies IDiscussionBoardComment.ICreate,
    });
    typia.assert(comment);
    comments.push(comment);
  }
  // Sort expected comments by creation time descending (latest first)
  const commentsSorted = [...comments].sort((a, b) => b.created_at.localeCompare(a.created_at));

  // 5. Retrieve comments via the PATCH endpoint, limit 5
  const page1 = await api.functional.discussionBoard.articles.comments.patch(connection, {
    body: {
      discussion_board_post_id: post.id,
      page: 1,
      limit: 5,
      sort: "created_at",
      order: "desc",
      deleted: false,
    } satisfies IDiscussionBoardComment.IListRequest,
  });
  typia.assert(page1);

  // Validate page1: 5 newest comments, correct pagination
  TestValidator.equals("first page count")(page1.data.length)(5);
  TestValidator.equals("first page meta")(page1.pagination.current)(1);
  TestValidator.equals("first page meta limit")(page1.pagination.limit)(5);
  TestValidator.equals("first page total")(page1.pagination.records)(12);
  TestValidator.equals("first page pages")(page1.pagination.pages)(Math.ceil(12 / 5));
  for (let i = 0; i < 5; ++i)
    TestValidator.equals(`comment order[${i}]`)(page1.data[i].id)(commentsSorted[i].id);
  for (const c of page1.data)
    TestValidator.equals("not soft deleted")(c.deleted_at)(null);

  // 6. Fetch all pages and collect ids
  const allCollected: IDiscussionBoardComment[] = [];
  for (let page = 1; page <= page1.pagination.pages; ++page) {
    const pg = await api.functional.discussionBoard.articles.comments.patch(connection, {
      body: {
        discussion_board_post_id: post.id,
        page,
        limit: 5,
        sort: "created_at",
        order: "desc",
        deleted: false,
      } satisfies IDiscussionBoardComment.IListRequest,
    });
    typia.assert(pg);
    for (const c of pg.data)
      allCollected.push(c);
  }
  // All collected should match sorted and not include soft-deleted
  TestValidator.equals("all collected length")(allCollected.length)(12);
  for (let i = 0; i < commentsSorted.length; ++i)
    TestValidator.equals(`comment id[${i}]`)(allCollected[i].id)(commentsSorted[i].id);

  // 7. Edge: Fetch page beyond range returns empty list
  const beyond = await api.functional.discussionBoard.articles.comments.patch(connection, {
    body: {
      discussion_board_post_id: post.id,
      page: 10,
      limit: 5,
      sort: "created_at",
      order: "desc",
      deleted: false,
    } satisfies IDiscussionBoardComment.IListRequest,
  });
  typia.assert(beyond);
  TestValidator.equals("beyond-page-empty")(beyond.data.length)(0);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IdiscussionBoardModerators } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardModerators";
import type { IModerationWarning } from "@ORGANIZATION/PROJECT-api/lib/structures/IModerationWarning";

/**
 * 경고 레코드 업데이트 시 비허용 필드(id, deleted_at 등)가 거부됨을 검증합니다.
 *
 * - 비즈니스 맥락: 경고 레코드(경고장)는 일부 필드만 업데이트 가능하며, 기본키(id)나 소프트 삭제 deleted_at 등은 update 엔드포인트에서 변경 불가합니다. 스키마 상 IModerationWarning.IUpdate에 없는 필드는 요청에서 허용되지 않아야 하며, API는 이런 시도에 에러를 반환해야 합니다.
 * - 목적: 경고 생성/모더레이터 할당까지 시나리오를 완결해 유효한 경고를 만들고, update 시 허용되지 않은 프로퍼티 추가 시 에러가 발생하는지, 유효 필드만 변경 시 정상 동작하는지 확인합니다.
 *
 * [테스트 절차]
 * 1. 유효한 member 등록 (username, email 등)
 * 2. 해당 멤버에 모더레이터 권한 할당
 * 3. 경고장 발급(member_id, moderator_id, warning_type, etc)
 * 4. 비허용 필드(id, deleted_at 포함) 추가하여 update 시도 ⇒ 에러 반환 검증(TestValidator.error)
 * 5. 정상 필드만으로 update(메시지, 유형 등 수정) 시 정상 반영됨을 검증
 */
export async function test_api_discussionBoard_test_update_warning_record_with_disallowed_fields(
  connection: api.IConnection,
) {
  // 1. 유효한 멤버 생성
  const memberInput = {
    username: RandomGenerator.alphaNumeric(10),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(32),
    display_name: RandomGenerator.name(),
    is_active: true,
    profile_image_url: null,
  } satisfies IdiscussionBoardMembers.ICreate;
  const member = await api.functional.discussionBoard.actors.members.post(connection, { body: memberInput });
  typia.assert(member);

  // 2. 모더레이터 권한 할당
  const moderatorInput = {
    member_id: member.id,
    assigned_at: new Date().toISOString(),
  } satisfies IdiscussionBoardModerators.ICreate;
  const moderator = await api.functional.discussionBoard.actors.moderators.post(connection, { body: moderatorInput });
  typia.assert(moderator);

  // 3. 경고장 발급
  const warningInput = {
    member_id: member.id,
    moderator_id: moderator.id,
    warning_type: "spam",
    message: "Do not post spam messages.",
    created_at: new Date().toISOString(),
    expires_at: null,
  } satisfies IModerationWarning.ICreate;
  const warning = await api.functional.discussionBoard.moderation.warnings.post(connection, { body: warningInput });
  typia.assert(warning);

  // 4. 비허용 필드 포함 update 시도 (명시적 타입 우회 테스트)
  await TestValidator.error("id 등 비허용 필드 포함 시 스키마 에러")(
    async () => {
      // @ts-expect-error: 테스트 목적으로 명시적 타입 우회(untyped object)
      await api.functional.discussionBoard.moderation.warnings.putById(connection, {
        id: warning.id,
        body: {
          warning_type: "scam",
          message: "Scam attempt.",
          id: warning.id, // 불가 필드
          deleted_at: new Date().toISOString(), // 불가 필드
        } as any, // 런타임 수준 schema 거부 검증
      });
    },
  );

  // 5. 허용 필드만 update 시 정상 수정됨
  const updateBody = {
    warning_type: "harassment",
    message: "Harassment - 2nd warning.",
    expires_at: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString(),
  } satisfies IModerationWarning.IUpdate;
  const updated = await api.functional.discussionBoard.moderation.warnings.putById(connection, {
    id: warning.id,
    body: updateBody,
  });
  typia.assert(updated);
  TestValidator.equals("warning_type 변경됨")(updated.warning_type)(updateBody.warning_type);
  TestValidator.equals("message 변경됨")(updated.message)(updateBody.message);
  TestValidator.equals("expires_at 변경됨")(updated.expires_at)(updateBody.expires_at);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IDiscussionBoardThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardThread";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";

/**
 * Validate that a discussion thread can be updated successfully by its creator.
 *
 * This test covers the full workflow from account and category creation to discussion thread creation and owned update. It ensures only schema-supported fields are changed, timestamps behave properly, and proper authorization is enforced for the editing user.
 *
 * Steps:
 * 1. Register a new member (author)
 * 2. Create a category
 * 3. Create a new thread in that category as the author
 * 4. Update title and body via update endpoint as the creator
 * 5. Validate returned attributes are updated, updated_at timestamp is recent, and non-schema fields are not returned
 * 6. Confirm member id (creator) remains unchanged after update
 */
export async function test_api_discussionBoard_test_update_thread_with_valid_attributes_by_creator(
  connection: api.IConnection,
) {
  // 1. Member account creation (author)
  const memberInput: IdiscussionBoardMembers.ICreate = {
    username: RandomGenerator.alphaNumeric(10),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(16),
    display_name: RandomGenerator.name(),
    is_active: true,
  };
  const author = await api.functional.discussionBoard.actors.members.post(connection, { body: memberInput });
  typia.assert(author);

  // 2. Create a category
  const categoryInput: IDiscussionBoardCategory.ICreate = {
    name: RandomGenerator.alphabets(8),
    description: RandomGenerator.paragraph()(),
  };
  const category = await api.functional.discussionBoard.categories.categories.post(connection, { body: categoryInput });
  typia.assert(category);

  // 3. Create initial discussion thread as author
  const threadInput: IDiscussionBoardThread.ICreate = {
    discussion_board_category_id: category.id,
    title: RandomGenerator.paragraph()(3),
    body: RandomGenerator.content()()(2),
    is_pinned: false,
    is_closed: false,
  };
  // Note: add required discussion_board_member_id property (from author)
  // even if ICreate doesn't show, endpoint expects full structure per post route
  const thread = await api.functional.discussionBoard.articles.threads.post(connection, { body: { ...threadInput, discussion_board_member_id: author.id } });
  typia.assert(thread);

  // Save original updated_at for comparison
  const originalUpdatedAt = thread.updated_at;

  // 4. Update the thread: change title and body
  const newTitle = RandomGenerator.paragraph()(1) + " (edited)";
  const newBody = RandomGenerator.content()()(2);
  const updateInput: IDiscussionBoardThread.IUpdate = {
    title: newTitle,
    body: newBody,
  };
  const updated = await api.functional.discussionBoard.articles.threads.putById(connection, { id: thread.id, body: updateInput });
  typia.assert(updated);

  // 5. Validate updated attributes and schema compliance
  TestValidator.notEquals("updated_at should change after update")(updated.updated_at)(originalUpdatedAt);
  TestValidator.equals("title updated")(updated.title)(newTitle);
  TestValidator.equals("body updated")(updated.body)(newBody);
  TestValidator.equals("creator id remains")(updated.discussion_board_member_id)(author.id);
  TestValidator.equals("category remains same")(updated.discussion_board_category_id)(category.id);
  TestValidator.predicate("updated_at is now or recent")(
    new Date(updated.updated_at).getTime() >= Date.now() - 1000 * 60 * 3,
  );

  // Confirm only schema fields are present
  const allowedFields = Object.keys(updated).sort();
  const schemaFields = [
    "id",
    "discussion_board_member_id",
    "discussion_board_category_id",
    "title",
    "body",
    "is_pinned",
    "is_closed",
    "created_at",
    "updated_at",
    "deleted_at",
  ].sort();
  TestValidator.equals("no extraneous fields")(allowedFields)(schemaFields);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IDiscussionBoardThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardThread";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IPageIDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardPost";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";

/**
 * Test filtering discussion board posts by a single member ID across multiple threads.
 *
 * This scenario verifies that the posts listing endpoint can correctly filter by the author's member ID even when posts are spread across different threads.
 * The steps imitate a real workflow:
 *   1. Create a member who will be authoring multiple posts.
 *   2. Create several categories (one per thread) to allow for thread distribution.
 *   3. For each category, create a separate discussion thread authored by the member.
 *   4. In each thread, create one or more posts by the same member (could be more than one post per thread to test robustness).
 *   5. List all posts using the posts PATCH endpoint, filtering by the member's id.
 *   6. Paginate the results (if total_post_count > page_size), iterate through pages if needed.
 *   7. Assert that:
 *         - Every returned post is authored by the target member
 *         - All created posts are eventually found among the paginated results
 */
export async function test_api_discussionBoard_test_list_posts_by_member_id_with_multiple_threads(
  connection: api.IConnection,
) {
  // 1. Create a member (author)
  const memberEmail: string = typia.random<string & tags.Format<"email">>();
  const memberUsername: string = RandomGenerator.alphaNumeric(10);
  const memberPassword: string = RandomGenerator.alphaNumeric(16);
  const memberDisplayName: string = RandomGenerator.name();

  const member = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: memberUsername,
      email: memberEmail,
      hashed_password: memberPassword,
      display_name: memberDisplayName,
      is_active: true,
      profile_image_url: null,
    },
  });
  typia.assert(member);

  // 2. Create multiple categories and threads
  const THREAD_COUNT = 3;
  const POSTS_PER_THREAD = 2;
  const categories = await Promise.all(
    ArrayUtil.repeat(THREAD_COUNT)(async (_, idx) => {
      const cat = await api.functional.discussionBoard.categories.categories.post(connection, {
        body: {
          name: `TestCat_${RandomGenerator.alphaNumeric(6)}`,
          description: `Test description ${idx}`,
        },
      });
      typia.assert(cat);
      return cat;
    }),
  );

  const threads = await Promise.all(
    categories.map(async (category, idx) => {
      const thread = await api.functional.discussionBoard.articles.threads.post(connection, {
        body: {
          discussion_board_category_id: category.id,
          title: `Test thread ${idx}`,
          body: `Thread body ${idx}`,
          is_pinned: false,
          is_closed: false,
        },
      });
      typia.assert(thread);
      return thread;
    }),
  );

  // 3. Create posts by the member in each thread
  const createdPostIds: Array<string> = [];
  for (const thread of threads) {
    for (let i = 0; i < POSTS_PER_THREAD; ++i) {
      const post = await api.functional.discussionBoard.articles.posts.post(connection, {
        body: {
          discussion_board_thread_id: thread.id,
          discussion_board_member_id: member.id,
          body: `Post body for thread ${thread.title}, post #${i}`,
        },
      });
      typia.assert(post);
      createdPostIds.push(post.id);
    }
  }

  // 4. List posts filtering by discussion_board_member_id
  let allRetrievedPostIds: Array<string> = [];
  let page = 1;
  const limit = 2; // Small limit to force pagination
  let totalPages = 1;
  do {
    const result = await api.functional.discussionBoard.articles.posts.patch(connection, {
      body: {
        page: page,
        limit: limit,
        discussion_board_member_id: member.id,
      },
    });
    typia.assert(result);
    TestValidator.predicate("all returned posts belong to the member")(
      result.data.every((p) => p.discussion_board_member_id === member.id),
    );
    allRetrievedPostIds.push(...result.data.map((p) => p.id));

    if (page === 1) totalPages = result.pagination.pages;
    page += 1;
  } while (page <= totalPages);

  // 5. Assert that all created post ids are found among the result
  for (const id of createdPostIds) {
    TestValidator.predicate(`created post with id ${id} was found in paginated results?`)(
      allRetrievedPostIds.includes(id),
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
