import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardGuests } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardGuests";

/**
 * 테스트 목적: 중복된 session_token으로 게스트 세션 생성 시 시스템이 고유성 제약(Unique Constraint)을 제대로 적용하는지 검증합니다.
 * 
 * 비즈니스 컨텍스트:
 * discussion_board_guests 테이블은 session_token의 중복을 허용하지 않으므로,
 * 이미 존재하는 session_token으로 다시 게스트 세션을 생성하려고 시도하면 고유성 위반 오류가 발생해야 합니다.
 * 이는 세션 추적 및 데이터 무결성 유지에 필수적입니다.
 * 
 * 테스트 시나리오 단계:
 * 1. 임의의 session_token으로 정상적인 게스트 세션을 생성한다.
 * 2. 동일한 session_token으로 한 번 더 생성 시도를 하여,
 *    시스템이 unique constraint violation 에러를 반환하는지 검증한다.
 */
export async function test_api_discussionBoard_test_create_guest_session_with_duplicate_session_token(
  connection: api.IConnection,
) {
  // 1. 테스트용 세션 정보 구성
  const sessionToken: string = RandomGenerator.alphabets(24);
  const ipAddress: string = "192.168.1." + typia.random<number & tags.Type<"uint8">>().toString();
  const userAgent: string = "Mozilla/5.0 (E2E-Test)";
  const expiresAt: string = new Date(Date.now() + 1000 * 60 * 60).toISOString();

  // 2. 첫 번째 세션 정상 생성
  const guest = await api.functional.discussionBoard.actors.guests.post(connection, {
    body: {
      session_token: sessionToken,
      ip_address: ipAddress,
      user_agent: userAgent,
      expires_at: expiresAt,
    },
  });
  typia.assert(guest);
  TestValidator.equals("session_token 일치")(guest.session_token)(sessionToken);
  TestValidator.equals("ip_address 일치")(guest.ip_address)(ipAddress);
  TestValidator.equals("user_agent 일치")(guest.user_agent)(userAgent);
  TestValidator.equals("expires_at 일치")(guest.expires_at)(expiresAt);

  // 3. 동일 session_token으로 중복 생성 시도 → 오류 발생해야 함
  await TestValidator.error("중복 session_token unique 제약 에러")(() =>
    api.functional.discussionBoard.actors.guests.post(connection, {
      body: {
        session_token: sessionToken,
        ip_address: ipAddress,
        user_agent: userAgent,
        expires_at: expiresAt,
      },
    })
  );
}

