import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IdiscussionBoardModerators } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardModerators";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";

/**
 * discussion_board_moderators 엔티티 업데이트 API의 밸리데이션 - 허용되지 않은 필드(id, member_id)나 타입/비즈니스 규칙 위반(revoked_at 잘못된 타입 또는 논리적 불가 시점 등) 업데이트 시도 시, 정상적으로 실패(에러)하는지 검증합니다.
 *
 * 1. 테스트용 회원을 생성합니다.
 * 2. 해당 회원에게 모더레이터 역할을 할당합니다.
 * 3. 아래와 같은 실패 케이스를 각각 검증합니다.
 *    a. 불변/허용되지 않은 필드(id, member_id 등)를 body에 포함하여 업데이트 시도 → 에러 발생해야 함
 *    b. revoked_at에 잘못된 타입(숫자 등)을 넣거나, revoked_at이 assigned_at보다 과거 등 논리 규칙을 위반한 값 입력 → 에러 발생해야 함
 *
 * 모든 실패 시나리오에서 TestValidator.error를 통해 명확하게 에러 검증을 수행합니다.
 */
export async function test_api_discussionBoard_actors_moderators_test_update_moderator_assignment_with_invalid_fields(
  connection: api.IConnection,
) {
  // 1. 테스트용 회원 생성 (의존성 시나리오: 멤버 계정 생성)
  const member = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphabets(10),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(32),
      display_name: RandomGenerator.name(),
      is_active: true,
    },
  });
  typia.assert(member);

  // 2. 해당 회원에 모더레이터 할당
  const moderator = await api.functional.discussionBoard.actors.moderators.post(connection, {
    body: {
      member_id: member.id,
      assigned_at: new Date().toISOString(),
    },
  });
  typia.assert(moderator);

  // 3a. 존재하지 않거나 불변 필드(id, member_id 등)를 업데이트 body에 포함시도 → 에러 발생
  await TestValidator.error("불변/비허용 필드(id, member_id)를 업데이트 시도하면 실패해야 한다")(() =>
    // @ts-expect-error: 타입 가드 우회 (에러 유발 목적)
    api.functional.discussionBoard.actors.moderators.putById(connection, {
      id: moderator.id,
      body: {
        id: typia.random<string & tags.Format<"uuid">>(),
        member_id: typia.random<string & tags.Format<"uuid">>(),
        assigned_at: new Date().toISOString(),
      },
    }),
  );

  // 3b. revoked_at 필드 타입/논리 밸리데이션 에러 검증
  // 타입 위반(숫자)
  await TestValidator.error("revoked_at 타입(숫자) 잘못 입력하면 실패해야 한다")(() =>
    // @ts-expect-error: 타입 무시 (schema validation error 유도)
    api.functional.discussionBoard.actors.moderators.putById(connection, {
      id: moderator.id,
      body: {
        revoked_at: 12345, // 잘못된 타입 (string & format: date-time이 아님)
      },
    }),
  );

  // revoked_at이 논리적으로 허용되지 않는 값(assigned_at보다 전 날짜)
  const assignedAt = new Date();
  const revokedAtInPast = new Date(assignedAt.getFullYear() - 10, assignedAt.getMonth(), assignedAt.getDate()).toISOString();
  await TestValidator.error("revoked_at이 assigned_at보다 과거면 실패해야 한다")(() =>
    api.functional.discussionBoard.actors.moderators.putById(connection, {
      id: moderator.id,
      body: {
        assigned_at: assignedAt.toISOString(),
        revoked_at: revokedAtInPast,
      },
    }),
  );
}

