 * Instead, test business-level errors: setting revoked_at earlier than assigned_at, setting fields to clearly invalid values, etc.
 *
 * Steps:
 * 1. Register a member
 * 2. Assign moderator record
 * 3. Try to update revoked_at to a date before assigned_at → should fail (runtime validation error)
 * 4. Try to update assigned_at to null (which is allowed by type, but likely forbidden in business logic) → check for error or acceptance as spec allows
 */
export async function test_api_discussionBoard_actors_moderators_test_update_moderator_assignment_with_invalid_fields(
  connection: api.IConnection,
) {
  // Step 1. Register new member
  const member = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphabets(10),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(32),
      display_name: RandomGenerator.name(),
      is_active: true,
    },
  });
