  // Step 2. Assign moderator
  const assigned_at = new Date();
  const moderator = await api.functional.discussionBoard.actors.moderators.post(connection, {
    body: {
      member_id: member.id,
      assigned_at: assigned_at.toISOString(),
    },
  });
  typia.assert(moderator);

  // Step 3. Attempt to set revoked_at before assigned_at (logical business rule violation)
  const revoked_at = new Date(assigned_at.getTime() - 86400000).toISOString(); // 1 day before assigned
  await TestValidator.error("revoked_at earlier than assigned_at should fail")(() =>
    api.functional.discussionBoard.actors.moderators.putById(connection, {
      id: moderator.id,
      body: {
        revoked_at,
        assigned_at: assigned_at.toISOString(),
      },
    }),
  );

  // Step 4. Attempt to set assigned_at to null if business logic forbids (allowed by type, but may be forbidden by business rules)
  await TestValidator.error("assigned_at set to null may be forbidden")(() =>
    api.functional.discussionBoard.actors.moderators.putById(connection, {
      id: moderator.id,
      body: {
        assigned_at: null,
      },
    }),
  );
}

