import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IDiscussionBoardThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardThread";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";

/**
 * Validate successful creation of a discussion thread by an authenticated member.
 *
 * This test verifies that a member can create a top-level (root) discussion thread
 * after signing up, ensuring all required and optional fields are respected, and
 * that security rules block unauthenticated access. Test covers business flow,
 * atomic field population, and essential authorization logic.
 *
 * Step-by-step process:
 * 1. Create a category to assign as the discussion_board_category_id.
 * 2. Register a member to be the authentic thread creator.
 * 3. Attempt to create a thread (providing valid discussion_board_member_id, category id, title, body, is_pinned, is_closed).
 *     - Validate all atomic fields are present; assert key data matches input.
 * 4. Confirm access control:
 *     - Try to create a thread using an unauthenticated connection and assert it fails.
 */
export async function test_api_discussionBoard_test_create_thread_success_all_required_fields(
  connection: api.IConnection,
) {
  // 1. Create a category for assignment
  const category = await api.functional.discussionBoard.categories.categories.post(connection, {
    body: {
      name: RandomGenerator.alphabets(8),
      description: RandomGenerator.paragraph()(),
    },
  });
  typia.assert(category);

  // 2. Register a member to be the thread creator
  const email = typia.random<string & tags.Format<"email">>();
  const username = RandomGenerator.alphaNumeric(10);
  const member = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username,
      email,
      hashed_password: RandomGenerator.alphaNumeric(32),
      display_name: RandomGenerator.name(),
      profile_image_url: null,
      is_active: true,
    },
  });
  typia.assert(member);

  // 3. Create thread (authenticated)
  const threadInput = {
    discussion_board_category_id: category.id,
    title: RandomGenerator.paragraph()(),
    body: RandomGenerator.content()()(),
    is_pinned: true,
    is_closed: false,
  } satisfies IDiscussionBoardThread.ICreate;
  const thread = await api.functional.discussionBoard.articles.threads.post(connection, { body: threadInput });
  typia.assert(thread);
  TestValidator.equals("category id on thread")(thread.discussion_board_category_id)(category.id);
  TestValidator.equals("title")(thread.title)(threadInput.title);
  TestValidator.equals("is_pinned")(thread.is_pinned)(true);
  TestValidator.equals("is_closed")(thread.is_closed)(false);
  TestValidator.equals("thread body")(thread.body)(threadInput.body);

  // 4. Attempt to create thread as unauthenticated/anonymous (should fail)
  const anonymousConnection = { ...connection, headers: { ...connection.headers, Authorization: undefined } };
  await TestValidator.error("unauthenticated cannot create thread")(() =>
    api.functional.discussionBoard.articles.threads.post(anonymousConnection, { body: threadInput }),
  );
}

