import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IDiscussionBoardThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardThread";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";

/**
 * Test thread creation fails for invalid or non-existent category/member IDs (foreign key integrity).
 *
 * Verifies: The API correctly enforces foreign key/ownership integrity by refusing thread creation
 * when an invalid (non-existent) discussion_board_category_id or discussion_board_member_id is supplied.
 *
 * Business context: Ensures that the system reliably prevents orphaned threads and data integrity is maintained
 * when clients attempt to use random UUIDs that do not correspond to real member or category records.
 *
 * Test steps:
 * 1. Create a valid category and a valid member for use as controls.
 * 2. Attempt thread creation with a non-existent category but valid member: must fail (error expected).
 * 3. Attempt thread creation with a valid category but non-existent member: must fail (error expected).
 * 4. Attempt thread creation with both IDs non-existent: must fail (error expected).
 * 5. (Control) Attempt thread creation with valid member and category: must succeed, and check links.
 */
export async function test_api_discussionBoard_test_create_thread_invalid_or_nonexistent_category_or_member(
  connection: api.IConnection,
) {
  // 1. Create a valid discussion board category
  const category = await api.functional.discussionBoard.categories.categories.post(connection, {
    body: {
      name: RandomGenerator.paragraph()(1),
      description: RandomGenerator.content()()(1),
    } satisfies IDiscussionBoardCategory.ICreate,
  });
  typia.assert(category);

  // 2. Create a valid discussion board member
  const member = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(32),
      display_name: RandomGenerator.name(),
      is_active: true,
    } satisfies IdiscussionBoardMembers.ICreate,
  });
  typia.assert(member);

  const fakeCategoryId = typia.random<string & tags.Format<"uuid">>();
  const fakeMemberId = typia.random<string & tags.Format<"uuid">>();

  // 3. Try: valid member, non-existent category (should error)
  await TestValidator.error("thread creation fails for non-existent category")(() =>
    api.functional.discussionBoard.articles.threads.post(connection, {
      body: {
        discussion_board_category_id: fakeCategoryId,
        title: RandomGenerator.paragraph()(1),
        body: RandomGenerator.content()()(1),
        is_pinned: false,
        is_closed: false,
        discussion_board_member_id: member.id,
      } satisfies IDiscussionBoardThread.ICreate,
    })
  );

  // 4. Try: valid category, non-existent member (should error)
  await TestValidator.error("thread creation fails for non-existent member")(() =>
    api.functional.discussionBoard.articles.threads.post(connection, {
      body: {
        discussion_board_category_id: category.id,
        title: RandomGenerator.paragraph()(1),
        body: RandomGenerator.content()()(1),
        is_pinned: false,
        is_closed: false,
        discussion_board_member_id: fakeMemberId,
      } satisfies IDiscussionBoardThread.ICreate,
    })
  );

  // 5. Try: both category and member non-existent (should error)
  await TestValidator.error("thread creation fails for both IDs non-existent")(() =>
    api.functional.discussionBoard.articles.threads.post(connection, {
      body: {
        discussion_board_category_id: fakeCategoryId,
        title: RandomGenerator.paragraph()(1),
        body: RandomGenerator.content()()(1),
        is_pinned: false,
        is_closed: false,
        discussion_board_member_id: fakeMemberId,
      } satisfies IDiscussionBoardThread.ICreate,
    })
  );

  // 6. (Control) Try: all valid references (should succeed)
  const thread = await api.functional.discussionBoard.articles.threads.post(connection, {
    body: {
      discussion_board_category_id: category.id,
      title: RandomGenerator.paragraph()(1),
      body: RandomGenerator.content()()(1),
      is_pinned: false,
      is_closed: false,
      discussion_board_member_id: member.id,
    } satisfies IDiscussionBoardThread.ICreate,
  });
  typia.assert(thread);
  TestValidator.equals("category ID matches")(thread.discussion_board_category_id)(category.id);
  TestValidator.equals("member ID matches")(thread.discussion_board_member_id)(member.id);
}

