import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IDiscussionBoardThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardThread";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { discussion_board_vote_types } from "@ORGANIZATION/PROJECT-api/lib/structures/discussion_board_vote_types";
import type { discussion_board_votes } from "@ORGANIZATION/PROJECT-api/lib/structures/discussion_board_votes";
import type { IPageDiscussion_board_votes } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageDiscussion_board_votes";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate paginated vote listings with multiple filters on voter, vote type, and voting targets (thread/post/comment).
 *
 * This test covers the following workflow:
 * 1. Create multiple board members to serve as voters.
 * 2. Create several vote types (e.g., upvote, downvote, funny).
 * 3. Create a set of threads (for thread vote targets).
 * 4. Create several posts under those threads (for post vote targets).
 * 5. Create a set of comments under posts (for comment vote targets).
 * 6. Cast many votes: distribute them among all vote types, all voters, and across all three possible target types (thread, post, comment).
 * 7. For each combination of filter (e.g. by voter, by vote_type, by target type):
 *    - List votes via PATCH /discussionBoard/votes/votes, filtered by the given parameter.
 *    - Verify that the returned votes match the query filter.
 *    - Verify pagination meta matches actual data (correct count, page, etc.)
 * 8. Additionally, test combined filters (e.g. voter_id + vote_type_id, or thread_id + vote_type_id).
 * 9. Also verify pagination behavior (limit and offset via page and limit fields).
 * 10. Negative/edge: filter that returns no results yields an empty array and correct pagination.
 *
 * Ensures vote search/list endpoint supports all core filtering, and pagination structures.
 */
export async function test_api_discussionBoard_votes_test_list_votes_with_filtering_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create 3 test members to use as voters.
  const members = await Promise.all(ArrayUtil.repeat(3)(async () => {
    const data = {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(12),
      display_name: RandomGenerator.name(),
      is_active: true,
    } satisfies IdiscussionBoardMembers.ICreate;
    const member = await api.functional.discussionBoard.actors.members.post(connection, { body: data });
    typia.assert(member);
    return member;
  }));

  // 2. Create 3 vote types (upvote, downvote, funny)
  const voteTypes = await Promise.all([
    { code: "upvote", name: "Upvote" },
    { code: "downvote", name: "Downvote" },
    { code: "funny", name: "Funny" },
  ].map(async vt => {
    const body = { ...vt, description: `${vt.name} vote` } satisfies discussion_board_vote_types.ICreate;
    const vtRes = await api.functional.discussionBoard.votes.voteTypes.post(connection, { body });
    typia.assert(vtRes);
    return vtRes;
  }));

  // 3. Create 2 threads with random category ids (category creation is out of scope for this API)
  const threads = await Promise.all(ArrayUtil.repeat(2)(async () => {
    const data = {
      discussion_board_category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(1),
      body: RandomGenerator.content()()(),
      is_pinned: false,
      is_closed: false,
    } satisfies IDiscussionBoardThread.ICreate;
    const thread = await api.functional.discussionBoard.articles.threads.post(connection, { body: data });
    typia.assert(thread);
    return thread;
  }));

  // 4. Create 2 posts in each thread by a random member
  const posts: IDiscussionBoardPost[] = [];
  for (const thread of threads) {
    for (let i = 0; i < 2; ++i) {
      const data = {
        discussion_board_thread_id: thread.id,
        discussion_board_member_id: RandomGenerator.pick(members).id,
        body: RandomGenerator.paragraph()(1),
      } satisfies IDiscussionBoardPost.ICreate;
      const post = await api.functional.discussionBoard.articles.posts.post(connection, { body: data });
      typia.assert(post);
      posts.push(post);
    }
  }

  // 5. Create 2 comments for each post by a random member
  const comments: IDiscussionBoardComment[] = [];
  for (const post of posts) {
    for (let i = 0; i < 2; ++i) {
      const data = {
        discussion_board_post_id: post.id,
        discussion_board_member_id: RandomGenerator.pick(members).id,
        body: RandomGenerator.content()()(),
      } satisfies IDiscussionBoardComment.ICreate;
      const comment = await api.functional.discussionBoard.articles.comments.post(connection, { body: data });
      typia.assert(comment);
      comments.push(comment);
    }
  }

  // 6. Cast 20 votes using random combinations to threads, posts, and comments.
  const allTargets = [
    ...threads.map(thread => ({ kind: "thread", id: thread.id })),
    ...posts.map(post => ({ kind: "post", id: post.id })),
    ...comments.map(comment => ({ kind: "comment", id: comment.id })),
  ];
  const allVotes: discussion_board_votes[] = [];
  await Promise.all(ArrayUtil.asyncRepeat(20)(async () => {
    const voteType = RandomGenerator.pick(voteTypes);
    const voter = RandomGenerator.pick(members);
    const target = RandomGenerator.pick(allTargets);
    // Only one of thread_id, post_id, comment_id is set for a single vote
    const input: discussion_board_votes.ICreate = {
      voter_id: voter.id,
      vote_type_id: voteType.id,
      thread_id: target.kind === "thread" ? target.id : undefined,
      post_id: target.kind === "post" ? target.id : undefined,
      comment_id: target.kind === "comment" ? target.id : undefined,
    };
    const created = await api.functional.discussionBoard.votes.votes.post(connection, { body: input });
    typia.assert(created);
    allVotes.push(created);
    return created;
  }));

  // --- Helper for verifying vote listing logic ---
  async function queryAndCheck(
    filter: Partial<discussion_board_votes.IRequest>,
    expectFilter: (v: discussion_board_votes) => boolean,
    testTitle: string,
    page?: number,
    limit?: number
  ) {
    const req: discussion_board_votes.IRequest = { ...filter, page, limit };
    const response = await api.functional.discussionBoard.votes.votes.patch(connection, { body: req });
    typia.assert(response);
    // Each result must match filter condition
    TestValidator.predicate(`${testTitle}: data matches filter`)(response.data.every(expectFilter));
    // Pagination record count is correct
    const actualTotal = allVotes.filter(expectFilter).length;
    TestValidator.equals(`${testTitle}: total records`)(response.pagination.records)(actualTotal);
    if (typeof limit === "number") {
      // Number of records on page matches min(limit, leftover)
      const skip = (page ? page - 1 : 0) * limit;
      const expectedLength = Math.max(Math.min(limit, Math.max(actualTotal - skip, 0)), 0);
      TestValidator.equals(`${testTitle}: per page limit`)(response.data.length)(expectedLength);
    }
  }
  // 7. Query single field filters
  for (const member of members) {
    await queryAndCheck({ voter_id: member.id }, v => v.voter_id === member.id, `Filter by voter_id=${member.id}`);
  }
  for (const vt of voteTypes) {
    await queryAndCheck({ vote_type_id: vt.id }, v => v.vote_type_id === vt.id, `Filter by vote_type_id=${vt.id}`);
  }
  for (const thread of threads) {
    await queryAndCheck({ thread_id: thread.id }, v => v.thread_id === thread.id, `Filter by thread_id=${thread.id}`);
  }
  for (const post of posts) {
    await queryAndCheck({ post_id: post.id }, v => v.post_id === post.id, `Filter by post_id=${post.id}`);
  }
  for (const comment of comments) {
    await queryAndCheck({ comment_id: comment.id }, v => v.comment_id === comment.id, `Filter by comment_id=${comment.id}`);
  }
  // Combined filters: voter+voteType
  for (const member of members) {
    const vt = RandomGenerator.pick(voteTypes);
    await queryAndCheck({ voter_id: member.id, vote_type_id: vt.id }, v => v.voter_id === member.id && v.vote_type_id === vt.id, `Filter by voter_id+vote_type_id`);
  }
  // Combined filters: thread+voteType
  for (const thread of threads) {
    const vt = RandomGenerator.pick(voteTypes);
    await queryAndCheck({ thread_id: thread.id, vote_type_id: vt.id }, v => v.thread_id === thread.id && v.vote_type_id === vt.id, `Filter by thread_id+vote_type_id`);
  }
  // Pagination checks
  await queryAndCheck({}, () => true, "No filter, page 1 limit 5", 1, 5);
  await queryAndCheck({}, () => true, "No filter, page 2 limit 5", 2, 5);

  // 10. Negative: a voter_id not in data yields no results
  const fakeUUID = typia.random<string & tags.Format<"uuid">>();
  await queryAndCheck({ voter_id: fakeUUID }, v => false, "Nonexistent voter_id, expect empty result");
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IDiscussionBoardThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardThread";
import type { IDiscussionBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReport";
import type { IPageIDiscussionBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardReport";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test listing and searching moderation reports (discussion_board_reports) with advanced filtering and pagination.
 *
 * Business context: This test simulates a typical moderator workflow, covering the dashboard/report management UI needs. It validates that:
 *   - Reports can be filtered by reporter, status, target type (thread), reason substring, and creation date.
 *   - Combination filters work as expected.
 *   - Pagination works and data segmentation is accurate.
 *   - Total counts, data accuracy, and integrity are preserved.
 *
 * Process:
 * 1. Create 3 unique members (A, B, C), using distinct usernames/emails (diverse test pool).
 * 2. Create 3 threads, each authored by a different member.
 * 3. Create 5 reports, mixing reporter, thread, status, and reason (with repetition for substring searches).
 * 4. List all reports: verify all are present and pagination metadata is correct.
 * 5. Filter reports by reporter_member_id.
 * 6. Filter by thread_id.
 * 7. Filter by status.
 * 8. Filter by reason substring ("욕설" appears in >=2 reports).
 * 9. Filter with reporter + status combined.
 * 10. Verify pagination with page/limit (multiple pages if reports > 2).
 * 11. Assert empty case returns for non-match filter values.
 */
export async function test_api_discussionBoard_moderation_reports_test_list_reports_with_pagination_and_filtering(
  connection: api.IConnection,
) {
  // Step 1: Create 3 unique members
  const members = await ArrayUtil.asyncRepeat(3)(async () => {
    const email = typia.random<string & tags.Format<"email">>();
    const member = await api.functional.discussionBoard.actors.members.post(connection, {
      body: {
        username: RandomGenerator.alphaNumeric(8),
        email,
        hashed_password: RandomGenerator.alphaNumeric(16),
        display_name: RandomGenerator.name(),
        profile_image_url: null,
        is_active: true,
      } satisfies IdiscussionBoardMembers.ICreate,
    });
    typia.assert(member);
    return member;
  });

  // Step 2: Create 3 threads, each authored by a different member
  const category_id = typia.random<string & tags.Format<"uuid">>();
  const threads = await ArrayUtil.asyncRepeat(3)(async (i) => {
    const thread = await api.functional.discussionBoard.articles.threads.post(connection, {
      body: {
        discussion_board_category_id: category_id,
        title: RandomGenerator.paragraph()(1),
        body: RandomGenerator.content()(1)(1),
        is_pinned: false,
        is_closed: false,
        discussion_board_member_id: members[i].id,
      } satisfies IDiscussionBoardThread.ICreate as any, // casting for extra member field actually required by API
    });
    typia.assert(thread);
    return thread;
  });

  // Step 3: Create 5 reports for diversity and repeatable reasons
  const reasons = ["욕설", "스팸", "욕설", "광고", "욕설"];
  const statuses = ["pending", "under_review", "resolved", "pending", "pending"];
  const reports = [];
  for (let i = 0; i < 5; ++i) {
    const reporter = members[i % 3];
    const thread = threads[i % 3];
    const report = await api.functional.discussionBoard.moderation.reports.post(connection, {
      body: {
        reporter_member_id: reporter.id,
        thread_id: thread.id,
        post_id: null,
        comment_id: null,
        reason: reasons[i],
        status: statuses[i],
      } satisfies IDiscussionBoardReport.ICreate,
    });
    typia.assert(report);
    reports.push(report);
  }

  // Step 4: List all reports, no filters
  const allResult = await api.functional.discussionBoard.moderation.reports.patch(connection, {
    body: { page: 1, limit: 10 } satisfies IDiscussionBoardReport.IRequest,
  });
  typia.assert(allResult);
  TestValidator.equals("all matched count")(allResult.pagination.records)(reports.length);

  // Step 5: reporter_member_id filtering
  for (const member of members) {
    const filtered = reports.filter((r) => r.reporter_member_id === member.id);
    if (filtered.length === 0) continue;
    const res = await api.functional.discussionBoard.moderation.reports.patch(connection, {
      body: { reporter_member_id: member.id, page: 1, limit: 10 } satisfies IDiscussionBoardReport.IRequest,
    });
    typia.assert(res);
    for (const r of res.data)
      TestValidator.equals("reporter matches")(r.reporter_member_id)(member.id);
    TestValidator.equals("member count matches")(res.pagination.records)(filtered.length);
  }

  // Step 6: thread_id filtering
  for (const thread of threads) {
    const filtered = reports.filter((r) => r.thread_id === thread.id);
    if (filtered.length === 0) continue;
    const res = await api.functional.discussionBoard.moderation.reports.patch(connection, {
      body: { thread_id: thread.id, page: 1, limit: 10 } satisfies IDiscussionBoardReport.IRequest,
    });
    typia.assert(res);
    for (const r of res.data)
      TestValidator.equals("thread matches")(r.thread_id)(thread.id);
    TestValidator.equals("thread count matches")(res.pagination.records)(filtered.length);
  }

  // Step 7: status filtering
  for (const status of [...new Set(reports.map((r) => r.status))]) {
    const filtered = reports.filter((r) => r.status === status);
    if (filtered.length === 0) continue;
    const res = await api.functional.discussionBoard.moderation.reports.patch(connection, {
      body: { status, page: 1, limit: 10 } satisfies IDiscussionBoardReport.IRequest,
    });
    typia.assert(res);
    for (const r of res.data)
      TestValidator.equals("status matches")(r.status)(status);
    TestValidator.equals("status count matches")(res.pagination.records)(filtered.length);
  }

  // Step 8: Reason substring filter
  const reasonSub = "욕설";
  const reasonFiltered = reports.filter((r) => r.reason.includes(reasonSub));
  if (reasonFiltered.length) {
    const res = await api.functional.discussionBoard.moderation.reports.patch(connection, {
      body: { reason: reasonSub, page: 1, limit: 10 } satisfies IDiscussionBoardReport.IRequest,
    });
    typia.assert(res);
    for (const r of res.data)
      TestValidator.predicate("reason contains")(r.reason.includes(reasonSub));
    TestValidator.equals("reason count matches")(res.pagination.records)(reasonFiltered.length);
  }

  // Step 9: reporter + status combined filter
  for (const member of members) {
    for (const status of [...new Set(reports.map((r) => r.status))]) {
      const filtered = reports.filter((r) => r.reporter_member_id === member.id && r.status === status);
      if (filtered.length === 0) continue;
      const res = await api.functional.discussionBoard.moderation.reports.patch(connection, {
        body: { reporter_member_id: member.id, status, page: 1, limit: 10 } satisfies IDiscussionBoardReport.IRequest,
      });
      typia.assert(res);
      for (const r of res.data) {
        TestValidator.equals("member status match")(r.reporter_member_id)(member.id);
        TestValidator.equals("status match")(r.status)(status);
      }
      TestValidator.equals("combo count matches")(res.pagination.records)(filtered.length);
    }
  }

  // Step 10: pagination segment test (limit=2)
  const pageRes = await api.functional.discussionBoard.moderation.reports.patch(connection, {
    body: { page: 1, limit: 2 } satisfies IDiscussionBoardReport.IRequest,
  });
  typia.assert(pageRes);
  TestValidator.equals("pagination.limit")(pageRes.pagination.limit)(2);
  TestValidator.equals("pagination.page")(pageRes.pagination.current)(1);
  TestValidator.equals("pagination.records")(pageRes.pagination.records)(reports.length);
  TestValidator.equals("page data length")(pageRes.data.length)(2);

  if (reports.length > 2) {
    const nextPageRes = await api.functional.discussionBoard.moderation.reports.patch(connection, {
      body: { page: 2, limit: 2 } satisfies IDiscussionBoardReport.IRequest,
    });
    typia.assert(nextPageRes);
    TestValidator.equals("pagination.page2")(nextPageRes.pagination.current)(2);
    // Should not overlap with previous page's report ids
    pageRes.data.forEach((item) => {
      TestValidator.predicate("no overlap")(nextPageRes.data.every((r2) => r2.id !== item.id));
    });
  }

  // Step 11: Edge: filter with no hits returns valid empty set
  const resNone = await api.functional.discussionBoard.moderation.reports.patch(connection, {
    body: { status: "nonexistentstatus", page: 1, limit: 10 } satisfies IDiscussionBoardReport.IRequest,
  });
  typia.assert(resNone);
  TestValidator.equals("no result count")(resNone.pagination.records)(0);
  TestValidator.equals("empty result")(resNone.data.length)(0);
}

