/**
 * 멤버 display_name, profile_image_url, is_active의 정상 업데이트 검증
 *
 * [비즈니스 맥락]
 * - 어드민이 멤버의 공개용 별명(display_name), 프로필 이미지 URL, 활성/비활성 상태(is_active)를 변경할 수 있어야 함
 * - 변경 후 해당 값들이 응답에 올바르게 반영되는지, 실제로 변경됨을 확인
 *
 * [테스트 절차]
 * 1. POST /discussionBoard/actors/members로 신규 멤버 계정 등록 (필수 필드 입력)
 * 2. PUT /discussionBoard/actors/members/{id}로 display_name, profile_image_url, is_active를 수정
 * 3. 응답 결과에 수정된 값들이 실제 반영됐는지 확인
 * 4. id, 불변 필드 정합성 체크 및 변경 전/후 값 차이 검증
 * 5. (Soft deleted 멤버에 대한 업데이트 금지 케이스는 본 테스트에서는 다루지 않음)
 */
export async function test_api_discussionBoard_actors_members_test_update_member_display_name_profile_image_and_activation_status_success(
  connection: api.IConnection,
) {
  // 1. 신규 멤버 등록
  const createInput: IdiscussionBoardMembers.ICreate = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(30),
    display_name: RandomGenerator.name(),
    is_active: true,
    profile_image_url: RandomGenerator.alphaNumeric(20) + ".png",
  };
  const created: IdiscussionBoardMembers = await api.functional.discussionBoard.actors.members.post(
    connection,
    { body: createInput }
  );
  typia.assert(created);

  // 2. 업데이트: display_name, profile_image_url, is_active
  const updateInput: IdiscussionBoardMembers.IUpdate = {
    display_name: RandomGenerator.alphaNumeric(12),
    profile_image_url: RandomGenerator.alphaNumeric(22) + ".jpg",
    is_active: false,
  };
  const updated: IdiscussionBoardMembers = await api.functional.discussionBoard.actors.members.putById(
    connection,
    { id: created.id, body: updateInput }
  );
  typia.assert(updated);

  // 3. 변경 사항이 실제 반영됐는지 검증
  TestValidator.equals("display_name 변경 적용")(updated.display_name)(updateInput.display_name);
  TestValidator.equals("profile_image_url 변경 적용")(updated.profile_image_url)(updateInput.profile_image_url);
  TestValidator.equals("is_active 비활성화")(updated.is_active)(false);
  // ID 일치 여부와 변경 전/후 display_name 차이까지 체크
  TestValidator.equals("id 유지")(updated.id)(created.id);
  TestValidator.notEquals("display_name 달라짐")(created.display_name)(updated.display_name);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";

/**
 * Test forbidden update attempt on a soft-deleted member account.
 *
 * This test verifies that once a member is soft-deleted (deleted_at set),
 * update operations (PUT) on the member record are forbidden by business logic.
 *
 * Step-by-step process:
 * 1. Register a new member, capturing username, email, and other required fields.
 * 2. Soft-delete the member using their ID.
 * 3. Attempt to update the deleted member's display_name; assert that an error is thrown (e.g., 404 or forbidden).
 *
 * Business context:
 * This scenario ensures that the system correctly enforces soft-delete restrictions, preventing accidental or malicious updates to deactivated member accounts and protecting audit integrity.
 *
 * The test sets up the dependency chain internally, with all data uniquely generated to avoid collisions.
 */
export async function test_api_discussionBoard_actors_members_test_update_member_forbidden_for_deleted_account(
  connection: api.IConnection
) {
  // 1. Register a new member
  const memberInput: IdiscussionBoardMembers.ICreate = {
    username: RandomGenerator.alphaNumeric(12),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(16),
    display_name: RandomGenerator.name(),
    profile_image_url: null,
    is_active: true,
  };
  const created = await api.functional.discussionBoard.actors.members.post(
    connection,
    { body: memberInput }
  );
  typia.assert(created);
  TestValidator.equals("created member matches input username")(created.username)(memberInput.username);
  TestValidator.equals("created member matches input email")(created.email)(memberInput.email);

  // 2. Soft-delete the member
  await api.functional.discussionBoard.actors.members.eraseById(connection, { id: created.id });

  // 3. Attempt forbidden update: should throw error
  await TestValidator.error("update attempt on soft-deleted member should fail")(
    async () => {
      await api.functional.discussionBoard.actors.members.putById(connection, {
        id: created.id,
        body: {
          display_name: RandomGenerator.name(),
        } satisfies IdiscussionBoardMembers.IUpdate,
      });
    }
  );
}

