 * correctly set the 'revoked_at' timestamp for audit tracking.
 *
 * Steps:
 * 1. Register a member (POST /discussionBoard/actors/members)
 * 2. Assign member as moderator (POST /discussionBoard/actors/moderators)
 * 3. Revoke the moderator assignment (PUT /discussionBoard/actors/moderators/{id}, setting revoked_at)
 * 4. Assert moderator assignment is updated: revoked_at set, all other fields consistent
 */
export async function test_api_discussionBoard_test_update_moderator_assignment_with_valid_revocation(
