 *
 * Steps:
 * 1. Register a member
 * 2. Assign moderator
 * 3. Attempt to set revoked_at to a time before assigned_at (should fail)
 * 4. Attempt to set assigned_at to null (type-legal, but possibly business invalid)
 */
export async function test_api_discussionBoard_actors_moderators_test_update_moderator_assignment_with_invalid_fields(
  connection: api.IConnection,
