 * 5. Attempt to re-fetch the deleted record and assert a not-found error is raised.
 *
 * This covers normal member workflow, verifies authorization on deletion, and validates the hard deletion (record truly gone, not soft-deleted).
 */
export async function test_api_discussionBoard_test_delete_search_history_with_valid_id_owned_by_user(
