import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IDiscussionBoardAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdministrator";
import type { IDiscussionBoardModerationLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerationLog";

/**
 * Validate administrator hard-delete of a moderation log entry.
 *
 * This test ensures an administrator can permanently delete a moderation log.
 * Workflow:
 * 1. Register new member (to promote as admin).
 * 2. Escalate member to administrator.
 * 3. Create new moderation log using this account as moderator.
 * 4. Perform DELETE on the created moderation log (as admin).
 * 5. (If any "get-by-id" for logs existed, would test retrieval fails.)
 */
export async function test_api_discussionBoard_test_hard_delete_moderation_log_success_by_admin(
  connection: api.IConnection,
) {
  // 1. Register a member eligible to become administrator
  const member = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(30),
      display_name: RandomGenerator.name(),
      is_active: true,
      profile_image_url: null,
    } satisfies IdiscussionBoardMembers.ICreate,
  });
  typia.assert(member);

  // 2. Escalate member to administrator
  const admin = await api.functional.discussionBoard.actors.administrators.post(connection, {
    body: {
      member_id: member.id,
      assigned_at: new Date().toISOString(),
    } satisfies IDiscussionBoardAdministrator.ICreate,
  });
  typia.assert(admin);

  // 3. Create a moderation log record linked to this administrator
  const log = await api.functional.discussionBoard.moderation.moderationLogs.post(connection, {
    body: {
      moderator_id: admin.id,
      action: "delete",
      action_reason: "Test for hard delete",
      thread_id: null,
      post_id: null,
      comment_id: null,
    } satisfies IDiscussionBoardModerationLog.ICreate,
  });
  typia.assert(log);

  // 4. Delete the moderation log as administrator
  await api.functional.discussionBoard.moderation.moderationLogs.eraseById(connection, {
    id: log.id,
  });

  // 5. (If SDK provided, would attempt to get-by-id to confirm deletion.)
}

