import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IDiscussionBoardModerationLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerationLog";

/**
 * Test that non-admin users cannot hard-delete a moderation log entry.
 *
 * This test checks that only administrator accounts are permitted to perform hard-deletions of moderation logs from the discussion_board_moderation_logs table. It simulates the following business flow:
 *
 * 1. Create a regular member account (non-admin) via the public sign-up endpoint.
 * 2. Use the member account's ID to create a fake moderation log entry acting as if this user is a moderator (since no real moderator creation endpoint provided), to generate a log entry in the DB.
 * 3. Attempt to perform a DELETE (hard-deletion) for the moderation log entry as the non-admin member (simulate the request with only member authentication context).
 * 4. Confirm that an authorization/forbidden error is raised and deletion is rejected for the non-admin user.
 *
 * This ensures auditability and privilege separation: only administrators can erase moderation logs. The business rule is that regular members or moderators (without admin role) must NOT be able to erase logs.
 *
 * No explicit admin/moderator management flows exist, so test is limited to verifying rejection for non-admin context.
 */
export async function test_api_discussionBoard_test_delete_moderation_log_unauthorized_user_forbidden(
  connection: api.IConnection,
) {
  // 1. Create a regular discussion board member (non-admin)
  const member = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      display_name: RandomGenerator.alphaNumeric(10),
      is_active: true,
      profile_image_url: null,
    } satisfies IdiscussionBoardMembers.ICreate,
  });
  typia.assert(member);

  // 2. Create a moderation log entry as this member (simulate as a moderator since no real moderator endpoint exists)
  const modLog = await api.functional.discussionBoard.moderation.moderationLogs.post(connection, {
    body: {
      moderator_id: member.id,
      action: "hide",
      action_reason: "Test moderation log creation by non-admin.",
      thread_id: null,
      post_id: null,
      comment_id: null,
    } satisfies IDiscussionBoardModerationLog.ICreate,
  });
  typia.assert(modLog);

  // 3. Attempt to delete the moderation log with non-admin credentials (should be forbidden)
  await TestValidator.error("Non-admin should not be able to hard-delete moderation log entry.")(
    async () => {
      await api.functional.discussionBoard.moderation.moderationLogs.eraseById(connection, {
        id: modLog.id,
      });
    },
  );
}

