import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";

/**
 * 존재하지 않는 moderation log entry 삭제 시 not-found 에러가 발생함을 검증합니다.
 *
 * - moderation log 엔트리는 hard delete만 지원하며, soft delete 개념이 없습니다.
 * - 삭제 대상이 테이블에 존재하지 않을 시 not-found 오류가 반환되어야 하며, 그 외 부수 효과가 없어야 합니다.
 *
 * [테스트 플로우]
 * 1. 무작위로 생성한 UUID(존재하지 않는 id로 가정)로 moderation log 삭제 시도
 * 2. not-found 오류가 발생하는지 TestValidator.error로 검증
 * 3. 추가적인 부수 효과(상태 변화, 부가 에러 발생 등)가 없는지 확인 (idempotent delete)
 */
export async function test_api_discussionBoard_moderation_moderationLogs_test_delete_moderation_log_not_found_error(
  connection: api.IConnection,
) {
  // 1. 무작위로 생성한 UUID 사용 (존재하지 않는 id 가정)
  const nonExistentId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();

  // 2. not-found 에러가 발생하는지 검증
  await TestValidator.error("존재하지 않는 moderation log id 삭제시 not-found 에러 발생")(
    async () => {
      await api.functional.discussionBoard.moderation.moderationLogs.eraseById(connection, { id: nonExistentId });
    },
  );

  // 3. 추가적인 부수 효과 없음(테스트 환경 단일 API 기반이므로 상태 변화까지는 검증 불가)
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IdiscussionBoardModerators } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardModerators";
import type { IModerationWarning } from "@ORGANIZATION/PROJECT-api/lib/structures/IModerationWarning";

/**
 * Test successful creation of a warning issued by a moderator to a member.
 *
 * This test verifies real-world permission and business logic:
 * - A member must exist to issue a warning to.
 * - A moderator must be assigned to create the warning.
 * - The moderator issues a warning with specified type and message.
 * - The resulting warning record is validated for data correctness and reference integrity.
 *
 * Workflow:
 * 1. Create a member (warned target)
 * 2. Create a member, promote to moderator
 * 3. Issue a warning from moderator to the first member, with testable properties
 * 4. Validate output correctness: foreign key fields, types, message, timestamps, and nullable fields
 */
export async function test_api_discussionBoard_moderation_warnings_test_create_warning_success_for_member_by_moderator(
  connection: api.IConnection,
) {
  // 1. Create the member to be warned
  const warnedMemberInput = {
    username: RandomGenerator.alphaNumeric(12),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(32),
    display_name: RandomGenerator.name(),
    profile_image_url: null,
    is_active: true,
  } satisfies IdiscussionBoardMembers.ICreate;
  const warnedMember = await api.functional.discussionBoard.actors.members.post(connection, { body: warnedMemberInput });
  typia.assert(warnedMember);

  // 2. Create the moderator (separate member, not same as warned target)
  const moderatorMemberInput = {
    username: RandomGenerator.alphaNumeric(12),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(32),
    display_name: RandomGenerator.name(),
    profile_image_url: null,
    is_active: true,
  } satisfies IdiscussionBoardMembers.ICreate;
  const moderatorMember = await api.functional.discussionBoard.actors.members.post(connection, { body: moderatorMemberInput });
  typia.assert(moderatorMember);

  // 3. Assign the moderator role to the new member
  const moderatorRoleInput = {
    member_id: moderatorMember.id,
    assigned_at: new Date().toISOString(),
  } satisfies IdiscussionBoardModerators.ICreate;
  const moderator = await api.functional.discussionBoard.actors.moderators.post(connection, { body: moderatorRoleInput });
  typia.assert(moderator);

  // 4. Compose and issue the warning as the moderator
  const warningType = "spam";
  const warningMessage = "Your post contained prohibited content (spam).";
  const warningCreationTime = new Date().toISOString();
  const warningInput = {
    member_id: warnedMember.id,
    moderator_id: moderator.id,
    warning_type: warningType,
    message: warningMessage,
    created_at: warningCreationTime,
    expires_at: null,
  } satisfies IModerationWarning.ICreate;
  const warning = await api.functional.discussionBoard.moderation.warnings.post(connection, { body: warningInput });
  typia.assert(warning);

  // 5. Assert correctness of returned warning object
  // Linkage fields match scenario actors
  TestValidator.equals("warned member reference")(warning.member_id)(warnedMember.id);
  TestValidator.equals("moderator reference")(warning.moderator_id)(moderator.id);
  TestValidator.equals("type matches")(warning.warning_type)(warningType);
  TestValidator.equals("message matches")(warning.message)(warningMessage);
  TestValidator.equals("created time matches")(warning.created_at)(warningCreationTime);
  TestValidator.equals("expires_at is null")(warning.expires_at)(null);
  // UUID and ISO time fields are correct
  TestValidator.predicate("id must be a valid UUID")(typeof warning.id === "string" && warning.id.length > 0);
  TestValidator.predicate("created_at must be valid ISO string")(typeof warning.created_at === "string" && !Number.isNaN(Date.parse(warning.created_at)));
  // deleted_at should be null or undefined on creation
  TestValidator.equals("deleted_at is null or not present")(warning.deleted_at ?? null)(null);
}

