import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardModerators } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardModerators";
import type { IModerationWarning } from "@ORGANIZATION/PROJECT-api/lib/structures/IModerationWarning";

/**
 * Validate error handling when creating a moderation warning for a non-existent member_id.
 *
 * This test ensures the API does not create a warning record if the target member (to be warned) does not exist.
 * It verifies business rules and error propagation for moderation warning creation with invalid input by a legitimate moderator.
 *
 * Steps:
 * 1. Create a fake member_id (UUID format, does not correspond to any member in the system).
 * 2. Create a moderator through the actor/moderator assignment API.
 * 3. Attempt to POST a moderation warning using the moderator_id (just created) and the fake member_id as the warned user.
 * 4. Expect the warnings API to throw an error (business logic violation: member_id foreign key does not exist).
 * 5. Validate the error (use TestValidator.error).
 * 6. Optionally, check that no warning was created (not required if error occurs before persistence).
 */
export async function test_api_discussionBoard_test_create_warning_invalid_member_id_error(
  connection: api.IConnection,
) {
  // 1. Generate a fake member_id (valid UUID format, but does not exist in the system)
  const fake_member_id: string = typia.random<string & tags.Format<"uuid">>();

  // 2. Generate a valid moderator_id by creating a new moderator assignment
  const moderator_member_id: string = typia.random<string & tags.Format<"uuid">>();
  const moderator_assigned_at: string = new Date().toISOString();
  const moderator = await api.functional.discussionBoard.actors.moderators.post(connection, {
    body: {
      member_id: moderator_member_id,
      assigned_at: moderator_assigned_at,
    } satisfies IdiscussionBoardModerators.ICreate,
  });
  typia.assert(moderator);

  // 3. Try to create a moderation warning with a non-existent target member
  const warning_body = {
    member_id: fake_member_id,
    moderator_id: moderator.id,
    warning_type: "harassment",
    message: "Automated test: warning for non-existing member",
    created_at: new Date().toISOString(),
    expires_at: null,
  } satisfies IModerationWarning.ICreate;

  // 4. Expect warning creation to throw an error due to invalid member_id
  await TestValidator.error("Creating warning for non-existent member should fail")(
    async () =>
      api.functional.discussionBoard.moderation.warnings.post(connection, {
        body: warning_body,
      }),
  );
}

