import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IdiscussionBoardModerators } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardModerators";
import type { IModerationWarning } from "@ORGANIZATION/PROJECT-api/lib/structures/IModerationWarning";

/**
 * Test the handling of duplicate warning creation for the same member, moderator, type, and message.
 *
 * 1. Create a discussion board member (target of warning).
 * 2. Assign a moderator role to the newly created member.
 * 3. Prepare warning request data (with all duplicate-prone fields identical: member, moderator, type, message, created_at).
 * 4. Create the first warning.
 * 5. Attempt to create a second warning with identical data.
 * 6. If duplicate allowed, verify returned warnings have different IDs but otherwise identical details.
 * 7. If system enforces idempotency or uniqueness, verify duplicate attempt fails cleanly with proper error handling using TestValidator.
 */
export async function test_api_discussionBoard_moderation_warnings_test_create_warning_duplicate_idempotency_or_uniqueness(
  connection: api.IConnection,
) {
  // 1. Create a discussion board member (target of warning)
  const member = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(20),
      display_name: RandomGenerator.name(),
      is_active: true,
      profile_image_url: null,
    } satisfies IdiscussionBoardMembers.ICreate,
  });
  typia.assert(member);

  // 2. Assign moderator role to this member
  const moderator = await api.functional.discussionBoard.actors.moderators.post(connection, {
    body: {
      member_id: member.id,
      assigned_at: new Date().toISOString(),
    } satisfies IdiscussionBoardModerators.ICreate,
  });
  typia.assert(moderator);

  // 3. Prepare warning data (fields identical for both attempts)
  const warningInput = {
    member_id: member.id,
    moderator_id: moderator.id,
    warning_type: "spam",
    message: "Repeated spam content in forum thread.",
    created_at: new Date().toISOString(),
    expires_at: null,
  } satisfies IModerationWarning.ICreate;

  // 4. Create first warning
  const warning1 = await api.functional.discussionBoard.moderation.warnings.post(connection, {
    body: warningInput,
  });
  typia.assert(warning1);

  // 5. Attempt to create duplicate warning (identical input)
  let warning2: IModerationWarning | null = null;
  let duplicateRejected = false;
  try {
    warning2 = await api.functional.discussionBoard.moderation.warnings.post(connection, { body: warningInput });
    typia.assert(warning2);
  } catch {
    duplicateRejected = true;
  }

  // 6. Branch: allowed duplicate or uniqueness enforced
  if (!duplicateRejected) {
    TestValidator.notEquals("warning IDs must differ")(warning1.id)(warning2!.id);
    TestValidator.equals("member_id identical")(warning1.member_id)(warning2!.member_id);
    TestValidator.equals("moderator_id identical")(warning1.moderator_id)(warning2!.moderator_id);
    TestValidator.equals("warning_type identical")(warning1.warning_type)(warning2!.warning_type);
    TestValidator.equals("message identical")(warning1.message)(warning2!.message);
  } else {
    TestValidator.predicate("duplicate warning correctly blocked")(duplicateRejected);
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IdiscussionBoardModerators } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardModerators";
import type { IModerationWarning } from "@ORGANIZATION/PROJECT-api/lib/structures/IModerationWarning";
import type { IPageIModerationWarning } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIModerationWarning";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test paginated, filterable listing of moderation warnings.
 *
 * This scenario ensures that the /discussionBoard/moderation/warnings PATCH endpoint
 * correctly supports filtering by member_id, moderator_id, warning_type,
 * and supports pagination. Includes setup of test members and moderators, creation
 * of multiple warnings with diverse filter criteria, then validates list queries.
 *
 * Steps:
 * 1. Create two members (memberA, memberB).
 * 2. Create two moderators (mod1, mod2).
 * 3. Issue multiple warnings with different combinations:
 *    - mod1 gives two warnings to memberA: types 'spam', 'harassment'
 *    - mod2 gives one warning to memberA: type 'spam'
 *    - mod2 gives two warnings to memberB: types 'harassment', 'customRule'
 * 4. For each filter (member_id, moderator_id, warning_type),
 *    perform a PATCH (list/search) and verify results and total counts.
 * 5. Validate pagination: fetch subsets using limit and page parameters, ensure accurate slicing and page counts.
 */
export async function test_api_discussionBoard_moderation_warnings_test_list_warnings_with_filtering_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create two members
  const memberA = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      display_name: RandomGenerator.name(),
      is_active: true,
      profile_image_url: null,
    } satisfies IdiscussionBoardMembers.ICreate,
  });
  typia.assert(memberA);
  const memberB = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      display_name: RandomGenerator.name(),
      is_active: true,
      profile_image_url: null,
    } satisfies IdiscussionBoardMembers.ICreate,
  });
  typia.assert(memberB);

  // 2. Create two moderators
  const mod1_member = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      display_name: RandomGenerator.name(),
      is_active: true,
      profile_image_url: null,
    } satisfies IdiscussionBoardMembers.ICreate,
  });
  typia.assert(mod1_member);
  const mod1 = await api.functional.discussionBoard.actors.moderators.post(connection, {
    body: {
      member_id: mod1_member.id,
      assigned_at: new Date().toISOString(),
    } satisfies IdiscussionBoardModerators.ICreate,
  });
  typia.assert(mod1);

  const mod2_member = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      display_name: RandomGenerator.name(),
      is_active: true,
      profile_image_url: null,
    } satisfies IdiscussionBoardMembers.ICreate,
  });
  typia.assert(mod2_member);
  const mod2 = await api.functional.discussionBoard.actors.moderators.post(connection, {
    body: {
      member_id: mod2_member.id,
      assigned_at: new Date().toISOString(),
    } satisfies IdiscussionBoardModerators.ICreate,
  });
  typia.assert(mod2);

  // 3. Issue warnings
  const warnings: IModerationWarning[] = [];
  // mod1 gives two warnings to memberA: types 'spam', 'harassment'
  warnings.push(await api.functional.discussionBoard.moderation.warnings.post(connection, {
    body: {
      member_id: memberA.id,
      moderator_id: mod1.id,
      warning_type: "spam",
      message: "No spamming, please.",
      created_at: new Date().toISOString(),
      expires_at: null,
    } satisfies IModerationWarning.ICreate,
  }));
  warnings.push(await api.functional.discussionBoard.moderation.warnings.post(connection, {
    body: {
      member_id: memberA.id,
      moderator_id: mod1.id,
      warning_type: "harassment",
      message: "Harassment is not tolerated.",
      created_at: new Date().toISOString(),
      expires_at: null,
    } satisfies IModerationWarning.ICreate,
  }));
  // mod2 gives one warning to memberA: type 'spam'
  warnings.push(await api.functional.discussionBoard.moderation.warnings.post(connection, {
    body: {
      member_id: memberA.id,
      moderator_id: mod2.id,
      warning_type: "spam",
      message: "Spam behavior detected.",
      created_at: new Date().toISOString(),
      expires_at: null,
    } satisfies IModerationWarning.ICreate,
  }));
  // mod2 gives two warnings to memberB: types 'harassment', 'customRule'
  warnings.push(await api.functional.discussionBoard.moderation.warnings.post(connection, {
    body: {
      member_id: memberB.id,
      moderator_id: mod2.id,
      warning_type: "harassment",
      message: "Harassment warning issued.",
      created_at: new Date().toISOString(),
      expires_at: null,
    } satisfies IModerationWarning.ICreate,
  }));
  warnings.push(await api.functional.discussionBoard.moderation.warnings.post(connection, {
    body: {
      member_id: memberB.id,
      moderator_id: mod2.id,
      warning_type: "customRule",
      message: "Violation of custom rule.",
      created_at: new Date().toISOString(),
      expires_at: null,
    } satisfies IModerationWarning.ICreate,
  }));
  warnings.forEach(w => typia.assert(w));

  // 4. Filter tests - by member_id
  const byMemberA = await api.functional.discussionBoard.moderation.warnings.patch(connection, {
    body: {
      member_id: memberA.id,
    } satisfies IModerationWarning.IRequest,
  });
  typia.assert(byMemberA);
  TestValidator.equals("memberA warning count")(byMemberA.pagination.records)(3);
  TestValidator.predicate("all belong to memberA")(byMemberA.data.every(w => w.member_id === memberA.id));

  // by moderator_id (mod2)
  const byMod2 = await api.functional.discussionBoard.moderation.warnings.patch(connection, {
    body: {
      moderator_id: mod2.id,
    } satisfies IModerationWarning.IRequest,
  });
  typia.assert(byMod2);
  TestValidator.equals("mod2 warning count")(byMod2.pagination.records)(3);
  TestValidator.predicate("all issued by mod2")(byMod2.data.every(w => w.moderator_id === mod2.id));

  // by warning_type 'harassment'
