import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IdiscussionBoardModerators } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardModerators";
import type { IModerationWarning } from "@ORGANIZATION/PROJECT-api/lib/structures/IModerationWarning";
import type { IPageIModerationWarning } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIModerationWarning";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test that soft-deleted warnings are not returned in standard warning lists.
 *
 * Business context:
 * In the discussion board moderation system, warnings issued to users are stored (notified to the member, including moderator assignment for audit/compliance). The system uses soft-deletion: when a warning is removed, it is just marked deleted (deleted_at is filled) but not fully removed for auditability.
 *
 * This test ensures that when warnings are listed using the patch endpoint, the default result does not include soft-deleted warnings. However, when explicitly searching for deleted warnings (deleted=true), soft-deleted entries are returned. This prevents confusion on user-facing lists and satisfies audit/compliance for admin-only queries.
 *
 * Steps:
 * 1. Create a member using POST /discussionBoard/actors/members.
 * 2. Assign moderator using POST /discussionBoard/actors/moderators (moderator is needed to issue a warning).
 * 3. Issue at least two warnings to the member using POST /discussionBoard/moderation/warnings.
 * 4. Soft delete one warning (using DELETE /discussionBoard/moderation/warnings/{id}).
 * 5. List warnings (PATCH /discussionBoard/moderation/warnings) and check only the non-deleted warning(s) are returned.
 * 6. List with filter {deleted:true} and confirm the soft-deleted entry appears.
 * 7. List with filter {deleted:null|false} and confirm soft-deleted warnings are not shown.
 */
export async function test_api_discussionBoard_test_list_warnings_excludes_soft_deleted_entries(
  connection: api.IConnection,
) {
  // 1. Create a normal member account
  const member = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphabets(12),
      display_name: RandomGenerator.name(),
      is_active: true,
      profile_image_url: null,
    },
  });
  typia.assert(member);

  // 2. Create a second member to act as moderator (need moderator to assign warnings)
  const modMember = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphabets(12),
      display_name: RandomGenerator.name(),
      is_active: true,
      profile_image_url: null,
    },
  });
  typia.assert(modMember);

  // 3. Assign moderator role to modMember.
  const moderator = await api.functional.discussionBoard.actors.moderators.post(connection, {
    body: {
      member_id: modMember.id,
      assigned_at: new Date().toISOString(),
    },
  });
  typia.assert(moderator);

  // 4. Issue two warnings to main member, issued from moderator
  const warning1 = await api.functional.discussionBoard.moderation.warnings.post(connection, {
    body: {
      member_id: member.id,
      moderator_id: moderator.id,
      warning_type: "spam",
      message: "Do not post spam links.",
      created_at: new Date().toISOString(),
      expires_at: null,
    },
  });
  typia.assert(warning1);

  const warning2 = await api.functional.discussionBoard.moderation.warnings.post(connection, {
    body: {
      member_id: member.id,
      moderator_id: moderator.id,
      warning_type: "harassment",
      message: "Do not harass other users.",
      created_at: new Date().toISOString(),
      expires_at: null,
    },
  });
  typia.assert(warning2);

  // 5. Soft delete warning1
  await api.functional.discussionBoard.moderation.warnings.eraseById(connection, {
    id: warning1.id,
  });

  // 6. List warnings for the member, default (should NOT show soft-deleted ones)
  const pageDefault = await api.functional.discussionBoard.moderation.warnings.patch(connection, {
    body: {
      member_id: member.id,
    },
  });
  typia.assert(pageDefault);
  // Only warning2 should be present
  TestValidator.predicate("list only non-deleted warnings")(pageDefault.data.length === 1 && pageDefault.data[0].id === warning2.id && !pageDefault.data[0].deleted_at);

  // 7. List with deleted: true (should return ONLY deleted warnings)
  const pageDeleted = await api.functional.discussionBoard.moderation.warnings.patch(connection, {
    body: {
      member_id: member.id,
      deleted: true,
    },
  });
  typia.assert(pageDeleted);
  // Only warning1 should be present
  TestValidator.predicate("list only soft-deleted warnings")(pageDeleted.data.length === 1 && pageDeleted.data[0].id === warning1.id && !!pageDeleted.data[0].deleted_at);

  // 8. List with deleted: false (should exclude soft-deleted)
  const pageNotDeleted = await api.functional.discussionBoard.moderation.warnings.patch(connection, {
    body: {
      member_id: member.id,
      deleted: false,
    },
  });
  typia.assert(pageNotDeleted);
  TestValidator.predicate("deleted:false behaves as default (shows only non-deleted)")(pageNotDeleted.data.length === 1 && pageNotDeleted.data[0].id === warning2.id && !pageNotDeleted.data[0].deleted_at);
}

