 * 2. Create another member and escalate them to moderator role.
 * 3. Moderator issues a warning for the target member.
 * 4. Retrieve the warning by id as the moderator.
 * 5. Validate that all schema fields are returned and match the created warning.
 */
export async function test_api_discussionBoard_test_get_warning_by_id_success(
  connection: api.IConnection,
) {
  // 1. Create a member to be warned
  const targetMember = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(32),
      display_name: RandomGenerator.name(),
      profile_image_url: null,
      is_active: true,
    } satisfies IdiscussionBoardMembers.ICreate,
  });
  typia.assert(targetMember);

  // 2. Create a member for moderator and escalate
  const moderatorMember = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(32),
      display_name: RandomGenerator.name(),
      profile_image_url: null,
      is_active: true,
    } satisfies IdiscussionBoardMembers.ICreate,
  });
  typia.assert(moderatorMember);
  const moderator = await api.functional.discussionBoard.actors.moderators.post(connection, {
    body: {
      member_id: moderatorMember.id,
      assigned_at: new Date().toISOString(),
    } satisfies IdiscussionBoardModerators.ICreate,
  });
  typia.assert(moderator);

  // 3. Moderator issues a warning
