 */
export async function test_api_discussionBoard_notifications_mentions_test_update_mention_actor_member_id_with_valid_and_invalid_values(
  connection: api.IConnection
) {
  // 1. Create original actor member
  const actorMember1 = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
