    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(20),
      display_name: RandomGenerator.name(),
      is_active: true
    } satisfies IdiscussionBoardMembers.ICreate
  });
  typia.assert(actorMember2);

  // 3. Create mentioned member (the target of the @mention)
  const mentionedMember = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(20),
      display_name: RandomGenerator.name(),
      is_active: true
    } satisfies IdiscussionBoardMembers.ICreate
  });
  typia.assert(mentionedMember);

  // Use a random UUID as the content (post/comment/thread) being referenced
  const contentId = typia.random<string & tags.Format<"uuid">>();

  // 4. Create the mention notification with the original actor
  const mentionCreated = await api.functional.discussionBoard.notifications.mentions.post(connection, {
    body: {
      mentioned_member_id: mentionedMember.id,
      actor_member_id: actorMember1.id,
      content_type: "post",
