import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IDiscussionBoardAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdministrator";

/**
 * Validate updating an administrator assignment to set revoked_at and assigned_at.
 *
 * This test covers a compliance/role management scenario in which a privileged actor
 * (assumed to be permitted by default connection context) first escalates a member
 * to the administrator role, then successfully updates that administrator assignment
 * to change both the 'assigned_at' timestamp (e.g., retroactive correction or compliance)
 * and set 'revoked_at' to indicate demotion or privilege revocation.
 *
 * Workflow:
 * 1. Create a member with a unique username and email. (POST /discussionBoard/actors/members)
 * 2. Assign the admin role to that member (POST /discussionBoard/actors/administrators), using current time for assigned_at.
 * 3. Update the administrator assignment (PUT /discussionBoard/actors/administrators/{id}):
 *    - Change assigned_at to a new (different) timestamp (simulate correction)
 *    - Set revoked_at (current time) to represent a role withdrawal
 * 4. Assert that the returned administrator assignment has the updated assigned_at
 *    and the provided revoked_at values, and both timestamps are correct and schema-valid.
 * 5. Attempt the same update as a non-privileged user, expecting the operation to be rejected (e.g., by lack of permission or error).
 *
 * Validation points:
 * - Only the valid schema fields are accepted and reflected
 * - Changing assigned_at and setting revoked_at both succeed for a privileged actor
 * - The API's response structure matches the schema
 * - Rejected operation for a non-privileged user role (if such enforcement is present)
 */
export async function test_api_discussionBoard_actors_administrators_test_update_administrator_revoked_at_and_assigned_at_success(
  connection: api.IConnection,
) {
  // 1. Create a new discussion board member with valid fields
  const member = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphabets(10),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphabets(32),
      display_name: RandomGenerator.name(),
      is_active: true,
      profile_image_url: null,
    } satisfies IdiscussionBoardMembers.ICreate,
  });
  typia.assert(member);

  // 2. Assign administrator rights to the created member
  const assignedAt = new Date().toISOString();
  const adminAssignment = await api.functional.discussionBoard.actors.administrators.post(connection, {
    body: {
      member_id: member.id,
      assigned_at: assignedAt,
    } satisfies IDiscussionBoardAdministrator.ICreate,
  });
  typia.assert(adminAssignment);
  TestValidator.equals("member_id matches assignment")(adminAssignment.member_id)(member.id);
  TestValidator.equals("assigned_at matches")(adminAssignment.assigned_at)(assignedAt);

  // 3. Update the administrator assignment: correct assigned_at and set revoked_at
  const newAssignedAt = new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString(); // 1 day ago
  const revokedAt = new Date().toISOString();
  const updatedAdminAssignment = await api.functional.discussionBoard.actors.administrators.putById(connection, {
    id: adminAssignment.id,
    body: {
      assigned_at: newAssignedAt,
      revoked_at: revokedAt,
    } satisfies IDiscussionBoardAdministrator.IUpdate,
  });
  typia.assert(updatedAdminAssignment);
  TestValidator.equals("assigned_at updated")(updatedAdminAssignment.assigned_at)(newAssignedAt);
  TestValidator.equals("revoked_at set")(updatedAdminAssignment.revoked_at)(revokedAt);
  TestValidator.equals("member_id unchanged")(updatedAdminAssignment.member_id)(member.id);

  // 4. (Negative case) Attempt the update as a non-privileged actor
  // For this test, we'll create a second member to simulate a non-admin
  const nonPrivMember = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphabets(12),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphabets(32),
      display_name: RandomGenerator.name(),
      is_active: true,
      profile_image_url: null,
    } satisfies IdiscussionBoardMembers.ICreate,
  });
  typia.assert(nonPrivMember);

  // If the system supports auth switching, simulate switching here — omitted unless API docs provide such endpoint.
  // Attempt update by non-privileged member (should be forbidden)
  // As we do not have authentication context switching in the provided SDK, this call is for design completeness:
  await TestValidator.error("non-privileged user cannot update admin assignment")(
    () => api.functional.discussionBoard.actors.administrators.putById(connection, {
      id: adminAssignment.id,
      body: {
        assigned_at: newAssignedAt,
        revoked_at: new Date().toISOString(),
      } satisfies IDiscussionBoardAdministrator.IUpdate,
    })
  );
}

