  typia.assert(member);

  // Step 2: Assign administrator privileges
  const assignInput = {
    member_id: member.id,
    assigned_at: new Date().toISOString(),
  } satisfies IDiscussionBoardAdministrator.ICreate;
  const admin = await api.functional.discussionBoard.actors.administrators.post(connection, { body: assignInput });
  typia.assert(admin);

  // Step 3: Prepare a valid update payload (only schema fields)
  const updatePayload = {
    assigned_at: new Date(Date.now() + 1000 * 60).toISOString(),
  } satisfies IDiscussionBoardAdministrator.IUpdate;

  // Step 4: Add a forbidden property (e.g., audit_trace)
  const invalidUpdatePayload = {
    ...updatePayload,
    audit_trace: "test-metadata", // schema-forbidden/non-existent
  };

  // Step 5: Attempt update with forbidden property, expect schema validation error
  await TestValidator.error("should reject forbidden field (audit_trace)")(
    async () => {
      await api.functional.discussionBoard.actors.administrators.putById(connection, {
        id: admin.id,
        body: invalidUpdatePayload, // This should trigger strict validation error
      });
    }
  );

  // Step 6: Valid update to demonstrate success-path and that resource is still updatable when schema is followed
  const updated = await api.functional.discussionBoard.actors.administrators.putById(connection, {
    id: admin.id,
    body: updatePayload,
  });
