import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IDiscussionBoardThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardThread";
import type { IPageIDiscussionBoardThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardThread";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";

/**
 * E2E test for the discussion board threads list endpoint with filtering and pagination.
 *
 * This test covers the following scenario:
 * - Create several categories for grouping threads.
 * - Register a number of member accounts to act as authors.
 * - For test coverage, create multiple threads with random assignments across these members and categories,
 *   and with a mix of is_pinned and is_closed statuses, and with known created_at timestamps.
 * - Using the /discussionBoard/articles/threads PATCH endpoint,
 *   request a paginated list filtered by category, is_pinned or created_at (date range).
 * - Assert that only threads matching the query filters appear in the response.
 * - Assert that IPageIDiscussionBoardThread.pagination accurately reflects the paging (current, limit, records, pages)
 *   and that the data array contains all and only the expected threads for the filter/page.
 * - Validate that results do NOT include threads omitted by the filter (e.g. with a different category or status).
 *
 * This test validates correct implementation of filtering and pagination logic on the threads list API.
 */
export async function test_api_discussionBoard_test_list_threads_with_pagination_and_status_filtering(
  connection: api.IConnection,
) {
  // 1. Create 3 categories
  const categories: IDiscussionBoardCategory[] = await ArrayUtil.asyncRepeat(3)(async () => {
    const newCategory = await api.functional.discussionBoard.categories.categories.post(connection, {
      body: {
        name: RandomGenerator.alphaNumeric(8),
        description: RandomGenerator.paragraph()(),
      } satisfies IDiscussionBoardCategory.ICreate,
    });
    typia.assert(newCategory);
    return newCategory;
  });

  // 2. Create 3 members
  const members: IdiscussionBoardMembers[] = await ArrayUtil.asyncRepeat(3)(async () => {
    const email = typia.random<string & tags.Format<"email">>();
    const newMember = await api.functional.discussionBoard.actors.members.post(connection, {
      body: {
        username: RandomGenerator.alphaNumeric(10),
        email,
        hashed_password: RandomGenerator.alphaNumeric(10),
        display_name: RandomGenerator.name(),
        profile_image_url: null,
        is_active: true,
      } satisfies IdiscussionBoardMembers.ICreate,
    });
    typia.assert(newMember);
    return newMember;
  });

  // 3. Create 12 threads (spread across categories, members, pinned & open/closed status)
  // We'll ensure clear combinations to allow filter assertion
  type ThreadMeta = { thread: IDiscussionBoardThread; meta: { categoryId: string; memberId: string; is_pinned: boolean; created_at: string } };
  const threads: ThreadMeta[] = [];
  for (let i = 0; i < 12; ++i) {
    const category = RandomGenerator.pick(categories);
    const member = RandomGenerator.pick(members);
    const is_pinned = i % 2 === 0;
    const is_closed = i % 3 === 0;
    // Space out created_at timestamps for filter testing
    // (note: actual thread.created_at comes from server, so capture and use it after creation)
    const thread = await api.functional.discussionBoard.articles.threads.post(connection, {
      body: {
        discussion_board_category_id: category.id,
        title: `Thread ${i} - ${RandomGenerator.paragraph()()}`,
        body: RandomGenerator.content()()(),
        is_pinned,
        is_closed,
      } satisfies IDiscussionBoardThread.ICreate,
    });
    typia.assert(thread);
    threads.push({ thread, meta: { categoryId: category.id, memberId: member.id, is_pinned: is_pinned, created_at: thread.created_at } });
  }

  // --- FILTERED PAGINATION TESTS ---

  // [A] Filter: By category, is_pinned=true, page 1, limit 3
  const targetCategory = categories[0];
  const targetPinned = true;
  const page = 1;
  const limit = 3;

  // Get expected thread ids using meta-data
  const expectedThreads = threads
    .filter(t => t.meta.categoryId === targetCategory.id && t.meta.is_pinned === targetPinned)
    .sort((a, b) => new Date(b.thread.created_at).getTime() - new Date(a.thread.created_at).getTime());
  const expectedPageThreads = expectedThreads.slice((page - 1) * limit, (page) * limit);

  // Call the endpoint under test
  const response = await api.functional.discussionBoard.articles.threads.patch(connection, {
    body: {
      discussion_board_category_id: targetCategory.id,
      is_pinned: targetPinned,
      page,
      limit,
    } satisfies IDiscussionBoardThread.IRequest,
  });
  typia.assert(response);
  // Validate pagination object
  TestValidator.equals("current page")(response.pagination.current)(page);
  TestValidator.equals("limit")(response.pagination.limit)(limit);
  TestValidator.equals("total records")(response.pagination.records)(expectedThreads.length);
  TestValidator.equals("pages")(response.pagination.pages)(Math.ceil(expectedThreads.length / limit));
  // Validate result threads
  TestValidator.equals("page data count")(response.data.length)(expectedPageThreads.length);
  for (let i = 0; i < response.data.length; ++i) {
    const actual = response.data[i];
    const expected = expectedPageThreads[i].thread;
    TestValidator.equals(`thread id at index ${i}`)(actual.id)(expected.id);
    TestValidator.equals(`thread is_pinned at index ${i}`)(actual.is_pinned)(expected.is_pinned);
    TestValidator.equals(`thread category at index ${i}`)(actual.discussion_board_category_id)(targetCategory.id);
  }

  // [B] Filter: By member (all threads by members[1]), no status filter
  const memberThreads = threads.filter(t => t.meta.memberId === members[1].id).sort((a, b) => new Date(b.thread.created_at).getTime() - new Date(a.thread.created_at).getTime());
  const memberRes = await api.functional.discussionBoard.articles.threads.patch(connection, {
    body: {
      discussion_board_member_id: members[1].id,
      page: 1,
      limit: 100,
    } satisfies IDiscussionBoardThread.IRequest,
  });
  typia.assert(memberRes);
  TestValidator.equals("member threads count")(memberRes.pagination.records)(memberThreads.length);
  for (const meta of memberThreads) {
    TestValidator.predicate(`check thread in data`)(memberRes.data.some(t => t.id === meta.thread.id));
  }

  // [C] Filter: By creation date (after a certain time)
  // Pick oldest thread's created_at and add 1ms, should exclude oldest
  const sortedThreads = threads.sort((a, b) => new Date(a.thread.created_at).getTime() - new Date(b.thread.created_at).getTime());
  const oldest = sortedThreads[0];
  const after = new Date(new Date(oldest.thread.created_at).getTime() + 1).toISOString();
  const dateFilteredExpected = threads.filter(t => new Date(t.thread.created_at) >= new Date(after));
  const dateFilteredRes = await api.functional.discussionBoard.articles.threads.patch(connection, {
    body: {
      created_at: after,
      limit: 100,
    } satisfies IDiscussionBoardThread.IRequest,
  });
  typia.assert(dateFilteredRes);
  TestValidator.equals("date filtered records")(dateFilteredRes.pagination.records)(dateFilteredExpected.length);
  for (const meta of dateFilteredExpected) {
    TestValidator.predicate(`thread appears in date filter list`)(dateFilteredRes.data.some(t => t.id === meta.thread.id));
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IDiscussionBoardThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardThread";
import type { IPageIDiscussionBoardThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardThread";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";

/**
 * Validate that soft-deleted discussion threads are excluded by default from thread listings.
 *
 * This test confirms the default exclusion of soft-deleted threads from the result of listing/searching discussion threads:
 * 1. Create a new category for testing.
 * 2. Register two member accounts to use as thread creators.
 * 3. Each member creates at least one thread in the test category.
 * 4. Soft-delete one of the created threads by calling the DELETE endpoint for that thread's id.
 * 5. List/search threads in the category (with no deleted_at in the filter/request).
 * 6. Confirm that the soft-deleted thread does NOT appear in the result, but the active (non-deleted) thread does.
 * 7. Confirm that, if searching again with the deleted_at filter set (non-null), the soft-deleted thread DOES appear and has its deleted_at set to a non-null value.
 */
export async function test_api_discussionBoard_test_list_threads_soft_deleted_exclusion_by_default(
  connection: api.IConnection,
) {
  // 1. Create a test category
  const category = await api.functional.discussionBoard.categories.categories.post(connection, {
    body: {
      name: "Test Category - soft delete",
      description: "Category for soft delete exclusion test",
    },
  });
  typia.assert(category);

  // 2. Register two member accounts
  const member1Details = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(15),
    display_name: RandomGenerator.name(),
    is_active: true,
  };
  const member1 = await api.functional.discussionBoard.actors.members.post(connection, { body: member1Details });
  typia.assert(member1);

  const member2Details = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(15),
    display_name: RandomGenerator.name(),
    is_active: true,
  };
  const member2 = await api.functional.discussionBoard.actors.members.post(connection, { body: member2Details });
  typia.assert(member2);

  // 3. Each member creates one thread in the category
  const thread1 = await api.functional.discussionBoard.articles.threads.post(connection, {
    body: {
      discussion_board_category_id: category.id,
      title: "Thread for Exclusion A",
      body: "This thread will be soft-deleted to test exclusion.",
      is_pinned: false,
      is_closed: false,
    },
  });
  typia.assert(thread1);

  const thread2 = await api.functional.discussionBoard.articles.threads.post(connection, {
    body: {
      discussion_board_category_id: category.id,
      title: "Thread for Inclusion B",
      body: "This thread should remain active and be visible.",
      is_pinned: false,
      is_closed: false,
    },
  });
  typia.assert(thread2);

  // 4. Soft-delete thread1
  const deleteResult = await api.functional.discussionBoard.articles.threads.eraseById(connection, { id: thread1.id });
  typia.assert(deleteResult);
  TestValidator.predicate("soft delete is successful")(deleteResult.success === true && deleteResult.thread.id === thread1.id && !!deleteResult.thread.deleted_at);

  // 5. List threads in the category without deleted_at filter (default logic: deleted threads excluded)
  const listDefault = await api.functional.discussionBoard.articles.threads.patch(connection, {
    body: { discussion_board_category_id: category.id },
  });
  typia.assert(listDefault);
  TestValidator.predicate("non-deleted thread is included")(listDefault.data.some(t => t.id === thread2.id));
  TestValidator.predicate("soft-deleted thread is excluded")(listDefault.data.every(t => t.id !== thread1.id));

  // 6. List threads in the category WITH deleted_at filter to show only deleted
  const listDeleted = await api.functional.discussionBoard.articles.threads.patch(connection, {
    body: { discussion_board_category_id: category.id, deleted_at: "1970-01-01T00:00:00.000Z" },
  });
  typia.assert(listDeleted);
  TestValidator.predicate("soft-deleted thread is included when searching for deleted")(listDeleted.data.some(t => t.id === thread1.id && !!t.deleted_at));
}

