/**
 * Validate not-found and soft-deleted thread access in discussion board (GET by ID).
 *
 * This test checks that if a user tries to fetch a thread either non-existent (random UUID) or soft-deleted,
 * the system returns not found (404) or does not present the resource, in full compliance with visibility rules.
 *
 * 1. Attempt to GET a thread by a random UUID that was never created -> expect a not found error (404)
 * 2. (Preparation) Soft-delete an existing thread ID via DELETE /discussionBoard/articles/threads/{id}
 * 3. Attempt to GET the same thread by ID after deletion -> expect a not found error (404) or exclusion, confirming soft-deleted threads are not retrievable
 *
 * Both error cases must fail by throwing, not by returning a thread entity.
 */
export async function test_api_discussionBoard_test_get_thread_not_found_or_soft_deleted(
