  const deleteResult = await api.functional.discussionBoard.articles.threads.eraseById(connection, { id: softDeletedThreadId });
  typia.assert(deleteResult);
  TestValidator.predicate("delete result for soft-deletion")(deleteResult.success === true || deleteResult.message.toLowerCase().includes("already deleted") || deleteResult.message.toLowerCase().includes("not found"));

  // 3. Attempt to GET the thread again after soft-delete; expect error
  await TestValidator.error("GET of soft-deleted thread")(() =>
