/**
 * Test successful creation of a discussion board system configuration property with all required fields and an optional description.
 *
 * This test verifies that:
 * - An admin can create a system configuration with a unique key, a value, and an optional description.
 * - The API responds with a record including all required schema fields (id, key, value, description, created_at, updated_at).
 * - All audit timestamps are set and the configuration is returned as immediately usable data.
 *
 * Step-by-step process:
 * 1. Generate a unique configuration key, a value string, and a sample description.
 * 2. Call the admin-only configuration creation API with these values.
 * 3. Validate that the response has all schema fields populated and matches the sent input.
 *
 * Note: As there is no API provided to re-fetch or use the configuration after creation, validation is limited to creation and schema/assertion checks.
 */
export async function test_api_discussionBoard_test_create_configuration_with_all_required_fields_and_optional_description(
  connection: api.IConnection,
) {
  // 1. Generate unique key and value, supply a sample description
  const uniqueKey = `max_post_length_${Date.now()}`;
  const value = Math.floor(Math.random() * 10000).toString();
  const description = "최대 게시물 길이(문자 수) 제한값입니다.";

  // 2. Call the API to create a new configuration property
  const config = await api.functional.discussionBoard.systematic.configurations.post(
    connection,
    {
      body: {
        key: uniqueKey,
        value,
        description,
      } satisfies IDiscussionBoardConfiguration.ICreate,
    },
  );
  typia.assert(config);

  // 3. Validate that all schema fields are present and correct
  TestValidator.equals("key")(config.key)(uniqueKey);
  TestValidator.equals("value")(config.value)(value);
  TestValidator.equals("description")(config.description)(description);
  TestValidator.predicate("id is a valid UUID")(typeof config.id === "string" && config.id.length > 0);
  TestValidator.predicate(
    "created_at is a valid date-time string",
  )(typeof config.created_at === "string" && config.created_at.length > 0);
  TestValidator.predicate(
    "updated_at is a valid date-time string",
  )(typeof config.updated_at === "string" && config.updated_at.length > 0);
}

