/**
 * 중복된 key로 시스템 구성 설정을 추가할 때 고유 제약(unique constraint) 에러가 발생하는지 검증합니다.
 *
 * 실제 서비스에서는 각 설정 키는 반드시 유일해야 하며, 중복 입력 시 시스템이 일관된 예외를 반환해야 합니다.
 *
 * 프로세스:
 * 1. 테스트용 키로 설정 행을 처음 추가 (정상 생성됨을 확인)
 * 2. 동일한 키로 다시 한 번 설정 행을 추가 시도
 * 3. 두 번째 요청이 unique constraint 위반으로 거부(에러 반환)되는지 검증
 */
export async function test_api_discussionBoard_test_create_configuration_with_duplicate_key_returns_unique_constraint_error(
