import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardConfiguration } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardConfiguration";
import type { IdiscussionBoardConfigurations } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardConfigurations";

/**
 * 관리자 권한으로 UUID 기반 설정 속성(key, value, description)을 업데이트하고, 결과가 스키마와 비즈니스 규칙대로 반영되는지 검증합니다.
 *
 * - 업데이트 후 updated_at(수정일) 타임스탬프가 변경되어야 하며,
 * - 모든 필드가 최신 상태로 반환되어야 합니다.
 *
 * # 테스트 절차
 * 1. 설정 속성(키, 값, 설명)을 등록하여 테스트에 사용할 UUID(식별자)를 확보합니다.
 * 2. PUT /discussionBoard/systematic/configurations/{id}를 활용해 key, value, description 필드를 수정합니다.
 * 3. 응답에서 각 필드가 변경된 내용을 반영하는지 확인합니다.
 * 4. 초기 생성시점의 created_at은 불변이지만 updated_at이 더 최신이어야 함을 확인합니다.
 * 5. 반환 필드 일치 및 타입을 검증합니다.
 */
export async function test_api_discussionBoard_systematic_configurations_test_update_configuration_with_valid_fields(
  connection: api.IConnection,
) {
  // 1. 테스트 대상 설정 행 생성 (유효한 UUID 확보)
  const initialConfig = await api.functional.discussionBoard.systematic.configurations.post(
    connection,
    {
      body: {
        key: "max_post_length_" + RandomGenerator.alphaNumeric(8),
        value: "1000",
        description: "Initial test config for update API",
      } satisfies IDiscussionBoardConfiguration.ICreate,
    },
  );
  typia.assert(initialConfig);

  // 2. key, value, description을 수정해 PUT으로 업데이트
  const updatedKey = initialConfig.key + "_updated";
  const updatedValue = "2000";
  const updatedDescription = "Updated config.\n" + (initialConfig.description || "");

  const updatedConfig = await api.functional.discussionBoard.systematic.configurations.putById(
    connection,
    {
      id: initialConfig.id,
      body: {
        key: updatedKey,
        value: updatedValue,
        description: updatedDescription,
      } satisfies IdiscussionBoardConfigurations.IUpdate,
    },
  );
  typia.assert(updatedConfig);

  // 3. 필드별 변경 내역 검증
  TestValidator.equals("updated key")(updatedConfig.key)(updatedKey);
  TestValidator.equals("updated value")(updatedConfig.value)(updatedValue);
  TestValidator.equals("updated description")(updatedConfig.description)(updatedDescription);
  TestValidator.equals("created_at unchanged")(updatedConfig.created_at)(initialConfig.created_at);
  TestValidator.predicate("updated_at은 created_at보다 늦음")(
    new Date(updatedConfig.updated_at).getTime() > new Date(initialConfig.updated_at).getTime(),
  );

  // 4. 반환 결과 타입 및 최신 상태 일치 검증
  typia.assert(updatedConfig);
}

