  TestValidator.equals('email')(output.email)(email);
  TestValidator.equals('display_name')(output.display_name)(display_name);
  TestValidator.equals('profile_image_url')(output.profile_image_url)(profile_image_url);
  TestValidator.equals('is_active')(output.is_active)(is_active);
  TestValidator.predicate('created_at present')(!!output.created_at);
  TestValidator.predicate('updated_at present')(!!output.updated_at);
  // hashed_password must never be in the response
  if ('hashed_password' in output) throw new Error('hashed_password leak');

