/**
 * Validate listing and filtering of discussion board members with default filters and pagination.
 *
 * This test covers the typical admin/member-directory listing scenario:
 *
 * 1. Register three active members with distinct usernames and emails via POST.
 * 2. Use the PATCH endpoint with an empty body to list all active, non-deleted members.
 *    - Ensure all created members are present in the result.
 *    - Validate pagination object for minimum record count and logical metadata.
 * 3. Use PATCH to list only inactive members (should return none).
 * 4. Use PATCH to filter by a specific known username, expecting only that member in response.
 * 5. Assert correct response types and business logic at all steps.
 */
export async function test_api_discussionBoard_actors_members_test_list_members_with_default_filter(
  connection: api.IConnection,
) {
  // 1. Register three active members
  const members: IdiscussionBoardMembers[] = [];
  for (const suffix of ["A", "B", "C"]) {
    const member: IdiscussionBoardMembers = await api.functional.discussionBoard.actors.members.post(connection, {
      body: {
        username: RandomGenerator.alphabets(8) + suffix,
        email: `${RandomGenerator.alphabets(8)}${suffix}@example.com`,
        hashed_password: RandomGenerator.alphabets(20),
        display_name: "User" + suffix,
        is_active: true,
        profile_image_url: null,
      } satisfies IdiscussionBoardMembers.ICreate,
    });
    typia.assert(member);
    members.push(member);
  }

  // 2. Fetch member list with default filter (should return active, non-deleted)
  const result = await api.functional.discussionBoard.actors.members.patch(connection, {
    body: {} satisfies IdiscussionBoardMembers.IRequest,
  });
  typia.assert(result);

  // Ensure all created members are returned and not soft-deleted
  for (const m of members) {
    const found = result.data.find((x) => x.id === m.id);
    TestValidator.predicate("Newly created member present")(!!found);
    if (found) {
      TestValidator.equals("deleted_at")(found.deleted_at)(null);
      TestValidator.equals("is_active")(found.is_active)(true);
    }
  }

  // Validate pagination metadata (at least 3 exists, page structure is logical)
  TestValidator.predicate("pagination.records >= 3")(result.pagination.records >= 3);
  TestValidator.predicate("pagination.limit > 0")(result.pagination.limit > 0);
  TestValidator.predicate("pagination.current >= 1")(result.pagination.current >= 1);
  TestValidator.predicate("pagination.pages >= 1")(result.pagination.pages >= 1);

  // 3. List ONLY inactive members (should be none)
  const inactiveResult = await api.functional.discussionBoard.actors.members.patch(connection, {
    body: { is_active: false } satisfies IdiscussionBoardMembers.IRequest,
  });
  typia.assert(inactiveResult);
  TestValidator.equals("No inactive members")(inactiveResult.data.length)(0);
  TestValidator.equals("Inactive records count")(inactiveResult.pagination.records)(0);

  // 4. Filter by known username (should match only one member)
  const username = members[0].username;
  const byName = await api.functional.discussionBoard.actors.members.patch(connection, {
    body: { username } satisfies IdiscussionBoardMembers.IRequest,
  });
  typia.assert(byName);
  TestValidator.equals("Exact username match")(byName.data.length)(1);
  TestValidator.equals("Username correct")(byName.data[0].username)(username);
  TestValidator.equals("Records == 1")(byName.pagination.records)(1);
}

