/**
 * 존재하지 않는 회원 명 또는 이메일로 검색 시 빈 결과 반환 테스트
 *
 * 이 테스트는 관리자가 회원 조회/검색 기능을 사용할 때,
 * 입력한 검색 조건(username/email 등)이 실제로 시스템 내에 매칭되는 회원이 없을 경우
 * 정상적으로 빈 리스트(0건)와 올바른 페이징 구조를 반환하는지 검증합니다.
 *
 * 검사 항목:
 * 1. 유효하지 않은 username/email로 회원 목록 조회
 * 2. 응답의 data 배열이 빈 배열([])인지 확인
 * 3. pagination.records 값이 0인지 확인
 * 4. pagination.pages, current, limit 등 페이징 값이 정상적인지 추가 검증
 *
 * 주요 비즈니스 목적:
 * - 검색 결과가 없을 때 프론트엔드, 운영 패널, 감사(Audit) 시스템 등이 예측 가능한 UI 렌더링이 가능한지
 * - 시스템이 빈 검색 결과 상황을 정상적으로 처리하는지 측정
 */
export async function test_api_discussionBoard_actors_members_test_list_members_with_no_matching_results(
  connection: api.IConnection,
) {
  // 1. 존재하지 않는 username/email 조합 생성
  const request = {
    username: `nonexistent_${typia.random<string>()}_${Date.now()}`,
    email: `nonexistent_${typia.random<string>()}_${Date.now()}@invalid-domain.com`,
  } satisfies IdiscussionBoardMembers.IRequest;

  // 2. API 호출: 존재하지 않는 회원명/이메일로 목록 검색
  const output = await api.functional.discussionBoard.actors.members.patch(connection, {
    body: request,
  });
  typia.assert(output);

  // 3. 결과 검증: data가 빈 배열([])이어야 함
  TestValidator.equals("data must be empty")(output.data)([]);

  // 4. pagination.records == 0 이어야 함
  TestValidator.equals("zero matching records")(output.pagination.records)(0);

  // 5. pagination.pages는 0 또는 1이 나올 수 있음 (구현체에 따라 다름)
  TestValidator.predicate("pages must be 0 or 1")(output.pagination.pages === 0 || output.pagination.pages === 1);

  // 6. pagination.current는 기본적으로 1 페이지여야 함
  TestValidator.equals("current page should be 1 when empty")(output.pagination.current)(1);

  // 7. pagination.limit > 0 (페이지 제한값이 0이면 페이징이 의미 없음)
  TestValidator.predicate("limit is nonzero")(output.pagination.limit > 0);
}

