import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IDiscussionBoardThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardThread";
import type { discussion_board_vote_types } from "@ORGANIZATION/PROJECT-api/lib/structures/discussion_board_vote_types";
import type { discussion_board_votes } from "@ORGANIZATION/PROJECT-api/lib/structures/discussion_board_votes";

/**
 * Validates updating a vote record as an administrator using valid schema fields.
 *
 * This test implements the scenario:
 * - Begin by creating two vote types (e.g., 'upvote', 'downvote') for use in the votes.
 * - Register a member account who can cast votes.
 * - Create a thread (the target to be voted on), authored by the registered member.
 * - Cast a vote on the thread by the member, using one of the vote types.
 * - Update the vote record (as admin) to change `vote_type_id` to the other vote type.
 * - Assert that only `vote_type_id` and `updated_at` fields change; others remain consistent.
 * - Check referential integrity: All foreign keys still point to valid, known entities.
 * - Validate that 'created_at' is unchanged but 'updated_at' increases.
 * - Attempt to update with a non-existent `vote_type_id` and verify error is thrown.
 *
 * Steps:
 * 1. Create a vote type ('upvote').
 * 2. Create a second vote type ('downvote') for change-test.
 * 3. Register a member for voting.
 * 4. Create a thread authored by that member.
 * 5. Cast an initial vote (member, 'upvote', thread).
 * 6. Update the vote record to change `vote_type_id` to 'downvote'.
 * 7. Assert only allowed changes occur; verify correctness and integrity refs.
 * 8. Test constraint error by updating with a non-existent vote_type_id.
 */
export async function test_api_discussionBoard_votes_votes_test_update_vote_record_with_valid_data(
  connection: api.IConnection,
) {
  // 1. Create a vote type ('upvote').
  const voteType1 = await api.functional.discussionBoard.votes.voteTypes.post(connection, {
    body: {
      code: "upvote",
      name: "Upvote",
      description: "Indicates a positive reaction",
    },
  });
  typia.assert(voteType1);

  // 2. Create a second vote type ('downvote').
  const voteType2 = await api.functional.discussionBoard.votes.voteTypes.post(connection, {
    body: {
      code: "downvote",
      name: "Downvote",
      description: "Indicates a negative reaction",
    },
  });
  typia.assert(voteType2);

  // 3. Register a member (to serve as voter).
  const passwordHash = RandomGenerator.alphaNumeric(32);
  const member = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: passwordHash,
      display_name: RandomGenerator.name(),
      is_active: true,
    },
  });
  typia.assert(member);

  // 4. Create a thread authored by the member. The category_id must be a well-formed uuid. Use a random.
  const thread = await api.functional.discussionBoard.articles.threads.post(connection, {
    body: {
      discussion_board_category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(),
      body: RandomGenerator.content()()(),
      is_pinned: false,
      is_closed: false,
    },
  });
  typia.assert(thread);

  // 5. Cast a vote (member upvotes the new thread)
  const vote = await api.functional.discussionBoard.votes.votes.post(connection, {
    body: {
      voter_id: member.id,
      vote_type_id: voteType1.id,
      thread_id: thread.id,
    },
  });
  typia.assert(vote);

  // 6. Update the vote record (as admin) to change vote_type_id to 'downvote'.
  // Ensure updated_at is later than created_at (wait at least 1ms for db granularity).
  await new Promise((resolve) => setTimeout(resolve, 1100));
  const updatedVote = await api.functional.discussionBoard.votes.votes.putById(connection, {
    id: vote.id,
    body: {
      vote_type_id: voteType2.id,
    },
  });
  typia.assert(updatedVote);

  // 7. Assert only allowed fields change (vote_type_id, updated_at)
  TestValidator.equals("voter unchanged")(updatedVote.voter_id)(vote.voter_id);
  TestValidator.equals("thread unchanged")(updatedVote.thread_id)(vote.thread_id);
  TestValidator.equals("post unchanged")(updatedVote.post_id)(vote.post_id);
  TestValidator.equals("comment unchanged")(updatedVote.comment_id)(vote.comment_id);
  TestValidator.notEquals("vote_type_id updated")(updatedVote.vote_type_id)(vote.vote_type_id);
  TestValidator.equals("vote_type_id now matches voteType2")(updatedVote.vote_type_id)(voteType2.id);
  TestValidator.equals("created_at unchanged")(updatedVote.created_at)(vote.created_at);
  TestValidator.predicate("updated_at increased")(Date.parse(updatedVote.updated_at) > Date.parse(vote.updated_at));

  // 8. Check referential integrity: foreign keys point to current entities
  TestValidator.equals("voteType2 id valid")(updatedVote.vote_type_id)(voteType2.id);
  TestValidator.equals("voter matches member id")(updatedVote.voter_id)(member.id);
  TestValidator.equals("thread matches thread id")(updatedVote.thread_id)(thread.id);

  // 9. Test constraint error: update using a non-existent vote_type_id
  await TestValidator.error("update with invalid vote_type_id should fail")(async () => {
    await api.functional.discussionBoard.votes.votes.putById(connection, {
      id: vote.id,
      body: {
        vote_type_id: typia.random<string & tags.Format<"uuid">>(),
      },
    });
  });
}

