 *
 * Steps:
 * 1. Create several tags (at least three, where at least two share a name or description substring for meaningful filter coverage).
 * 2. Use the PATCH endpoint to search tags with a filter value for `name` (partial match), specifying explicit pagination (`page`, `limit`).
 * 3. Validate:
 *     - Only tags whose name includes the filter value are returned in `data`.
 *     - At least one known tag matching the filter is present.
 *     - Pagination metadata (`current`, `limit`) is as requested.
 *     - All returned tags match the IDiscussionBoardTag schema.
 */
export async function test_api_discussionBoard_test_search_tags_with_name_filter_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create several tags (with known names and descriptions)
  const tagA = await api.functional.discussionBoard.categories.tags.post(connection, {
    body: {
      name: "inflation",
      description: "Macroeconomic inflation topics"
    },
  });
  typia.assert(tagA);

  const tagB = await api.functional.discussionBoard.categories.tags.post(connection, {
    body: {
      name: "policy",
      description: "Government fiscal policy"
    },
