    body: {
      name: "deflation",
      description: "Macroeconomic deflation topics"
    },
  });
  typia.assert(tagC);

  // 2. Search for tags whose name contains 'infl', with paging
  const filter = { name: "infl", page: 1, limit: 2 } satisfies IDiscussionBoardTag.IRequest;
  const output = await api.functional.discussionBoard.categories.tags.patch(connection, { body: filter });
  typia.assert(output);

  // 3. Validate response
  // Should contain only tags whose name matches the filter
  TestValidator.predicate("only tags with 'infl' in name are returned")(
    output.data.every((t) => t.name.includes("infl")),
  );
  // Must include our created 'inflation' tag
  TestValidator.predicate("tagA present in filtered result")(
    output.data.some((t) => t.id === tagA.id),
  );
  // Pagination fields match request
  TestValidator.equals("pagination.limit")(output.pagination.limit)(2);
  TestValidator.equals("pagination.current")(output.pagination.current)(1);
  // All returned tags are valid by schema
  output.data.forEach((tag) => typia.assert(tag));
}

