 * - 각 필드의 값 일치성(데이터가 올바르게 저장 및 반환되었는지)
 * 를 검증한다.
 *
 * 1. 임의의 채널 코드/이름/설명 값으로 채널을 생성한다.
 * 2. 생성된 채널의 id로 상세 조회 API를 호출한다.
 * 3. 응답으로 받은 객체가 스키마의 모든 필드를 포함하는지 typia.assert로 체크한다.
 * 4. 조회 결과의 데이터(코드, 이름, 설명, created_at/updated_at 등)가 생성 시점과 일치하는지 검사한다.
 * 5. deleted_at 필드는 새 채널인 경우 null 또는 undefined임을 확인한다.
 */
export async function test_api_discussionBoard_systematic_channels_getById(
  connection: api.IConnection,
) {
  // 1. 신규 채널 생성
  const createInput: IDiscussionBoardChannel.ICreate = {
    code: `eco-${RandomGenerator.alphaNumeric(8)}`,
    name: `이슈토론-${RandomGenerator.alphaNumeric(6)}`,
    description: `자동생성 테스트 - ${RandomGenerator.paragraph()(1)}`,
  };
  const created = await api.functional.discussionBoard.systematic.channels.post(connection, {
    body: createInput,
  });
  typia.assert(created);

  // 2. 상세조회 호출
  const fetched = await api.functional.discussionBoard.systematic.channels.getById(connection, {
    id: created.id,
  });
  typia.assert(fetched);

  // 3. 필드 값 일치성 검증
  TestValidator.equals("id 일치")(fetched.id)(created.id);
  TestValidator.equals("code 일치")(fetched.code)(createInput.code);
  TestValidator.equals("name 일치")(fetched.name)(createInput.name);
  TestValidator.equals("description 일치")(fetched.description)(createInput.description);

  // 4. created/updated_at이 ISO 형식인지 및 값 타입 체크
  TestValidator.predicate("created_at ISO 8601")(!!Date.parse(fetched.created_at));
  TestValidator.predicate("updated_at ISO 8601")(!!Date.parse(fetched.updated_at));

  // 5. deleted_at이 없다면(null 또는 undefined) 정상임
  TestValidator.predicate("새 채널은 삭제상태 아님")(
    fetched.deleted_at === null || typeof fetched.deleted_at === "undefined"
  );
}

