import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardChannel";

/**
 * Test admin policy for fetch-by-id on soft-deleted channels.
 *
 * This E2E test checks if a channel that has been soft-deleted (deleted_at set)
 * can be fetched by id. The policy may allow viewing soft-deleted channels with
 * deleted_at populated or may reject access. Either outcome must be handled.
 *
 * Steps:
 * 1. Create a discussion board channel using POST endpoint.
 * 2. Soft-delete (DELETE) the same channel. Confirm deleted_at is set.
 * 3. Try fetching the channel by id. If result is returned, assert deleted_at is set.
 *    If error is thrown, assert error.
 *
 * This ensures either visibility-with-deleted_at or error blocking is enforced by policy.
 */
export async function test_api_discussionBoard_systematic_channels_test_get_soft_deleted_channel_by_id(
  connection: api.IConnection,
) {
  // 1. Create a new discussion board channel
  const createInput = {
    code: RandomGenerator.alphabets(8),
    name: RandomGenerator.paragraph()(1),
    description: RandomGenerator.paragraph()(1),
  } satisfies IDiscussionBoardChannel.ICreate;
  const created = await api.functional.discussionBoard.systematic.channels.post(connection, {
    body: createInput,
  });
  typia.assert(created);

  // 2. Soft-delete the channel
  const deleted = await api.functional.discussionBoard.systematic.channels.eraseById(connection, {
    id: created.id,
  });
  typia.assert(deleted);
  TestValidator.predicate("deleted_at is set after deletion")(!!deleted.deleted_at);

  // 3. Attempt to fetch the soft-deleted channel
  let fetchResult: IDiscussionBoardChannel | undefined = undefined;
  let fetchError: unknown = undefined;
  try {
    const fetched = await api.functional.discussionBoard.systematic.channels.getById(connection, {
      id: created.id,
    });
    typia.assert(fetched);
    fetchResult = fetched;
  } catch (err) {
    fetchError = err;
  }

  // 4. Validate policy: returned with deleted_at or error on access
  if (fetchResult !== undefined) {
    TestValidator.predicate("soft-deleted channel fetch yields deleted_at value")(!!fetchResult.deleted_at);
  } else {
    TestValidator.error("fetching soft-deleted channel results in error")(() => {
      if (fetchError === undefined) throw new Error("Expected error, got none");
      throw fetchError;
    });
  }
}

