  const initialDescription = RandomGenerator.paragraph()();
  const channel = await api.functional.discussionBoard.systematic.channels.post(connection, {
    body: {
      code: initialCode,
      name: initialName,
      description: initialDescription,
    } satisfies IDiscussionBoardChannel.ICreate,
  });
  typia.assert(channel);

  // 2. 생성 결과값 저장
  const { id, code, name, description, created_at, updated_at, deleted_at } = channel;

  // 3. 변경용 값 준비
  const updatedName = RandomGenerator.alphaNumeric(10);
  const updatedDescription = RandomGenerator.paragraph()();

  // 4. 이름과 설명만 변경
  const updated = await api.functional.discussionBoard.systematic.channels.putById(connection, {
    id: id,
    body: {
      name: updatedName,
      description: updatedDescription,
    } satisfies IDiscussionBoardChannel.IUpdate,
  });
  typia.assert(updated);

  // 5. code, created_at, deleted_at 등은 동일한지, name/description은 반영됐는지, updated_at이 변경됐는지
  TestValidator.equals("채널 id 동일")(updated.id)(id);
  TestValidator.equals("code 불변")(updated.code)(code);
  TestValidator.equals("created_at 불변")(updated.created_at)(created_at);
  TestValidator.equals("deleted_at 불변")(updated.deleted_at)(deleted_at);
  TestValidator.equals("name 변경됨")(updated.name)(updatedName);
  TestValidator.equals("description 변경됨")(updated.description)(updatedDescription);
  TestValidator.notEquals("updated_at 갱신됨")(updated.updated_at)(updated_at);
}

