 *
 * 두 개의 채널을 서로 다른 코드로 차례로 생성한 후,
 * 두 번째 채널의 코드를 첫 번째 채널의 코드로 업데이트 시도했을 때
 * API가 고유 제약(Unique Constraint) 에러를 반환하는지 확인합니다.
 *
 * 1. 첫 번째 채널을 고유 code로 생성
 * 2. 두 번째 채널을 또 다른 고유 code로 생성
 * 3. 두 번째 채널을 첫 번째의 code로 변경 시도 → 실패해야 함
 */
export async function test_api_discussionBoard_systematic_channels_test_update_channel_code_to_duplicate(
  connection: api.IConnection,
) {
  // 1. 첫 번째 채널 생성: 고유 code 사용
  const codeA = `codeA_${RandomGenerator.alphabets(8)}`;
  const channelA = await api.functional.discussionBoard.systematic.channels.post(
    connection,
    {
      body: {
        code: codeA,
        name: `채널A_${RandomGenerator.alphabets(8)}`,
        description: "유니크 테스트용 첫 번째 채널",
      } satisfies IDiscussionBoardChannel.ICreate,
    },
  );
  typia.assert(channelA);
  TestValidator.equals("codeA 채널 코드")(channelA.code)(codeA);

  // 2. 두 번째 채널 생성: 또 다른 고유 code
  const codeB = `codeB_${RandomGenerator.alphabets(8)}`;
  const channelB = await api.functional.discussionBoard.systematic.channels.post(
    connection,
    {
      body: {
        code: codeB,
        name: `채널B_${RandomGenerator.alphabets(8)}`,
        description: "유니크 테스트용 두 번째 채널",
      } satisfies IDiscussionBoardChannel.ICreate,
    },
  );
  typia.assert(channelB);
  TestValidator.equals("codeB 채널 코드")(channelB.code)(codeB);

  // 3. 두 번째 채널의 code를 첫 번째 채널의 code로 변경 시도 → unique 제약 에러를 기대
  await TestValidator.error("채널 코드 중복 업데이트는 실패해야 함")(
    () =>
      api.functional.discussionBoard.systematic.channels.putById(
        connection,
        {
          id: channelB.id,
          body: {
            code: codeA,
          } satisfies IDiscussionBoardChannel.IUpdate,
        },
      ),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardChannel";

/**
 * 채널 스키마에 없는 필드(예: deleted_at)를 포함하여 업데이트 요청을 시도할 때 시스템 거부 및 무시 동작을 검증한다.
 *
 * 이 테스트는 DiscussionBoard 채널 업데이트 API에서 스키마(타입)에 포함되지 않은 필드는 타입 차원 및 시스템 정책상
 * body로 전달 자체가 불가능하다는 점을 검증한다. 즉, deleted_at 등 시스템 필드는 타입 차단으로 인해 런타임에서 테스트가 불가하다.
 *
 * 따라서 테스트는 아래 프로세스를 따른다:
 * 1. 정상적인 채널을 생성한다.
 * 2. 스키마 필드(code, name, description)로만 update를 진행한다.
 * 3. updated_at, deleted_at 등 시스템 필드가 update로 변경되지 않음을 assertion한다.
 *   - deleted_at, created_at은 update API 상 변경 불가임을 검증
 *
 * (타입 정의 외의 임의 필드는 타입에러로 인해 테스트 코드 내에서 전달 자체가 불가하므로, runtime 유효성 실패 형태의 negative test 구현이 불가하다)
 */
export async function test_api_discussionBoard_systematic_channels_test_update_non_schema_fields(
  connection: api.IConnection,
) {
  // 1. 정상 채널 생성
  const created = await api.functional.discussionBoard.systematic.channels.post(connection, {
    body: {
      code: `eco-${Date.now()}`,
      name: "생성채널",
      description: "설명입니다",
    },
  });
  typia.assert(created);

  // 2. (negative path 없음) 비스키마 필드 update 시도는 타입 단에서 불가
  //    --> 즉, { deleted_at: ... } 형태 전달 자체가 compile error이므로 실제 시도 생략

  // 3. 정상 필드만으로 업데이트
  const updated = await api.functional.discussionBoard.systematic.channels.putById(connection, {
    id: created.id,
    body: {
      name: "수정된채널명",
      description: "수정된설명",
    },
  });
  typia.assert(updated);
  // 기본 불변성 및 변경점 검증
  TestValidator.equals("id 동일성")(updated.id)(created.id);
  TestValidator.equals("code 동일성")(updated.code)(created.code);
  TestValidator.equals("이름 정상 업데이트")(updated.name)("수정된채널명");
  TestValidator.equals("설명 정상 업데이트")(updated.description)("수정된설명");
  // deleted_at, created_at은 update에서 변경 불가함을 검증
  TestValidator.equals("deleted_at 불변성")(updated.deleted_at)(created.deleted_at);
  TestValidator.equals("created_at 불변성")(updated.created_at)(created.created_at);
}

