/**
 * Test soft-deleting a discussion board channel by setting deleted_at.
 *
 * This test verifies that the channel "delete" operation correctly marks a channel as deleted by updating the deleted_at field, rather than removing the record.
 *
 * Workflow:
 * 1. Create a new discussion board channel by supplying unique code, name, and optional description.
 * 2. Soft-delete the created channel by calling the eraseById (delete) API with its id.
 * 3. Validate:
 *    - The returned object has the same id, code, name, and description as originally created.
 *    - The deleted_at field is set to a valid date-time string (not null or undefined), proving soft-deletion.
 */
export async function test_api_discussionBoard_systematic_channels_test_soft_delete_channel_by_id(
