        description: Math.random() < 0.5 ? RandomGenerator.paragraph()(1) : undefined,
      } satisfies IDiscussionBoardChannel.ICreate,
    },
  );
  typia.assert(createdChannel);

  // 2. Soft-delete the channel by its id
  const deletedChannel = await api.functional.discussionBoard.systematic.channels.eraseById(
    connection,
    {
      id: createdChannel.id,
    },
  );
