/**
 * Validates that attempting to create a board mention event with a non-existent content_id fails, enforcing foreign key integrity.
 *
 * This test ensures mention events cannot be created referencing invalid posts, threads, or comments. It:
 * 1. Creates two real members (the actor and the mentioned member)
 * 2. Attempts to create an @mention event in the notification system with a random/fake UUID as content_id (guaranteed not to exist)
 * 3. Expects a failure, asserting an error is thrown due to invalid content_id (foreign key violation)
 */
export async function test_api_discussionBoard_test_create_mention_invalid_content_id_fails(
  connection: api.IConnection,
) {
  // 1. Create the actor member (the user who will mention someone)
  const actor: IdiscussionBoardMembers = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
