    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(12),
      display_name: RandomGenerator.name(),
      profile_image_url: null,
      is_active: true,
    } satisfies IdiscussionBoardMembers.ICreate,
  });
  typia.assert(mentioned);

  // 3. Attempt to create a mention with an invalid (not real) content_id
  await TestValidator.error("creating mention with invalid content_id should fail")(() =>
    api.functional.discussionBoard.notifications.mentions.post(connection, {
