import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IDiscussionBoardThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardThread";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardMention } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMention";
import type { IPageIDiscussionBoardMention } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardMention";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate listing of @mention notifications for a member, supporting paginated results.
 *
 * This test verifies that after creating multiple mention events, the API correctly retrieves paginated mention lists for a specified member. Two members are created (actor and mentioned). The actor mentions the mentioned member in two distinct content contexts (a post and a comment). The test queries the mention list for the mentioned member using pagination (page, limit) to check correct splitting of events across pages, and validates the correctness of returned data, counts, and context linkage.
 *
 * Implementation steps:
 * 1. Create two discussion board members: actor and mentioned member.
 * 2. Create a thread (using the actor as thread creator).
 * 3. Create a post in the thread (actor is the post author).
 * 4. Create a comment in the post (actor is the comment author).
 * 5. Create two mention events, both targeting the mentioned member:
 *    - One for the post ('content_type': 'post', 'content_id' = post id)
 *    - One for the comment ('content_type': 'comment', 'content_id' = comment id)
 * 6. List mentions for the mentioned member with pagination (limit=1, page=1: first result, page=2: second result).
 * 7. Validate that both individual pages return one mention each, and combined they cover both events, with the correct context type and id.
 */
export async function test_api_discussionBoard_test_list_mentions_for_member_with_pagination(
  connection: api.IConnection,
) {
  // 1. Create two members: actor and mentioned member
  const actorMember = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      display_name: RandomGenerator.name(),
      profile_image_url: null,
      is_active: true,
    } satisfies IdiscussionBoardMembers.ICreate,
  });
  typia.assert(actorMember);
  const mentionedMember = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      display_name: RandomGenerator.name(),
      profile_image_url: null,
      is_active: true,
    } satisfies IdiscussionBoardMembers.ICreate,
  });
  typia.assert(mentionedMember);

  // 2. Create a thread (actor is creator)
  const thread = await api.functional.discussionBoard.articles.threads.post(connection, {
    body: {
      discussion_board_category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(1),
      body: RandomGenerator.content()()(),
      is_pinned: false,
      is_closed: false,
      // actor is the creator
      discussion_board_member_id: actorMember.id,
    } as any, // suppress TS error for extra property, will be ignored by API if not part of schema
  });
  typia.assert(thread);

  // 3. Create a post in the thread (actor is author)
  const post = await api.functional.discussionBoard.articles.posts.post(connection, {
    body: {
      discussion_board_thread_id: thread.id,
      discussion_board_member_id: actorMember.id,
      body: RandomGenerator.content()()(),
    } satisfies IDiscussionBoardPost.ICreate,
  });
  typia.assert(post);

  // 4. Create a comment in the post (actor is author)
  const comment = await api.functional.discussionBoard.articles.comments.post(connection, {
    body: {
      discussion_board_post_id: post.id,
      discussion_board_member_id: actorMember.id,
      body: RandomGenerator.content()()(),
      parent_id: null,
    } satisfies IDiscussionBoardComment.ICreate,
  });
  typia.assert(comment);

  // 5. Create two mentions for the mentioned member (for post and comment)
  const now = new Date().toISOString();
  const mentionOnPost = await api.functional.discussionBoard.notifications.mentions.post(connection, {
    body: {
      mentioned_member_id: mentionedMember.id,
      actor_member_id: actorMember.id,
      content_type: "post",
      content_id: post.id,
      created_at: now,
    } satisfies IDiscussionBoardMention.ICreate,
  });
  typia.assert(mentionOnPost);
  const mentionOnComment = await api.functional.discussionBoard.notifications.mentions.post(connection, {
    body: {
      mentioned_member_id: mentionedMember.id,
      actor_member_id: actorMember.id,
      content_type: "comment",
      content_id: comment.id,
      created_at: now,
    } satisfies IDiscussionBoardMention.ICreate,
  });
  typia.assert(mentionOnComment);

  // 6. List mentions, page 1 (limit=1, page=1)
  const page1 = await api.functional.discussionBoard.notifications.mentions.patch(connection, {
    body: {
      mentioned_member_id: mentionedMember.id,
      page: 1,
      limit: 1,
    } satisfies IDiscussionBoardMention.IRequest,
  });
  typia.assert(page1);
  TestValidator.equals("pagination.current is 1")(page1.pagination.current)(1);
  TestValidator.equals("pagination.limit is 1")(page1.pagination.limit)(1);
  TestValidator.equals("pagination.pages is 2")(page1.pagination.pages)(2);
  TestValidator.equals("pagination.records is 2")(page1.pagination.records)(2);
  TestValidator.equals("data.length is 1")(page1.data.length)(1);
  const mention1 = page1.data[0];

  // 7. List mentions, page 2 (limit=1, page=2)
  const page2 = await api.functional.discussionBoard.notifications.mentions.patch(connection, {
    body: {
      mentioned_member_id: mentionedMember.id,
      page: 2,
      limit: 1,
    } satisfies IDiscussionBoardMention.IRequest,
  });
  typia.assert(page2);
  TestValidator.equals("pagination.current is 2")(page2.pagination.current)(2);
  TestValidator.equals("pagination.limit is 1")(page2.pagination.limit)(1);
  TestValidator.equals("pagination.pages is 2")(page2.pagination.pages)(2);
  TestValidator.equals("pagination.records is 2")(page2.pagination.records)(2);
  TestValidator.equals("data.length is 1")(page2.data.length)(1);
  const mention2 = page2.data[0];

  // 8. Validate that both mentions are returned and have correct content context
  const expected = [
    {
      content_type: mentionOnPost.content_type,
      content_id: mentionOnPost.content_id,
    },
    {
      content_type: mentionOnComment.content_type,
      content_id: mentionOnComment.content_id,
    },
  ];
  const actual = [
    { content_type: mention1.content_type, content_id: mention1.content_id },
    { content_type: mention2.content_type, content_id: mention2.content_id },
  ];
  // Since order is not specified, validate both expected events are present across the two pages
  for (const exp of expected) {
    TestValidator.predicate(`mention of type ${exp.content_type} with correct id exists`)(
      actual.some(a => a.content_type === exp.content_type && a.content_id === exp.content_id),
    );
  }
}

