      actor_member_id: actorMember.id,
      content_type: "post",
      content_id: post.id,
      created_at: now,
    },
  });
  typia.assert(mention);

  // 6. Retrieve the mention event by ID
  const mentionDetail = await api.functional.discussionBoard.notifications.mentions.getById(connection, {
    id: mention.id,
  });
  typia.assert(mentionDetail);

  // 7. Validate all details match
  TestValidator.equals("mentioned_member_id")(mentionDetail.mentioned_member_id)(mention.mentioned_member_id);
  TestValidator.equals("actor_member_id")(mentionDetail.actor_member_id)(mention.actor_member_id);
  TestValidator.equals("content_type")(mentionDetail.content_type)(mention.content_type);
  TestValidator.equals("content_id")(mentionDetail.content_id)(mention.content_id);
