import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IdiscussionBoardModerators } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardModerators";
import type { IDiscussionBoardThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardThread";
import type { IDiscussionBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReport";

/**
 * moderation report 담당 지정 & 상태 변경 E2E 테스트
 *
 * - 신고(리포트)를 정상적으로 업데이트(모더레이터 할당, 상태 수동 변경, 처리 노트 입력)할 수 있는지 E2E로 검증합니다.
 *
 * [시나리오 및 절차]
 * 1. 신고 작성자 역할 member 회원 등록 (member1)
 * 2. 모더레이터로 사용할 member 회원 등록 (member2)
 * 3. 게시글(thread) 생성 (신고할 타겟)
 * 4. 신고 생성 (member1이 thread를 'pending'으로 신고), 생성 결과의 report.id 확보
 * 5. member2를 모더레이터로 승격시켜 moderation report에 moderator_id로 부여
 * 6. report를 업데이트하여 (a) moderator 할당, (b) status를 'in_progress'로 변경, (c) 노트 입력
 * 7. 반환된 report에서 할당된 moderator, 상태, 노트 반영 확인(TestValidator)
 */
export async function test_api_discussionBoard_moderation_reports_test_update_moderation_report_assign_moderator_and_change_status(
  connection: api.IConnection,
) {
  // 1. 신고 작성자 회원 생성 (member1)
  const member1Email = typia.random<string & tags.Format<"email">>();
  const member1Username = RandomGenerator.alphaNumeric(10);
  const member1: IdiscussionBoardMembers = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: member1Username,
      email: member1Email,
      hashed_password: RandomGenerator.alphaNumeric(12),
      display_name: RandomGenerator.name(),
      is_active: true,
    },
  });
  typia.assert(member1);

  // 2. 모더레이터 전환할 회원 생성 (member2)
  const member2Email = typia.random<string & tags.Format<"email">>();
  const member2Username = RandomGenerator.alphaNumeric(10);
  const member2: IdiscussionBoardMembers = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: member2Username,
      email: member2Email,
      hashed_password: RandomGenerator.alphaNumeric(12),
      display_name: RandomGenerator.name(),
      is_active: true,
    },
  });
  typia.assert(member2);

  // 3. 신고할 thread 엔티티 생성
  const thread: IDiscussionBoardThread = await api.functional.discussionBoard.articles.threads.post(connection, {
    body: {
      discussion_board_category_id: typia.random<string & tags.Format<"uuid">>(), // 실제 운영환경에선 유효 카테고리 필요
      title: RandomGenerator.paragraph()(1),
      body: RandomGenerator.content()(1)(1),
      is_pinned: false,
      is_closed: false,
    },
  });
  typia.assert(thread);

  // 4. moderation report 생성: member1이 thread를 'pending' 상태로 신고
  const report: IDiscussionBoardReport = await api.functional.discussionBoard.moderation.reports.post(connection, {
    body: {
      reporter_member_id: member1.id,
      thread_id: thread.id,
      reason: "스팸 신고 테스트",
      status: "pending"
    },
  });
  typia.assert(report);

  // 5. member2를 모더레이터로 승격 (moderators row insert)
  const nowIso = new Date().toISOString();
  const moderatorObj = await api.functional.discussionBoard.actors.moderators.post(connection, {
    body: {
      member_id: member2.id,
      assigned_at: nowIso,
    },
  });
  typia.assert(moderatorObj);

  // 6. 신고 report 업데이트: moderator 배정, status 변경, 노트 기록
  const updatedReport: IDiscussionBoardReport = await api.functional.discussionBoard.moderation.reports.putById(connection, {
    id: report.id,
    body: {
      moderator_id: moderatorObj.id,
      status: "in_progress",
      resolution_notes: "초기 검토 및 배정 완료"
    },
  });
  typia.assert(updatedReport);

  // 7. 결과 검증 - 할당, 상태, 노트
  TestValidator.equals("moderator assigned")(updatedReport.moderator_id)(moderatorObj.id);
  TestValidator.equals("status changed")(updatedReport.status)("in_progress");
  TestValidator.equals("resolution notes")(updatedReport.resolution_notes)("초기 검토 및 배정 완료");
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IdiscussionBoardModerators } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardModerators";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReport";

/**
 * Validate updating a moderation report's workflow status to 'resolved' with proper resolution notes and audit.
 *
 * This test ensures moderators can resolve reports, fills necessary updatable fields (status, resolution_notes, resolved_at), and verifies updates persist.
 *
 * Steps:
 * 1. Member creation: Create a non-moderator member (will report the post)
 * 2. Post creation: Member creates post (post to be reported)
 * 3. Report creation: Member reports the created post
 * 4. Moderator creation: Register new member and assign as moderator
 * 5. Update the report: As moderator, update report with status='resolved', set resolution_notes, set resolved_at to current time, and assign moderator_id.
 * 6. Assert: Report fields updated: status, resolution_notes, resolved_at, moderator_id. Unchanged: immutable fields.
 * 7. Edge: Attempt to update immutable fields (e.g. reporter_member_id) and confirm error is returned.
 */
export async function test_api_discussionBoard_moderation_reports_test_update_moderation_report_status_to_resolved_with_resolution_notes(
  connection: api.IConnection,
) {
  // 1. Create reporting member
  const reporterMember = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(24),
      display_name: RandomGenerator.name(),
      is_active: true,
      profile_image_url: null,
    } satisfies IdiscussionBoardMembers.ICreate,
  });
  typia.assert(reporterMember);

  // 2. Create a dummy thread to satisfy post (thread id required)
  const dummyThreadId = typia.random<string & tags.Format<"uuid">>();

  // 3. Create a post by reporter
  const post = await api.functional.discussionBoard.articles.posts.post(connection, {
    body: {
      discussion_board_thread_id: dummyThreadId,
      discussion_board_member_id: reporterMember.id,
      body: RandomGenerator.paragraph()(),
    } satisfies IDiscussionBoardPost.ICreate,
  });
  typia.assert(post);

  // 4. Create moderation report against the post
  const report = await api.functional.discussionBoard.moderation.reports.post(connection, {
    body: {
      reporter_member_id: reporterMember.id,
      post_id: post.id,
      thread_id: null,
      comment_id: null,
      reason: "Test spam",
      status: "pending",
    } satisfies IDiscussionBoardReport.ICreate,
  });
  typia.assert(report);

  // 5. Create moderator user and assign moderator role
  const moderatorMember = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(24),
      display_name: RandomGenerator.name(),
      is_active: true,
      profile_image_url: null,
    } satisfies IdiscussionBoardMembers.ICreate,
  });
  typia.assert(moderatorMember);

  const assignedAt = new Date().toISOString();
  const moderator = await api.functional.discussionBoard.actors.moderators.post(connection, {
    body: {
      member_id: moderatorMember.id,
      assigned_at: assignedAt,
    } satisfies IdiscussionBoardModerators.ICreate,
  });
  typia.assert(moderator);

  // 6. Moderator resolves the report
  const now = new Date().toISOString();
  const resolutionNotes = "Marked as resolved by test case.";
  const updatedReport = await api.functional.discussionBoard.moderation.reports.putById(connection, {
    id: report.id,
    body: {
      moderator_id: moderator.id,
      status: "resolved",
      resolution_notes: resolutionNotes,
      resolved_at: now,
    } satisfies IDiscussionBoardReport.IUpdate,
  });
  typia.assert(updatedReport);
  TestValidator.equals("status should be updated")(updatedReport.status)("resolved");
  TestValidator.equals("resolution_notes updated")(updatedReport.resolution_notes)(resolutionNotes);
  TestValidator.equals("resolved_at updated")(updatedReport.resolved_at)(now);
  TestValidator.equals("moderator_id set")(updatedReport.moderator_id)(moderator.id);
  TestValidator.equals("reporter_member_id unchanged")(updatedReport.reporter_member_id)(report.reporter_member_id);
  TestValidator.equals("post_id unchanged")(updatedReport.post_id)(report.post_id);

  // 7. Attempt updating immutable field (should fail)
  await TestValidator.error("updating reporter_member_id should fail")(() =>
    api.functional.discussionBoard.moderation.reports.putById(connection, {
      id: report.id,
      body: {
        reporter_member_id: typia.random<string & tags.Format<"uuid">>(), // should be rejected
      } as any,
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IDiscussionBoardThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardThread";
import type { IDiscussionBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReport";

/**
 * Validate error handling when updating a moderation report with forbidden fields or using a non-existent report ID.
 *
 * This test verifies that the API returns appropriate error responses and preserves report data integrity when:
 *  - An attempt is made to update immutable fields ('reporter_member_id', 'created_at', 'deleted_at').
 *  - An attempt is made to update a non-existent report ID.
 *
 * Steps:
 * 1. Create a member (who will serve as the report's author).
 * 2. Create a discussion thread (to serve as the report's target).
 * 3. Create a moderation report for the thread by the created member.
 * 4. Attempt to update the report with each forbidden field in the update body — expect 400 Bad Request for each.
 * 5. Attempt to update a random non-existent report ID with legal update body — expect 404 Not Found.
 * 6. Fetch the report after invalid updates and verify it has not changed.
 */
export async function test_api_discussionBoard_moderation_reports_test_update_moderation_report_with_invalid_fields_should_return_error(
  connection: api.IConnection
) {
  // 1. Create a new discussion board member
  const memberCreateInput = {
    username: RandomGenerator.alphaNumeric(12),
    email: typia.random<string & tags.Format<'email'>>(),
    hashed_password: RandomGenerator.alphaNumeric(20),
    display_name: RandomGenerator.name(),
    is_active: true,
    profile_image_url: null
  } satisfies IdiscussionBoardMembers.ICreate;
  const member = await api.functional.discussionBoard.actors.members.post(connection, { body: memberCreateInput });
  typia.assert(member);

  // 2. Create a discussion thread
  const threadCreateInput = {
    discussion_board_category_id: typia.random<string & tags.Format<'uuid'>>(),
    title: RandomGenerator.paragraph()(12),
    body: RandomGenerator.content()()(),
    is_pinned: false,
    is_closed: false
  } satisfies IDiscussionBoardThread.ICreate;
  const thread = await api.functional.discussionBoard.articles.threads.post(connection, { body: threadCreateInput });
  typia.assert(thread);

  // 3. Create a moderation report with the member as reporter, against the thread
  const reportCreateInput = {
    reporter_member_id: member.id,
    thread_id: thread.id,
    reason: 'Test immutable field update',
    status: 'pending'
  } satisfies IDiscussionBoardReport.ICreate;
  const report = await api.functional.discussionBoard.moderation.reports.post(connection, { body: reportCreateInput });
  typia.assert(report);

  // 4. Try to update forbidden fields
  const forbiddenFieldsUpdates = [
    { reporter_member_id: typia.random<string & tags.Format<'uuid'>>() },
    { created_at: new Date().toISOString() },
    { deleted_at: new Date().toISOString() }
  ];
  for (const forbiddenUpdate of forbiddenFieldsUpdates) {
    await TestValidator.error("should reject forbidden field update")(async () => {
      await api.functional.discussionBoard.moderation.reports.putById(connection, {
        id: report.id,
        body: forbiddenUpdate as any // forcibly inject invalid field for negative test
      });
    });
  }

  // 5. Try to update a non-existent report ID with a legal update
  await TestValidator.error("should return 404 for non-existent report")(async () => {
    await api.functional.discussionBoard.moderation.reports.putById(connection, {
      id: typia.random<string & tags.Format<'uuid'>>(),
      body: { status: "resolved" } satisfies IDiscussionBoardReport.IUpdate
    });
  });

  // 6. Confirm that the original report was not updated erroneously (apply a legal update, verify correctness)
  const updated = await api.functional.discussionBoard.moderation.reports.putById(connection, {
    id: report.id,
    body: { resolution_notes: 'Normal legal update' } satisfies IDiscussionBoardReport.IUpdate
  });
  typia.assert(updated);
  TestValidator.equals('resolution_notes is updated')(updated.resolution_notes)('Normal legal update');
  TestValidator.equals('report still owns same reporter')(updated.reporter_member_id)(member.id);
  TestValidator.equals('report still targets same thread')(updated.thread_id)(thread.id);
}

