/**
 * Validate soft deletion of a moderation report and post-deletion visibility rules.
 *
 * This test ensures:
 * 1. A moderation report can be soft deleted by a moderator.
 * 2. After deletion, the report has its 'deleted_at' field set (not null).
 * 3. The deleted report is no longer active in the system (omitted from listings if such endpoints exist; checked by deleted_at presence here).
 *
 * Steps:
 * 1. Create a member (reporter).
 * 2. Create a thread (content to be reported).
 * 3. Reporter files a moderation report on the thread.
 * 4. Moderator soft deletes the report by ID.
 * 5. Assert deleted_at is set and type is correct.
 * 6. If any listing/fetch API were available, would attempt retrieval to confirm non-inclusion or deletion flag (omitted; not available).
 */
export async function test_api_discussionBoard_test_soft_delete_report_successful_and_inaccessible_in_listing(
  connection: api.IConnection,
) {
  // 1. Create a reporter member
  const member = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(24),
      display_name: RandomGenerator.name(),
      profile_image_url: null,
      is_active: true,
    } satisfies IdiscussionBoardMembers.ICreate
  });
  typia.assert(member);

  // 2. Create a thread for reporting
  const thread = await api.functional.discussionBoard.articles.threads.post(connection, {
    body: {
      discussion_board_category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(3),
      body: RandomGenerator.content()()(2),
      is_pinned: false,
      is_closed: false,
    } satisfies IDiscussionBoardThread.ICreate
  });
  typia.assert(thread);

  // 3. File the moderation report referencing the member and thread
  const report = await api.functional.discussionBoard.moderation.reports.post(connection, {
    body: {
      reporter_member_id: member.id,
      thread_id: thread.id,
      post_id: null,
      comment_id: null,
      reason: "Test thread soft-deletion report",
      status: "pending",
    } satisfies IDiscussionBoardReport.ICreate
  });
  typia.assert(report);
  TestValidator.equals("report not yet soft-deleted")(report.deleted_at)(null);

  // 4. Soft delete the report as moderator
  const deleted = await api.functional.discussionBoard.moderation.reports.eraseById(connection, {
    id: report.id,
  });
  typia.assert(deleted);
  TestValidator.predicate("deleted_at is set (not null)")(!!deleted.deleted_at);
  TestValidator.equals("deleted_at present & string")(typeof deleted.deleted_at === "string")(true);

  // 5. Omitting fetch/list test as SDK does not expose these; deletion is validated via 'deleted_at' presence in returned object.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
