import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IdiscussionBoardModerators } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardModerators";
import type { IDiscussionBoardThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardThread";
import type { IDiscussionBoardModerationLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerationLog";

/**
 * 토론 게시판 스레드에 대한 모더레이션 로그 성공 생성 플로우 검증
 *
 * - 신규 멤버 계정 생성 및 모더레이터 승격
 * - 스레드 생성 후, 모더레이터 액션 기록('hide' 또는 'delete')
 * - moderation log 반환 필드(모더레이터 id, 스레드 id, action, reason) 및 timestamp 유효성 검증
 *
 * 절차:
 * 1. 신규 멤버 계정 생성 (활성 계정)
 * 2. 해당 계정으로 모더레이터 할당
 * 3. 테스트용 토론 스레드 생성
 * 4. 모더레이터로 moderation log 생성(action, action_reason 포함)
 * 5. 반환 로그 필드(모더레이터, 스레드, action/reason, created_at 등) 검증
 */
export async function test_api_discussionBoard_moderation_moderationLogs_test_create_moderation_log_success_for_thread_action(
  connection: api.IConnection,
) {
  // 1. 신규 멤버 계정 생성
  const memberInput: IdiscussionBoardMembers.ICreate = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(24),
    display_name: RandomGenerator.name(),
    profile_image_url: null,
    is_active: true,
  };
  const member = await api.functional.discussionBoard.actors.members.post(connection, { body: memberInput });
  typia.assert(member);

  // 2. 멤버를 모더레이터로 할당
  const nowISO = new Date().toISOString();
  const moderator = await api.functional.discussionBoard.actors.moderators.post(connection, {
    body: {
      member_id: member.id,
      assigned_at: nowISO,
    } satisfies IdiscussionBoardModerators.ICreate
  });
  typia.assert(moderator);
  TestValidator.equals("moderator.member_id matches member.id")(moderator.member_id)(member.id);
  TestValidator.equals("moderator.revoked_at is null")((moderator.revoked_at ?? null))(null);

  // 3. 테스트용 토론 스레드 생성
  const threadInput: IDiscussionBoardThread.ICreate = {
    discussion_board_category_id: typia.random<string & tags.Format<"uuid">>(),
    title: RandomGenerator.paragraph()(1),
    body: RandomGenerator.content()()(1),
    is_pinned: false,
    is_closed: false,
  };
  const thread = await api.functional.discussionBoard.articles.threads.post(connection, {
    body: threadInput
  });
  typia.assert(thread);
  TestValidator.equals("thread creator matches")(thread.discussion_board_member_id)(member.id);
  TestValidator.equals("category id matches")(thread.discussion_board_category_id)(threadInput.discussion_board_category_id);

  // 4. 모더레이션 로그 생성
  const action = RandomGenerator.pick(["hide", "delete"]);
  const actionReason = "Content policy violation: spam detected";
  const moderationLogInput: IDiscussionBoardModerationLog.ICreate = {
    moderator_id: moderator.id,
    thread_id: thread.id,
    post_id: null,
    comment_id: null,
    action,
    action_reason: actionReason,
  };
  const moderationLog = await api.functional.discussionBoard.moderation.moderationLogs.post(connection, { body: moderationLogInput });
  typia.assert(moderationLog);

  // 5. 반환 필드 검증 (주요 속성/관계 등)
  TestValidator.equals("moderationLog.moderator_id matches input")(moderationLog.moderator_id)(moderationLogInput.moderator_id);
  TestValidator.equals("moderationLog.thread_id matches thread.id")(moderationLog.thread_id)(thread.id);
  TestValidator.equals("moderationLog.action matches input")(moderationLog.action)(action);
  TestValidator.equals("moderationLog.action_reason matches")(moderationLog.action_reason)(actionReason);
  TestValidator.equals("moderationLog.post_id is null")((moderationLog.post_id ?? null))(null);
  TestValidator.equals("moderationLog.comment_id is null")((moderationLog.comment_id ?? null))(null);
  // created_at timestamp이 5분 이내(시간 왜곡 없음)
  const createdAt = new Date(moderationLog.created_at).getTime();
  const skew = Math.abs(Date.now() - createdAt);
  TestValidator.predicate("created_at 5분 이내 skew 검증")(skew < 5 * 60 * 1000);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IdiscussionBoardModerators } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardModerators";
import type { IDiscussionBoardModerationLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerationLog";

/**
 * Validate that attempting to create a moderation log with non-existent thread_id,
 * post_id, or comment_id references is properly rejected by the API.
 *
 * Context:
 * Moderation logs in a discussion board should only be associated with existing content.
 * Attempting to log moderation actions against non-existent content (invalid foreign keys)
 * poses a risk for audit integrity and can indicate either a client or service bug,
 * or possible abuse of the endpoint. This test ensures the API enforces referential integrity
 * and will respond with an error (400/404) when asked to log moderation against missing or invalid targets.
 *
 * Step-by-step process:
 * 1. Register a legitimate user/member (to later escalate to moderator).
 * 2. Escalate this member to moderator using the moderator assignment endpoint, capturing their moderator_id.
 * 3. Construct clearly non-existent UUID values for thread_id, post_id, and comment_id (not associated with any real content).
 * 4. Attempt to create moderation log records using the valid moderator_id, but with each of the invalid content reference fields filled individually (one test each for thread_id, post_id, and comment_id).
 * 5. API should reject these attempts – for each, verify that the response throws an error (e.g., status 400 or 404).
 * 6. Also check that mixing multiple invalid references in one payload is rejected.
 * 7. Confirm that error responses occur for each invalid content ID case.
 */
export async function test_api_discussionBoard_moderation_moderationLogs_test_create_moderation_log_with_invalid_content_reference_returns_error(
  connection: api.IConnection,
) {
  // Step 1: Create a valid discussion board member (future moderator)
  const memberInput: IdiscussionBoardMembers.ICreate = {
    username: RandomGenerator.alphaNumeric(10),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(32),
    display_name: RandomGenerator.name(),
    profile_image_url: null,
    is_active: true,
  };
  const member = await api.functional.discussionBoard.actors.members.post(connection, { body: memberInput });
  typia.assert(member);

  // Step 2: Assign moderator role to the member
  const moderatorInput: IdiscussionBoardModerators.ICreate = {
    member_id: member.id,
    assigned_at: new Date().toISOString(),
  };
  const moderator = await api.functional.discussionBoard.actors.moderators.post(connection, { body: moderatorInput });
  typia.assert(moderator);

  // Step 3: Create guaranteed non-existent content IDs
  const invalid_thread_id = typia.random<string & tags.Format<"uuid">>();
  const invalid_post_id = typia.random<string & tags.Format<"uuid">>();
  const invalid_comment_id = typia.random<string & tags.Format<"uuid">>();

  // Step 4-7: Test creating moderation log with each kind of invalid ID
  // Thread only
  await TestValidator.error("creating log with invalid thread_id should fail")(
    async () => {
      await api.functional.discussionBoard.moderation.moderationLogs.post(connection, {
        body: {
          moderator_id: moderator.id,
          thread_id: invalid_thread_id,
          post_id: null,
          comment_id: null,
          action: "hide",
          action_reason: "Testing with invalid thread_id",
        },
      });
    },
  );

  // Post only
  await TestValidator.error("creating log with invalid post_id should fail")(
    async () => {
      await api.functional.discussionBoard.moderation.moderationLogs.post(connection, {
        body: {
          moderator_id: moderator.id,
          thread_id: null,
          post_id: invalid_post_id,
          comment_id: null,
          action: "delete",
          action_reason: "Testing with invalid post_id",
        },
      });
    },
  );

  // Comment only
  await TestValidator.error("creating log with invalid comment_id should fail")(
    async () => {
      await api.functional.discussionBoard.moderation.moderationLogs.post(connection, {
        body: {
          moderator_id: moderator.id,
          thread_id: null,
          post_id: null,
          comment_id: invalid_comment_id,
          action: "warn",
          action_reason: "Testing with invalid comment_id",
        },
      });
    },
  );

  // Both thread and post invalid
  await TestValidator.error("creating log with invalid thread_id and post_id should fail")(
    async () => {
      await api.functional.discussionBoard.moderation.moderationLogs.post(connection, {
        body: {
          moderator_id: moderator.id,
          thread_id: invalid_thread_id,
          post_id: invalid_post_id,
          comment_id: null,
          action: "hide",
          action_reason: "Testing with multiple invalid content references",
        },
      });
    },
  );

  // All three invalid at once
  await TestValidator.error("creating log with all invalid references should fail")(
    async () => {
      await api.functional.discussionBoard.moderation.moderationLogs.post(connection, {
        body: {
          moderator_id: moderator.id,
          thread_id: invalid_thread_id,
          post_id: invalid_post_id,
          comment_id: invalid_comment_id,
          action: "edit",
          action_reason: "Testing with all invalid content refs",
        },
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IdiscussionBoardModerators } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardModerators";
import type { IDiscussionBoardThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardThread";
import type { IDiscussionBoardModerationLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerationLog";
