import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test the full search, filtering, and pagination capabilities of moderation logs.
 *
 * This E2E test validates that the moderation logs listing endpoint properly supports filters for moderator_id, action type, and content reference (thread_id).
 * The business goal is to ensure that auditors, admins, and compliance reviewers can reliably search for, segment, and paginate moderation actions by actor or by target entity.
 *
 * Steps covered:
 * 1. Create two members (unique identities)
 * 2. Escalate both to distinct moderators, producing two moderator_id values
 * 3. Create two threads (each by a different moderator as creator)
 * 4. Have both moderators create moderation log entries using different actions (e.g., "hide", "warn") and on different threads
 * 5. For each filter: (a) by moderator_id, (b) by action, (c) by thread_id, (d) by combination (moderator_id+action+thread_id), and (e) with limit/pagination, validate that only strictly-matching results are included in data, total/pagination metadata reflects the correct amounts, and that no record from other combinations appears.
 * 6. Assert types of all API results and thoroughly check that all response data matches the filter logic precisely.
 */
export async function test_api_discussionBoard_moderation_moderationLogs_test_list_moderation_logs_with_filter_by_moderator_and_content(connection: api.IConnection) {
  // 1. Create two unique members
  const member1 = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: RandomGenerator.alphaNumeric(8) + "@example.com",
      hashed_password: RandomGenerator.alphaNumeric(32),
      display_name: RandomGenerator.name(),
      is_active: true
    } satisfies IdiscussionBoardMembers.ICreate,
  });
  typia.assert(member1);
  const member2 = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: RandomGenerator.alphaNumeric(8) + "@example.com",
      hashed_password: RandomGenerator.alphaNumeric(32),
      display_name: RandomGenerator.name(),
      is_active: true
    } satisfies IdiscussionBoardMembers.ICreate,
  });
  typia.assert(member2);

  // 2. Escalate both to moderators
  const assigned_at = new Date().toISOString();
  const moderator1 = await api.functional.discussionBoard.actors.moderators.post(connection, {
    body: {
      member_id: member1.id,
      assigned_at,
    } satisfies IdiscussionBoardModerators.ICreate,
  });
  typia.assert(moderator1);
  const moderator2 = await api.functional.discussionBoard.actors.moderators.post(connection, {
    body: {
      member_id: member2.id,
      assigned_at,
    } satisfies IdiscussionBoardModerators.ICreate,
  });
  typia.assert(moderator2);

  // 3. Create two threads (by each moderator as creator)
  // Generate random dummy category uuid
  const dummy_category_1 = typia.random<string & tags.Format<"uuid">>();
  const thread1 = await api.functional.discussionBoard.articles.threads.post(connection, {
    body: {
      discussion_board_category_id: dummy_category_1,
      title: RandomGenerator.paragraph()(10),
      body: RandomGenerator.content()(5)(2),
      is_pinned: false,
      is_closed: false
    } satisfies IDiscussionBoardThread.ICreate,
  });
  typia.assert(thread1);
  const dummy_category_2 = typia.random<string & tags.Format<"uuid">>();
  const thread2 = await api.functional.discussionBoard.articles.threads.post(connection, {
    body: {
      discussion_board_category_id: dummy_category_2,
      title: RandomGenerator.paragraph()(10),
      body: RandomGenerator.content()(5)(2),
      is_pinned: false,
      is_closed: false
    } satisfies IDiscussionBoardThread.ICreate,
  });
  typia.assert(thread2);

  // 4. Log moderation actions: moderator1 logs "hide" on thread1, moderator2 logs "warn" on thread2
  const action1 = "hide";
  const log1 = await api.functional.discussionBoard.moderation.moderationLogs.post(connection, {
    body: {
      moderator_id: moderator1.id,
      thread_id: thread1.id,
      action: action1,
    } satisfies IDiscussionBoardModerationLog.ICreate,
  });
  typia.assert(log1);
  const action2 = "warn";
  const log2 = await api.functional.discussionBoard.moderation.moderationLogs.post(connection, {
    body: {
      moderator_id: moderator2.id,
      thread_id: thread2.id,
      action: action2,
    } satisfies IDiscussionBoardModerationLog.ICreate,
  });
  typia.assert(log2);

  // 5a. Filter: moderator_id = moderator1.id
  const res_by_mod1 = await api.functional.discussionBoard.moderation.moderationLogs.patch(connection, {
    body: {
      moderator_id: moderator1.id
    } satisfies IDiscussionBoardModerationLog.IRequest,
  });
  typia.assert(res_by_mod1);
  for (const entry of res_by_mod1.data) {
    TestValidator.equals("moderator_id only moderator1")(entry.moderator_id)(moderator1.id);
  }

  // 5b. Filter: action = "warn"
  const res_by_action_warn = await api.functional.discussionBoard.moderation.moderationLogs.patch(connection, {
    body: {
      action: action2
    } satisfies IDiscussionBoardModerationLog.IRequest,
  });
  typia.assert(res_by_action_warn);
  for (const entry of res_by_action_warn.data) {
    TestValidator.equals("action only warn")(entry.action)(action2);
  }

  // 5c. Filter: thread_id = thread1.id
  const res_by_thread1 = await api.functional.discussionBoard.moderation.moderationLogs.patch(connection, {
    body: {
      thread_id: thread1.id
    } satisfies IDiscussionBoardModerationLog.IRequest,
  });
  typia.assert(res_by_thread1);
  for (const entry of res_by_thread1.data) {
    TestValidator.equals("thread_id only thread1")(entry.thread_id)(thread1.id);
  }

  // 5d. Pagination: mod1, limit=1
  const res_mod1_limit = await api.functional.discussionBoard.moderation.moderationLogs.patch(connection, {
    body: {
      moderator_id: moderator1.id,
      limit: 1
    } satisfies IDiscussionBoardModerationLog.IRequest,
  });
  typia.assert(res_mod1_limit);
  TestValidator.equals("pagination limit 1")(res_mod1_limit.pagination.limit)(1);
  TestValidator.predicate("returns 1 or fewer records")(res_mod1_limit.data.length <= 1);

  // 5e. Combo: moderator_id + action + thread_id
  const combo = await api.functional.discussionBoard.moderation.moderationLogs.patch(connection, {
    body: {
      moderator_id: moderator1.id,
      action: action1,
      thread_id: thread1.id
    } satisfies IDiscussionBoardModerationLog.IRequest,
  });
  typia.assert(combo);
  for (const entry of combo.data) {
    TestValidator.equals("moderator combo")(entry.moderator_id)(moderator1.id);
    TestValidator.equals("action combo")(entry.action)(action1);
    TestValidator.equals("thread combo")(entry.thread_id)(thread1.id);
  }

  // 6. Negative: ensure no extraneous records in filtered results
  for (const entry of res_by_mod1.data) {
    TestValidator.equals("filtered by moderator1")(entry.moderator_id)(moderator1.id);
  }
  for (const entry of res_by_action_warn.data) {
    TestValidator.equals("filtered by action warn")(entry.action)(action2);
  }
  for (const entry of res_by_thread1.data) {
    TestValidator.equals("filtered by thread1")(entry.thread_id)(thread1.id);
  }
  for (const entry of combo.data) {
    TestValidator.equals("moderator combo")(entry.moderator_id)(moderator1.id);
    TestValidator.equals("action combo")(entry.action)(action1);
    TestValidator.equals("thread combo")(entry.thread_id)(thread1.id);
  }
}

