import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";

/**
 * 카테고리 이름 중복 업데이트 방지 및 충돌 오류 확인 테스트
 *
 * 이 테스트는 서로 다른 두 개의 카테고리를 먼저 생성한 뒤, 두 번째 카테고리의 이름을 첫 번째 카테고리의 이름으로
 * 업데이트를 시도했을 때 API가 고유성(Unique) 제약조건을 위반했다고 올바르게 충돌 에러/코드를 반환하는지 검증합니다.
 *
 * 1. 첫 번째 카테고리를 랜덤한 이름으로 생성합니다.
 * 2. 두 번째 카테고리를 첫 번째와는 다른(중복되지 않은) 랜덤한 이름으로 생성합니다.
 * 3. 두 번째 카테고리의 id로 카테고리 업데이트(이름을 첫 번째 카테고리의 이름으로 바꿈)를 시도합니다.
 * 4. API가 충돌(409 Conflict 등), 혹은 유사한 고유성 제약 위반 오류를 올바르게 반환하는지 확인하며,
 *    예외가 발생해야 테스트가 정상 통과하도록 구현합니다.
 * 5. 두 카테고리의 이름이 실제로 충돌하지 않는 경우에는 정상적으로 업데이트되어야 하며, 이 경우 정상 케이스도 테스트합니다.
 */
export async function test_api_discussionBoard_categories_categories_test_update_category_with_duplicate_name(
  connection: api.IConnection,
) {
  // 1. 첫 번째 카테고리 생성
  const categoryName1 = RandomGenerator.alphaNumeric(12);
  const category1 = await api.functional.discussionBoard.categories.categories.post(connection, {
    body: { name: categoryName1, description: RandomGenerator.paragraph()() }
  });
  typia.assert(category1);

  // 2. 두 번째(중복 아닌) 카테고리 생성
  let categoryName2 = RandomGenerator.alphaNumeric(14);
  while (categoryName2 === categoryName1) categoryName2 = RandomGenerator.alphaNumeric(14);
  const category2 = await api.functional.discussionBoard.categories.categories.post(connection, {
    body: { name: categoryName2, description: RandomGenerator.paragraph()() }
  });
  typia.assert(category2);

  // 3. 두 번째 카테고리의 이름을 첫 번째 이름으로 업데이트(중복 조건 유발)
  await TestValidator.error("동일 이름으로 카테고리명 변경 시 고유성 충돌 오류가 발생해야 한다.")(
    async () => {
      await api.functional.discussionBoard.categories.categories.putById(connection, {
        id: category2.id,
        body: { name: categoryName1 }
      });
    }
  );

  // 4. 추가: 정상 케이스(서로 다른 이름으로는 잘 업데이트 됨을 보장)
  const newNonConflictName = RandomGenerator.alphaNumeric(16);
  const updated = await api.functional.discussionBoard.categories.categories.putById(connection, {
    id: category2.id,
    body: { name: newNonConflictName }
  });
  typia.assert(updated);
  TestValidator.equals("카테고리명 정상 변경 여부")(updated.name)(newNonConflictName);
}

