/**
 * Validate that attempting to update a category with a non-existent UUID results in a 404 error.
 *
 * This test ensures the update endpoint (PUT /discussionBoard/categories/categories/:id) returns a Not Found error when given a UUID that does not correspond to any existing category. This guards against unintended creation or silent failure on missing categories.
 *
 * Steps:
 * 1. Generate a random UUID that is extremely unlikely to exist in the system (since we're not creating any category during this test).
 * 2. Attempt to update a category using the generated UUID and any update payload.
 * 3. Assert that a 404 error is thrown by the API (not a silent failure or other error code).
 */
export async function test_api_discussionBoard_test_update_non_existent_category(
  connection: api.IConnection,
) {
  // 1. Generate a random (nonexistent) UUID
  const randomCategoryId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();

  // 2. Prepare an arbitrary valid update payload
  const updatePayload: IDiscussionBoardCategory.IUpdate = {
    name: "Nonexistent Category",
    description: "Trying to update a category that does not exist.",
  };

  // 3. Attempt to update and assert that a 404 error is thrown
  await TestValidator.error("should throw 404 Not Found")(
    async () => {
      await api.functional.discussionBoard.categories.categories.putById(
        connection,
        {
          id: randomCategoryId,
          body: updatePayload,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";

/**
 * Validates that category immutable/system fields (id, created_at, updated_at, deleted_at)
 * cannot be updated via the API. Only name and description are allowed to change.
 *
 * This test covers both negative (malicious/invalid update) and positive (normal update)
 * cases for the PUT /discussionBoard/categories/categories/{id} endpoint.
 *
 * Steps:
 * 1. Create a new category for testing
 * 2. Attempt to update immutable fields (id, created_at, etc.) via PUT (using cast or any)
 *    - Expect an error or that the system ignores/filters these fields
 * 3. After the invalid attempt, perform a legitimate name/description update and verify change
 * 4. Check that all fields except name/description remained unchanged
 */
export async function test_api_discussionBoard_test_update_category_with_immutable_field(
  connection: api.IConnection,
) {
  // 1. Create a category to test updates on
  const createInput: IDiscussionBoardCategory.ICreate = {
    name: RandomGenerator.alphabets(8),
    description: RandomGenerator.paragraph()(),
  };
  const original = await api.functional.discussionBoard.categories.categories.post(
    connection,
    {
      body: createInput,
    },
  );
  typia.assert(original);

  // 2. Try to maliciously update immutable fields (id, created_at, updated_at, deleted_at)
  const forbiddenUpdate: any = {
    name: RandomGenerator.alphabets(8),
    id: typia.random<string & tags.Format<"uuid">>(),
    created_at: typia.random<string & tags.Format<"date-time">>(),
    updated_at: typia.random<string & tags.Format<"date-time">>(),
    deleted_at: null,
    description: RandomGenerator.paragraph()(),
  };
  await TestValidator.error("Updating immutable fields must fail or be filtered")(
    async () => {
      await api.functional.discussionBoard.categories.categories.putById(
        connection,
        {
          id: original.id,
          body: forbiddenUpdate,
        },
      );
    },
  );

  // 3. Now do a valid update, only name/description
  const updateInput: IDiscussionBoardCategory.IUpdate = {
    name: RandomGenerator.alphabets(12),
    description: RandomGenerator.paragraph()(),
  };
  const updated = await api.functional.discussionBoard.categories.categories.putById(
    connection,
    {
      id: original.id,
      body: updateInput,
    },
  );
  typia.assert(updated);

  // 4. Assert that only allowed fields have changed
  TestValidator.equals("id stays same")(updated.id)(original.id);
  TestValidator.equals("created_at stays same")(updated.created_at)(original.created_at);
  TestValidator.equals("deleted_at stays same")(
    updated.deleted_at,
  )(original.deleted_at ?? null);
  TestValidator.equals("name updated")(updated.name)(updateInput.name);
  TestValidator.equals("description updated")(updated.description)(updateInput.description);
}

