  );
  typia.assert(created);
  TestValidator.equals("category name matches")(created.name)(name);
  TestValidator.equals("category description matches")(created.description)(description);
  TestValidator.equals("category is not soft deleted")(created.deleted_at)(null);

  // 2. List all categories and verify the new one appears
  const page1 = await api.functional.discussionBoard.categories.categories.patch(
    connection,
    { body: { name } satisfies IDiscussionBoardCategory.IRequest }
  );
  typia.assert(page1);
  const found1 = page1.data.find(cat => cat.id === created.id);
  TestValidator.predicate("created category found in list")(!!found1);
  TestValidator.equals("category is not soft deleted")(found1?.deleted_at)(null);

  // 3. Soft delete the category
  await api.functional.discussionBoard.categories.categories.eraseById(
    connection,
    { id: created.id },
  );

  // 4. List categories (active only, deleted_at:false or omitted)
  const page2 = await api.functional.discussionBoard.categories.categories.patch(
    connection,
    { body: { name } satisfies IDiscussionBoardCategory.IRequest }
  );
  typia.assert(page2);
  const found2 = page2.data.find(cat => cat.id === created.id);
  TestValidator.equals("category is not in active categories after delete")(found2)(undefined);

  // 5. List categories with deleted_at=true to fetch soft-deleted ones
  const page3 = await api.functional.discussionBoard.categories.categories.patch(
    connection,
    { body: { name, deleted_at: true } satisfies IDiscussionBoardCategory.IRequest }
  );
  typia.assert(page3);
  const found3 = page3.data.find(cat => cat.id === created.id);
  TestValidator.predicate("deleted category is found when including deleted_at=true")(!!found3);
  TestValidator.predicate("deleted_at field is set (category is soft deleted)")(!!found3?.deleted_at);
}

