import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IDiscussionBoardSearchHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardSearchHistory";
import type { IPageIDiscussionBoardSearchHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardSearchHistory";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate keyword filtering and pagination of user search histories.
 *
 * This E2E test ensures that the search history query endpoint correctly implements keyword filtering and pagination for a given member.
 *
 * It covers:
 * 1. Creating a unique discussion board member (the actor of the search history).
 * 2. Inserting several search history records for this user with distinct keywords (e.g., 'python', 'typescript', etc.).
 * 3. Querying search histories for this member filtered by a specific keyword, with pagination (low limit per page).
 * 4. Confirming only records with the filtered keyword appear, the pagination info is accurate, and no other keywords are present in the result.
 *
 * Steps:
 * 1. Register a discussion board member.
 * 2. Add at least 5 search history records with distinct keywords for that member.
 * 3. Fetch a filtered, paginated list using one of the keywords and limit=2.
 * 4. Assert: all returned entries match the filter, pagination info is correct, and records with other keywords are absent.
 */
export async function test_api_discussionBoard_test_search_search_histories_by_keyword_and_pagination(
  connection: api.IConnection,
) {
  // 1. Register member
  const member = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      display_name: RandomGenerator.name(),
      profile_image_url: null,
      is_active: true,
    } satisfies IdiscussionBoardMembers.ICreate,
  });
  typia.assert(member);

  // 2. Add search histories with distinct keywords
  const keywords = ["python", "typescript", "nodejs", "ai", "blockchain"];
  const histories = await ArrayUtil.asyncMap(keywords)(async (kw) => {
    const created = await api.functional.discussionBoard.search.searchHistories.post(connection, {
      body: {
        actor_id: member.id,
        keyword: kw,
        filters: null,
        search_context: null,
        created_at: new Date().toISOString(),
      } satisfies IDiscussionBoardSearchHistory.ICreate,
    });
    typia.assert(created);
    return created;
  });

  // 3. Choose filter keyword and setup paging
  const filterKeyword = keywords[0];
  const limit = 2;
  const page = 1;

  // 4. Query search histories with keyword filter and pagination
  const pageResult = await api.functional.discussionBoard.search.searchHistories.patch(connection, {
    body: {
      actor_id: member.id,
      keyword: filterKeyword,
      page,
      limit,
    } satisfies IDiscussionBoardSearchHistory.IRequest,
  });
  typia.assert(pageResult);

  // 5. Assert all returned entries match the filter keyword
  TestValidator.predicate("all entries match filter")(pageResult.data.every(h => h.keyword === filterKeyword));
  TestValidator.predicate("limit not exceeded")(pageResult.data.length <= limit);
  TestValidator.equals("pagination current")(pageResult.pagination.current)(page);
  TestValidator.equals("pagination limit")(pageResult.pagination.limit)(limit);
  TestValidator.equals("pagination record count matches filter")(pageResult.pagination.records)(histories.filter(h => h.keyword === filterKeyword).length);

  // 6. Assert no unwanted keywords present
  const otherKeywordCount = pageResult.data.filter(h => h.keyword !== filterKeyword).length;
  TestValidator.equals("all results are filtered")(otherKeywordCount)(0);
}

