    // Page = 0 (minimum allowed is 1)
    { actor_id: member.id, page: 0 },
    // Both page and limit invalid
    { actor_id: member.id, page: -2, limit: 101 },
  ];

  // 3. Each case: request search histories and expect error
  for (const params of invalidCases) {
    await TestValidator.error("invalid pagination is rejected")(async () => {
      await api.functional.discussionBoard.search.searchHistories.patch(connection, {
