import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IDiscussionBoardThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardThread";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";

/**
 * Validate that a discussion board post can be soft-deleted by its author,
 * and that the deletion is non-destructive (data preserved, hidden from regular queries).
 *
 * This test verifies the full soft-delete author flow:
 *   1. Register a new member who will author and later delete the post
 *   2. Create a discussion thread
 *   3. Create a post in the new thread as the registered member
 *   4. Request a soft deletion of the post via the author
 *   5. Confirm that deleted_at is set and other post fields are intact
 *
 * **Verifies:**
 *   - Soft deletion sets deleted_at (timestamp is not null)
 *   - Original post data is preserved (id, thread_id, member_id, body)
 *   - The deletion operation reports success
 *   - Hard deletion does not occur (row is not erased)
 *   - (Visibility restriction to regular members/moderators would need more endpoints)
 */
export async function test_api_discussionBoard_test_soft_delete_post_by_author_success(
  connection: api.IConnection,
) {
  // 1. Register a discussion board member
  const createdMember = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphabets(10),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      display_name: RandomGenerator.name(),
      profile_image_url: null,
      is_active: true,
    } satisfies IdiscussionBoardMembers.ICreate,
  });
  typia.assert(createdMember);

  // 2. Create a discussion thread (category id random for test purposes)
  const thread = await api.functional.discussionBoard.articles.threads.post(connection, {
    body: {
      discussion_board_category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(20),
      body: RandomGenerator.content()()(50),
      is_pinned: false,
      is_closed: false,
    } satisfies IDiscussionBoardThread.ICreate,
  });
  typia.assert(thread);

  // 3. Create a post in the new thread as the registered member
  const post = await api.functional.discussionBoard.articles.posts.post(connection, {
    body: {
      discussion_board_thread_id: thread.id,
      discussion_board_member_id: createdMember.id,
      body: RandomGenerator.content()()(30),
    } satisfies IDiscussionBoardPost.ICreate,
  });
  typia.assert(post);
  TestValidator.equals("soft-delete must not have been called yet")(post.deleted_at)(null);

  // 4. Soft-delete the created post as the author
  const eraseResult = await api.functional.discussionBoard.articles.posts.eraseById(connection, {
    id: post.id,
  });
  typia.assert(eraseResult);
  TestValidator.equals("delete success")(eraseResult.success)(true);
  TestValidator.equals("original post id matches")(eraseResult.post.id)(post.id);
  TestValidator.equals("soft-delete should set deleted_at")(typeof eraseResult.post.deleted_at === "string")(true);
  TestValidator.notEquals("deleted_at is not null after soft delete")(eraseResult.post.deleted_at)(null);
  TestValidator.equals("thread id stays same")(eraseResult.post.discussion_board_thread_id)(post.discussion_board_thread_id);
  TestValidator.equals("member id stays same")(eraseResult.post.discussion_board_member_id)(post.discussion_board_member_id);
  TestValidator.equals("body stays same")(eraseResult.post.body)(post.body);
  TestValidator.equals("hard delete never occurs")(typeof eraseResult.post.id === "string")(true);
}

