 * Test workflow:
 * 1. Register a new member who will author the post.
 * 2. Create a discussion thread for contextualizing the post.
 * 3. Post a new message into the thread as the created member.
 * 4. Soft-delete the post by its ID.
 * 5. Attempt to soft-delete the same post again; verify this results in an error or failed operation (do not allow double deletion).
 * 6. Validate that the error is returned and the post state has not changed.
 */
export async function test_api_discussionBoard_test_soft_delete_post_fails_if_already_soft_deleted(
  connection: api.IConnection,
) {
