import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IDiscussionBoardThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardThread";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IPageIDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardComment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test comment list pagination per post for discussion board.
 *
 * This test covers the following workflow:
 * 1. Register a new test member.
 * 2. Create a new thread on the discussion board.
 * 3. Create a post inside that thread.
 * 4. Add multiple comments to the post – these will test pagination and return.
 * 5. Fetch the comments for the post using the PATCH endpoint with pagination parameters (limit/page) and verify:
 *    - Only the correct comments for the target post are returned
 *    - Comments are ordered as expected (by creation date desc by default)
 *    - Pagination meta (current, limit, records, pages) reflects the inserted count/params
 *    - No soft-deleted comments (deleted_at != null) are present in results
 *
 * Steps:
 *  - Generate and register a unique member
 *  - Create a thread (any category, test value)
 *  - Create a post by the member in the thread
 *  - Insert, e.g., 12 comments for the post (for 5-per-page pagination)
 *  - Fetch the first page (limit 5) and check top 5 are most recently created and are not deleted
 *  - Fetch all pages in a loop, collect, and verify all undeleted comments are present, in correct order, and count matches meta
 *  - Edge: request a page number beyond max and ensure empty result
 *
 * Note: If there's no soft-deletion comment endpoint, manually set a comment's deleted_at to simulate (skip this if impossible).
 */
export async function test_api_discussionBoard_test_list_comments_by_post_id_pagination(
  connection: api.IConnection,
) {
  // 1. Register a member
  const member = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(40),
      display_name: RandomGenerator.name(),
      is_active: true,
      profile_image_url: null,
    } satisfies IdiscussionBoardMembers.ICreate,
  });
  typia.assert(member);

  // 2. Create a new thread
  const thread = await api.functional.discussionBoard.articles.threads.post(connection, {
    body: {
      discussion_board_category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(1),
      body: RandomGenerator.paragraph()(),
      is_pinned: false,
      is_closed: false,
    } satisfies IDiscussionBoardThread.ICreate,
  });
  typia.assert(thread);

  // 3. Create a post by the member in the thread
  const post = await api.functional.discussionBoard.articles.posts.post(connection, {
    body: {
      discussion_board_thread_id: thread.id,
      discussion_board_member_id: member.id,
      body: RandomGenerator.content()()(),
    } satisfies IDiscussionBoardPost.ICreate,
  });
  typia.assert(post);

  // 4. Insert 12 comments for the post
  const comments: IDiscussionBoardComment[] = [];
  for (let i = 0; i < 12; ++i) {
    const comment = await api.functional.discussionBoard.articles.comments.post(connection, {
      body: {
        discussion_board_post_id: post.id,
        discussion_board_member_id: member.id,
        body: `Comment content ${i + 1}`,
      } satisfies IDiscussionBoardComment.ICreate,
    });
    typia.assert(comment);
    comments.push(comment);
  }
  // Sort expected comments by creation time descending (latest first)
  const commentsSorted = [...comments].sort((a, b) => b.created_at.localeCompare(a.created_at));

  // 5. Retrieve comments via the PATCH endpoint, limit 5
  const page1 = await api.functional.discussionBoard.articles.comments.patch(connection, {
    body: {
      discussion_board_post_id: post.id,
      page: 1,
      limit: 5,
      sort: "created_at",
      order: "desc",
      deleted: false,
    } satisfies IDiscussionBoardComment.IListRequest,
  });
  typia.assert(page1);

  // Validate page1: 5 newest comments, correct pagination
  TestValidator.equals("first page count")(page1.data.length)(5);
  TestValidator.equals("first page meta")(page1.pagination.current)(1);
  TestValidator.equals("first page meta limit")(page1.pagination.limit)(5);
  TestValidator.equals("first page total")(page1.pagination.records)(12);
  TestValidator.equals("first page pages")(page1.pagination.pages)(Math.ceil(12 / 5));
  for (let i = 0; i < 5; ++i)
    TestValidator.equals(`comment order[${i}]`)(page1.data[i].id)(commentsSorted[i].id);
  for (const c of page1.data)
    TestValidator.equals("not soft deleted")(c.deleted_at)(null);

  // 6. Fetch all pages and collect ids
  const allCollected: IDiscussionBoardComment[] = [];
  for (let page = 1; page <= page1.pagination.pages; ++page) {
    const pg = await api.functional.discussionBoard.articles.comments.patch(connection, {
      body: {
        discussion_board_post_id: post.id,
        page,
        limit: 5,
        sort: "created_at",
        order: "desc",
        deleted: false,
      } satisfies IDiscussionBoardComment.IListRequest,
    });
    typia.assert(pg);
    for (const c of pg.data)
      allCollected.push(c);
  }
  // All collected should match sorted and not include soft-deleted
  TestValidator.equals("all collected length")(allCollected.length)(12);
  for (let i = 0; i < commentsSorted.length; ++i)
    TestValidator.equals(`comment id[${i}]`)(allCollected[i].id)(commentsSorted[i].id);

  // 7. Edge: Fetch page beyond range returns empty list
  const beyond = await api.functional.discussionBoard.articles.comments.patch(connection, {
    body: {
      discussion_board_post_id: post.id,
      page: 10,
      limit: 5,
      sort: "created_at",
      order: "desc",
      deleted: false,
    } satisfies IDiscussionBoardComment.IListRequest,
  });
  typia.assert(beyond);
  TestValidator.equals("beyond-page-empty")(beyond.data.length)(0);
}

