  };
  const member = await api.functional.discussionBoard.actors.members.post(connection, { body: memberInput });
  typia.assert(member);

  // 2. Create a thread with the member as the author
  // Thread must reference a (random) category; we provide a new UUID for category linkage
  const categoryId = typia.random<string & tags.Format<"uuid">>();
  const threadInput: IDiscussionBoardThread.ICreate = {
    discussion_board_category_id: categoryId,
    title: RandomGenerator.paragraph()(1),
