import type { IModerationWarning } from "@ORGANIZATION/PROJECT-api/lib/structures/IModerationWarning";

/**
 * Validate a moderator can update allowed fields of an existing warning record on the discussion board.
 *
 * Business context:
 * This test ensures that a moderator can update editable fields (warning_type, message, expires_at)
 * of an existing warning record, while immutable fields (id, deleted_at) remain unchanged.
 *
 * Step-by-step process:
 * 1. Create a regular member (collect member_id for later steps)
 * 2. Assign moderator role to the created member (collect moderator_id)
 * 3. Issue a warning to the member as the new moderator
 * 4. Update the warning record's allowed fields (warning_type, message, expires_at)
 * 5. Assert that updatable fields have changed, and immutable fields remain the same
 */
export async function test_api_discussionBoard_moderation_warnings_test_update_warning_record_with_valid_fields(
  connection: api.IConnection,
) {
  // 1. Create a member to be warned
  const memberInput: IdiscussionBoardMembers.ICreate = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(20),
    display_name: RandomGenerator.name(),
    profile_image_url: null,
    is_active: true,
  };
  const member = await api.functional.discussionBoard.actors.members.post(connection, {
    body: memberInput,
  });
  typia.assert(member);

  // 2. Assign moderator role to the created member
  const assignmentTime = new Date().toISOString();
  const moderatorInput: IdiscussionBoardModerators.ICreate = {
    member_id: member.id,
    assigned_at: assignmentTime,
  };
  const moderator = await api.functional.discussionBoard.actors.moderators.post(connection, {
    body: moderatorInput,
  });
