import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IdiscussionBoardModerators } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardModerators";
import type { IModerationBan } from "@ORGANIZATION/PROJECT-api/lib/structures/IModerationBan";

/**
 * Validates retrieval of a specific ban record by id and proper handling of sensitive attributes.
 *
 * 1. Register a normal member (to be the ban target).
 * 2. Elevate a separate member to moderator role (for ban issuance).
 * 3. The moderator issues a ban for the target member, with random but valid rationale and ban status.
 * 4. Fetch the ban record by its id using GET /discussionBoard/moderation/bans/{id}.
 * 5. Assert all schema fields in the response, and confirm soft deletion markers, ban type (temporary vs permanent), and required references.
 * 6. (As business logic dictates) Ensure that no confidential attributes outside the schema are exposed in the response.
 */
export async function test_api_discussionBoard_test_get_ban_by_id_success_and_sensitive_field_handling(
  connection: api.IConnection,
) {
  // 1. Create the member who will be banned
  const member = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(20),
      display_name: RandomGenerator.name(),
      is_active: true,
      profile_image_url: null,
    } satisfies IdiscussionBoardMembers.ICreate,
  });
  typia.assert(member);

  // 2. Create a separate member for moderator, then elevate to moderator role
  const moderatorMember = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(20),
      display_name: RandomGenerator.name(),
      is_active: true,
      profile_image_url: null,
    } satisfies IdiscussionBoardMembers.ICreate,
  });
  typia.assert(moderatorMember);

  const moderator = await api.functional.discussionBoard.actors.moderators.post(connection, {
    body: {
      member_id: moderatorMember.id,
      assigned_at: new Date().toISOString(),
    } satisfies IdiscussionBoardModerators.ICreate,
  });
  typia.assert(moderator);

  // 3. Moderator issues a ban against the member
  const banCreate: IModerationBan.ICreate = {
    member_id: member.id,
    moderator_id: moderator.id,
    ban_reason: RandomGenerator.paragraph()(),
    permanent: RandomGenerator.pick([true, false]),
    expires_at: null, // For permanent ban
  };
  if (!banCreate.permanent) {
    banCreate.expires_at = new Date(Date.now() + 7 * 24 * 3600 * 1000).toISOString();
  }
  const ban = await api.functional.discussionBoard.moderation.bans.post(connection, { body: banCreate });
  typia.assert(ban);

  // 4. Retrieve the ban by id
  const fetched = await api.functional.discussionBoard.moderation.bans.getById(connection, { id: ban.id });
  typia.assert(fetched);

  // 5. Assert schema conformity and data match
  TestValidator.equals("ban.id matches")(fetched.id)(ban.id);
  TestValidator.equals("ban.member_id matches")(fetched.member_id)(ban.member_id);
  TestValidator.equals("ban.moderator_id matches")(fetched.moderator_id)(ban.moderator_id);
  TestValidator.equals("ban_reason matches")(fetched.ban_reason)(ban.ban_reason);
  TestValidator.equals("permanent flag matches")(fetched.permanent)(ban.permanent);
  if (ban.permanent) {
    TestValidator.equals("expires_at is null for permanent")(fetched.expires_at)(null);
  } else {
    TestValidator.equals("expires_at matches")(fetched.expires_at)(ban.expires_at);
  }
  if ('hashed_password' in fetched) {
    throw new Error('Sensitive field "hashed_password" must not be present in ban fetch API response.');
  }
  TestValidator.predicate("created_at is ISO8601")(typeof fetched.created_at === "string" && !isNaN(Date.parse(fetched.created_at)));
  if (typeof fetched.deleted_at !== "undefined" && fetched.deleted_at !== null) {
    TestValidator.predicate("deleted_at is ISO8601 when not null")(typeof fetched.deleted_at === "string" && !isNaN(Date.parse(fetched.deleted_at)));
  }
}

