import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IDiscussionBoardThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardThread";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";

/**
 * Validate that a discussion thread can be updated successfully by its creator.
 *
 * This test covers the full workflow from account and category creation to discussion thread creation and owned update. It ensures only schema-supported fields are changed, timestamps behave properly, and proper authorization is enforced for the editing user.
 *
 * Steps:
 * 1. Register a new member (author)
 * 2. Create a category
 * 3. Create a new thread in that category as the author
 * 4. Update title and body via update endpoint as the creator
 * 5. Validate returned attributes are updated, updated_at timestamp is recent, and non-schema fields are not returned
 * 6. Confirm member id (creator) remains unchanged after update
 */
export async function test_api_discussionBoard_test_update_thread_with_valid_attributes_by_creator(
  connection: api.IConnection,
) {
  // 1. Member account creation (author)
  const memberInput: IdiscussionBoardMembers.ICreate = {
    username: RandomGenerator.alphaNumeric(10),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(16),
    display_name: RandomGenerator.name(),
    is_active: true,
  };
  const author = await api.functional.discussionBoard.actors.members.post(connection, { body: memberInput });
  typia.assert(author);

  // 2. Create a category
  const categoryInput: IDiscussionBoardCategory.ICreate = {
    name: RandomGenerator.alphabets(8),
    description: RandomGenerator.paragraph()(),
  };
  const category = await api.functional.discussionBoard.categories.categories.post(connection, { body: categoryInput });
  typia.assert(category);

  // 3. Create initial discussion thread as author
  const threadInput: IDiscussionBoardThread.ICreate = {
    discussion_board_category_id: category.id,
    title: RandomGenerator.paragraph()(3),
    body: RandomGenerator.content()()(2),
    is_pinned: false,
    is_closed: false,
  };
  // Only allowed properties per schema; do not include disallowed fields
  const thread = await api.functional.discussionBoard.articles.threads.post(connection, { body: threadInput });
  typia.assert(thread);

  // Save original updated_at for comparison
  const originalUpdatedAt = thread.updated_at;

  // 4. Update the thread: change title and body
  const newTitle = RandomGenerator.paragraph()(1) + " (edited)";
  const newBody = RandomGenerator.content()()(2);
  const updateInput: IDiscussionBoardThread.IUpdate = {
    title: newTitle,
    body: newBody,
  };
  const updated = await api.functional.discussionBoard.articles.threads.putById(connection, { id: thread.id, body: updateInput });
  typia.assert(updated);

  // 5. Validate updated attributes and schema compliance
  TestValidator.notEquals("updated_at should change after update")(updated.updated_at)(originalUpdatedAt);
  TestValidator.equals("title updated")(updated.title)(newTitle);
  TestValidator.equals("body updated")(updated.body)(newBody);
  TestValidator.equals("creator id remains")(updated.discussion_board_member_id)(author.id);
  TestValidator.equals("category remains same")(updated.discussion_board_category_id)(category.id);
  TestValidator.predicate("updated_at is now or recent")(
    new Date(updated.updated_at).getTime() >= Date.now() - 1000 * 60 * 3,
  );

  // Confirm only schema fields are present
  const allowedFields = Object.keys(updated).sort();
  const schemaFields = [
    "id",
    "discussion_board_member_id",
    "discussion_board_category_id",
    "title",
    "body",
    "is_pinned",
    "is_closed",
    "created_at",
    "updated_at",
    "deleted_at",
  ].sort();
  TestValidator.equals("no extraneous fields")(allowedFields)(schemaFields);
}

