import type { IdiscussionBoardModerators } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardModerators";
import type { IDiscussionBoardThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardThread";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";

/**
 * Test successful soft deletion of a discussion thread by a moderator.
 *
 * This test covers the end-to-end workflow in which a discussion thread is created and then soft-deleted by a moderator. It ensures that the thread's `deleted_at` field is set, the thread record persists for audit or potential reversal, and all entities conform to their respective type constraints. Only implementable business steps are tested with the available API endpoints.
 *
 * Steps:
 * 1. Register a new member.
 * 2. Assign that member as a moderator (track assignment time).
 * 3. Create a new discussion category.
 * 4. Create a thread within the new category as the member-moderator.
 * 5. Soft-delete the thread using the moderator role.
 * 6. Validate that the API response marks the thread as deleted (deleted_at set), that the thread record is preserved, and the correct thread is affected.
 */
export async function test_api_discussionBoard_test_soft_delete_thread_as_moderator_success(connection: api.IConnection) {
  // 1. Register a new member
  const member = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
