/**
 * Validate post creation fails for closed threads in the discussion board.
 *
 * Business context:
 * Forum threads can be closed (locked) by moderators/admins or through workflows, preventing further posting. This test ensures the system enforces this rule:
 * - Users cannot add a post to a thread after the thread is marked closed.
 * - An informative error is thrown, not silent failure nor acceptance.
 *
 * Test steps:
 * 1. Register a new member (to author the thread and post).
 * 2. Create a category for the thread.
 * 3. Create a new thread under the category, open (is_closed: false).
 * 4. Update the thread, setting is_closed: true.
 * 5. Attempt to create a post in this closed thread. Assert that an error is thrown, confirming the thread's closed status is enforced at post creation.
 *
 * This validates moderation/locking features and error handling for closed-thread posting attempts.
 */
export async function test_api_discussionBoard_test_create_post_in_closed_thread_returns_error(
  connection: api.IConnection,
) {
  // 1. Register a new discussion board member
  const member = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      display_name: RandomGenerator.name(),
      is_active: true,
      profile_image_url: null,
