import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IdiscussionBoardModerators } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardModerators";
import type { IDiscussionBoardThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardThread";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";

/**
 * Validate that only moderators can access soft-deleted discussion board posts, while regular members cannot.
 *
 * Business context: A soft-deleted post should not be visible to non-moderator members for both privacy and moderation audit reasons. However, moderators must retain the ability to view and possibly restore or investigate such posts. This test ensures that after a post is soft-deleted, it is only retrievable by an authorized moderator.
 *
 * Test Steps:
 * 1. Register a new member (who will later be a moderator)
 * 2. Assign moderator role to the new member
 * 3. Create a discussion category/thread context
 * 4. Create a new thread as the registered member
 * 5. Create a post in the new thread as the same member
 * 6. Soft-delete the post
 * 7. As a regular member (not moderator), attempt to fetch the soft-deleted post and assert access denied (NotFound or Forbidden)
 * 8. As a moderator, fetch the soft-deleted post and assert full post detail is returned including deleted_at
 */
export async function test_api_discussionBoard_test_get_soft_deleted_post_visible_only_to_moderator(
  connection: api.IConnection,
) {
  // 1. Register a new member (who will later be moderator)
  const memberReq: IdiscussionBoardMembers.ICreate = {
    username: RandomGenerator.alphabets(12),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(32),
    display_name: RandomGenerator.name(),
    profile_image_url: null,
    is_active: true,
  };
  const member = await api.functional.discussionBoard.actors.members.post(connection, { body: memberReq });
  typia.assert(member);

  // 2. Assign moderator role to this member
  const modReq: IdiscussionBoardModerators.ICreate = {
    member_id: member.id,
    assigned_at: new Date().toISOString(),
  };
  const moderator = await api.functional.discussionBoard.actors.moderators.post(connection, { body: modReq });
  typia.assert(moderator);

  // 3. Create a new discussion category
  const catReq: IDiscussionBoardCategory.ICreate = {
    name: RandomGenerator.alphabets(10),
    description: RandomGenerator.paragraph()(),
  };
  const category = await api.functional.discussionBoard.categories.categories.post(connection, { body: catReq });
  typia.assert(category);

  // 4. Create a thread in the new category as this member
  const threadReq: IDiscussionBoardThread.ICreate = {
    discussion_board_category_id: category.id,
    title: RandomGenerator.paragraph()(),
    body: RandomGenerator.content()()(),
    is_pinned: false,
    is_closed: false,
  };
  const thread = await api.functional.discussionBoard.articles.threads.post(connection, { body: threadReq });
  typia.assert(thread);

  // 5. Create a post in the new thread
  const postReq: IDiscussionBoardPost.ICreate = {
    discussion_board_thread_id: thread.id,
    discussion_board_member_id: member.id,
    body: RandomGenerator.content()()(),
  };
  const post = await api.functional.discussionBoard.articles.posts.post(connection, { body: postReq });
  typia.assert(post);

  // 6. Soft-delete the post
  const delResult = await api.functional.discussionBoard.articles.posts.eraseById(connection, { id: post.id });
  typia.assert(delResult);
  TestValidator.predicate("soft delete success")(delResult.success === true);
  TestValidator.equals("deleted_at set on post")(typeof delResult.post.deleted_at === "string")(true);

  // 7. Attempt to fetch soft-deleted post as a regular member (should error)
  await TestValidator.error("Regular member cannot fetch soft-deleted post")(
    async () => {
      await api.functional.discussionBoard.articles.posts.getById(connection, { id: post.id });
    },
  );

  // 8. As a moderator, fetch the soft-deleted post (should succeed)
  // In real auth, connection context would be refreshed; here we assume moderator context is set already
  const softDeleted = await api.functional.discussionBoard.articles.posts.getById(connection, { id: post.id });
  typia.assert(softDeleted);
  TestValidator.equals("soft-deleted post id")(softDeleted.id)(post.id);
  TestValidator.equals("soft-deleted post has deleted_at")(typeof softDeleted.deleted_at === "string")(true);
}

