/**
 * Tests that a discussion board comment cannot be updated by a non-author member.
 *
 * This test simulates realistic user and content flows:
 * 1. Register two separate members: one "author" and one "non-author"
 * 2. As the author, create a new thread
 * 3. As the author, create a post in the new thread
 * 4. As the author, create a comment on the post
 * 5. As the non-author member, attempt to update (edit) the author's comment
 * 6. Validate that the update attempt is denied due to lack of ownership (forbidden)
 *
 * Validates member authorization/ownership on comment update endpoint:
 * - Only the original comment author (or moderator, if supported) can update the comment
 * - Ordinary users cannot update someone else's comment
 */
export async function test_api_discussionBoard_test_update_comment_by_non_author_forbidden(
  connection: api.IConnection,
) {
  // 1. Register the author member
  const authorInput: IdiscussionBoardMembers.ICreate = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(32),
    display_name: RandomGenerator.name(),
    is_active: true,
    profile_image_url: null,
  };
  const author = await api.functional.discussionBoard.actors.members.post(connection, { body: authorInput });
  typia.assert(author);

  // 2. Register the non-author member
  const nonAuthorInput: IdiscussionBoardMembers.ICreate = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(32),
    display_name: RandomGenerator.name(),
    is_active: true,
    profile_image_url: null,
  };
  const nonAuthor = await api.functional.discussionBoard.actors.members.post(connection, { body: nonAuthorInput });
  typia.assert(nonAuthor);

  // 3. As the author, create a thread
  const threadInput: IDiscussionBoardThread.ICreate = {
    discussion_board_category_id: typia.random<string & tags.Format<"uuid">>(), // Use random category for test
    title: RandomGenerator.paragraph()(1),
    body: RandomGenerator.content()()(),
    is_pinned: false,
    is_closed: false,
  };
  const thread = await api.functional.discussionBoard.articles.threads.post(connection, { body: { ...threadInput } });
  typia.assert(thread);

  // 4. As the author, create a post in the thread
  const postInput: IDiscussionBoardPost.ICreate = {
    discussion_board_thread_id: thread.id,
    discussion_board_member_id: author.id,
    body: RandomGenerator.content()()(),
  };
  const post = await api.functional.discussionBoard.articles.posts.post(connection, { body: postInput });
  typia.assert(post);

  // 5. As the author, create a comment on the post
  const commentInput: IDiscussionBoardComment.ICreate = {
    discussion_board_post_id: post.id,
    parent_id: null,
    discussion_board_member_id: author.id,
    body: RandomGenerator.paragraph()(1),
  };
  const comment = await api.functional.discussionBoard.articles.comments.post(connection, { body: commentInput });
  typia.assert(comment);

  // 6. As the non-author, attempt to update the author's comment
  // This should be forbidden (authorization failure)
  // -- simulate non-author context by overriding for this call only (since API does not have login/auth)
  const updateInput: IDiscussionBoardComment.IUpdate = {
    body: "Malicious update attempt by non-author member",
  };
  await TestValidator.error("Only comment author can update the comment")(
    async () => {
      await api.functional.discussionBoard.articles.comments.putById(connection, {
        id: comment.id,
        body: updateInput
      });
    }
  );
}

