/**
 * Verify soft deletion of a comment by its author.
 *
 * This test ensures a member can delete their own comment, and that soft delete works as expected:
 * - deleted_at should be set after deletion
 * - regular members should no longer see the deleted comment in post listings
 *
 * Step-by-step process:
 * 1. Register a new member
 * 2. Create a thread as that member
 * 3. Create a post under the thread
 * 4. Add a comment to the post
 * 5. Soft delete the comment as the same member
 * 6. Assert that the deletion result marks the comment as soft deleted (deleted_at is set, result is "success")
 *
 * Note: No listing retrieval function is described in the API surface, so member visibility of deleted comments cannot be covered directly in this test.
 */
export async function test_api_discussionBoard_test_soft_delete_comment_by_author(connection: api.IConnection) {
  // 1. Register a member
  const memberInput: IdiscussionBoardMembers.ICreate = {
    username: RandomGenerator.alphabets(8),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(20),
