  };
  const comment = await api.functional.discussionBoard.articles.comments.post(connection, { body: commentInput });
  typia.assert(comment);

  // 5. Soft delete the comment as the same member
  const deletionResult = await api.functional.discussionBoard.articles.comments.eraseById(connection, { id: comment.id });
  typia.assert(deletionResult);

