 * Validate successful attachment creation on discussion board post by member.
 *
 * This test ensures that attachment upload for a discussion post works as intended, covering the full business flow:
 * 1. Register a new member (with unique username, valid email, and pre-hashed password). Confirm member object.
 * 2. Create a discussion thread as that member in a category. Confirm returned thread object fields.
 * 3. Create a post in the thread as the member. Validate all returned post fields.
 * 4. Attach a file to the post, providing all required meta (file uri, type, name, unique content_hash). Validate the returned attachment fields and their relation to the previous entities.
 *
 * This verifies the integrity of the creation pipeline, linkage between entities, and completeness of returned data per schema.
 */
export async function test_api_discussionBoard_test_create_attachment_on_post_successfully(
  connection: api.IConnection,
) {
  // 1. Register member
  const username = RandomGenerator.alphaNumeric(10);
  const email = typia.random<string & tags.Format<"email">>();
  const display_name = RandomGenerator.name();
  const member = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username,
      email,
      hashed_password: typia.random<string>(),
      display_name,
      is_active: true,
      // Optionally add profile_image_url (not essential for happy-path)
    } satisfies IdiscussionBoardMembers.ICreate,
  });
  typia.assert(member);
  TestValidator.equals("username")(member.username)(username);
  TestValidator.equals("email")(member.email)(email);

  // 2. Create a thread in a random category (simulate with random UUID)
  const categoryId = typia.random<string & tags.Format<"uuid">>();
  const threadTitle = RandomGenerator.paragraph()();
  const threadBody = RandomGenerator.content()()();
  const thread = await api.functional.discussionBoard.articles.threads.post(connection, {
    body: {
      discussion_board_category_id: categoryId,
      title: threadTitle,
      body: threadBody,
      is_pinned: false,
      is_closed: false,
    } satisfies IDiscussionBoardThread.ICreate,
  });
  typia.assert(thread);
  TestValidator.equals("category id")(thread.discussion_board_category_id)(categoryId);
  TestValidator.equals("title")(thread.title)(threadTitle);
  TestValidator.equals("body")(thread.body)(threadBody);

  // 3. Create a post in the thread as the member
  const postBody = RandomGenerator.content()()();
  const post = await api.functional.discussionBoard.articles.posts.post(connection, {
    body: {
      discussion_board_thread_id: thread.id,
      discussion_board_member_id: member.id,
      body: postBody,
    } satisfies IDiscussionBoardPost.ICreate,
  });
  typia.assert(post);
  TestValidator.equals("post thread id")(post.discussion_board_thread_id)(thread.id);
  TestValidator.equals("member id")(post.discussion_board_member_id)(member.id);
  TestValidator.equals("body")(post.body)(postBody);

  // 4. Upload attachment to the post as the member
  const fileName = "attachment.pdf";
  const fileUri = "https://cdn.example.com/testing/" + RandomGenerator.alphaNumeric(12) + ".pdf";
  const contentType = "application/pdf";
  const contentHash = "sha256-" + RandomGenerator.alphaNumeric(64);
  const attachment = await api.functional.discussionBoard.articles.attachments.post(connection, {
    body: {
      discussion_board_post_id: post.id,
      discussion_board_comment_id: null,
      discussion_board_member_id: member.id,
      file_name: fileName,
      file_uri: fileUri,
      content_type: contentType,
      content_hash: contentHash,
    } satisfies IDiscussionBoardAttachment.ICreate,
  });
  typia.assert(attachment);
  TestValidator.equals("discussion_board_post_id")(attachment.discussion_board_post_id)(post.id);
  TestValidator.equals("discussion_board_member_id")(attachment.discussion_board_member_id)(member.id);
  TestValidator.equals("file_name")(attachment.file_name)(fileName);
  TestValidator.equals("file_uri")(attachment.file_uri)(fileUri);
  TestValidator.equals("content_type")(attachment.content_type)(contentType);
  TestValidator.equals("content_hash")(attachment.content_hash)(contentHash);
  TestValidator.equals("discussion_board_comment_id")(attachment.discussion_board_comment_id)(null);
  TestValidator.predicate("created_at is ISO8601")(!!Date.parse(attachment.created_at));
  TestValidator.equals("not deleted")(attachment.deleted_at === undefined || attachment.deleted_at === null)(true);
}

