import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate listing and filtering of attachments by post ID.
 *
 * This test simulates a typical file attachment workflow:
 * 1. Register a new forum member who will perform all actions.
 * 2. Create a new discussion thread initiated by this member.
 * 3. Create a post within the thread by the same member (as required for attachment linkage).
 * 4. Upload two attachments, both associated with the created post.
 * 5. Retrieve the list of attachments using a filter for the specific post ID (the post just created).
 * 6. Assert the returned list contains exactly the uploaded attachments with correct association, and matches the schema
 * 7. Additionally, check an unrelated post ID (for negative filtering).
 */
export async function test_api_discussionBoard_test_list_attachments_by_post_id(connection: api.IConnection) {
  // 1. Register a member
  const member = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphabets(10),
      email: typia.random<string & tags.Format<'email'>>(),
      hashed_password: RandomGenerator.alphaNumeric(32),
      display_name: RandomGenerator.name(),
      is_active: true,
      profile_image_url: null,
    } satisfies IdiscussionBoardMembers.ICreate,
  });
  typia.assert(member);

  // 2. Create a thread
  const categoryId = typia.random<string & tags.Format<'uuid'>>();
  const thread = await api.functional.discussionBoard.articles.threads.post(connection, {
    body: {
      discussion_board_category_id: categoryId,
      title: RandomGenerator.paragraph()(8),
      body: RandomGenerator.content()()(12),
      is_pinned: false,
      is_closed: false,
    } satisfies IDiscussionBoardThread.ICreate,
  });
  typia.assert(thread);

  // 3. Create a post in the thread
  const post = await api.functional.discussionBoard.articles.posts.post(connection, {
    body: {
      discussion_board_thread_id: thread.id,
      discussion_board_member_id: member.id,
      body: RandomGenerator.content()()(10),
    } satisfies IDiscussionBoardPost.ICreate,
  });
  typia.assert(post);

  // 4. Upload two attachments to the post
  const attachmentData = [0, 1].map(() => ({
    discussion_board_post_id: post.id,
    discussion_board_comment_id: null,
    discussion_board_member_id: member.id,
    file_name: RandomGenerator.alphaNumeric(12) + '.jpg',
    file_uri: 'https://cdn.test/' + RandomGenerator.alphaNumeric(40),
    content_type: 'image/jpeg',
    content_hash: RandomGenerator.alphaNumeric(64),
  }));

  const attachments = [] as IDiscussionBoardAttachment[];
  for (const data of attachmentData) {
    const attachment = await api.functional.discussionBoard.articles.attachments.post(connection, {
      body: data satisfies IDiscussionBoardAttachment.ICreate,
    });
    typia.assert(attachment);
    attachments.push(attachment);
  }

  // 5. List/filter attachments by post ID
  const list = await api.functional.discussionBoard.articles.attachments.patch(connection, {
    body: {
      discussion_board_post_id: post.id,
      discussion_board_comment_id: null,
      discussion_board_member_id: null,
      file_name: null,
      content_type: null,
      created_at_from: null,
      created_at_to: null,
      deleted: null,
      page: 1,
      limit: 100,
      sort: null,
      order: null,
    } satisfies IDiscussionBoardAttachment.IRequest,
  });
  typia.assert(list);
  // Must contain both uploaded attachments
  TestValidator.equals('attachments by post ID')(list.data.length)(2);
  for (const att of attachments) {
    const found = list.data.find(x => x.id === att.id);
    TestValidator.predicate('attachment present for id: '+att.id)(!!found);
    if (found) TestValidator.equals('attachment info')(found)(att);
  }

  // 6. Negative test: different post ID returns zero attachments
  const negative = await api.functional.discussionBoard.articles.attachments.patch(connection, {
    body: {
      discussion_board_post_id: typia.random<string & tags.Format<'uuid'>>(),
      discussion_board_comment_id: null,
      discussion_board_member_id: null,
      file_name: null,
      content_type: null,
      created_at_from: null,
      created_at_to: null,
      deleted: null,
      page: 1,
      limit: 100,
      sort: null,
      order: null,
    } satisfies IDiscussionBoardAttachment.IRequest,
  });
  typia.assert(negative);
  TestValidator.equals('attachments for non-existent post')(negative.data.length)(0);
}

