 *
 * This test verifies the workflow for updating a vote type entry via the admin-only endpoints in the discussion board system.
 *
 * Steps:
 * 1. Create a new vote type record via POST, storing its id and details.
 * 2. Update this vote type with new name and description fields using PUT.
 * 3. Validate that mutable fields are updated as expected, while immutable fields (id, created_at, code) remain unchanged.
 * 4. Confirm that updated_at timestamp has been changed to reflect the update.
 */
export async function test_api_discussionBoard_votes_voteTypes_test_update_vote_type_with_valid_fields(
  connection: api.IConnection,
) {
  // 1. Create initial vote type (POST)
  const initialInput: discussion_board_vote_types.ICreate = {
    code: `votetype_${RandomGenerator.alphaNumeric(6)}`,
    name: `Name_${RandomGenerator.alphabets(8)}`,
    description: `Desc_${RandomGenerator.alphaNumeric(15)}`,
  };
  const created: discussion_board_vote_types = await api.functional.discussionBoard.votes.voteTypes.post(connection, {
    body: initialInput,
  });
  typia.assert(created);

  // 2. Prepare update input (PUT) — change name and description only
  const updateInput: discussion_board_vote_types.IUpdate = {
    name: `Updated_${RandomGenerator.alphabets(8)}`,
    description: `Updated desc ${RandomGenerator.alphaNumeric(12)}`,
  };

  // 3. Update the vote type by id
