import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IDiscussionBoardThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardThread";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { discussion_board_vote_types } from "@ORGANIZATION/PROJECT-api/lib/structures/discussion_board_vote_types";
import type { discussion_board_votes } from "@ORGANIZATION/PROJECT-api/lib/structures/discussion_board_votes";

/**
 * Test the successful creation of a vote on a post in the discussion board.
 *
 * This test covers the end-to-end workflow of voting on a post, including:
 * 1. Creating a member who will act as the voter
 * 2. Creating a vote type that will be used for the vote (e.g., "upvote")
 * 3. Creating a thread (since posts are made in threads)
 * 4. Creating a post within the thread (this is the target post for voting)
 * 5. Creating a vote associated with the post, referencing the appropriate voter, vote type, and post ID
 * 6. Verifying that the returned vote record is correctly linked to the voter, vote type, and post, and that
 *    the schema matches the expected structure, with thread_id and comment_id being null/undefined
 */
export async function test_api_discussionBoard_test_create_vote_on_post_success(
  connection: api.IConnection,
) {
  // 1. Create a member who will be the voter
  const member = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(12),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(32),
      display_name: RandomGenerator.name(),
      is_active: true,
      // profile_image_url omitted for brevity (optional)
    } satisfies IdiscussionBoardMembers.ICreate,
  });
  typia.assert(member);

  // 2. Create a vote type (e.g., 'upvote')
  const voteType = await api.functional.discussionBoard.votes.voteTypes.post(connection, {
    body: {
      code: "upvote-" + RandomGenerator.alphaNumeric(6),
      name: "Upvote",
      description: "Indicates a positive reaction (test-generated)",
    } satisfies discussion_board_vote_types.ICreate,
  });
  typia.assert(voteType);

  // 3. Create a thread
  const thread = await api.functional.discussionBoard.articles.threads.post(connection, {
    body: {
      discussion_board_category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(6),
      body: RandomGenerator.content()()(),
      is_pinned: false,
      is_closed: false,
    } satisfies IDiscussionBoardThread.ICreate,
  });
  typia.assert(thread);

  // 4. Create a post on the thread
  const post = await api.functional.discussionBoard.articles.posts.post(connection, {
    body: {
      discussion_board_thread_id: thread.id,
      discussion_board_member_id: member.id,
      body: RandomGenerator.content()()(),
    } satisfies IDiscussionBoardPost.ICreate,
  });
  typia.assert(post);

  // 5. Create the vote associated with the post (not thread/comment)
  const vote = await api.functional.discussionBoard.votes.votes.post(connection, {
    body: {
      voter_id: member.id,
      vote_type_id: voteType.id,
      thread_id: null, // vote is for post only
      post_id: post.id,
      comment_id: null,
    } satisfies discussion_board_votes.ICreate,
  });
  typia.assert(vote);

  // 6. Verify correct linking and schema fields
  TestValidator.equals("vote.voter_id matches member.id")(vote.voter_id)(member.id);
  TestValidator.equals("vote.vote_type_id matches voteType.id")(vote.vote_type_id)(voteType.id);
  TestValidator.equals("vote.post_id matches post.id")(vote.post_id)(post.id);
  TestValidator.equals("vote.thread_id is null")(vote.thread_id)(null);
  TestValidator.equals("vote.comment_id is null")(vote.comment_id)(null);
}

