/**
 * 댓글에 투표(vote) 성공 케이스를 검증하는 테스트 함수입니다.
 *
 * [비즈니스 목적 및 맥락]
 * - 회원이 토론 게시판 내에서 댓글에 투표(예: 좋아요, 반대 등)를 할 수 있는지, 그리고 모든 선행 조건(회원, 투표 유형, 스레드, 게시물, 댓글)이 정상적으로 충족된 상황에서 투표가 올바르게 생성되는지 검증합니다.
 *
 * [프로세스 설명]
 * 1. 새로운 토론 게시판 회원(투표자)을 생성합니다.
 * 2. 투표 유형(예: 'upvote')을 등록합니다.
 * 3. 임의의 카테고리 UUID를 기반으로 스레드를 생성합니다.
 * 4. 해당 스레드 내에 게시물을 생성합니다.
 * 5. 생성된 게시물에 댓글을 작성합니다.
 * 6. 준비된 회원, 투표 유형, 댓글 정보를 기반으로 댓글 투표를 생성합니다.
 * 7. API 응답값이 논리 및 관계적으로 일관되는지(투표자, 투표유형, 투표대상 comment 등) 검증합니다.
 */
export async function test_api_discussionBoard_votes_votes_post_test_create_vote_on_comment_success(
  connection: api.IConnection,
) {
  // 1. 회원(투표자) 생성
  const member = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(14),
      display_name: RandomGenerator.name(),
      profile_image_url: null,
      is_active: true,
    },
  });
  typia.assert(member);

  // 2. 투표 타입 생성
  const voteType = await api.functional.discussionBoard.votes.voteTypes.post(connection, {
    body: {
      code: `upvote_${RandomGenerator.alphaNumeric(6)}`,
      name: "Upvote",
      description: "Upvote for comment",
    },
  });
  typia.assert(voteType);

  // 3. 스레드 카테고리 UUID 임의 생성 및 스레드 생성
  const threadCategoryId = typia.random<string & tags.Format<"uuid">>();
  const thread = await api.functional.discussionBoard.articles.threads.post(connection, {
    body: {
      discussion_board_category_id: threadCategoryId,
      title: RandomGenerator.paragraph()(),
      body: RandomGenerator.content()()(),
      is_pinned: false,
      is_closed: false,
    },
  });
  typia.assert(thread);

  // 4. 게시물(post) 생성
  const post = await api.functional.discussionBoard.articles.posts.post(connection, {
    body: {
      discussion_board_thread_id: thread.id,
      discussion_board_member_id: member.id,
      body: RandomGenerator.content()()(),
    },
  });
  typia.assert(post);

  // 5. 댓글(comment) 생성
  const comment = await api.functional.discussionBoard.articles.comments.post(connection, {
    body: {
      discussion_board_post_id: post.id,
      discussion_board_member_id: member.id,
      body: RandomGenerator.content()()(),
    },
  });
  typia.assert(comment);

  // 6. 댓글에 투표(vote) 생성
  const vote = await api.functional.discussionBoard.votes.votes.post(connection, {
    body: {
      voter_id: member.id,
      vote_type_id: voteType.id,
      thread_id: null,
      post_id: null,
      comment_id: comment.id,
    },
  });
  typia.assert(vote);

  // 7. 연관성 및 응답 검증
  TestValidator.equals("투표자 일치")(vote.voter_id)(member.id);
  TestValidator.equals("투표 타입 일치")(vote.vote_type_id)(voteType.id);
  TestValidator.equals("댓글 투표 대상 일치")(vote.comment_id)(comment.id);
  TestValidator.equals("스레드 투표 아님")(vote.thread_id)(null);
  TestValidator.equals("게시물 투표 아님")(vote.post_id)(null);
}

