/**
 * Validate strict schema enforcement when creating a vote.
 *
 * This test ensures that the vote creation endpoint rejects or ignores forbidden (extra) fields and enforces schema validation strictly. It also verifies that required relationships (such as voter, vote type, and target entity) are properly validated.
 *
 * Steps:
 * 1. Create a member voter using the appropriate endpoint.
 * 2. Create a valid vote type using the vote type creation endpoint.
 * 3. Create a thread to serve as target for the vote.
 * 4. Successfully create a valid vote as a baseline check.
 * 5. Attempt to create a vote with forbidden extra fields and confirm that the API rejects the request (error expected).
 * 6. Attempt to create a vote missing required relationships (all of thread_id, post_id, comment_id omitted) and confirm that the API validation fails.
 */
export async function test_api_discussionBoard_test_create_vote_forbidden_fields_ignored(
  connection: api.IConnection,
) {
