  const memberReq: IdiscussionBoardMembers.ICreate = {
    username: RandomGenerator.alphabets(8),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(16),
    display_name: RandomGenerator.name(),
    is_active: true,
  };
  const member = await api.functional.discussionBoard.actors.members.post(connection, { body: memberReq });
  typia.assert(member);

  // 2. Create a vote type
  const voteTypeReq: discussion_board_vote_types.ICreate = {
    code: RandomGenerator.alphabets(7).toLowerCase(),
    name: "Test Upvote",
    description: "For test case.",
  };
  const voteType = await api.functional.discussionBoard.votes.voteTypes.post(connection, { body: voteTypeReq });
  typia.assert(voteType);

  // 3. Create a thread
  const threadReq: IDiscussionBoardThread.ICreate = {
    discussion_board_category_id: typia.random<string & tags.Format<"uuid">>(),
    title: RandomGenerator.paragraph()(),
    body: RandomGenerator.content()()(),
    is_pinned: false,
    is_closed: false,
  };
  const thread = await api.functional.discussionBoard.articles.threads.post(connection, { body: threadReq });
  typia.assert(thread);

  // 4. Baseline — create a valid vote (should succeed)
  const properVoteReq: discussion_board_votes.ICreate = {
    voter_id: member.id,
    vote_type_id: voteType.id,
    thread_id: thread.id,
  };
  const properVote = await api.functional.discussionBoard.votes.votes.post(connection, { body: properVoteReq });
  typia.assert(properVote);
