  TestValidator.equals("vote_type_id")(properVote.vote_type_id)(voteType.id);
  TestValidator.equals("thread_id")(properVote.thread_id)(thread.id);

  // 5. Attempt to create a vote with an extra forbidden field. Should fail
  TestValidator.error("Creating vote with forbidden extra fields should fail")(async () => {
    const invalidVoteReq = {
      voter_id: member.id,
      vote_type_id: voteType.id,
      thread_id: thread.id,
      unexpected_field: "intruder!", // forbidden field
    } as any;
    await api.functional.discussionBoard.votes.votes.post(connection, { body: invalidVoteReq });
  });

  // 6. Attempt to create a vote with all relationships omitted (thread_id, post_id, comment_id missing). Should fail
  TestValidator.error("Schema should require at least one target id (thread/post/comment)")(async () => {
