/**
 * Test updating an existing ban to make it permanent.
 *
 * This test simulates a moderation scenario where a temporary user ban is escalated to a permanent one. The steps are as follows:
 *
 * 1. Create a target member account to be banned.
 * 2. Create a moderator account with authority to impose bans.
 * 3. The moderator creates a temporary ban against the member (with expires_at set).
 * 4. The moderator updates the ban: sets permanent: true and expires_at: null.
 * 5. Validate that the ban update is reflected (permanent: true, expires_at: null) and other fields remain consistent.
 */
export async function test_api_discussionBoard_test_update_ban_to_permanent(connection: api.IConnection) {
  // 1. Create member account
  const member = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(24),
      display_name: RandomGenerator.name(),
      is_active: true,
      profile_image_url: null,
    } satisfies IdiscussionBoardMembers.ICreate
  });
  typia.assert(member);

  // 2. Create moderator account (assume same schema for test)
  const moderator = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(24),
      display_name: RandomGenerator.name(),
      is_active: true,
      profile_image_url: null,
    } satisfies IdiscussionBoardMembers.ICreate
  });
  typia.assert(moderator);

  // 3. Create a temporary ban
  const tempBan = await api.functional.discussionBoard.moderation.bans.post(connection, {
    body: {
      member_id: member.id,
      moderator_id: moderator.id,
      ban_reason: "Spamming forum posts with advertisements",
      permanent: false,
      expires_at: new Date(Date.now() + 5 * 24 * 60 * 60 * 1000).toISOString(), // 5 days in future
    } satisfies IModerationBan.ICreate
  });
  typia.assert(tempBan);
  TestValidator.equals("Temporary ban created")(tempBan.permanent)(false);
  TestValidator.predicate("Temporary ban has expires_at")(!!tempBan.expires_at);

  // 4. Update the ban to be permanent (expires_at must become null)
  const updatedBan = await api.functional.discussionBoard.moderation.bans.putById(connection, {
    id: tempBan.id,
    body: {
      ban_reason: tempBan.ban_reason,
      permanent: true,
      expires_at: null,
    } satisfies IModerationBan.IUpdate
  });
  typia.assert(updatedBan);

  // 5. Validate update: permanent is true, expires_at is null
  TestValidator.equals("Ban is now permanent")(updatedBan.permanent)(true);
  TestValidator.equals("Ban expires_at is null")(updatedBan.expires_at)(null);
  // Other identity fields should not have changed
  TestValidator.equals("Ban id unchanged")(updatedBan.id)(tempBan.id);
  TestValidator.equals("Ban member_id unchanged")(updatedBan.member_id)(member.id);
  TestValidator.equals("Ban moderator_id unchanged")(updatedBan.moderator_id)(moderator.id);
  TestValidator.equals("Ban reason unchanged")(updatedBan.ban_reason)(tempBan.ban_reason);
}

