import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IDiscussionBoardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardNotification";

/**
 * Validate successful creation of a discussion board notification with valid data.
 *
 * This test covers the following workflow:
 * 1. Create a member as the recipient of the notification using /discussionBoard/actors/members (POST).
 * 2. Create a second member to serve as the trigger actor (sender of the notification event).
 * 3. Create a notification by sending a POST request to /discussionBoard/notifications/notifications,
 *    setting all required and optional fields in the body. Provide recipient_member_id using the
 *    first member, trigger_actor_id from the second. Set required: type, url, read, created_at,
 *    and optionally set: content_preview, delivered_at.
 * 4. Assert a proper successful response and validate that the response follows the
 *    IDiscussionBoardNotification schema and matches input expectations.
 */
export async function test_api_discussionBoard_notifications_notifications_test_create_notification_with_valid_data(
  connection: api.IConnection
) {
  // 1. Create recipient member
  const recipient: IdiscussionBoardMembers = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(24),
      display_name: RandomGenerator.name(),
      profile_image_url: null,
      is_active: true,
    } satisfies IdiscussionBoardMembers.ICreate,
  });
  typia.assert(recipient);
  // Validate recipient properties
  TestValidator.predicate("recipient id format")(typeof recipient.id === "string" && recipient.id.length > 0);
  TestValidator.predicate("recipient email format")(recipient.email.includes("@"));
  TestValidator.equals("recipient active")(recipient.is_active)(true);
  TestValidator.equals("recipient.deleted_at null")(recipient.deleted_at)(null);

  // 2. Create trigger actor member
  const triggerActor: IdiscussionBoardMembers = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(24),
      display_name: RandomGenerator.name(),
      profile_image_url: null,
      is_active: true,
    } satisfies IdiscussionBoardMembers.ICreate,
  });
  typia.assert(triggerActor);
  // Validate trigger actor properties
  TestValidator.predicate("trigger actor id format")(typeof triggerActor.id === "string" && triggerActor.id.length > 0);
  TestValidator.predicate("trigger actor email format")(triggerActor.email.includes("@"));
  TestValidator.equals("trigger actor active")(triggerActor.is_active)(true);
  TestValidator.equals("trigger actor.deleted_at null")(triggerActor.deleted_at)(null);
  // Ensure recipient and trigger actor are distinct
  TestValidator.notEquals("recipient and trigger actor must be different")(recipient.id)(triggerActor.id);

  // 3. Create notification event with all required and optional fields set
  const now: string & tags.Format<"date-time"> = new Date().toISOString() as string & tags.Format<"date-time">;
  const notificationInput: IDiscussionBoardNotification.ICreate = {
    recipient_member_id: recipient.id,
    trigger_actor_id: triggerActor.id,
    type: "mention",
    content_preview: "You were mentioned in the discussion.",
    url: "https://forum.example.com/thread/123#comment-456",
    read: false,
    delivered_at: now,
    created_at: now,
  };
  const notification: IDiscussionBoardNotification = await api.functional.discussionBoard.notifications.notifications.post(connection, {
    body: notificationInput,
  });
  typia.assert(notification);
  // 4. Validate returned data matches input & schema requirements
  TestValidator.equals("recipient matches")(notification.recipient_member_id)(recipient.id);
  TestValidator.equals("trigger actor matches")(notification.trigger_actor_id)(triggerActor.id);
  TestValidator.equals("type")(notification.type)(notificationInput.type);
  TestValidator.equals("content_preview")(notification.content_preview)(notificationInput.content_preview);
  TestValidator.equals("url")(notification.url)(notificationInput.url);
  TestValidator.equals("read status")(notification.read)(false);
  TestValidator.equals("delivered_at")(notification.delivered_at)(now);
  TestValidator.equals("created_at")(notification.created_at)(now);
  TestValidator.predicate("notification id format")(typeof notification.id === "string" && notification.id.length > 0);
  // deleted_at should be null or undefined on creation
  TestValidator.equals("deleted_at null at creation")(notification.deleted_at)(null);
}

