 *
 * 1. Register a recipient member for notification.
 * 2. Register a second member as a trigger actor.
 * 3. Create several notifications with various type/read/delivered_at attributes (using both actor and null for trigger_actor_id).
 * 4. Exercise the notifications listing (PATCH):
 *    a. Filter by type; verify only notifications of that type are returned.
 *    b. Filter by read status; verify only unread notifications are returned.
 *    c. Filter by delivered date range; check delivered_at within expected window.
 *    d. List all notifications with no filters; verify count equals created set.
 *    e. Validate pagination meta and data shape matches schema and records.
 */
export async function test_api_discussionBoard_notifications_notifications_test_list_notifications_with_filtering_and_pagination(connection: api.IConnection) {
  // 1. Register a recipient member
