 * 4. 응답의 필드 값이 입력한 값으로 정확히 반영되었으며, id/부모채널id는 그대로이고, updated_at이 기존과 다르게 현재 시각으로 갱신되었음을 검증한다.
 */
export async function test_api_discussionBoard_systematic_sections_test_update_section_fields_success(
