  const sectionInput: IDiscussionBoardSection.ICreate = {
    discussion_board_channel_id: channel.id,
    code: RandomGenerator.alphaNumeric(8),
    name: RandomGenerator.paragraph()(1),
    description: RandomGenerator.paragraph()(),
  };
