/**
 * 섹션 코드 업데이트 시, 채널 내에서 중복된 코드로 변경을 시도하면 유니크 제약 조건이 제대로 강제되는지 검증합니다.
 *
 * - 테스트 목적: discussion_board_sections의 code 필드는 동일 채널 내에서만 유니크하게 관리되므로,
 *   다른 섹션이 이미 사용하는 코드를 update로 지정할 경우 에러가 발생해야 하며, 이때 런타임 예외가 정상적으로 발생하는지 검증합니다.
 *
 * - 테스트 과정:
 *   1. 먼저 새로운 채널을 생성합니다(채널 code, name, description 입력).
 *   2. 해당 채널 내에 sectionA, sectionB 두 개의 섹션을 각각 서로 다른 code로 만듭니다.
 *   3. sectionA의 code를 sectionB의 code로(=이미 존재하는 섹션 코드) 변경하려고 update를 시도합니다.
 *   4. 이때 API가 유니크 제약조건 위반(runtime error)을 반환하는지 TestValidator로 검증합니다.
 *
 * 실제 운영 환경에서의 유니크 키 데이터 무결성 보장 및 예외 감지 자동화에 매우 필수적인 시나리오 테스트입니다.
 */
export async function test_api_discussionBoard_systematic_sections_test_update_section_with_duplicate_code_in_channel(
  connection: api.IConnection,
) {
  // 1. 신규 채널 생성
  const channelCode = RandomGenerator.alphaNumeric(10);
  const channel = await api.functional.discussionBoard.systematic.channels.post(connection, {
    body: {
      code: channelCode,
      name: RandomGenerator.paragraph()(2),
      description: RandomGenerator.paragraph()(3),
    },
  });
  typia.assert(channel);

  // 2. sectionA, sectionB: 동일 채널 내 서로 다른 code로 두개 생성
  const sectionACode = RandomGenerator.alphaNumeric(8);
  const sectionBCode = RandomGenerator.alphaNumeric(8);
  const sectionA = await api.functional.discussionBoard.systematic.sections.post(connection, {
    body: {
      discussion_board_channel_id: channel.id,
      code: sectionACode,
      name: RandomGenerator.paragraph()(2),
      description: RandomGenerator.paragraph()(2),
    },
  });
  typia.assert(sectionA);
  const sectionB = await api.functional.discussionBoard.systematic.sections.post(connection, {
    body: {
      discussion_board_channel_id: channel.id,
      code: sectionBCode,
      name: RandomGenerator.paragraph()(2),
      description: RandomGenerator.paragraph()(2),
    },
  });
  typia.assert(sectionB);

  // 3. sectionA의 code를 sectionB의 code로 강제로 update 시도 - 유니크 제약 위반 발생확인
  await TestValidator.error("동일 채널 내 섹션 코드 중복 업데이트 시 에러 발생 확인")(
    async () => {
      await api.functional.discussionBoard.systematic.sections.putById(connection, {
        id: sectionA.id,
        body: { code: sectionB.code },
      });
    }
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
