import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IDiscussionBoardThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardThread";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAttachment";

/**
 * Test updating an attachment's metadata by a moderator for a valid attachment.
 *
 * This test covers the full workflow for updating the metadata of an attachment in a discussion board system, simulating a moderator action.
 *
 * Business context:
 * - Metadata edits for attachments may be required during content migration, file retagging, or audit corrections.
 * - Moderators/admins should be able to update mutable fields (file_name, file_uri, content_type, content_hash) without altering immutable fields (created_at, deleted_at).
 *
 * Workflow:
 * 1. Create a member who will act as the uploader of the attachment.
 * 2. Create a new thread, assigning the member as the creator (requires a valid category; we'll mock a UUID for the category as it is not part of dependencies).
 * 3. Create a post within the created thread, authored by the member.
 * 4. Upload an attachment file to the post, providing file metadata and linking it to the member and post.
 * 5. Update the attachment's metadata as a moderator (simulate moderator context by just calling the update function, since role-specific auth is not enforced at API level).
 * 6. Validate that the updatable fields (file_name, file_uri, content_type, content_hash) are updated, and immutable fields like created_at and deleted_at are unchanged.
 * 7. Ensure the attachment record remains accessible and unchanged in non-updated fields.
 */
export async function test_api_discussionBoard_test_update_attachment_metadata_with_valid_data(connection: api.IConnection) {
  // 1. Create member
  const memberCreate = {
    username: RandomGenerator.alphaNumeric(12),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(16),
    display_name: RandomGenerator.name(),
    profile_image_url: null,
    is_active: true,
  } satisfies IdiscussionBoardMembers.ICreate;
  const member = await api.functional.discussionBoard.actors.members.post(connection, { body: memberCreate });
  typia.assert(member);

  // 2. Create thread
  // We require a valid category UUID (discussion_board_category_id) but there's no endpoint for category creation. We'll mock one.
  const threadCreate = {
    discussion_board_category_id: typia.random<string & tags.Format<"uuid">>(),
    title: RandomGenerator.paragraph()(),
    body: RandomGenerator.content()()(),
    is_pinned: false,
    is_closed: false,
  } satisfies IDiscussionBoardThread.ICreate;
  // Attach the member to the thread as creator
  (threadCreate as any)["discussion_board_member_id"] = member.id;
  const thread = await api.functional.discussionBoard.articles.threads.post(connection, { body: threadCreate as any });
  typia.assert(thread);

  // 3. Create post
  const postCreate = {
    discussion_board_thread_id: thread.id,
    discussion_board_member_id: member.id,
    body: RandomGenerator.content()()(),
  } satisfies IDiscussionBoardPost.ICreate;
  const post = await api.functional.discussionBoard.articles.posts.post(connection, { body: postCreate });
  typia.assert(post);

  // 4. Upload an attachment to the post
  const attachmentCreate = {
    discussion_board_post_id: post.id,
    discussion_board_comment_id: null,
    discussion_board_member_id: member.id,
    file_name: RandomGenerator.alphaNumeric(10) + '.txt',
    file_uri: 'https://cdn.example.com/files/' + RandomGenerator.alphaNumeric(30),
    content_type: 'text/plain',
    content_hash: typia.random<string>(),
  } satisfies IDiscussionBoardAttachment.ICreate;
  const attachment = await api.functional.discussionBoard.articles.attachments.post(connection, { body: attachmentCreate });
  typia.assert(attachment);

  // 5. Prepare new metadata for update
  const updateInput = {
    file_name: RandomGenerator.alphaNumeric(8) + '.md',
    file_uri: 'https://cdn.example.com/files/' + RandomGenerator.alphaNumeric(32),
    content_type: 'text/markdown',
    content_hash: typia.random<string>(),
  } satisfies IDiscussionBoardAttachment.IUpdate;

  // 6. Perform attachment metadata update
  const updated = await api.functional.discussionBoard.articles.attachments.putById(connection, {
    id: attachment.id,
    body: updateInput,
  });
  typia.assert(updated);

  // 7. Validate update and immutability
  TestValidator.equals("file_name updated")(updated.file_name)(updateInput.file_name);
  TestValidator.equals("file_uri updated")(updated.file_uri)(updateInput.file_uri);
  TestValidator.equals("content_type updated")(updated.content_type)(updateInput.content_type);
  TestValidator.equals("content_hash updated")(updated.content_hash)(updateInput.content_hash);
  // Immutable fields unchanged
  TestValidator.equals("created_at unchanged")(updated.created_at)(attachment.created_at);
  TestValidator.equals("deleted_at unchanged")(updated.deleted_at ?? null)(attachment.deleted_at ?? null);
  // Unrelated fields are preserved
  TestValidator.equals("post linkage")(updated.discussion_board_post_id)(attachment.discussion_board_post_id);
  TestValidator.equals("uploader linkage")(updated.discussion_board_member_id)(attachment.discussion_board_member_id);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IDiscussionBoardThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardThread";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAttachment";

/**
 * Validate rejection of invalid attachment update data by strict schema compliance.
 *
 * Scenario: Try to update an attachment in two ways that should fail strict validation:
 *   - Include extra (non-schema) fields in the update body.
 *   - Omit all allowed fields (empty body).
 * This checks that only exactly allowed schema fields are permitted in update operations, and that the server enforces this. Also verify a successful valid update.
 *
 * Steps:
 * 1. Register a member to associate with the attachment.
 * 2. Create a thread so a post can be made for attachment association.
 * 3. Post an article to hold the attachment.
 * 4. Upload a valid attachment.
 * 5. Attempt to update the attachment with extra fields not in schema (should error).
 * 6. Attempt to update the attachment with an empty body (should error).
 * 7. Attempt a valid update to ensure valid behavior (positive control).
 */
export async function test_api_discussionBoard_test_update_attachment_metadata_with_invalid_fields(
  connection: api.IConnection,
) {
  // 1. Register a member for attachment
  const member = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(12),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(24),
      display_name: RandomGenerator.name(),
      is_active: true,
    } satisfies IdiscussionBoardMembers.ICreate,
  });
  typia.assert(member);

  // 2. Create a thread (category id is randomly generated UUID)
  const thread = await api.functional.discussionBoard.articles.threads.post(connection, {
    body: {
      discussion_board_category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(1),
      body: RandomGenerator.content()()(1),
      is_pinned: false,
      is_closed: false,
    } satisfies IDiscussionBoardThread.ICreate,
  });
  typia.assert(thread);

  // 3. Create a post in the thread
  const post = await api.functional.discussionBoard.articles.posts.post(connection, {
    body: {
      discussion_board_thread_id: thread.id,
      discussion_board_member_id: member.id,
      body: RandomGenerator.content()()(1),
    } satisfies IDiscussionBoardPost.ICreate,
  });
  typia.assert(post);

  // 4. Upload an attachment associated to the post
  const attachment = await api.functional.discussionBoard.articles.attachments.post(connection, {
    body: {
      discussion_board_post_id: post.id,
      discussion_board_member_id: member.id,
      file_name: "test-file.txt",
      file_uri: "https://cdn.example.com/test-file.txt",
      content_type: "text/plain",
      content_hash: RandomGenerator.alphaNumeric(64),
    } satisfies IDiscussionBoardAttachment.ICreate,
  });
  typia.assert(attachment);

  // 5. Attempt to update with a non-schema (forbidden) field
  await TestValidator.error("should reject update with extra non-schema fields")(
    async () => {
      await api.functional.discussionBoard.articles.attachments.putById(connection, {
        id: attachment.id,
        // This body includes a property NOT in IDiscussionBoardAttachment.IUpdate
        body: {
          file_name: "malicious-file.txt",
          forbidden_field: "not allowed",
        } as any, // Forcing to bypass type check to test actual API behavior
      });
    },
  );

  // 6. Attempt to update with an empty object (no allowed fields)
  await TestValidator.error("should reject update with empty body")(
    async () => {
      await api.functional.discussionBoard.articles.attachments.putById(connection, {
        id: attachment.id,
        body: {},
      });
    }
  );

  // 7. Positive case: update with a valid schema-only field
  const updated = await api.functional.discussionBoard.articles.attachments.putById(connection, {
    id: attachment.id,
    body: {
      file_name: "updated-file.txt",
    } satisfies IDiscussionBoardAttachment.IUpdate,
  });
  typia.assert(updated);
  TestValidator.equals("filename updated")(updated.file_name)("updated-file.txt");
}

