import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IDiscussionBoardThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardThread";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAttachment";

/**
 * 이 테스트는 moderator(관리자)가 첨부파일을 soft delete 처리하는 기능을 검증합니다.
 * 
 * 비즈니스 흐름상 첨부파일이 있으려면 회원 등록, 스레드 등록, 게시물 작성, 첨부파일 업로드가 선행되어야 하며,
 * 그 후 관리자가 첨부파일을 soft delete(삭제 타임스탬프를 세팅) 처리합니다.
 * 주요 검증 포인트는 다음과 같습니다.
 *
 * 1. 회원을 생성한다 (업로더 역할)
 * 2. 쓰레드를 생성한다 (게시판 맥락 필요)
 * 3. 게시물을 생성한다 (게시글에 첨부 예정)
 * 4. 첨부파일을 업로드한다
 * 5. moderator 권한으로 첨부파일을 soft delete한다
 * 6. 삭제된 첨부파일 응답의 deleted_at 필드가 ISO8601 string으로 설정되었는지 확인한다
 * 7. 첨부파일 조회 리스트에서, 기본적으로 삭제된 첨부파일이 노출되지 않음을 (삭제 필터 없는 기본조회 시) 확인한다
 * (단, 실제 조회 API가 제공된다면 추가한다. 미제공 시 6번까지만 구현)
 */
export async function test_api_discussionBoard_test_soft_delete_attachment_by_moderator(
  connection: api.IConnection,
) {
  // 1. 회원 생성 (업로더)
  const member = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<'email'>>(),
      hashed_password: RandomGenerator.alphaNumeric(24),
      display_name: RandomGenerator.name(),
      profile_image_url: null,
      is_active: true,
    },
  });
