import type { IDiscussionBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReport";

/**
 * Validate duplicate moderation report submission handling in the discussion board.
 *
 * This test ensures that if a member submits two identical reports (same reporter and content target),
 * the API correctly enforces business logic regarding duplicate prevention. Depending on the platform's
 * duplicate detection policy, the second submission should either succeed, be deduplicated, or raise an error.
 * The test attempts both submissions and validates the resulting system behavior.
 *
 * Steps:
 * 1. Register a member account who will act as the reporter.
 * 2. Create a thread in the discussion board to serve as the report target.
 * 3. Submit a moderation report for the thread by the member.
 * 4. Attempt to submit an identical moderation report for the same thread and member.
 * 5. Verify: If the system enforces duplicate prevention, the second attempt should fail; otherwise, it may succeed
 *    or result in deduplication. Both paths are validated accordingly.
 */
export async function test_api_discussionBoard_test_create_duplicate_moderation_report(
  connection: api.IConnection,
) {
  // 1. Register a member account (reporter)
  const reporterInput: IdiscussionBoardMembers.ICreate = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(16),
    display_name: RandomGenerator.name(),
    is_active: true,
  };
  const reporter = await api.functional.discussionBoard.actors.members.post(connection, {
    body: reporterInput
  });
  typia.assert(reporter);

  // 2. Create a new thread to be reported
  const threadInput: IDiscussionBoardThread.ICreate = {
    discussion_board_category_id: typia.random<string & tags.Format<"uuid">>(),
    title: RandomGenerator.paragraph()(),
    body: RandomGenerator.content()()(),
    is_pinned: false,
    is_closed: false,
  };
  const thread = await api.functional.discussionBoard.articles.threads.post(connection, {
    body: threadInput
  });
  typia.assert(thread);

  // 3. Submit the initial moderation report for the thread by the reporter
  const reportInput: IDiscussionBoardReport.ICreate = {
    reporter_member_id: reporter.id,
    thread_id: thread.id,
    reason: "Duplicate test report",
    status: "pending",
  };
  const firstReport = await api.functional.discussionBoard.moderation.reports.post(connection, {
    body: reportInput
  });
  typia.assert(firstReport);

  // 4. Attempt to submit the identical moderation report again
  let duplicateError: unknown = null;
  let secondReport: IDiscussionBoardReport | null = null;
  try {
    secondReport = await api.functional.discussionBoard.moderation.reports.post(connection, {
      body: reportInput
    });
    typia.assert(secondReport);
  } catch (exp) {
    duplicateError = exp;
  }

  // 5. Verify duplicate handling
  if (duplicateError !== null) {
    TestValidator.error("Duplicate report should reject or error")(async () => { throw duplicateError; });
  } else {
    // If accepted, responses must not be identical
    TestValidator.notEquals("Duplicate report should not create identical record")(secondReport!.id)(firstReport.id);
    TestValidator.equals("Reporter matches")(secondReport!.reporter_member_id)(firstReport.reporter_member_id);
    TestValidator.equals("Thread matches")(secondReport!.thread_id)(firstReport.thread_id);
    TestValidator.equals("Reason matches")(secondReport!.reason)(firstReport.reason);
    TestValidator.equals("Status matches")(secondReport!.status)(firstReport.status);
  }
}

