import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IDiscussionBoardThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardThread";
import type { IDiscussionBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReport";

/**
 * 유효한 신고ID로 중재 리포트 상세 조회 (GET by id)
 *
 * - 신규 회원을 생성한 뒤, 신고 대상 스레드를 등록합니다.
 * - 해당 스레드에 대해 moderation(신고) 리포트를 생성합니다.
 * - 등록된 신고 리포트의 id로 상세조회(getById)를 호출하여,
 *   실제 조회 결과가 schema와 일치하고, 신고 생성 시 데이터(특히 PK/신고자/대상/사유/상태)가 올바로 반영됐는지 검증합니다.
 *
 * 테스트 주요 절차
 * 1. 회원 회원가입 (discussionBoard.actors.members.post)
 * 2. 토론 스레드 생성 (discussionBoard.articles.threads.post)
 * 3. moderation 신고 생성 (discussionBoard.moderation.reports.post)
 * 4. 신고ID로 상세조회 (discussionBoard.moderation.reports.getById)
 * 5. 조회값과 최초 생성시 값 일치 검증 (핵심 필드)
 */
export async function test_api_discussionBoard_test_get_moderation_report_by_valid_id(
  connection: api.IConnection,
) {
  // 1. 새 회원 등록
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberUsername = RandomGenerator.alphabets(10);
  const member = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: memberUsername,
      email: memberEmail,
      hashed_password: RandomGenerator.alphaNumeric(16),
      display_name: RandomGenerator.name(),
      is_active: true,
      profile_image_url: null,
    },
  });
  typia.assert(member);

  // 2. 토론 스레드 생성 (카테고리 엔드포인트 없음 → 임의 uuid)
  const threadCategoryId = typia.random<string & tags.Format<"uuid">>();
  const thread = await api.functional.discussionBoard.articles.threads.post(connection, {
    body: {
      discussion_board_category_id: threadCategoryId,
      title: RandomGenerator.paragraph()(8),
      body: RandomGenerator.content()(1)(2),
      is_pinned: false,
      is_closed: false,
    },
  });
  typia.assert(thread);

  // 3. moderation 신고 등록
  const reportData = {
    reporter_member_id: member.id,
    thread_id: thread.id,
    post_id: null,
    comment_id: null,
    reason: "스팸 의심 게시글",
    status: "pending",
  };
  const createdReport = await api.functional.discussionBoard.moderation.reports.post(connection, {
    body: reportData,
  });
  typia.assert(createdReport);

  // 4. 해당 신고 ID로 상세조회
  const fetchedReport = await api.functional.discussionBoard.moderation.reports.getById(connection, {
    id: createdReport.id,
  });
  typia.assert(fetchedReport);

  // 5. 주요 필드 동등성 체크 (최초 생성 데이터와 실제 조회 값 일치 확인)
  TestValidator.equals("신고자 UUID")(fetchedReport.reporter_member_id)(reportData.reporter_member_id);
  TestValidator.equals("스레드ID")(fetchedReport.thread_id)(reportData.thread_id);
  TestValidator.equals("신고 사유")(fetchedReport.reason)(reportData.reason);
  TestValidator.equals("신고 상태")(fetchedReport.status)(reportData.status);
  TestValidator.equals("신고 PK(id)")(fetchedReport.id)(createdReport.id);
}

