 * a member cannot be assigned moderator privileges more than once concurrently.
 *
 * Steps:
 * 1. Create a new member account.
 * 2. Assign moderator role to that member.
 * 3. Attempt to assign moderator role again for the same member (with a new assignment time).
 * 4. The second assignment should fail due to the uniqueness constraint (one moderator role per member).
 */
export async function test_api_discussionBoard_test_assign_moderator_role_to_already_moderator_member_fails(
  connection: api.IConnection,
) {
  // 1. Create a new member
  const memberInput = {
    username: RandomGenerator.alphabets(10),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphabets(32),
    display_name: RandomGenerator.alphabets(10),
    is_active: true,
    profile_image_url: null,
  } satisfies IdiscussionBoardMembers.ICreate;
  const member = await api.functional.discussionBoard.actors.members.post(connection, {
    body: memberInput,
  });
  typia.assert(member);

  // 2. Assign moderator role to that member
  const assignmentTime1 = new Date().toISOString();
  const moderatorAssignment = await api.functional.discussionBoard.actors.moderators.post(connection, {
    body: {
      member_id: member.id,
      assigned_at: assignmentTime1,
    } satisfies IdiscussionBoardModerators.ICreate,
  });
  typia.assert(moderatorAssignment);

  // 3 & 4. Attempt to assign moderator role again (should fail due to uniqueness constraint)
  const assignmentTime2 = new Date(Date.now() + 1000).toISOString();
  await TestValidator.error("Cannot assign moderator twice to same member")(
    async () => {
      await api.functional.discussionBoard.actors.moderators.post(connection, {
        body: {
          member_id: member.id,
          assigned_at: assignmentTime2,
