import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";

/**
 * Validate the successful retrieval of a moderator assignment by its unique ID.
 *
 * This test ensures that after registering a new member and assigning them as a moderator,
 * the system returns a complete and accurate moderator assignment record when fetched by ID.
 *
 * Steps:
 * 1. Register a new member (unique username/email, random password, display name, is_active=true)
 * 2. Assign moderator role to that new member (with assignment timestamp)
 * 3. Retrieve the moderator assignment by its ID using the GET endpoint
 * 4. Validate all schema-defined fields:
 *    - id: Matches the created assignment
 *    - member_id: Matches the assigned member
 *    - assigned_at: Matches the timestamp of assignment (truncated to seconds to tolerate ms rounding)
 *    - revoked_at: null for new assignments (not yet revoked)
 */
export async function test_api_discussionBoard_actors_moderators_test_get_moderator_assignment_details_success(
  connection: api.IConnection,
) {
  // 1. Register a new member
  const signupInput: IdiscussionBoardMembers.ICreate = {
    username: RandomGenerator.alphabets(10),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(32),
    display_name: RandomGenerator.name(),
    is_active: true,
    // optional profile_image_url: randomly present or null
    profile_image_url: Math.random() < 0.5 ? null : `https://picsum.photos/seed/${Math.random().toString().slice(2)}/200/200`,
  };
  const member = await api.functional.discussionBoard.actors.members.post(connection, { body: signupInput });
  typia.assert(member);

  // 2. Assign moderator to that member
  const timestampNow = new Date().toISOString();
  const modAssignInput: IdiscussionBoardModerators.ICreate = {
    member_id: member.id,
    assigned_at: timestampNow,
  };
  const moderator = await api.functional.discussionBoard.actors.moderators.post(connection, { body: modAssignInput });
  typia.assert(moderator);

  // 3. Fetch moderator assignment by assignment ID
  const modAssignment = await api.functional.discussionBoard.actors.moderators.getById(connection, { id: moderator.id });
  typia.assert(modAssignment);

  // 4. Validate that all schema-defined fields match expected values
  TestValidator.equals("moderator assignment id matches")(modAssignment.id)(moderator.id);
  TestValidator.equals("assigned member id matches")(modAssignment.member_id)(member.id);

  // Compare assignment times up to seconds to avoid issues with ms truncation
  TestValidator.equals("assigned_at up to seconds matches")(
    modAssignment.assigned_at.slice(0, 19)
  )(
    timestampNow.slice(0, 19)
  );

  // revoked_at should be null for newly assigned moderators
  TestValidator.equals("revoked_at is null for new moderator")(modAssignment.revoked_at)(null);
}

